--
-- Name: apps_notify_egress_allowlist_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_notify_egress_allowlist_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_notify(
        'app_egress_policy_changed',
        json_build_object(
            'app_id', NEW.id,
            'revision', NEW.egress_allowlist_revision
        )::text
    );
    RETURN NEW;
END;
$$;


--
-- Name: apps_public_auth_ip_allowlist_cidr_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_public_auth_ip_allowlist_cidr_check() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  bad cidr;
begin
  if new.public_auth_ip_allowlist is null or cardinality(new.public_auth_ip_allowlist) = 0 then
    return new;
  end if;
  -- Per-entry guards: family must be v4 or v6, mask must be non-zero.
  -- The /0 reject closes the same hole as the egress allowlist's
  -- chain-policy accept: an operator cannot pin "the entire
  -- address space" — that is the default-pass posture's job, not
  -- the allowlist's. Two narrow selects (one per guard) keep the
  -- error messages specific; a combined select with bool_or would
  -- conflate family and masklen failures.
  for bad in
    select c
      from unnest(new.public_auth_ip_allowlist) c
     where family(c) not in (4, 6)
     limit 1
  loop
    raise exception 'apps_public_auth_ip_allowlist: only v4 or v6 CIDRs (got family % for %)', family(bad), bad
      using errcode = '23514',
            constraint = 'apps_public_auth_ip_allowlist_cidr';
  end loop;
  for bad in
    select c
      from unnest(new.public_auth_ip_allowlist) c
     where masklen(c) = 0
     limit 1
  loop
    raise exception 'apps_public_auth_ip_allowlist: rejected % (masklen /0; ADR-118 non-/0 contract)', bad
      using errcode = '23514',
            constraint = 'apps_public_auth_ip_allowlist_cidr';
  end loop;
  return new;
end;
$$;


--
-- Name: apps_record_control_plane_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_record_control_plane_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Scale-in/out bookkeeping changes often and is not gateway policy.
    -- Avoid serializing those writes behind the global replay-order lock or
    -- claiming that a gateway has a new policy revision to apply.
    IF TG_OP = 'UPDATE' THEN
        IF (to_jsonb(NEW) - ARRAY['last_scale_out_at', 'last_scale_in_at']) =
           (to_jsonb(OLD) - ARRAY['last_scale_out_at', 'last_scale_in_at']) THEN
            RETURN NEW;
        END IF;
    END IF;
    PERFORM pg_advisory_xact_lock(711901248671::bigint);
    IF TG_OP = 'INSERT' THEN
        INSERT INTO control_plane_change_log (resource_type, resource_id, app_id, operation)
        VALUES ('app', NEW.id, NEW.id, 'created');
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO control_plane_change_log (resource_type, resource_id, app_id, operation)
        VALUES ('app', NEW.id, NEW.id, 'updated');
        RETURN NEW;
    ELSE
        INSERT INTO control_plane_change_log (resource_type, resource_id, app_id, operation)
        VALUES ('app', OLD.id, OLD.id, 'deleted');
        RETURN OLD;
    END IF;
END;
$$;


--
-- Name: apps_streaming_plan_account_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_streaming_plan_account_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.plan='free' AND OLD.plan IS DISTINCT FROM NEW.plan AND EXISTS(
  SELECT 1 FROM apps a LEFT JOIN orgs o ON o.id=a.org_id WHERE a.account_id=NEW.id
  AND (a.org_id IS NULL OR o.personal_org OR NOT o.resource_ownership_enabled) AND a.streaming_enabled) THEN
  RAISE EXCEPTION 'personal streaming app prevents Free downgrade' USING ERRCODE='23514',CONSTRAINT='apps_streaming_enabled_plan_check';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: apps_streaming_plan_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_streaming_plan_allowed(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM accounts
         WHERE id = p_account_id
           AND plan <> 'free'
    );
$$;


--
-- Name: apps_streaming_plan_app_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_streaming_plan_app_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.streaming_enabled THEN
  IF EXISTS(SELECT 1 FROM orgs WHERE id=NEW.org_id AND NOT personal_org AND resource_ownership_enabled) THEN
   PERFORM id FROM orgs WHERE id=NEW.org_id FOR SHARE;
  ELSE
   PERFORM id FROM accounts WHERE id=NEW.account_id FOR NO KEY UPDATE;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: apps_visibility_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_visibility_notify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.visibility IS DISTINCT FROM OLD.visibility THEN
    PERFORM pg_notify(
      'app_changed',
      json_build_object('kind', 'updated', 'app_id', NEW.id::text)::text
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: assert_clone_configuration_mutable(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_clone_configuration_mutable(project uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    guard_state text;
BEGIN
    IF project IS NULL THEN RETURN; END IF;
    -- A locking read also prevents repeatable-read writers with a snapshot
    -- predating acquisition from bypassing the committed hold.
    SELECT state INTO guard_state FROM project_environment_clone_configuration_guards
    WHERE project_id = project FOR SHARE;
    IF NOT FOUND THEN
        -- The project or account BEFORE DELETE guard already admitted this
        -- deletion. FK cascades can remove the guard before dependent rows,
        -- or before the project itself, are cleaned. A live project in a
        -- live account with missing evidence must still fail closed.
        IF NOT EXISTS (
            SELECT 1 FROM projects p JOIN accounts a ON a.id = p.account_id
            WHERE p.id = project
        ) THEN RETURN; END IF;
        RAISE EXCEPTION 'project configuration guard is missing'
            USING ERRCODE = '55000', CONSTRAINT = 'clone_configuration_guard_missing';
    END IF;
    IF guard_state <> 'open' THEN
        RAISE EXCEPTION 'source configuration is held for stage capture'
            USING ERRCODE = '55000', CONSTRAINT = 'clone_configuration_write_fenced';
    END IF;
END;
$$;


--
-- Name: assert_object_copy_source_authority(uuid, uuid, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_object_copy_source_authority(a uuid, destination uuid, subject text, source uuid, key text, epoch uuid) RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE c object_storage_s3_credentials; p object_storage_s3_credentials; g object_s3_copy_source_grants;
BEGIN
 IF subject !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Invalid copy subject';
 END IF;
 SELECT * INTO c FROM object_storage_s3_credentials WHERE id=subject::uuid FOR SHARE;
 IF c.id IS NULL OR c.account_id<>a OR c.bucket_id<>destination OR c.status<>'active' OR
  c.permission NOT IN ('write','read_write') OR c.url_request IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Copy writer is unavailable';
 END IF;
 SELECT * INTO p FROM object_storage_s3_credentials WHERE id=coalesce(c.rotation_parent_id,c.id) FOR SHARE;
 SELECT * INTO g FROM object_s3_copy_source_grants WHERE credential_id=p.id AND source_bucket_id=source FOR SHARE;
 IF p.id IS NULL OR p.account_id<>a OR p.bucket_id<>destination OR p.status<>'active' OR
  p.permission NOT IN ('write','read_write') OR p.url_request IS NOT NULL OR g.id IS NULL OR
  g.id<>epoch OR g.account_id<>a OR g.bucket_id<>destination OR key='' OR octet_length(key)>1024 OR
  left(key,length(g.prefix))<>g.prefix OR key ~ E'[\\r\\n]' OR
  NOT EXISTS(SELECT 1 FROM object_buckets d JOIN object_buckets s ON s.id=source
    WHERE d.id=destination AND d.account_id=a AND s.account_id=a AND d.state='ready' AND s.state='ready'
    AND (d.backend_id,d.backend_fingerprint)=(s.backend_id,s.backend_fingerprint)) OR
  EXISTS(SELECT 1 FROM object_deletions WHERE bucket_id IN (destination,source) AND state IN ('prepared','dispatched')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Copy source authority changed';
 END IF;
END $_$;


--
-- Name: assign_app_service_address_index(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_app_service_address_index() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.service_address_index IS NULL AND NEW.status <> 'deleted' THEN
        NEW.service_address_index := allocate_app_service_address_index(NEW.account_id);
    ELSIF TG_OP = 'INSERT' AND NEW.service_address_index IS NOT NULL THEN
        -- An explicit index (data repair, tests) must never be handed out
        -- again by the cursor.
        INSERT INTO app_service_address_cursors AS c (account_id, last_index)
        VALUES (NEW.account_id, NEW.service_address_index)
        ON CONFLICT (account_id) DO UPDATE
           SET last_index = greatest(c.last_index, EXCLUDED.last_index);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: authorize_binding_release_deactivation(uuid, text, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_binding_release_deactivation(target_project uuid, target_environment text, receipt_id uuid, prior_release text, members jsonb, fences jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE g jsonb;
BEGIN
 IF prior_release='' THEN RAISE EXCEPTION 'active graph required' USING ERRCODE='23514',CONSTRAINT='binding_release_changed'; END IF;
 IF EXISTS (SELECT 1 FROM deployments d JOIN apps a ON a.id=d.app_id WHERE a.project_id=target_project AND a.status<>'deleted' AND coalesce(a.preview_of_slug,'')='' AND d.scope=target_environment AND d.environment_workload_runtime IS NOT NULL) THEN
  RAISE EXCEPTION 'managed workload requires GitOps graph' USING ERRCODE='23514',CONSTRAINT='binding_release_changed';
 END IF;
 PERFORM authorize_binding_release_graph(target_project,target_environment,receipt_id,prior_release,members,fences);
 g:=nullif(current_setting('gregale.binding_release_graph',true),'')::jsonb;
 -- This grant can retire the exact current graph, never insert a replacement.
 PERFORM set_config('gregale.binding_release_graph',(g || jsonb_build_object('new_id','','action','deactivate','receipt_id',receipt_id))::text,true);
 RETURN true;
END $$;


--
-- Name: authorize_binding_release_graph(uuid, text, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_binding_release_graph(target_project uuid, target_environment text, next_release uuid, prior_release text, members jsonb, fences jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE a apps%ROWTYPE; f jsonb; ready_count integer; latest text;
BEGIN
 IF jsonb_typeof(members) <> 'object' OR (SELECT count(*) FROM jsonb_each(members)) = 0 THEN
  RAISE EXCEPTION 'invalid checked graph' USING ERRCODE='23514', CONSTRAINT='binding_release_changed';
 END IF;
 -- publishProjectReleaseSetTx already holds the project and app locks.
 SELECT id::text INTO latest FROM project_release_sets WHERE project_id=target_project AND environment_slug=target_environment AND active;
 IF coalesce(latest,'') <> prior_release THEN RAISE EXCEPTION 'active graph changed' USING ERRCODE='23514',CONSTRAINT='binding_release_changed'; END IF;
 PERFORM authorize_binding_release_traffic(fences);
 IF (SELECT count(*) FROM apps WHERE project_id=target_project AND status<>'deleted' AND coalesce(preview_of_slug,'')='') <> (SELECT count(*) FROM jsonb_each(members)) THEN
  RAISE EXCEPTION 'graph membership changed' USING ERRCODE='23514',CONSTRAINT='binding_release_changed';
 END IF;
 FOR a IN SELECT * FROM apps WHERE project_id=target_project AND status<>'deleted' AND coalesce(preview_of_slug,'')='' ORDER BY id LOOP
  SELECT value INTO f FROM jsonb_array_elements(fences) WHERE value->>'app_id'=a.id::text;
  IF f IS NULL OR f->>'deployment_id' IS DISTINCT FROM members->>a.id::text OR f->>'account_id' IS DISTINCT FROM a.account_id::text OR f->>'scope' IS DISTINCT FROM target_environment OR
    NOT EXISTS (SELECT 1 FROM app_binding_release_policies p WHERE p.app_id=a.id AND p.scope=target_environment AND p.mode='enforce') THEN
   RAISE EXCEPTION 'graph member lacks enforced evidence' USING ERRCODE='23514',CONSTRAINT='binding_release_required';
  END IF;
  IF coalesce(a.manifest->>'execution_mode','')='service' THEN
   SELECT count(*) INTO ready_count FROM (SELECT id FROM instances WHERE app_id=a.id AND deployment_id=(members->>a.id::text)::uuid AND mode='service' AND state='running' FOR SHARE) ready;
   IF ready_count < greatest(1,coalesce((a.manifest->'service_replicas'->>'desired')::integer,1)) THEN
    RAISE EXCEPTION 'graph service recipient is not ready' USING ERRCODE='23514',CONSTRAINT='binding_release_changed';
   END IF;
  END IF;
 END LOOP;
 PERFORM set_config('gregale.binding_release_graph',jsonb_build_object('project_id',target_project,'environment',target_environment,'new_id',next_release,'old_id',prior_release,'members',members,'fences',fences)::text,true);
 RETURN true;
END $$;


--
-- Name: authorize_binding_release_traffic(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_binding_release_traffic(fences jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE f jsonb; observed text; d deployments%ROWTYPE; p app_binding_release_policies%ROWTYPE;
BEGIN
 FOR f IN SELECT value FROM jsonb_array_elements(fences) LOOP
  SELECT r.epoch::text||':'||r.revision::text INTO observed FROM app_binding_promotion_revisions r
  JOIN apps a ON a.id=r.app_id WHERE r.app_id=(f->>'app_id')::uuid AND a.account_id=(f->>'account_id')::uuid AND a.status<>'deleted'
  FOR UPDATE OF r;
  IF observed IS NULL OR observed<>f->>'revision' THEN
   RAISE EXCEPTION 'binding facts changed' USING ERRCODE='23514',CONSTRAINT='binding_release_changed';
  END IF;
  SELECT * INTO d FROM deployments WHERE id=(f->>'deployment_id')::uuid AND app_id=(f->>'app_id')::uuid;
  IF d.id IS NULL OR d.status<>'live' OR d.scope<>f->>'scope' OR coalesce(d.rootfs_key,'')='' OR coalesce(d.image_digest,'')='' THEN
   RAISE EXCEPTION 'binding deployment changed' USING ERRCODE='23514',CONSTRAINT='binding_release_changed';
  END IF;
  IF NULLIF(f->>'valid_until','')::timestamptz <= clock_timestamp() THEN
   RAISE EXCEPTION 'binding evidence expired' USING ERRCODE='23514',CONSTRAINT='binding_release_expired';
  END IF;
  SELECT * INTO p FROM app_binding_release_policies WHERE app_id=d.app_id AND scope=d.scope;
  IF p.mode='enforce' AND NOT coalesce((f->>'policy_revision')::bigint=p.revision AND (f->>'max_age_seconds')::numeric>0 AND (f->>'max_age_seconds')::numeric<=p.max_age_seconds AND NOT (f->>'allow_unsupported')::boolean AND (NOT p.require_application_ack OR (f->>'require_application_ack')::boolean) AND coalesce(NULLIF(f->'object_storage_requirements','null'::jsonb),'{}'::jsonb)=p.object_storage_requirements AND coalesce(NULLIF(f->'queue_requirements','null'::jsonb),'{}'::jsonb)=p.queue_requirements,false) THEN
   RAISE EXCEPTION 'binding release policy changed' USING ERRCODE='23514',CONSTRAINT='binding_release_changed';
  END IF;
 END LOOP;
 PERFORM set_config('gregale.binding_release_fences',fences::text,true);
 RETURN true;
END $$;


--
-- Name: authorize_environment_binding_release(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_environment_binding_release(target_graph uuid, next_release uuid, prior_release text, members jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE g environment_workload_graphs%ROWTYPE; s environment_git_sources%ROWTYPE; release_scope text; deadline timestamptz; actual jsonb; latest text;
BEGIN
 SELECT * INTO g FROM environment_workload_graphs WHERE id=target_graph;
 SELECT * INTO s FROM active_environment_git_sources WHERE id=g.source_id;
 SELECT slug INTO release_scope FROM project_environments WHERE id=g.environment_id;
 IF NOT EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=s.id AND j.claimed_generation=s.generation AND j.lease_token=current_setting('gregale.gitops_lease',true) AND j.lease_until>clock_timestamp()) THEN
  RAISE EXCEPTION 'candidate binding release requires its intent lease' USING ERRCODE='23514',CONSTRAINT='binding_release_required'; END IF;
 PERFORM r.app_id FROM app_binding_promotion_revisions r JOIN apps a ON a.id=r.app_id WHERE a.project_id=s.project_id ORDER BY r.app_id FOR UPDATE OF r;
 SELECT id::text INTO latest FROM project_release_sets WHERE project_id=s.project_id AND environment_slug=release_scope AND active;
 SELECT jsonb_object_agg(app_id::text,deployment_id::text) INTO actual FROM environment_workload_qualification_requests WHERE graph_id=g.id;
 deadline:=environment_binding_qualification_deadline(g.id);
 IF deadline IS NULL OR actual IS DISTINCT FROM members OR coalesce(latest,'')<>prior_release OR
  (SELECT count(*) FROM apps WHERE project_id=s.project_id AND status<>'deleted' AND coalesce(preview_of_slug,'')='')<>(SELECT count(*) FROM jsonb_each(members)) THEN
  RAISE EXCEPTION 'managed graph requires current complete candidate binding evidence' USING ERRCODE='23514',CONSTRAINT='binding_release_required'; END IF;
 INSERT INTO environment_binding_release_receipts(release_id,graph_id,members,valid_until) VALUES(next_release,g.id,members,deadline);
 PERFORM set_config('gregale.binding_release_graph',jsonb_build_object('project_id',s.project_id,'environment',release_scope,'new_id',next_release,'old_id',prior_release,'members',members,'fences',jsonb_build_array(jsonb_build_object('valid_until',deadline)))::text,true);
 RETURN true;
END $$;


--
-- Name: authorize_environment_binding_retirement(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_environment_binding_retirement(target_source uuid, next_release uuid, prior_release text, reviewed_plan text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE s environment_git_sources%ROWTYPE; audit environment_binding_retirement_receipts%ROWTYPE; release_scope text; latest text;
BEGIN
 SELECT * INTO s FROM active_environment_git_sources WHERE id=target_source FOR UPDATE;
 IF s.id IS NULL THEN RAISE EXCEPTION 'retirement source changed' USING ERRCODE='23514',CONSTRAINT='binding_release_changed'; END IF;
 PERFORM id FROM projects WHERE id=s.project_id AND account_id=s.account_id FOR UPDATE;
 PERFORM id FROM apps WHERE project_id=s.project_id ORDER BY id FOR UPDATE;
 PERFORM r.app_id FROM app_binding_promotion_revisions r JOIN apps a ON a.id=r.app_id WHERE a.project_id=s.project_id ORDER BY r.app_id FOR UPDATE OF r;
 SELECT slug INTO release_scope FROM project_environments WHERE id=s.environment_id;
 SELECT id::text INTO latest FROM project_release_sets WHERE project_id=s.project_id AND environment_slug=release_scope AND active;
 IF coalesce(latest,'')<>prior_release THEN RAISE EXCEPTION 'active graph changed' USING ERRCODE='23514',CONSTRAINT='binding_release_changed'; END IF;
 audit.release_id:=next_release; audit.source_id:=s.id; audit.revision_id:=s.approved_revision_id; audit.generation:=s.generation;
 audit.intent_version:=s.intent_version; audit.plan_hash:=reviewed_plan; audit.prior_release:=prior_release;
 SELECT array_agg(id ORDER BY id),jsonb_object_agg(id::text,binding_policy_context) INTO audit.retirement_ids,audit.policies
 FROM environment_workload_retirements WHERE source_id=s.id AND revision_id=s.approved_revision_id AND generation=s.generation AND phase='retiring';
 SELECT lease_until INTO audit.valid_until FROM environment_gitops_jobs WHERE source_id=s.id AND lease_token=current_setting('gregale.gitops_lease',true);
 IF audit.retirement_ids IS NULL OR audit.valid_until IS NULL OR NOT environment_binding_retirement_current(audit) THEN
  RAISE EXCEPTION 'complete removal requires current reviewed binding retirement authority' USING ERRCODE='23514',CONSTRAINT='binding_release_required'; END IF;
 INSERT INTO environment_binding_retirement_receipts(release_id,source_id,revision_id,generation,intent_version,plan_hash,prior_release,retirement_ids,policies,valid_until)
 VALUES(audit.release_id,audit.source_id,audit.revision_id,audit.generation,audit.intent_version,audit.plan_hash,audit.prior_release,audit.retirement_ids,audit.policies,audit.valid_until);
 PERFORM set_config('gregale.binding_release_graph',jsonb_build_object('project_id',s.project_id,'environment',release_scope,'new_id',next_release,'old_id',prior_release,'members','{}'::jsonb,'fences',jsonb_build_array(jsonb_build_object('valid_until',audit.valid_until)))::text,true);
 RETURN true;
END $$;


--
-- Name: authorize_environment_binding_traffic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_environment_binding_traffic(target_graph uuid, target_release uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE audit environment_binding_release_receipts%ROWTYPE; g environment_workload_graphs%ROWTYPE; s environment_git_sources%ROWTYPE; release_scope text; grants jsonb;
BEGIN
 SELECT * INTO g FROM environment_workload_graphs WHERE id=target_graph;
 SELECT * INTO s FROM active_environment_git_sources WHERE id=g.source_id;
 SELECT slug INTO release_scope FROM project_environments WHERE id=g.environment_id;
 IF NOT EXISTS(SELECT 1 FROM apps a JOIN app_binding_release_policies p ON p.app_id=a.id WHERE a.project_id=s.project_id AND p.scope=release_scope AND p.mode='enforce') THEN RETURN true; END IF;
 PERFORM r.app_id FROM app_binding_promotion_revisions r JOIN apps a ON a.id=r.app_id WHERE a.project_id=s.project_id ORDER BY r.app_id FOR UPDATE OF r;
 SELECT * INTO audit FROM environment_binding_release_receipts WHERE release_id=target_release AND graph_id=target_graph;
 IF audit.release_id IS NULL OR audit.valid_until<=clock_timestamp() OR environment_binding_qualification_deadline(target_graph) IS NULL OR
 NOT EXISTS(SELECT 1 FROM project_release_sets WHERE id=target_release AND active) OR
 NOT EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=s.id AND j.claimed_generation=s.generation AND j.lease_token=current_setting('gregale.gitops_lease',true) AND j.lease_until>clock_timestamp()) THEN
 RAISE EXCEPTION 'managed serving requires its current checked candidate graph' USING ERRCODE='23514',CONSTRAINT='binding_release_required'; END IF;
 SELECT jsonb_agg(jsonb_build_object('app_id',q.app_id,'deployment_id',q.deployment_id,'scope',release_scope,'policy_revision',p.revision,'valid_until',audit.valid_until)) INTO grants
 FROM environment_workload_qualification_requests q JOIN app_binding_release_policies p ON p.app_id=q.app_id AND p.scope=release_scope WHERE q.graph_id=g.id;
 PERFORM set_config('gregale.binding_release_fences',grants::text,true);
 RETURN true;
END $$;


--
-- Name: automatic_route_check_capture_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automatic_route_check_capture_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        PERFORM enqueue_automatic_route_check(OLD.app_id, OLD.deployment_id);
        RETURN OLD;
    END IF;
    IF TG_OP = 'INSERT' OR NEW.doc_sha256 IS DISTINCT FROM OLD.doc_sha256 OR NEW.truncated IS DISTINCT FROM OLD.truncated THEN
        PERFORM enqueue_automatic_route_check(NEW.app_id, NEW.deployment_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: automatic_route_check_intent_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automatic_route_check_intent_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' OR NEW.revision IS DISTINCT FROM OLD.revision OR NEW.sha256 IS DISTINCT FROM OLD.sha256 THEN
        PERFORM enqueue_automatic_route_check(NEW.app_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: base_image_producer_current_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.base_image_producer_current_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'DELETE' AND current_setting('gregale.base_producer_insert',true)=NEW.producer_id::text
   AND (TG_OP='INSERT' OR NEW.storage_key=OLD.storage_key) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'base producer selection is private' USING ERRCODE='23514',CONSTRAINT='base_image_producer_immutable';
END;
$$;


--
-- Name: base_image_producer_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.base_image_producer_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' AND current_setting('gregale.base_producer_insert',true)=NEW.id::text THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'base producer evidence is immutable/private' USING ERRCODE='23514',CONSTRAINT='base_image_producer_immutable';
END;
$$;


--
-- Name: base_image_scan_current_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.base_image_scan_current_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'DELETE' AND current_setting('gregale.base_scan_insert',true)=NEW.scan_id::text
   AND (TG_OP='INSERT' OR NEW.storage_key=OLD.storage_key) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'base scan selection is private' USING ERRCODE='23514',CONSTRAINT='base_image_scan_immutable';
END;
$$;


--
-- Name: base_image_scan_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.base_image_scan_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' AND current_setting('gregale.base_scan_insert',true)=NEW.id::text THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'base scan evidence is immutable/private' USING ERRCODE='23514',CONSTRAINT='base_image_scan_immutable';
END;
$$;


--
-- Name: bind_app_builder_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_app_builder_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE app_org uuid;
BEGIN
 SELECT o.id INTO app_org FROM apps a JOIN orgs o ON o.id=a.org_id WHERE a.id=NEW.app_id AND NOT o.personal_org AND o.resource_ownership_enabled;
 IF app_org IS NOT NULL THEN NEW.account_id:=app_org;NEW.org_id:=app_org;END IF;
 RETURN NEW;
END $$;


--
-- Name: bind_app_quota_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_app_quota_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE personal_owner uuid; is_personal boolean;
BEGIN
    IF NEW.org_id IS NULL THEN
        SELECT id INTO NEW.org_id FROM orgs
        WHERE personal_org AND personal_owner_account_id = NEW.account_id;
    END IF;
    IF NEW.org_id IS NOT NULL THEN
        SELECT personal_org, personal_owner_account_id INTO is_personal, personal_owner
        FROM orgs WHERE id = NEW.org_id FOR SHARE;
        IF is_personal AND personal_owner IS DISTINCT FROM NEW.account_id THEN
            RAISE EXCEPTION 'app personal organization does not match account' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END $$;


--
-- Name: bind_app_storage_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_app_storage_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE app_org uuid; original_subject uuid;
BEGIN
 SELECT o.id INTO app_org FROM apps a JOIN orgs o ON o.id=a.org_id WHERE a.id=NEW.app_id AND NOT o.personal_org AND o.resource_ownership_enabled;
 IF app_org IS NOT NULL THEN
  SELECT account_id INTO original_subject FROM snapshot_storage_daily WHERE app_id=NEW.app_id AND day=NEW.day ORDER BY account_id LIMIT 1;
  NEW.account_id:=coalesce(original_subject,app_org);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: bind_app_usage_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_app_usage_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE app_org uuid; personal boolean;
BEGIN
    IF NEW.app_id IS NOT NULL AND NEW.meter_kind = 'app' THEN
        SELECT o.id, o.personal_org INTO app_org, personal FROM apps a JOIN orgs o ON o.id=a.org_id
        WHERE a.id=NEW.app_id;
        IF app_org IS NOT NULL THEN
            NEW.org_id := app_org;
            IF NOT personal AND EXISTS(SELECT 1 FROM orgs WHERE id=app_org AND resource_ownership_enabled) THEN NEW.account_id := app_org; END IF;
        END IF;
    END IF;
    RETURN NEW;
END $$;


--
-- Name: bind_core_app_resource_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_core_app_resource_org() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE owning_org uuid;
BEGIN
 SELECT org_id INTO owning_org FROM apps WHERE id=NEW.app_id;
 IF owning_org IS NOT NULL THEN NEW.org_id:=owning_org;END IF;
 RETURN NEW;
END $$;


--
-- Name: bind_deployment_runtime_environment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_deployment_runtime_environment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    selected_environment uuid;
    original_environment uuid;
BEGIN
    SELECT s.environment_id INTO STRICT selected_environment
    FROM project_environment_workload_specs s
    JOIN project_environments e ON e.id=s.environment_id
    JOIN apps a ON a.id=s.app_id AND a.account_id=e.account_id AND a.project_id=e.project_id
    JOIN deployments d ON d.app_id=a.id AND d.id=NEW.deployment_id
    WHERE s.id=NEW.spec_id AND e.slug=CASE WHEN d.scope='default' THEN 'production' ELSE d.scope END;
    INSERT INTO deployment_runtime_environment_owners (deployment_id, environment_id)
    VALUES (NEW.deployment_id, selected_environment)
    ON CONFLICT (deployment_id) DO NOTHING;
    SELECT environment_id INTO STRICT original_environment
    FROM deployment_runtime_environment_owners WHERE deployment_id=NEW.deployment_id;
    IF original_environment <> selected_environment THEN
        RAISE EXCEPTION 'deployment runtime environment is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: bind_job_run_image_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_job_run_image_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.image_materialization_status = 'ready' AND NEW.image_storage_key IS NOT NULL THEN
        UPDATE job_runs SET
            image_resolved_digest_snapshot = NEW.image_resolved_digest,
            image_storage_key_snapshot = NEW.image_storage_key
        WHERE job_id = NEW.id
          AND image_ref_snapshot = NEW.image_ref
          AND image_storage_key_snapshot IS NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: bind_managed_postgres_resource_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_managed_postgres_resource_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.account_id<>OLD.account_id) THEN
  RAISE EXCEPTION 'database ownership is immutable' USING ERRCODE='23514', CONSTRAINT='managed_postgres_resource_owner';
 END IF;
 IF NEW.org_id IS NULL AND NEW.environment_clone_operation_id IS NOT NULL THEN
  SELECT p.org_id INTO NEW.org_id FROM project_environment_clone_operations c JOIN projects p ON p.id=c.project_id WHERE c.id=NEW.environment_clone_operation_id;
 END IF;
 IF NEW.org_id IS NULL THEN SELECT id INTO NEW.org_id FROM orgs WHERE personal_org AND personal_owner_account_id=NEW.account_id; END IF;
 PERFORM id FROM orgs WHERE id=NEW.org_id AND NOT deleted_pending FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'database organization unavailable' USING ERRCODE='23514',CONSTRAINT='managed_postgres_resource_owner'; END IF;
 IF NOT EXISTS(SELECT 1 FROM orgs o JOIN resource_namespaces n ON n.id=NEW.account_id
               WHERE o.id=NEW.org_id AND (NOT o.personal_org OR o.personal_owner_account_id=NEW.account_id))
 OR (NEW.restore_source_database_id IS NOT NULL AND NOT EXISTS(
     SELECT 1 FROM managed_postgres_databases s WHERE s.id=NEW.restore_source_database_id AND s.org_id=NEW.org_id)) THEN
  RAISE EXCEPTION 'invalid database organization' USING ERRCODE='23514', CONSTRAINT='managed_postgres_resource_owner';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: bind_object_bucket_organization(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_object_bucket_organization() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_org uuid; parent_account uuid;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.account_id<>OLD.account_id OR NEW.app_id<>OLD.app_id) THEN
  RAISE EXCEPTION 'bucket ownership is immutable' USING ERRCODE='23514',CONSTRAINT='object_bucket_organization';
 END IF;
 SELECT a.org_id,a.account_id INTO parent_org,parent_account FROM apps a WHERE a.id=NEW.app_id;
 IF NEW.org_id IS NULL THEN NEW.org_id=parent_org; END IF;
 IF parent_org IS NULL OR NEW.org_id<>parent_org OR NEW.account_id<>parent_account THEN
  RAISE EXCEPTION 'invalid bucket organization' USING ERRCODE='23514',CONSTRAINT='object_bucket_organization';
 END IF;
 PERFORM id FROM orgs WHERE id=NEW.org_id AND NOT deleted_pending FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'bucket organization unavailable' USING ERRCODE='23514',CONSTRAINT='object_bucket_organization'; END IF;
 RETURN NEW;
END $$;


--
-- Name: bind_project_resource_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_project_resource_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.account_id<>OLD.account_id) THEN
  RAISE EXCEPTION 'project ownership is immutable' USING ERRCODE='23514', CONSTRAINT='project_resource_owner';
 END IF;
 IF NEW.org_id IS NULL THEN
  SELECT o.id INTO NEW.org_id FROM orgs o WHERE o.personal_org AND o.personal_owner_account_id=NEW.account_id;
 END IF;
 IF NOT EXISTS (SELECT 1 FROM orgs o JOIN resource_namespaces n ON n.id=NEW.account_id
                WHERE o.id=NEW.org_id AND (NOT o.personal_org OR o.personal_owner_account_id=NEW.account_id)) THEN
  RAISE EXCEPTION 'invalid project ownership' USING ERRCODE='23503', CONSTRAINT='project_resource_owner';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: bind_project_workload_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_project_workload_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p projects%ROWTYPE;
BEGIN
 IF NEW.project_id IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO p FROM projects WHERE id=NEW.project_id FOR SHARE;
 IF NOT FOUND OR p.account_id<>NEW.account_id THEN
  RAISE EXCEPTION 'workload project namespace mismatch' USING ERRCODE='23514', CONSTRAINT='project_workload_owner';
 END IF;
 IF NEW.org_id IS NULL THEN NEW.org_id=p.org_id; END IF;
 IF p.org_id<>NEW.org_id THEN
  RAISE EXCEPTION 'workload project organization mismatch' USING ERRCODE='23514', CONSTRAINT='project_workload_owner';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: bind_queue_organization(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_queue_organization() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE owner_org uuid; namespace uuid;
BEGIN
 SELECT org_id,account_id INTO owner_org,namespace FROM apps WHERE id=NEW.app_id FOR SHARE;
 IF NOT FOUND OR owner_org IS NULL OR namespace IS DISTINCT FROM NEW.account_id
   OR (NEW.org_id IS NOT NULL AND NEW.org_id IS DISTINCT FROM owner_org) THEN
  RAISE EXCEPTION 'queue binding organization does not match its app' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND (NEW.account_id,NEW.app_id,NEW.org_id) IS DISTINCT FROM (OLD.account_id,OLD.app_id,OLD.org_id) THEN
  RAISE EXCEPTION 'queue binding ownership is immutable' USING ERRCODE='23514';
 END IF;
 NEW.org_id:=owner_org;
 RETURN NEW;
END $$;


--
-- Name: build_export_publication_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_export_publication_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF current_setting('gregale.build_export_publication_insert',true) IS DISTINCT FROM NEW.id::text THEN
   RAISE EXCEPTION 'build export must use private store' USING ERRCODE='23514',CONSTRAINT='build_export_publication_immutable';
  END IF;
  IF EXISTS(SELECT 1 FROM build_export_publications p WHERE p.build_id=NEW.build_id
   AND p.input_snapshot->'claims'->>'claim_started_at'=NEW.input_snapshot->'claims'->>'claim_started_at'
   AND p.input_snapshot->'claims' IS DISTINCT FROM NEW.input_snapshot->'claims') THEN
   RAISE EXCEPTION 'build export claim already published' USING ERRCODE='23514',CONSTRAINT='build_export_publication_conflict';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='DELETE' AND (NOT EXISTS(SELECT 1 FROM builds WHERE id=OLD.build_id) OR NOT EXISTS(SELECT 1 FROM deployments WHERE id=OLD.deployment_id)) THEN RETURN OLD;END IF;
 RAISE EXCEPTION 'build export is immutable' USING ERRCODE='23514',CONSTRAINT='build_export_publication_immutable';
END;
$$;


--
-- Name: bump_binding_promotion_revision(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_binding_promotion_revision(target uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
 INSERT INTO app_binding_promotion_revisions(app_id)
 SELECT id FROM apps WHERE id=target
 ON CONFLICT(app_id) DO UPDATE SET revision=app_binding_promotion_revisions.revision+1;
END $$;


--
-- Name: capture_binding_promotion_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_binding_promotion_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
 old_row jsonb := CASE WHEN TG_OP='INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
 new_row jsonb := CASE WHEN TG_OP='DELETE' THEN '{}'::jsonb ELSE to_jsonb(NEW) END;
 old_facts jsonb;
 new_facts jsonb;
 row_data jsonb;
 target uuid;
 targets uuid[] := '{}';
 watched text[] := string_to_array(TG_ARGV[0],',');
BEGIN
 IF TG_OP='UPDATE' THEN
  SELECT jsonb_object_agg(key,value) INTO old_facts FROM jsonb_each(old_row) WHERE key=ANY(watched);
  SELECT jsonb_object_agg(key,value) INTO new_facts FROM jsonb_each(new_row) WHERE key=ANY(watched);
  IF old_facts IS NOT DISTINCT FROM new_facts THEN RETURN NEW; END IF;
 END IF;
 IF TG_TABLE_NAME='app_tasks' AND old_row->>'binding_verification' IS NULL AND new_row->>'binding_verification' IS NULL THEN
  IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
 END IF;
 FOR row_data IN SELECT old_row UNION SELECT new_row LOOP
  IF row_data='{}'::jsonb THEN CONTINUE; END IF;
  CASE TG_TABLE_NAME
   WHEN 'apps' THEN targets:=targets||ARRAY[(row_data->>'id')::uuid];
   WHEN 'accounts' THEN
    targets:=targets||ARRAY(SELECT id FROM apps WHERE account_id=(row_data->>'id')::uuid);
   WHEN 'managed_postgres_databases' THEN
    targets:=targets||ARRAY(SELECT app_id FROM managed_postgres_bindings WHERE database_id=(row_data->>'id')::uuid);
   WHEN 'object_storage_s3_credentials' THEN
    targets:=targets||ARRAY[NULLIF(row_data->>'managed_app_id','')::uuid];
    targets:=targets||ARRAY(SELECT managed_app_id FROM object_storage_s3_credentials WHERE id=NULLIF(row_data->>'rotation_parent_id','')::uuid);
   WHEN 'outbound_integration_probe_policies' THEN
    targets:=targets||ARRAY(SELECT app_id FROM outbound_app_bindings WHERE integration_id=(row_data->>'integration_id')::uuid);
   WHEN 'outbound_integrations' THEN
    targets:=targets||ARRAY(SELECT app_id FROM outbound_app_bindings WHERE integration_id=(row_data->>'id')::uuid);
   WHEN 'outbound_integration_credentials' THEN
    targets:=targets||ARRAY(SELECT app_id FROM outbound_app_bindings WHERE integration_id=(row_data->>'integration_id')::uuid);
   WHEN 'trigger_consumer_health' THEN
    targets:=targets||ARRAY(SELECT app_id FROM triggers WHERE id=(row_data->>'trigger_id')::uuid);
   WHEN 'notification_outbox' THEN
    IF row_data->>'channel'='runtime_config_restart' THEN
     BEGIN
      targets:=targets||ARRAY[NULLIF((row_data->>'payload')::jsonb->>'app_id','')::uuid];
     EXCEPTION WHEN invalid_text_representation THEN
      -- Malformed refresh metadata makes inventory unreadable; invalidate all
      -- approvals rather than allowing an old readable projection to survive.
      targets:=targets||ARRAY(SELECT id FROM apps);
     END;
    END IF;
   WHEN 'instances' THEN
    IF row_data->>'kind'='wake' AND row_data->>'mode'<>'mirror' AND
       row_data->>'state' IN ('running','waking','cold_booting','warm','frozen','snapshotting','draining','migrating') THEN
     targets:=targets||ARRAY[(row_data->>'app_id')::uuid];
    END IF;
   ELSE targets:=targets||ARRAY[(row_data->>'app_id')::uuid];
  END CASE;
 END LOOP;
 -- Stable ordering also serializes writes that affect multiple bound apps.
 FOR target IN SELECT DISTINCT id FROM unnest(targets) id WHERE id IS NOT NULL ORDER BY id LOOP
  PERFORM bump_binding_promotion_revision(target);
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;


--
-- Name: capture_binding_release_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_binding_release_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.app_id<>OLD.app_id OR NEW.scope<>OLD.scope OR NEW.revision<>OLD.revision+1) THEN
  RAISE EXCEPTION 'release policy revision changed' USING ERRCODE='23514',CONSTRAINT='binding_release_policy_revision';
 END IF;
 IF NEW.mode='off' AND btrim(NEW.reason)='' THEN
  RAISE EXCEPTION 'disabling enforcement requires a reason' USING ERRCODE='23514',CONSTRAINT='binding_release_policy_reason';
 END IF;
 PERFORM bump_binding_promotion_revision(NEW.app_id);
 INSERT INTO app_binding_release_policy_history(app_id,scope,revision,policy)
 VALUES(NEW.app_id,NEW.scope,NEW.revision,to_jsonb(NEW));
 RETURN NEW;
END $$;


--
-- Name: capture_deployment_public_build_urls(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_deployment_public_build_urls() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.kind IN ('tarball','github','dockerfile') AND NEW.scope='default' THEN
  INSERT INTO deployment_public_build_urls(deployment_id,urls)
  SELECT NEW.id,COALESCE(a.manifest->'public_build_urls','{}'::jsonb)
  FROM apps a WHERE a.id=NEW.app_id AND COALESCE(a.preview_of_slug,'')='';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: capture_deployment_recovery_lineage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_deployment_recovery_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE predecessor uuid;
BEGIN
 PERFORM id FROM apps WHERE id=NEW.app_id FOR UPDATE;
 IF (SELECT count(*) FROM deployments d WHERE d.app_id=NEW.app_id AND d.scope=NEW.scope AND d.id<>NEW.id
  AND d.status='live' AND d.traffic_percent>0 AND d.deleted_at IS NULL)=1 THEN
  SELECT id INTO predecessor FROM deployments d WHERE d.app_id=NEW.app_id AND d.scope=NEW.scope AND d.id<>NEW.id
   AND d.status='live' AND d.traffic_percent=100 AND d.rollout_state='complete' AND d.deleted_at IS NULL
   AND (d.canary_total_steps=0 OR d.canary_step>=d.canary_total_steps);
  IF predecessor IS NOT NULL THEN
   INSERT INTO deployment_recovery_lineage(deployment_id,predecessor_deployment_id) VALUES(NEW.id,predecessor);
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: capture_environment_qualification_execution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_environment_qualification_execution() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q environment_workload_qualification_requests%ROWTYPE; b environment_qualification_restore_reservations%ROWTYPE;
BEGIN
 SELECT * INTO q FROM environment_workload_qualification_requests WHERE reserved_instance_id=NEW.id;
 IF q.id IS NULL THEN
  SELECT * INTO b FROM environment_qualification_restore_reservations WHERE instance_id=NEW.id;
  SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=b.request_id AND reserved_instance_id=b.capture_instance_id AND attempt=b.attempt;
 END IF;
 IF q.id IS NOT NULL THEN
  INSERT INTO environment_qualification_executions(instance_id,request_id,frame,cleanup_token,capture_instance_id)
   VALUES(NEW.id,q.id,environment_qualification_execution_frame(q,NEW)||CASE WHEN b.capture_instance_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('capture_instance_id',b.capture_instance_id) END,gen_random_uuid(),b.capture_instance_id);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: capture_event_execution_outcome(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_event_execution_outcome() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE finished timestamptz := clock_timestamp(); result text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.state='dispatching' AND OLD.attempts>0 THEN
   PERFORM record_event_execution_outcome(OLD.id,OLD.created_at,OLD.replay_root_invocation_id,OLD.replay_root_created_at,
    OLD.account_id,OLD.app_id,OLD.replay_generation,OLD.attempts,'attempt',finished,'unknown');
  END IF;
  RETURN OLD;
 END IF;
 IF OLD.state='dispatching' AND OLD.attempts>0 AND (NEW.state<>'dispatching' OR NEW.attempts<>OLD.attempts OR NEW.replay_generation<>OLD.replay_generation) THEN
  result := CASE WHEN NEW.replay_generation<>OLD.replay_generation THEN 'unknown'
   WHEN NEW.state='completed' THEN 'succeeded' WHEN NEW.outcome='uncertain' THEN 'unknown'
   WHEN NEW.state='pending' AND NEW.last_error='dispatch lease expired; requeued' THEN 'unknown'
   WHEN NEW.state='pending' THEN 'retry' WHEN NEW.state='failed' THEN 'failed'
   WHEN NEW.state='dead_letter' THEN 'dead_letter' WHEN NEW.state='cancelled' THEN 'cancelled' ELSE 'unknown' END;
  PERFORM record_event_execution_outcome(OLD.id,OLD.created_at,OLD.replay_root_invocation_id,OLD.replay_root_created_at,
   OLD.account_id,OLD.app_id,OLD.replay_generation,OLD.attempts,'attempt',finished,result);
 END IF;
 IF NEW.state='completed' AND NEW.completed_at IS NOT NULL THEN
  PERFORM record_event_execution_outcome(NEW.id,NEW.created_at,NEW.replay_root_invocation_id,NEW.replay_root_created_at,
   NEW.account_id,NEW.app_id,NEW.replay_generation,0,'completion',NEW.completed_at,'succeeded');
 END IF;
 RETURN NEW;
END $$;


--
-- Name: capture_event_recipient_ordering_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_event_recipient_ordering_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    snapshot jsonb;
    lane record;
BEGIN
    IF NEW.recipient_snapshot IS NULL OR jsonb_array_length(NEW.recipient_snapshot) = 0 THEN
        RETURN NEW;
    END IF;

    FOR lane IN
        SELECT DISTINCT event_order_lane_lock_id(
            item.recipient->>'app_id', item.recipient->'work'->>'policy_name', NEW.payload,
            item.recipient->'work'->>'key_selector') AS lock_id
        FROM jsonb_array_elements(NEW.recipient_snapshot) item(recipient)
        WHERE jsonb_typeof(item.recipient->'work') = 'object'
          AND item.recipient->'work'->>'policy_name' <> ''
          AND event_order_lane_active(item.recipient->>'app_id',
              item.recipient->'work'->>'policy_name',
              coalesce((item.recipient->'work'->>'ordered')::boolean, false))
          AND event_order_lane_lock_id(
            item.recipient->>'app_id', item.recipient->'work'->>'policy_name', NEW.payload,
            item.recipient->'work'->>'key_selector') IS NOT NULL
        ORDER BY lock_id
    LOOP
        PERFORM pg_advisory_xact_lock(lane.lock_id);
    END LOOP;

    SELECT coalesce(jsonb_agg(
        CASE WHEN jsonb_typeof(item.recipient->'work') = 'object'
                   AND event_order_lane_active(item.recipient->>'app_id',
                       item.recipient->'work'->>'policy_name',
                       coalesce((item.recipient->'work'->>'ordered')::boolean, false))
                   AND event_order_lane_lock_id(item.recipient->>'app_id',
                       item.recipient->'work'->>'policy_name', NEW.payload,
                       item.recipient->'work'->>'key_selector') IS NOT NULL
             THEN jsonb_set(item.recipient, '{work,routing_order}',
                       to_jsonb(nextval('event_fanout_acceptance_order_seq')::bigint), true)
             ELSE item.recipient
        END ORDER BY item.position), '[]'::jsonb)
    INTO snapshot
    FROM jsonb_array_elements(NEW.recipient_snapshot) WITH ORDINALITY AS item(recipient, position);

    UPDATE event_fanout_outbox SET recipient_snapshot = snapshot WHERE id = NEW.id;
    RETURN NEW;
END;
$$;


--
-- Name: capture_event_recovery_invocation_result(uuid, uuid, uuid, timestamp with time zone, bigint, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_event_recovery_invocation_result(p_invocation uuid, p_account uuid, p_app uuid, p_created timestamp with time zone, p_generation bigint, p_state text, p_outcome text, p_attempts integer, p_completed timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
 observed timestamptz := clock_timestamp();
 terminal text := CASE p_state WHEN 'completed' THEN 'succeeded' WHEN 'failed' THEN 'failed'
  WHEN 'dead_letter' THEN 'dead_lettered' WHEN 'expired' THEN 'expired'
  WHEN 'cancelled' THEN 'cancelled' WHEN 'superseded' THEN 'superseded' END;
BEGIN
 IF terminal IS NULL OR p_outcome='uncertain' OR p_created>observed
  OR p_completed>observed OR p_completed<p_created THEN RETURN; END IF;
 INSERT INTO event_recovery_execution_results(job_id,position,replay_invocation_id,replay_generation,replay_created_at,
  state,attempts,completed_at,recorded_at,evidence_source)
 SELECT item.job_id,item.position,p_invocation,p_generation,p_created,terminal,p_attempts,p_completed,observed,'invocation'
 FROM event_recovery_items item JOIN event_recovery_jobs job ON job.id=item.job_id
 WHERE item.state='queued' AND job.selection->>'mode'='execution' AND job.account_id=p_account AND job.app_id=p_app
  AND item.replay_invocation_id=p_invocation AND item.replay_generation=p_generation AND item.replay_created_at=p_created
 ORDER BY item.job_id,item.position
 FOR KEY SHARE OF item
 ON CONFLICT (job_id,position) DO NOTHING;
END $$;


--
-- Name: capture_event_recovery_workflow_result(uuid, uuid, text, integer, text, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_event_recovery_workflow_result(p_run uuid, p_app uuid, p_name text, p_count integer, p_status text, p_updated timestamp with time zone, p_finished timestamp with time zone, p_cancelled boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE observed timestamptz := clock_timestamp();
BEGIN
 IF p_updated>observed THEN RETURN; END IF;
 INSERT INTO event_recovery_workflow_results(job_id,position,run_id,resume_number,admitted_at,state,completed_at,recorded_at)
 SELECT item.job_id,item.position,p_run,resume.resume_number,resume.created_at,
 CASE WHEN p_count>resume.resume_number THEN 'superseded'
 WHEN p_status='succeeded' THEN 'succeeded'
 WHEN p_cancelled THEN 'cancelled' ELSE 'failed' END,
 CASE WHEN p_count>resume.resume_number THEN NULL ELSE p_finished END,observed
 FROM event_recovery_items item JOIN event_recovery_jobs job ON job.id=item.job_id
 JOIN apps app ON app.id=job.app_id AND app.account_id=job.account_id
 JOIN workflow_run_resumes resume ON resume.run_id=p_run AND resume.account_id=job.account_id
  AND resume.resume_number=(item.expected_progress->>'expected_resume_count')::integer+1
  AND resume.created_at>=job.created_at AND resume.created_at<=observed
 WHERE item.state='queued' AND job.selection->>'mode'='workflow' AND job.app_id=p_app
  AND job.selection->'workflow_runs'->>'name'=p_name
  AND (item.expected_progress->>'run_id')::uuid=p_run
  AND p_count>=resume.resume_number AND p_updated>=resume.created_at
  AND (p_count>resume.resume_number OR p_status IN ('succeeded','failed','dead'))
  AND (p_count>resume.resume_number OR p_finished IS NULL OR p_finished BETWEEN resume.created_at AND observed)
 ORDER BY item.job_id,item.position
 FOR KEY SHARE OF item
 ON CONFLICT (job_id,position) DO NOTHING;
END $$;


--
-- Name: capture_instance_billing_interval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_instance_billing_interval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  old_billable boolean := false;
  new_billable boolean;
  changed_at timestamptz := clock_timestamp();
BEGIN
  new_billable := NEW.state IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm')
                  AND COALESCE(NEW.mode, 'normal') <> 'mirror';
  IF TG_OP = 'INSERT' THEN
    old_billable := false;
  ELSE
    old_billable := OLD.state IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm')
                    AND COALESCE(OLD.mode, 'normal') <> 'mirror';
  END IF;

  IF new_billable AND NOT old_billable THEN
    INSERT INTO instance_billing_intervals (instance_id, started_at)
    VALUES (NEW.id, CASE WHEN TG_OP = 'INSERT' THEN COALESCE(NEW.started_at, changed_at) ELSE changed_at END)
    ON CONFLICT (instance_id) WHERE ended_at IS NULL DO NOTHING;
  ELSIF old_billable AND NOT new_billable THEN
    UPDATE instance_billing_intervals
       SET ended_at = changed_at
     WHERE instance_id = NEW.id AND ended_at IS NULL;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: capture_instance_capacity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_instance_capacity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p service_capacity_policy%ROWTYPE; main_cpu integer; guest_vcpu integer; side_ram bigint; side_cpu bigint;
BEGIN
    IF TG_OP='UPDATE' THEN
        NEW.capacity_ram_mb:=greatest(OLD.capacity_ram_mb,NEW.capacity_ram_mb);
        NEW.capacity_cpu_millicores:=greatest(OLD.capacity_cpu_millicores,NEW.capacity_cpu_millicores);
        NEW.capacity_vcpu:=greatest(OLD.capacity_vcpu,NEW.capacity_vcpu);
        RETURN NEW;
    END IF;
    SELECT * INTO STRICT p FROM service_capacity_policy WHERE singleton;
    SELECT greatest(a.cpu_millicores,p.startup_cpu),coalesce((p.plan_vcpus->>ac.plan)::integer,4)
      INTO main_cpu,guest_vcpu FROM apps a JOIN app_resource_accounts ac ON ac.app_id=a.id WHERE a.id=NEW.app_id;
    SELECT coalesce(sum(greatest(0,(sc->>'ram_mb')::integer)),0),
           coalesce(sum(greatest(0,coalesce(nullif(greatest(0,(sc->>'cpu_millicores')::integer),0),p.startup_cpu))),0)
      INTO side_ram,side_cpu FROM deployments d,
        LATERAL jsonb_array_elements(coalesce(d.sidecars,'[]'::jsonb)) sc WHERE d.id=NEW.deployment_id;
    NEW.capacity_ram_mb:=greatest(NEW.capacity_ram_mb,NEW.ram_mb+p.overhead_mb+side_ram);
    NEW.capacity_cpu_millicores:=greatest(NEW.capacity_cpu_millicores,coalesce(main_cpu,p.startup_cpu)+side_cpu);
    NEW.capacity_vcpu:=greatest(NEW.capacity_vcpu,coalesce(guest_vcpu,1));
    RETURN NEW;
END;
$$;


--
-- Name: capture_queue_canary_invocation_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_queue_canary_invocation_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE affected_app uuid;
BEGIN
 IF ROW(OLD.state,OLD.attempts,OLD.replay_generation,OLD.received_at,OLD.completed_at,OLD.headers,OLD.queue_binding_id,OLD.deployment_scope,OLD.deadline_at,OLD.account_id,OLD.app_id)
 IS NOT DISTINCT FROM ROW(NEW.state,NEW.attempts,NEW.replay_generation,NEW.received_at,NEW.completed_at,NEW.headers,NEW.queue_binding_id,NEW.deployment_scope,NEW.deadline_at,NEW.account_id,NEW.app_id) THEN RETURN NEW; END IF;
 SELECT app_id INTO affected_app FROM queue_binding_canaries WHERE id=NEW.id;
 IF affected_app IS NOT NULL THEN PERFORM bump_binding_promotion_revision(affected_app); END IF;
 RETURN NEW;
END $$;


--
-- Name: capture_runtime_upgrade_public_edge_withdrawals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_runtime_upgrade_public_edge_withdrawals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE added bigint;
BEGIN
 INSERT INTO runtime_upgrade_public_edge_withdrawals(id,slot_id,public_session_id,config_sha256,roster_revision)
 SELECT gen_random_uuid(),prior.slot_ids[i],prior.public_sessions[i],prior.config_sha256s[i],prior.revision
 FROM runtime_upgrade_public_edge_rosters prior, generate_subscripts(prior.public_sessions,1) i
 WHERE prior.revision=OLD.revision AND NOT EXISTS
  (SELECT 1 FROM runtime_upgrade_public_edge_rosters next WHERE next.revision=NEW.revision AND prior.public_sessions[i]=ANY(next.public_sessions))
 ON CONFLICT (public_session_id) DO NOTHING;
 GET DIAGNOSTICS added=ROW_COUNT;
 IF added > 0 AND (SELECT count(*) FROM (SELECT 1 FROM runtime_upgrade_public_edge_withdrawals w
  WHERE NOT EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_withdrawal_receipts r WHERE r.withdrawal_id=w.id)
   AND NOT EXISTS (SELECT 1 FROM runtime_upgrade_external_fence_receipts r WHERE r.withdrawal_id=w.id)
  LIMIT 65) pending) > 64 THEN
  RAISE EXCEPTION 'public edge withdrawal capacity exceeded' USING ERRCODE='23514';
 END IF;
 IF NEW.revision IS DISTINCT FROM OLD.revision THEN
  DELETE FROM runtime_upgrade_public_edge_guards;
  DELETE FROM runtime_upgrade_public_edge_activity;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: capture_service_binding_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_service_binding_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
 old_row jsonb := CASE WHEN TG_OP='INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
 new_row jsonb := CASE WHEN TG_OP='DELETE' THEN '{}'::jsonb ELSE to_jsonb(NEW) END;
 old_facts jsonb;
 new_facts jsonb;
 target uuid;
 watched text[] := string_to_array(TG_ARGV[0],',');
BEGIN
 IF TG_OP='UPDATE' THEN
  SELECT jsonb_object_agg(key,value) INTO old_facts FROM jsonb_each(old_row) WHERE key=ANY(watched);
  SELECT jsonb_object_agg(key,value) INTO new_facts FROM jsonb_each(new_row) WHERE key=ANY(watched);
  IF old_facts IS NOT DISTINCT FROM new_facts THEN RETURN NEW; END IF;
 END IF;
 FOR target IN SELECT a.id FROM apps a
  WHERE a.account_id IN (NULLIF(old_row->>'account_id','')::uuid,NULLIF(new_row->>'account_id','')::uuid)
   AND a.status<>'deleted' AND COALESCE(a.manifest->'service_bindings','[]'::jsonb)<>'[]'::jsonb
  ORDER BY a.id LOOP
  INSERT INTO app_binding_promotion_revisions(app_id,service_revision) VALUES(target,2)
  ON CONFLICT(app_id) DO UPDATE SET
   revision=app_binding_promotion_revisions.revision+1,
   service_revision=app_binding_promotion_revisions.service_revision+1;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;


--
-- Name: capture_sidecar_binding_promotion_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_sidecar_binding_promotion_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
 old_row jsonb := CASE WHEN TG_OP='INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
 new_row jsonb := CASE WHEN TG_OP='DELETE' THEN '{}'::jsonb ELSE to_jsonb(NEW) END;
 target uuid;
BEGIN
 IF TG_OP='UPDATE' AND OLD.deployment_id=NEW.deployment_id AND OLD.sidecar_name=NEW.sidecar_name AND OLD.signal=NEW.signal THEN RETURN NEW; END IF;
 FOR target IN SELECT DISTINCT app_id FROM deployments
  WHERE id IN (NULLIF(old_row->>'deployment_id','')::uuid,NULLIF(new_row->>'deployment_id','')::uuid)
  ORDER BY app_id LOOP
  PERFORM bump_binding_promotion_revision(target);
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;


--
-- Name: capture_workflow_recovery_failure(uuid, uuid, text, text, integer, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_workflow_recovery_failure(p_app uuid, p_run uuid, p_workflow text, p_status text, p_count integer, p_completed timestamp with time zone, p_cancelled boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE observed timestamptz:=clock_timestamp(); retained integer; age_seconds bigint; inserted uuid;
BEGIN
 IF p_status NOT IN ('failed','dead') OR p_cancelled OR p_completed>observed THEN RETURN; END IF;
 IF NOT EXISTS(SELECT 1 FROM apps WHERE id=p_app AND status<>'deleted') THEN RETURN; END IF;
 -- Serialize retention and first-observation capture for this app only.
 PERFORM pg_advisory_xact_lock(hashtextextended('workflow-failure-evidence:'||p_app::text,0));
 SELECT max_entries,retention_seconds INTO retained,age_seconds FROM workflow_recovery_failure_capture WHERE singleton;
 INSERT INTO workflow_recovery_failure_evidence(id,app_id,run_id,workflow,resume_count,failure_status,observed_at,completed_at)
 VALUES(gen_random_uuid(),p_app,p_run,p_workflow,p_count,p_status,observed,p_completed)
 ON CONFLICT(app_id,run_id,resume_count) DO NOTHING RETURNING id INTO inserted;
 IF inserted IS NULL THEN RETURN; END IF;
 DELETE FROM workflow_recovery_failure_evidence WHERE app_id=p_app AND observed_at<=observed-make_interval(secs=>age_seconds::double precision);
 DELETE FROM workflow_recovery_failure_evidence WHERE app_id=p_app AND sequence < (
 SELECT sequence FROM workflow_recovery_failure_evidence WHERE app_id=p_app ORDER BY sequence DESC OFFSET retained-1 LIMIT 1);
END $$;


--
-- Name: check_managed_postgres_resize_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_managed_postgres_resize_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE r managed_postgres_resizes; d managed_postgres_databases; target_spec jsonb; actual_spec jsonb;
BEGIN
 SELECT * INTO r FROM managed_postgres_resizes WHERE id=NEW.id;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO d FROM managed_postgres_databases WHERE id=r.database_id FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 target_spec := r.source_spec || jsonb_build_object('Class',r.target_class);
 IF r.target_scale_to_zero IS NOT NULL THEN
  target_spec := target_spec || jsonb_build_object('ScaleToZero',r.target_scale_to_zero);
 END IF;
 actual_spec := jsonb_build_object('Region',d.region,'PostgresMajor',d.postgres_major,'Class',d.service_class,
  'Availability',d.availability,'ScaleToZero',d.scale_to_zero,'StorageLimitBytes',d.storage_limit_bytes,'RestoreWindowSeconds',d.restore_window_seconds);
 IF r.account_id<>d.account_id OR (r.state='succeeded' AND d.observed_generation<r.generation)
  OR (r.state='succeeded' AND d.observed_generation=r.generation AND (target_spec IS DISTINCT FROM actual_spec
    OR r.backend_id<>d.backend_id OR r.backend_fingerprint<>d.backend_fingerprint
    OR r.provider_resource_id IS DISTINCT FROM d.provider_resource_id OR r.data_resource_id IS DISTINCT FROM d.data_resource_id))
  OR (r.state='pending' AND (d.state<>'updating' OR d.desired_generation<>r.generation OR d.observed_generation<>r.generation-1
    OR d.environment_clone_operation_id IS NOT NULL OR d.clone_resource_role<>'target' OR d.cutover_id IS NOT NULL
    OR r.backend_id<>d.backend_id OR r.backend_fingerprint<>d.backend_fingerprint
    OR r.provider_resource_id IS DISTINCT FROM d.provider_resource_id OR r.data_resource_id IS DISTINCT FROM d.data_resource_id
    OR r.source_spec<>jsonb_build_object('Region',d.region,'PostgresMajor',d.postgres_major,'Class',d.service_class,
      'Availability',d.availability,'ScaleToZero',d.scale_to_zero,'StorageLimitBytes',d.storage_limit_bytes,'RestoreWindowSeconds',d.restore_window_seconds))) THEN
  RAISE EXCEPTION 'resize receipt does not match database' USING ERRCODE='23514', CONSTRAINT='managed_postgres_resize_conflict';
 END IF;
 RETURN NULL;
END;
$$;


--
-- Name: check_org_credential_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_org_credential_membership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_org uuid;
    is_personal boolean;
BEGIN
    IF NEW.status = 'revoked' THEN RETURN NEW; END IF;
    IF TG_TABLE_NAME = 'deploy_tokens' THEN
        SELECT a.org_id INTO target_org FROM apps a WHERE a.id = NEW.app_id;
    ELSE
        target_org := NEW.org_id;
    END IF;
    SELECT o.personal_org INTO is_personal FROM orgs o WHERE o.id = target_org;
    IF is_personal IS FALSE THEN
        PERFORM 1 FROM org_memberships
        WHERE org_id = target_org AND account_id = NEW.account_id AND removed_at IS NULL
        FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'organization access revoked' USING ERRCODE = '42501';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: check_project_dependency_release(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_project_dependency_release() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE gate deployment_dependency_gates; pin jsonb; target_status text; target_traffic integer; parked text;
BEGIN
    IF NEW.status <> 'live' OR OLD.status = 'live' OR OLD.serving_ended_at IS NOT NULL THEN
        RETURN NEW;
    END IF;
    SELECT * INTO gate FROM deployment_dependency_gates WHERE deployment_id = NEW.id;
    IF NOT FOUND THEN RETURN NEW; END IF;
    IF gate.status = 'failed' OR (gate.status <> 'ready' AND gate.deadline_at <= clock_timestamp()) THEN
        RAISE EXCEPTION 'dependency release gate failed' USING ERRCODE = '23514', CONSTRAINT = 'deployment_dependency_not_ready';
    END IF;
    FOR pin IN SELECT value FROM jsonb_array_elements(gate.pins) ORDER BY value->>'deployment_id' LOOP
        SELECT d.status, d.traffic_percent, coalesce(d.parked_reason, '')
        INTO target_status, target_traffic, parked
        FROM deployments d JOIN apps a ON a.id = d.app_id JOIN apps owner ON owner.id = NEW.app_id
        WHERE d.id = (pin->>'deployment_id')::uuid AND d.app_id = (pin->>'app_id')::uuid
          AND a.account_id = owner.account_id AND a.project_id = owner.project_id AND a.status <> 'deleted'
          AND a.workload_class <> 'job' AND coalesce(a.manifest->>'execution_mode', '') <> 'job'
          AND coalesce(a.preview_pr_number, 0) = coalesce(owner.preview_pr_number, 0)
          AND (coalesce(a.preview_of_slug, '') = '') = (coalesce(owner.preview_of_slug, '') = '')
          AND d.scope = NEW.scope AND d.environment_workload_runtime IS NULL
        FOR SHARE OF d;
        IF NOT FOUND OR target_status <> 'live' OR target_traffic <= 0 OR parked <> '' THEN
            RAISE EXCEPTION 'dependency deployment is not ready' USING ERRCODE = '23514', CONSTRAINT = 'deployment_dependency_not_ready';
        END IF;
    END LOOP;
    RETURN NEW;
END;
$$;


--
-- Name: clone_checkpoint_deployment_fenced(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clone_checkpoint_deployment_fenced(deployment uuid, request_reason text) RETURNS boolean
    LANGUAGE sql
    AS $$
 SELECT EXISTS(SELECT 1 FROM project_environment_clone_checkpoint_workload_retirements r
 WHERE r.state IN ('requested','retired') AND
 (request_reason='environment-clone:'||r.operation_id::text OR
 r.plan @> jsonb_build_object('Workloads',jsonb_build_array(jsonb_build_object('TargetDeploymentID',deployment::text)))))
$$;


