--
-- Name: copy_object_storage_grants_on_key_rotation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_object_storage_grants_on_key_rotation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.rotated_from_id IS NOT NULL THEN
        INSERT INTO object_storage_access_grants
            (account_id, bucket_id, api_key_id, permission, created_at, updated_at)
        SELECT account_id, bucket_id, NEW.id, permission, now(), now()
          FROM object_storage_access_grants
         WHERE api_key_id = NEW.rotated_from_id
        ON CONFLICT (bucket_id, api_key_id) DO UPDATE
            SET permission = EXCLUDED.permission, updated_at = now();
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: cors_presets_changed_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cors_presets_changed_notify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_advisory_xact_lock(711901248671::bigint);

    IF TG_OP = 'DELETE' THEN
        INSERT INTO cors_preset_change_log (account_id, preset_id, operation)
        VALUES (OLD.account_id, OLD.id, 'deleted');
        PERFORM pg_notify('cors_preset_changed', OLD.account_id::text);
        RETURN OLD;
    ELSIF TG_OP = 'INSERT' THEN
        INSERT INTO cors_preset_change_log (account_id, preset_id, operation)
        VALUES (NEW.account_id, NEW.id, 'created');
        PERFORM pg_notify('cors_preset_changed', NEW.account_id::text);
        RETURN NEW;
    END IF;

    IF OLD.account_id IS DISTINCT FROM NEW.account_id THEN
        INSERT INTO cors_preset_change_log (account_id, preset_id, operation)
        VALUES (OLD.account_id, OLD.id, 'updated');
        PERFORM pg_notify('cors_preset_changed', OLD.account_id::text);
    END IF;
    INSERT INTO cors_preset_change_log (account_id, preset_id, operation)
    VALUES (NEW.account_id, NEW.id, 'updated');
    PERFORM pg_notify('cors_preset_changed', NEW.account_id::text);
    RETURN NEW;
END;
$$;


