-- Name: edge_rule_set_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edge_rule_set_snapshot(target uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.id), '[]'::jsonb)
    FROM (
        SELECT id, account_id, app_id, match_host, match_path, match_methods,
               match_headers, priority, enabled, kind, action, validate_mode,
               cors_preset_id, manifest_key, name, description, expires_at,
               created_at, match_expr, mode
        FROM edge_rules
        WHERE app_id = target
    ) r;
$$;


--
-- Name: edge_rules_mcp_access_commit_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edge_rules_mcp_access_commit_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    old_account uuid;
    new_account uuid;
    target uuid;
BEGIN
    IF TG_OP <> 'INSERT' THEN old_account := OLD.account_id; END IF;
    IF TG_OP <> 'DELETE' THEN new_account := NEW.account_id; END IF;
    FOR target IN
        SELECT DISTINCT account_id FROM unnest(ARRAY[old_account, new_account]) AS account_id
        WHERE account_id IS NOT NULL ORDER BY account_id
    LOOP
        PERFORM pg_advisory_xact_lock(hashtext('mcp_access_policy'), hashtext(target::text));
    END LOOP;
    RETURN NULL;
END;
$$;


--
-- Name: edge_rules_record_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edge_rules_record_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    owners uuid[];
BEGIN
    PERFORM pg_advisory_xact_lock(711901248671::bigint);
    IF TG_OP = 'INSERT' THEN
        owners := ARRAY[NEW.account_id];
        INSERT INTO edge_rule_change_log (app_id, rule_id, operation, match_hosts, account_ids)
        VALUES (NEW.app_id, NEW.id, 'created', ARRAY[NEW.match_host], owners);
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        owners := ARRAY[NEW.account_id];
        IF OLD.account_id IS DISTINCT FROM NEW.account_id THEN
            owners := ARRAY[OLD.account_id, NEW.account_id];
        END IF;
        INSERT INTO edge_rule_change_log (app_id, rule_id, operation, match_hosts, account_ids)
        VALUES (NEW.app_id, NEW.id, 'updated', ARRAY[OLD.match_host, NEW.match_host], owners);
        RETURN NEW;
    ELSE
        owners := ARRAY[OLD.account_id];
        INSERT INTO edge_rule_change_log (app_id, rule_id, operation, match_hosts, account_ids)
        VALUES (OLD.app_id, OLD.id, 'deleted', ARRAY[OLD.match_host], owners);
        RETURN OLD;
    END IF;
END;
$$;


--
-- Name: edge_rules_record_set_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edge_rules_record_set_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target   uuid := COALESCE(NEW.app_id, OLD.app_id);
    snapshot jsonb;
    digest   text;
    latest   record;
BEGIN
    -- Serialize version numbering per app across concurrent commits.
    PERFORM pg_advisory_xact_lock(hashtext('edge_rule_set_versions'), hashtext(target::text));
    snapshot := edge_rule_set_snapshot(target);
    digest := encode(sha256(convert_to(snapshot::text, 'UTF8')), 'hex');
    SELECT version, rules_sha256 INTO latest
    FROM edge_rule_set_versions
    WHERE app_id = target
    ORDER BY version DESC
    LIMIT 1;
    IF FOUND AND latest.rules_sha256 = digest THEN
        RETURN NULL;
    END IF;
    INSERT INTO edge_rule_set_versions (app_id, version, rules, rules_sha256, rule_count)
    VALUES (target, COALESCE(latest.version, 0) + 1, snapshot, digest, jsonb_array_length(snapshot));
    DELETE FROM edge_rule_set_versions
    WHERE app_id = target
      AND version <= COALESCE(latest.version, 0) + 1 - 100;
    RETURN NULL;
END;
$$;


