--
-- Name: enforce_app_task_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_app_task_status_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status IN ('succeeded', 'failed', 'timed_out', 'cancelled') THEN
        IF OLD.status IN ('failed', 'timed_out')
           AND NEW.status = 'queued'
           AND OLD.kind = 'cron'
           AND OLD.retry_max > 0
           AND OLD.attempt_count BETWEEN 1 AND OLD.retry_max
           AND NEW.attempt_count = OLD.attempt_count
           AND NEW.retry_max = OLD.retry_max
           AND NEW.cron_id IS NOT DISTINCT FROM OLD.cron_id
           AND NEW.scheduled_for IS NOT DISTINCT FROM OLD.scheduled_for
           AND NEW.retry_at > NEW.updated_at
           AND NEW.updated_at >= OLD.updated_at
           AND NEW.started_at IS NULL
           AND NEW.finished_at IS NULL
           AND NEW.lease_token IS NULL
           AND NEW.lease_owner IS NULL
           AND NEW.lease_expires_at IS NULL
           AND NEW.cancel_requested_at IS NULL THEN
            -- Retry is a lifecycle-only rewrite: all payload, ownership,
            -- command, and prior failure evidence must remain unchanged.
            -- Subtract only fields that are expected to change so any new
            -- app_tasks column remains immutable by default.
            IF (to_jsonb(NEW) - ARRAY['status', 'retry_at', 'started_at', 'finished_at', 'updated_at',
                                      'lease_token', 'lease_owner', 'lease_expires_at']) =
               (to_jsonb(OLD) - ARRAY['status', 'retry_at', 'started_at', 'finished_at', 'updated_at',
                                      'lease_token', 'lease_owner', 'lease_expires_at']) THEN
                RETURN NEW;
            END IF;
        END IF;
        IF NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'terminal app task % is immutable', OLD.id USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;

    IF NOT (
        (OLD.status = 'queued' AND NEW.status IN ('restoring', 'cancelled'))
        OR
        (OLD.status = 'restoring' AND NEW.status IN ('queued', 'running', 'failed',
                                                     'timed_out', 'cancelled'))
        OR
        (OLD.status = 'running' AND NEW.status IN ('succeeded', 'failed',
                                                   'timed_out', 'cancelled'))
    ) THEN
        RAISE EXCEPTION 'invalid app task % transition from % to %',
            OLD.id, OLD.status, NEW.status USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END
$$;


--
-- Name: enforce_binding_release_graph(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_binding_release_graph() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE grant_value jsonb; f jsonb;
BEGIN
 IF TG_OP='UPDATE' AND NEW.active=OLD.active THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' AND NOT NEW.active THEN RETURN NEW; END IF;
 PERFORM 1 FROM app_binding_promotion_revisions r JOIN apps a ON a.id=r.app_id
 WHERE a.project_id=NEW.project_id ORDER BY r.app_id FOR UPDATE OF r;
 IF EXISTS (SELECT 1 FROM app_binding_release_policies p JOIN apps a ON a.id=p.app_id
 WHERE a.project_id=NEW.project_id AND p.scope=NEW.environment_slug AND p.mode='enforce') THEN
  grant_value := nullif(current_setting('gregale.binding_release_graph',true),'')::jsonb;
  IF grant_value IS NULL OR grant_value->>'project_id' IS DISTINCT FROM NEW.project_id::text OR grant_value->>'environment' IS DISTINCT FROM NEW.environment_slug OR
   (TG_OP='INSERT' AND (NOT NEW.active OR grant_value->>'new_id' IS DISTINCT FROM NEW.id::text)) OR
   (TG_OP='UPDATE' AND (NEW.active OR grant_value->>'old_id' IS DISTINCT FROM NEW.id::text)) THEN
   RAISE EXCEPTION 'project graph requires checked binding evidence' USING ERRCODE='23514',CONSTRAINT='binding_release_required';
  END IF;
  FOR f IN SELECT value FROM jsonb_array_elements(grant_value->'fences') LOOP
   IF nullif(f->>'valid_until','')::timestamptz <= clock_timestamp() THEN
    RAISE EXCEPTION 'graph evidence expired' USING ERRCODE='23514',CONSTRAINT='binding_release_expired';
   END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: enforce_binding_release_traffic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_binding_release_traffic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE prior_percent integer:=0; p app_binding_release_policies%ROWTYPE; f jsonb; granted boolean:=false;
BEGIN
 IF TG_OP='UPDATE' AND OLD.status='live' AND OLD.app_id=NEW.app_id AND OLD.scope=NEW.scope THEN prior_percent:=OLD.traffic_percent; END IF;
 -- Admission with positive intended traffic is also gated, so unguarded
 -- automatic activation cannot fail only after a build has run.
 IF NEW.traffic_percent<=prior_percent OR NEW.traffic_percent=0 OR (TG_OP='UPDATE' AND NEW.status<>'live') THEN RETURN NEW; END IF;
 -- Even a missing policy must serialize with concurrent enabling.
 PERFORM 1 FROM app_binding_promotion_revisions WHERE app_id=NEW.app_id FOR UPDATE;
 SELECT * INTO p FROM app_binding_release_policies WHERE app_id=NEW.app_id AND scope=NEW.scope;
 IF p.mode IS DISTINCT FROM 'enforce' THEN RETURN NEW; END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(NULLIF(current_setting('gregale.binding_release_fences',true),''),'[]')::jsonb) LOOP
  IF f->>'deployment_id'=NEW.id::text AND f->>'app_id'=NEW.app_id::text AND f->>'scope'=NEW.scope
    AND (f->>'policy_revision')::bigint=p.revision
    AND (NULLIF(f->>'valid_until','') IS NULL OR (f->>'valid_until')::timestamptz>clock_timestamp()) THEN granted:=true; EXIT; END IF;
 END LOOP;
 IF NOT granted THEN
  RAISE EXCEPTION 'binding release requires fresh checked evidence' USING ERRCODE='23514',CONSTRAINT='binding_release_required';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: enforce_cancelled_deployment_release_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_cancelled_deployment_release_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    terminal_at timestamptz;
    cancel_detail text;
    stage_started_at timestamptz;
    duration_ms bigint;
BEGIN
    IF NEW.status = 'cancelled' THEN
        terminal_at := COALESCE(NEW.cancelled_at, now());
        cancel_detail := 'deployment cancelled: ' || COALESCE(NULLIF(NEW.cancel_reason, ''), 'system');
        NEW.cancelled_at := terminal_at;
        NEW.traffic_percent := 0;
        NEW.rollout_state := 'aborted';
        NEW.rollout_completed_at := NULL;
        NEW.rollout_aborted_at := COALESCE(NEW.rollout_aborted_at, terminal_at);
        NEW.rollout_aborted_reason := COALESCE(NULLIF(NEW.rollout_aborted_reason, ''), cancel_detail);

        IF COALESCE(NEW.stage_state->>'current', '') <> '' THEN
            stage_started_at := COALESCE(
				NULLIF(NEW.stage_state->>'current_started_at', '')::timestamptz,
                NEW.created_at,
                terminal_at
            );
            duration_ms := GREATEST(0, floor(extract(epoch FROM (terminal_at - stage_started_at)) * 1000)::bigint);
            NEW.stage_state := jsonb_set(
                jsonb_set(
                    jsonb_set(
                        NEW.stage_state,
                        '{history}',
                        COALESCE(NEW.stage_state->'history', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
                            'name', NEW.stage_state->>'current',
                            'started_at', to_jsonb(stage_started_at),
                            'ended_at', to_jsonb(terminal_at),
                            'duration_ms', duration_ms,
                            'status', 'cancelled',
                            'reason', cancel_detail
                        )),
                        true
                    ),
                    '{current}', '""'::jsonb, true
                ),
                '{current_started_at}', 'null'::jsonb, true
            );
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_event_delivery_age_ordering(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_event_delivery_age_ordering() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p jsonb;
BEGIN
 IF TG_TABLE_NAME='event_subscriptions' THEN
  IF coalesce((NEW.routing_retry_policy->>'max_delivery_age_ms')::bigint,0)>0
   AND EXISTS(SELECT 1 FROM event_subscription_work_bindings b WHERE b.subscription_id=NEW.id AND b.ordered) THEN
   RAISE EXCEPTION 'ordered event delivery cannot configure max_delivery_age' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.ordered THEN
  SELECT routing_retry_policy INTO p FROM event_subscriptions WHERE id=NEW.subscription_id FOR UPDATE;
  IF coalesce((p->>'max_delivery_age_ms')::bigint,0)>0 THEN
   RAISE EXCEPTION 'ordered event delivery cannot configure max_delivery_age' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: enforce_execution_profile_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_execution_profile_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.profile IS DISTINCT FROM OLD.profile THEN
  RAISE EXCEPTION 'execution profile is immutable' USING ERRCODE = '23514';
 END IF;
 IF TG_TABLE_NAME = 'executions' THEN
  IF NEW.runtime_image_digest IS DISTINCT FROM OLD.runtime_image_digest AND
     (OLD.status <> 'restoring' OR OLD.runtime_image_digest IS NOT NULL) THEN
   RAISE EXCEPTION 'execution image digest is immutable after selection' USING ERRCODE = '23514';
  END IF;
 END IF;
 RETURN NEW;
END
$$;


--
-- Name: enforce_execution_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_execution_status_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status IN ('succeeded', 'failed', 'timed_out', 'out_of_memory', 'cancelled') THEN
        RAISE EXCEPTION 'terminal execution % is immutable', OLD.id USING ERRCODE = '23514';
    END IF;

    IF NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;

    IF NOT (
        (OLD.status = 'queued' AND NEW.status IN ('restoring', 'timed_out', 'cancelled'))
        OR
        (OLD.status = 'restoring' AND NEW.status IN ('queued', 'running', 'failed',
                                                     'timed_out', 'out_of_memory', 'cancelled'))
        OR
        (OLD.status = 'running' AND NEW.status IN ('succeeded', 'failed',
                                                   'timed_out', 'out_of_memory', 'cancelled'))
    ) THEN
        RAISE EXCEPTION 'invalid execution % transition from % to %',
            OLD.id, OLD.status, NEW.status USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END
$$;


--
-- Name: enforce_failed_deployment_stage_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_failed_deployment_stage_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    terminal_at timestamptz;
    stage_started_at timestamptz;
    duration_ms bigint;
    failure_detail text;
BEGIN
    IF NEW.status = 'failed' AND COALESCE(NEW.stage_state->>'current', '') <> '' THEN
        terminal_at := COALESCE(NEW.rollout_aborted_at, now());
        stage_started_at := COALESCE(
            NULLIF(NEW.stage_state->>'current_started_at', '')::timestamptz,
            NEW.created_at,
            terminal_at
        );
        duration_ms := GREATEST(
            0,
            floor(extract(epoch FROM (GREATEST(stage_started_at, terminal_at) - stage_started_at)) * 1000)::bigint
        );
        failure_detail := COALESCE(
            NULLIF(NEW.error_code, ''),
            NULLIF(NEW.error, ''),
            'deployment failed'
        );
        NEW.stage_state := jsonb_set(
            jsonb_set(
                jsonb_set(
                    NEW.stage_state,
                    '{history}',
                    jsonb_path_query_array(
                        COALESCE(NEW.stage_state->'history', '[]'::jsonb),
                        '$[last - 62 to last]'
                    ) || jsonb_build_array(jsonb_build_object(
                        'name', NEW.stage_state->>'current',
                        'started_at', to_jsonb(stage_started_at),
                        'ended_at', to_jsonb(GREATEST(stage_started_at, terminal_at)),
                        'duration_ms', duration_ms,
                        'status', 'failed',
                        'reason', failure_detail
                    )),
                    true
                ),
                '{current}', '""'::jsonb, true
            ),
            '{current_started_at}', 'null'::jsonb, true
        );
    END IF;
    RETURN NEW;
END;
$_$;


--
-- Name: enforce_failed_deployment_traffic_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_failed_deployment_traffic_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'failed' THEN
        NEW.traffic_percent := 0;
        NEW.rollout_state := 'aborted';
        NEW.rollout_completed_at := NULL;
        NEW.rollout_aborted_at := COALESCE(NEW.rollout_aborted_at, now());
        NEW.rollout_aborted_reason := COALESCE(NULLIF(NEW.rollout_aborted_reason, ''), NULLIF(NEW.error, ''), 'deployment failed');
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_runtime_upgrade_pin_traffic_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_runtime_upgrade_pin_traffic_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE candidate deployments;
BEGIN
 SELECT * INTO candidate FROM deployments WHERE id=NEW.deployment_id FOR SHARE;
 IF candidate.status='live' AND candidate.traffic_percent>0 THEN
  RAISE EXCEPTION 'serving deployment cannot acquire runtime upgrade preparation'
   USING ERRCODE='23514',CONSTRAINT='runtime_upgrade_traffic_fenced';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: enforce_runtime_upgrade_traffic_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_runtime_upgrade_traffic_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.status='live' AND NEW.traffic_percent>0
  AND EXISTS(SELECT 1 FROM deployment_runtime_upgrade_targets WHERE deployment_id=NEW.id)
  AND NOT EXISTS (
   SELECT 1 FROM deployment_runtime_upgrade_cutovers c
   JOIN deployment_runtime_upgrade_acceptances a ON a.deployment_id=c.deployment_id
   JOIN deployment_runtime_upgrade_targets t ON t.deployment_id=c.deployment_id
   WHERE c.deployment_id=NEW.id AND c.target_release_id=t.release_id AND c.target_release_id=a.target_release_id
    AND c.wake_id=a.wake_id AND c.qualification_report_sha256=a.qualification_report_sha256 AND a.rootfs_key=NEW.rootfs_key
  ) THEN
  RAISE EXCEPTION 'runtime upgrade requires atomic qualified cutover' USING ERRCODE='23514',CONSTRAINT='runtime_upgrade_traffic_fenced';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: enqueue_automatic_route_check(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_automatic_route_check(p_app uuid, p_deployment uuid DEFAULT NULL::uuid, p_force boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO automatic_route_checks (deployment_id, app_id, account_id)
    SELECT d.id, a.id, a.account_id FROM deployments d
    JOIN apps a ON a.id = d.app_id
    JOIN saved_route_requirements s ON s.app_id = a.id AND s.account_id = a.account_id
    WHERE a.id = p_app AND a.status <> 'deleted'
      AND (p_deployment IS NULL OR d.id = p_deployment)
      AND (p_deployment IS NOT NULL OR EXISTS (SELECT 1 FROM deployment_openapi_docs c WHERE c.deployment_id = d.id AND c.app_id = a.id AND c.account_id = a.account_id) OR EXISTS (SELECT 1 FROM automatic_route_checks j WHERE j.deployment_id = d.id))
    ORDER BY d.id
    ON CONFLICT (deployment_id) DO UPDATE SET
        request_id = gen_random_uuid(), queued_at = now(), next_attempt_at = now(),
        attempts = 0, last_error_code = '', lease_token = NULL, lease_until = NULL, claimed_request_id = NULL
    WHERE p_force OR automatic_route_checks.completed_request_id = automatic_route_checks.request_id OR automatic_route_checks.last_error_code <> '';
END;
$$;


--
-- Name: enqueue_debug_regression_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_debug_regression_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_name text;
    event_payload jsonb;
    transition_id timestamptz;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'active' THEN
            RETURN NEW;
        END IF;
        event_name := 'debug.regression.detected';
        transition_id := NEW.first_detected_at;
    ELSIF NEW.state = 'active' AND OLD.state <> 'active' THEN
        event_name := 'debug.regression.detected';
        transition_id := NEW.first_detected_at;
    ELSIF NEW.state = 'active' AND OLD.kind = 'latency' AND NEW.kind <> 'latency' THEN
        event_name := 'debug.regression.detected';
        transition_id := NEW.first_detected_at;
    ELSIF NEW.state = 'resolved' AND OLD.state <> 'resolved' THEN
        event_name := 'debug.regression.resolved';
        transition_id := NEW.resolved_at;
    ELSE
        RETURN NEW;
    END IF;

    event_payload := jsonb_build_object(
        'app_id', NEW.app_id,
        'deployment_id', NEW.deployment_id,
        'route', NEW.route,
        'kind', NEW.kind,
        'p95_ms', NEW.p95_ms,
        'p95_base_ms', NEW.p95_base_ms,
        'affected_count', NEW.affected_count,
        'regression_factor', NEW.regression_factor,
        'error_rate_pct', NEW.error_rate_pct,
        'error_rate_base_pct', NEW.error_rate_base_pct,
        'error_count', NEW.error_count,
        'first_detected_at', NEW.first_detected_at,
        'last_detected_at', NEW.last_detected_at,
        'state', NEW.state,
        'transition_id', transition_id,
        'resolved_at', NEW.resolved_at,
        'suspected_dependency', NEW.suspected_dependency
    );

    INSERT INTO app_webhook_deliveries
        (webhook_id, app_id, account_id, event, payload)
    SELECT h.id, NEW.app_id, h.account_id, event_name, event_payload
      FROM app_webhooks h
      JOIN apps a ON a.id = NEW.app_id AND a.account_id = h.account_id
     WHERE h.scope = 'app'
       AND h.app_id = NEW.app_id
       AND h.enabled
       AND (cardinality(h.event_filter) = 0 OR event_name = ANY(h.event_filter))
    ON CONFLICT DO NOTHING;

    RETURN NEW;
END;
$$;


--
-- Name: enqueue_deployment_lifecycle_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_deployment_lifecycle_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_name text;
    event_payload jsonb;
BEGIN
    IF NEW.status = OLD.status OR NEW.status NOT IN ('live', 'failed') THEN
        RETURN NEW;
    END IF;

    event_name := 'deployment.' || NEW.status;
    event_payload := jsonb_build_object(
        'app_id', NEW.app_id,
        'deployment_id', NEW.id,
        'status', NEW.status
    );
    IF NEW.status = 'failed' THEN
        event_payload := event_payload || jsonb_strip_nulls(jsonb_build_object(
            'error_code', NEW.error_code,
            'error_hint', NEW.error_hint,
            'error_why', NEW.error_why,
            'error_fix', NEW.error_fix
        ));
    END IF;

    INSERT INTO app_webhook_deliveries
        (webhook_id, app_id, account_id, event, payload)
    SELECT h.id, NEW.app_id, h.account_id, event_name, event_payload
      FROM app_webhooks h
      JOIN apps a ON a.id = NEW.app_id AND a.account_id = h.account_id
     WHERE h.enabled
       AND ((h.scope = 'app' AND h.app_id = NEW.app_id)
            OR (h.scope = 'account' AND h.app_id IS NULL))
       AND (event_name = ANY(h.event_filter)
            OR (h.scope = 'app' AND cardinality(h.event_filter) = 0));
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_environment_git_source_poll(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_environment_git_source_poll() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO environment_git_source_polls(source_id) VALUES (NEW.id);
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_event_fanout(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_event_fanout() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE existing_type text;
DECLARE existing_data jsonb;
DECLARE existing_schema_version text;
DECLARE recipients jsonb;
DECLARE target_app uuid;
DECLARE target_tenant uuid;
BEGIN
    IF NEW.kind <> 'event.published' THEN
        RETURN NEW;
    END IF;
    IF NEW.subject IS NULL OR NEW.data->>'source' IS NULL OR
       NEW.data->>'id' IS NULL OR NEW.data->>'type' IS NULL OR
       NEW.data->'data' IS NULL THEN
        RAISE EXCEPTION 'event.published requires account, source, id, type and data'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.data ? 'platformtenantid' THEN
        BEGIN
            target_app := (NEW.data->>'appid')::uuid;
            target_tenant := (NEW.data->>'platformtenantid')::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'tenant event identity must be UUIDs' USING ERRCODE = '23514';
        END;
        recipients := coalesce((SELECT jsonb_agg(recipient ORDER BY recipient->>'id')
            FROM workflow_tenant_event_recipients(NEW.subject, target_app, target_tenant,
                NEW.data->>'source', NEW.data->>'type')), '[]'::jsonb);
    ELSE
        SELECT coalesce(jsonb_agg(jsonb_build_object(
            'id', s.id, 'account_id', s.account_id, 'app_id', s.app_id,
            'source', s.source, 'type', s.type, 'filter', s.filter,
            'routing_retry_policy', s.routing_retry_policy,
            'acknowledgment_lease_seconds', s.acknowledgment_lease_seconds,
            'schema_versions', s.schema_versions,
            'work_snapshot_captured', true,
            'work', CASE WHEN b.subscription_id IS NULL THEN NULL
                ELSE jsonb_build_object(
                    'policy_name', b.policy_name, 'key_selector', b.key_selector,
                    'fairness_selector', b.fairness_key_selector, 'action', b.action,
                    'ordered', b.ordered,
                    'policy', CASE WHEN p.name IS NULL THEN NULL
                        ELSE jsonb_build_object(
                            'revision', p.revision,
                            'max_running_per_key', p.max_running_per_key,
                            'max_running_per_fairness_key', p.max_running_per_fairness_key,
                            'pending_updates', p.pending_updates,
                            'debounce_ms', p.debounce_ms,
                            'expires_after_ms', p.expires_after_ms) END)
                END)
            ORDER BY s.created_at, s.id), '[]'::jsonb)
        INTO recipients
        FROM event_subscriptions s
        JOIN apps a ON a.id = s.app_id AND a.account_id = s.account_id
        LEFT JOIN event_subscription_work_bindings b
          ON b.subscription_id = s.id AND b.app_id = s.app_id
        LEFT JOIN app_work_policies p
          ON p.app_id = b.app_id AND p.name = b.policy_name
        WHERE s.account_id = NEW.subject AND s.enabled AND a.status <> 'deleted'
          AND event_fanout_pattern_matches(s.source, NEW.data->>'source')
          AND event_fanout_pattern_matches(s.type, NEW.data->>'type');

        recipients := recipients || coalesce((SELECT jsonb_agg(recipient ORDER BY recipient->>'id')
            FROM workflow_event_recipients(NEW.subject, NEW.data->>'source', NEW.data->>'type')), '[]'::jsonb);
    END IF;

    INSERT INTO event_fanout_outbox
        (account_id, source, event_id, event_type, schema_version, event_data, payload, recipient_snapshot)
    VALUES (NEW.subject, NEW.data->>'source', NEW.data->>'id',
            NEW.data->>'type', NEW.data->>'schemaversion', NEW.data->'data', NEW.data, recipients)
    ON CONFLICT (account_id, source, event_id) DO NOTHING;
    IF NOT FOUND THEN
        SELECT event_type, schema_version, event_data INTO existing_type, existing_schema_version, existing_data
        FROM event_fanout_outbox WHERE account_id = NEW.subject
          AND source = NEW.data->>'source' AND event_id = NEW.data->>'id';
        IF existing_type IS DISTINCT FROM NEW.data->>'type' OR
           existing_schema_version IS DISTINCT FROM NEW.data->>'schemaversion' OR
           existing_data IS DISTINCT FROM NEW.data->'data' THEN
            RAISE EXCEPTION 'event identity already has different content'
                USING ERRCODE = '23505', CONSTRAINT = 'event_fanout_identity_uniq';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_customer_lifecycle_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_customer_lifecycle_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  event_name text;
  tenant_external_ref text;
  event_payload jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.platform_tenant_id IS NULL OR NEW.status <> 'active' THEN
      RETURN NEW;
    END IF;
    event_name := 'platform_tenant.customer.linked';
  ELSIF OLD.platform_tenant_id IS NULL AND NEW.platform_tenant_id IS NOT NULL
        AND OLD.status = 'active' AND NEW.status = 'active' THEN
    event_name := 'platform_tenant.customer.linked';
  ELSIF OLD.platform_tenant_id = NEW.platform_tenant_id
        AND OLD.platform_tenant_id IS NOT NULL
        AND OLD.status = 'active' AND NEW.status = 'revoked' THEN
    event_name := 'platform_tenant.customer.offboarded';
  ELSE
    RETURN NEW;
  END IF;

  SELECT external_ref INTO tenant_external_ref
    FROM platform_tenants
   WHERE account_id = NEW.account_id AND id = NEW.platform_tenant_id;
  IF tenant_external_ref IS NULL THEN
    RETURN NEW;
  END IF;

  event_payload := jsonb_build_object(
    'platform_tenant_id', NEW.platform_tenant_id,
    'external_ref', tenant_external_ref,
    'consumer_id', NEW.id,
    'app_id', NEW.app_id,
    'customer_external_ref', NEW.external_ref,
    'customer_name', NEW.name,
    'customer_status', NEW.status,
    'changed_at', statement_timestamp()
  );

  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, h.account_id, event_name, event_payload
    FROM app_webhooks h
   WHERE h.scope = 'platform_tenant'
     AND h.platform_tenant_id = NEW.platform_tenant_id
     AND h.account_id = NEW.account_id
     AND h.enabled
     AND event_name = ANY(h.event_filter)
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_hostname_verified_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_hostname_verified_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  event_payload jsonb;
  v_tenant_id uuid;
  v_tenant_external_ref text;
  v_surface_name text;
  v_app_id uuid;
  v_account_id uuid;
BEGIN
  IF OLD.verified_at IS NOT NULL OR NEW.verified_at IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT s.platform_tenant_id, t.external_ref, s.name::text, s.app_id, s.account_id
    INTO v_tenant_id, v_tenant_external_ref, v_surface_name, v_app_id, v_account_id
    FROM tenant_surfaces s
    LEFT JOIN platform_tenants t
      ON t.account_id = s.account_id AND t.id = s.platform_tenant_id
   WHERE s.id = NEW.surface_id;

  -- Unlinked surfaces stay on their existing app-scoped integration path.
  IF v_tenant_id IS NULL OR v_tenant_external_ref IS NULL THEN
    RETURN NEW;
  END IF;

  event_payload := jsonb_build_object(
    'platform_tenant_id', v_tenant_id,
    'external_ref', v_tenant_external_ref,
    'surface_id', NEW.surface_id,
    'surface_name', v_surface_name,
    'app_id', v_app_id,
    'hostname_id', NEW.id,
    'hostname', NEW.hostname,
    'verified_at', NEW.verified_at
  );

  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, h.account_id, 'platform_tenant.hostname.verified', event_payload
    FROM app_webhooks h
   WHERE h.scope = 'platform_tenant'
     AND h.platform_tenant_id = v_tenant_id
     AND h.account_id = v_account_id
     AND h.enabled
     AND 'platform_tenant.hostname.verified' = ANY(h.event_filter)
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_reconciliation_applied_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_reconciliation_applied_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, h.account_id, 'platform_tenant.reconciliation.applied',
         jsonb_build_object(
           'platform_tenant_id', t.id,
           'external_ref', t.external_ref,
           'receipt_id', NEW.receipt_id,
           'plan_hash', NEW.plan_hash,
           'applied_at', NEW.applied_at,
           'change_count', jsonb_array_length(NEW.changes)
         )
    FROM platform_tenants t
    JOIN app_webhooks h
      ON h.account_id = t.account_id
     AND h.platform_tenant_id = t.id
     AND h.scope = 'platform_tenant'
     AND h.enabled
     AND 'platform_tenant.reconciliation.applied' = ANY(h.event_filter)
   WHERE t.account_id = NEW.account_id
     AND t.id = NEW.tenant_id
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_statement_finalized_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_statement_finalized_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  event_payload jsonb;
  tenant_external_ref text;
BEGIN
  IF OLD.status = 'finalized' OR NEW.status <> 'finalized' THEN
    RETURN NEW;
  END IF;

  SELECT external_ref INTO tenant_external_ref
    FROM platform_tenants
   WHERE account_id = NEW.account_id AND id = NEW.platform_tenant_id;

  event_payload := jsonb_build_object(
    'platform_tenant_id', NEW.platform_tenant_id,
    'external_ref', tenant_external_ref,
    'statement_id', NEW.id,
    'revision', NEW.revision,
    'status', NEW.status,
    'period_start', NEW.period_start,
    'period_end', NEW.period_end,
    'currency', NEW.currency,
    'billable_units', NEW.billable_units,
    'unpriced_units', NEW.unpriced_units,
    'amount_millicents', NEW.amount_millicents,
    'priced', NEW.unpriced_units = 0 AND NEW.currency <> '',
    'lines', NEW.lines,
    'fees', NEW.fees,
    'as_of', NEW.as_of,
    'finalized_at', NEW.finalized_at
  );

  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, NEW.account_id, 'platform_tenant.statement.finalized', event_payload
    FROM app_webhooks h
   WHERE h.scope = 'platform_tenant'
     AND h.platform_tenant_id = NEW.platform_tenant_id
     AND h.account_id = NEW.account_id
     AND h.enabled
     AND 'platform_tenant.statement.finalized' = ANY(h.event_filter)
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_surface_certificate_changed_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_surface_certificate_changed_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  event_payload jsonb;
  v_tenant_external_ref text;
BEGIN
  IF OLD.cert_state IS NOT DISTINCT FROM NEW.cert_state THEN
    RETURN NEW;
  END IF;

  IF NEW.platform_tenant_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT external_ref INTO v_tenant_external_ref
    FROM platform_tenants
   WHERE account_id = NEW.account_id AND id = NEW.platform_tenant_id;

  -- Unlinked surfaces remain on the existing app-scoped integration path.
  IF v_tenant_external_ref IS NULL THEN
    RETURN NEW;
  END IF;

  event_payload := jsonb_build_object(
    'platform_tenant_id', NEW.platform_tenant_id,
    'external_ref', v_tenant_external_ref,
    'surface_id', NEW.id,
    'surface_name', NEW.name::text,
    'app_id', NEW.app_id,
    'cert_state', NEW.cert_state,
    'cert_not_after', NEW.cert_not_after,
    'changed_at', statement_timestamp()
  );

  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, h.account_id, 'platform_tenant.surface.certificate.changed', event_payload
    FROM app_webhooks h
   WHERE h.scope = 'platform_tenant'
     AND h.platform_tenant_id = NEW.platform_tenant_id
     AND h.account_id = NEW.account_id
     AND h.enabled
     AND 'platform_tenant.surface.certificate.changed' = ANY(h.event_filter)
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_surface_deployment_changed_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_surface_deployment_changed_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status NOT IN ('live', 'failed') OR NEW.revision <= 0 THEN
    RETURN NEW;
  END IF;

  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, h.account_id, 'platform_tenant.surface.deployment.changed',
         jsonb_build_object(
           'platform_tenant_id', t.id,
           'external_ref', t.external_ref,
           'surface_id', s.id,
           'surface_name', s.name::text,
           'revision', NEW.revision,
           'deployment_status', NEW.status,
           'started_at', NEW.created_at,
           'changed_at', statement_timestamp()
         )
    FROM tenant_surfaces s
    JOIN platform_tenants t
      ON t.account_id = s.account_id AND t.id = s.platform_tenant_id
    JOIN app_webhooks h
      ON h.account_id = s.account_id
     AND h.platform_tenant_id = t.id
     AND h.scope = 'platform_tenant'
     AND h.enabled
     AND 'platform_tenant.surface.deployment.changed' = ANY(h.event_filter)
   WHERE s.app_id = NEW.app_id
     AND s.platform_tenant_id IS NOT NULL
     AND s.status <> 'deleted'
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_realtime_channel_acknowledgement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_realtime_channel_acknowledgement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE recipients uuid[]; v_app uuid; v_account uuid; event_id uuid;
BEGIN
 IF NEW.acknowledged_sequence IS NULL OR NEW.acknowledged_sequence IS NOT DISTINCT FROM OLD.acknowledged_sequence THEN RETURN NEW; END IF;
 SELECT e.app_id,e.account_id,array_agg(h.id ORDER BY h.id) INTO v_app,v_account,recipients
 FROM managed_realtime_endpoints e JOIN app_webhooks h ON h.app_id=e.app_id AND h.account_id=e.account_id
 WHERE e.id=NEW.endpoint_id AND h.scope='app' AND h.enabled
 AND 'realtime.channel.acknowledged'=ANY(h.event_filter) GROUP BY e.app_id,e.account_id;
 IF recipients IS NULL THEN RETURN NEW; END IF;
 event_id:=gen_random_uuid();
 INSERT INTO app_webhook_event_outbox(id,account_id,app_id,event,source_id,payload,recipient_webhook_ids)
 VALUES(event_id,v_account,v_app,'realtime.channel.acknowledged',event_id,
 jsonb_build_object('event_id',event_id,'app_id',v_app,'endpoint_id',NEW.endpoint_id,
 'principal',NEW.principal,'subscription',NEW.subscription,'channel',NEW.channel,
 'sequence',NEW.acknowledged_sequence::text,'occurred_at',NEW.acknowledged_at),recipients);
 RETURN NEW;
END $$;


--
-- Name: enqueue_realtime_channel_webhook(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_realtime_channel_webhook() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE recipients uuid[]; v_app uuid; v_account uuid; event_id uuid;
BEGIN
 SELECT e.app_id,e.account_id,array_agg(h.id ORDER BY h.id)
 INTO v_app,v_account,recipients
 FROM managed_realtime_endpoints e
 JOIN managed_realtime_channel_webhook_filters f ON f.endpoint_id=e.id AND f.channel=NEW.channel
 JOIN app_webhooks h ON h.id=f.webhook_id AND h.app_id=e.app_id AND h.account_id=e.account_id
 WHERE e.id=NEW.endpoint_id AND h.scope='app' AND h.enabled
 AND 'realtime.channel.published'=ANY(h.event_filter)
 AND coalesce(NEW.metadata,'{}'::jsonb) @> f.metadata
 GROUP BY e.app_id,e.account_id;
 IF recipients IS NULL THEN RETURN NEW; END IF;
 event_id:=gen_random_uuid();
 INSERT INTO app_webhook_event_outbox(id,account_id,app_id,event,source_id,payload,recipient_webhook_ids)
 VALUES(event_id,v_account,v_app,'realtime.channel.published',event_id,
 jsonb_build_object('event_id',event_id,'app_id',v_app,'endpoint_id',NEW.endpoint_id,
 'channel',NEW.channel,'sequence',NEW.sequence::text,'data_base64',replace(encode(NEW.data,'base64'),E'\n',''),
 'binary',NEW.is_binary,'metadata',NEW.metadata,'target_message_id',NEW.target_message_id,
 'version',NEW.version,'message_event',NEW.message_event,'deleted',NEW.deleted,'occurred_at',NEW.created_at),recipients);
 RETURN NEW;
END $$;


--
-- Name: enqueue_realtime_circuit_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_realtime_circuit_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE recipients uuid[]; v_app uuid; v_account uuid; event_id uuid; event_name text;
BEGIN
 IF NEW.circuit_state=OLD.circuit_state THEN RETURN NEW; END IF;
 event_name:=CASE NEW.circuit_state WHEN 'open' THEN 'realtime.consumer_group.circuit_opened' WHEN 'half_open' THEN 'realtime.consumer_group.circuit_half_open' ELSE 'realtime.consumer_group.circuit_closed' END;
 SELECT e.app_id,e.account_id,array_agg(h.id ORDER BY h.id) INTO v_app,v_account,recipients
 FROM managed_realtime_endpoints e JOIN app_webhooks h ON h.account_id=e.account_id AND h.app_id=e.app_id
 WHERE e.id=NEW.endpoint_id AND h.scope='app' AND h.enabled AND event_name=ANY(h.event_filter) GROUP BY e.app_id,e.account_id;
 IF recipients IS NULL THEN RETURN NEW; END IF;
 event_id:=gen_random_uuid();
 INSERT INTO app_webhook_event_outbox(id,account_id,app_id,event,source_id,payload,recipient_webhook_ids)
 VALUES(event_id,v_account,v_app,event_name,event_id,
 jsonb_build_object('event_id',event_id,'app_id',v_app,'endpoint_id',NEW.endpoint_id,'group_id',NEW.id,'channel',NEW.channel,'group',NEW.name,
 'state',NEW.circuit_state,'enabled',NEW.circuit_enabled,'reason',NEW.circuit_reason,'consecutive_failures',NEW.circuit_failures,'failure_threshold',NEW.circuit_threshold,'cooldown_seconds',NEW.circuit_cooldown_seconds,'next_probe_at',NEW.circuit_open_until,'occurred_at',clock_timestamp()),recipients);
 RETURN NEW;
END $$;


--
-- Name: enqueue_realtime_consumer_group_dead_letter(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_realtime_consumer_group_dead_letter() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE recipients uuid[]; v_app uuid; v_account uuid; v_endpoint uuid;
 v_channel text; v_group text; v_max_attempts integer; event_id uuid; occurred_at timestamptz;
BEGIN
 IF NEW.status <> 'dead' OR OLD.status = 'dead' THEN RETURN NEW; END IF;
 SELECT e.app_id,e.account_id,g.endpoint_id,g.channel,g.name,g.max_attempts,array_agg(h.id ORDER BY h.id)
 INTO v_app,v_account,v_endpoint,v_channel,v_group,v_max_attempts,recipients
 FROM managed_realtime_consumer_groups g
 JOIN managed_realtime_endpoints e ON e.id=g.endpoint_id
 JOIN app_webhooks h ON h.app_id=e.app_id AND h.account_id=e.account_id
 WHERE g.id=NEW.group_id AND h.scope='app' AND h.enabled
 AND 'realtime.consumer_group.dead_lettered'=ANY(h.event_filter)
 GROUP BY e.app_id,e.account_id,g.endpoint_id,g.channel,g.name,g.max_attempts;
 IF recipients IS NULL THEN RETURN NEW; END IF;
 event_id:=gen_random_uuid(); occurred_at:=clock_timestamp();
 INSERT INTO app_webhook_event_outbox(id,account_id,app_id,event,source_id,payload,recipient_webhook_ids)
 VALUES(event_id,v_account,v_app,'realtime.consumer_group.dead_lettered',event_id,
 jsonb_build_object('event_id',event_id,'app_id',v_app,'endpoint_id',v_endpoint,
 'group_id',NEW.group_id,'group',v_group,'channel',v_channel,'sequence',NEW.sequence::text,
 'attempts',NEW.attempts,'max_attempts',v_max_attempts,'failure_code',NEW.failure_code,
 'occurred_at',occurred_at),recipients);
 RETURN NEW;
END $$;


--
-- Name: enqueue_realtime_delivery_expired(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_realtime_delivery_expired() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE recipients uuid[]; v_app uuid; v_account uuid; v_endpoint uuid; v_channel text; v_group text; event_id uuid;
BEGIN
 IF NEW.status<>'dead' OR OLD.status='dead' OR NOT coalesce(NEW.deadline_invalid OR (NEW.delivery_deadline<=clock_timestamp() AND NEW.failure_code='delivery_expired'),false) THEN RETURN NEW; END IF;
 UPDATE managed_realtime_consumer_groups SET expired_deliveries=expired_deliveries+1 WHERE id=NEW.group_id;
 SELECT e.app_id,e.account_id,g.endpoint_id,g.channel,g.name,array_agg(h.id ORDER BY h.id)
 INTO v_app,v_account,v_endpoint,v_channel,v_group,recipients
 FROM managed_realtime_consumer_groups g JOIN managed_realtime_endpoints e ON e.id=g.endpoint_id
 JOIN app_webhooks h ON h.account_id=e.account_id AND h.app_id=e.app_id
 WHERE g.id=NEW.group_id AND h.scope='app' AND h.enabled AND 'realtime.consumer_group.delivery_expired'=ANY(h.event_filter)
 GROUP BY e.app_id,e.account_id,g.endpoint_id,g.channel,g.name;
 IF recipients IS NULL THEN RETURN NEW; END IF;
 event_id:=gen_random_uuid();
 INSERT INTO app_webhook_event_outbox(id,account_id,app_id,event,source_id,payload,recipient_webhook_ids)
 VALUES(event_id,v_account,v_app,'realtime.consumer_group.delivery_expired',event_id,
 jsonb_build_object('event_id',event_id,'app_id',v_app,'endpoint_id',v_endpoint,'group_id',NEW.group_id,'channel',v_channel,'group',v_group,
 'sequence',NEW.sequence::text,'attempts',NEW.attempts,'failure_code',NEW.failure_code,'delivery_deadline',NEW.delivery_deadline,'occurred_at',clock_timestamp()),recipients);
 RETURN NEW;
END $$;


--
-- Name: enqueue_realtime_replay_job_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_realtime_replay_job_notification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE recipients uuid[]; v_app uuid; v_account uuid; v_endpoint uuid;
 v_channel text; v_group text; v_slug text; event_id uuid; event_name text;
 replayed integer; inspector_path text;
 -- Keep synchronized with api.RealtimeReplayJobNotificationErrorThreshold.
 error_threshold CONSTANT integer := 3;
BEGIN
 IF NEW.state<>OLD.state AND NEW.state IN ('completed','cancelled') THEN
  event_name:='realtime.replay_job.'||NEW.state;
 ELSIF NEW.state='running' AND OLD.error_count<error_threshold AND NEW.error_count>=error_threshold THEN
  event_name:='realtime.replay_job.processing_failed';
 ELSE RETURN NEW;
 END IF;
 SELECT e.app_id,e.account_id,e.id,g.channel,g.name,p.slug,array_agg(h.id ORDER BY h.id)
 INTO v_app,v_account,v_endpoint,v_channel,v_group,v_slug,recipients
 FROM managed_realtime_consumer_groups g
 JOIN managed_realtime_endpoints e ON e.id=g.endpoint_id
 JOIN apps p ON p.id=e.app_id
 JOIN app_webhooks h ON h.app_id=e.app_id AND h.account_id=e.account_id
 WHERE g.id=NEW.group_id AND h.scope='app' AND h.enabled AND event_name=ANY(h.event_filter)
 GROUP BY e.app_id,e.account_id,e.id,g.channel,g.name,p.slug;
 IF recipients IS NULL THEN RETURN NEW; END IF;
 SELECT count(*) INTO replayed FROM jsonb_array_elements(NEW.outcomes) AS outcome WHERE outcome->>'status'='replayed';
 -- Percent-encode every UTF-8 byte in variable URL components, including reserved characters.
 inspector_path:='/dashboard/apps/'||regexp_replace(encode(convert_to(v_slug,'UTF8'),'hex'),'(..)','%\1','g')||'/realtime?endpoint_id='||v_endpoint::text||
  '&channel='||regexp_replace(encode(convert_to(v_channel,'UTF8'),'hex'),'(..)','%\1','g')||
  '&group='||regexp_replace(encode(convert_to(v_group,'UTF8'),'hex'),'(..)','%\1','g')||'#replay-job-'||NEW.id::text;
 event_id:=gen_random_uuid();
 INSERT INTO app_webhook_event_outbox(id,account_id,app_id,event,source_id,payload,recipient_webhook_ids)
 VALUES(event_id,v_account,v_app,event_name,NEW.id,
 jsonb_build_object('event_id',event_id,'app_id',v_app,'endpoint_id',v_endpoint,'group_id',NEW.group_id,
 'channel',v_channel,'group',v_group,'job_id',NEW.id,'state',NEW.state,'rate',NEW.rate,
 'selected',jsonb_array_length(NEW.selection),'processed',NEW.position,'replayed',replayed,'skipped',NEW.position-replayed,
 'remaining',jsonb_array_length(NEW.selection)-NEW.position,'error_count',NEW.error_count,
 'error_code',CASE WHEN event_name='realtime.replay_job.processing_failed' THEN 'processing_failed' ELSE '' END,
 'error_threshold',error_threshold,'inspector_path',inspector_path,'occurred_at',clock_timestamp()),recipients)
 ON CONFLICT (event,source_id) DO NOTHING;
 RETURN NEW;
END $$;


--
-- Name: enqueue_realtime_worker_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_realtime_worker_health() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE recipients uuid[]; v_app uuid; v_account uuid; v_endpoint uuid; v_channel text; v_group text; event_id uuid; event_name text;
BEGIN
 IF NEW.lost=OLD.lost THEN RETURN NEW; END IF;
 event_name:=CASE WHEN NEW.lost THEN 'realtime.consumer_group.worker_lost' ELSE 'realtime.consumer_group.worker_recovered' END;
 SELECT e.app_id,e.account_id,g.endpoint_id,g.channel,g.name,array_agg(h.id ORDER BY h.id)
 INTO v_app,v_account,v_endpoint,v_channel,v_group,recipients
 FROM managed_realtime_consumer_groups g JOIN managed_realtime_endpoints e ON e.id=g.endpoint_id
 JOIN app_webhooks h ON h.account_id=e.account_id AND h.app_id=e.app_id
 WHERE g.id=NEW.group_id AND h.scope='app' AND h.enabled AND event_name=ANY(h.event_filter)
 GROUP BY e.app_id,e.account_id,g.endpoint_id,g.channel,g.name;
 IF recipients IS NULL THEN RETURN NEW; END IF;
 event_id:=gen_random_uuid();
 INSERT INTO app_webhook_event_outbox(id,account_id,app_id,event,source_id,payload,recipient_webhook_ids)
 VALUES(event_id,v_account,v_app,event_name,event_id,
 jsonb_build_object('event_id',event_id,'app_id',v_app,'endpoint_id',v_endpoint,'group_id',NEW.group_id,'channel',v_channel,'group',v_group,
 'heartbeat_id',NEW.id,'worker',NEW.worker,'ready',NEW.ready,'status_code',NEW.status_code,'last_seen_at',NEW.last_seen_at,'occurred_at',clock_timestamp()),recipients);
 RETURN NEW;
END $$;


--
-- Name: enqueue_rollout_outcome_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_rollout_outcome_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_name text;
    event_payload jsonb;
BEGIN
    IF NEW.rollout_state IS NOT DISTINCT FROM OLD.rollout_state
       OR OLD.rollout_state NOT IN ('pending', 'rolling_out') THEN
        RETURN NEW;
    END IF;

    IF NEW.rollout_state = 'complete' AND NEW.status = 'live' THEN
        event_name := 'rollout.completed';
        event_payload := jsonb_build_object(
            'app_id', NEW.app_id,
            'deployment_id', NEW.id,
            'rollout_state', 'complete',
            'traffic_percent', NEW.traffic_percent,
            'completed_at', COALESCE(NEW.rollout_completed_at, now())
        ) || jsonb_strip_nulls(jsonb_build_object('decision',
            CASE WHEN NEW.rollout_decision->>'kind' = 'advance' THEN NEW.rollout_decision END));
    ELSIF NEW.rollout_state = 'aborted' AND OLD.status = 'live'
          AND NEW.status IN ('live', 'superseded') THEN
        event_name := 'rollout.aborted';
        event_payload := jsonb_build_object(
            'app_id', NEW.app_id,
            'deployment_id', NEW.id,
            'rollout_state', 'aborted',
            'traffic_percent', NEW.traffic_percent,
            'reason', COALESCE(NULLIF(NEW.rollout_aborted_reason, ''), 'rollout aborted'),
            'aborted_at', COALESCE(NEW.rollout_aborted_at, now())
        ) || jsonb_strip_nulls(jsonb_build_object('decision',
            CASE WHEN NEW.rollout_decision->>'kind' = 'abort' THEN NEW.rollout_decision END));
    ELSE
        RETURN NEW;
    END IF;

    INSERT INTO app_webhook_deliveries
        (webhook_id, app_id, account_id, event, payload)
    SELECT h.id, NEW.app_id, h.account_id, event_name, event_payload
      FROM app_webhooks h
      JOIN apps a ON a.id = NEW.app_id AND a.account_id = h.account_id
     WHERE h.enabled
       AND ((h.scope = 'app' AND h.app_id = NEW.app_id)
            OR (h.scope = 'account' AND h.app_id IS NULL))
       AND (event_name = ANY(h.event_filter)
            OR (h.scope = 'app' AND cardinality(h.event_filter) = 0));
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_route_insight_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_route_insight_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_name text;
    transition_id timestamptz;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'active' THEN
            RETURN NEW;
        END IF;
        event_name := 'routes.insight.detected';
        transition_id := NEW.first_detected_at;
    ELSIF NEW.state = 'active' AND OLD.state <> 'active' THEN
        event_name := 'routes.insight.detected';
        transition_id := NEW.first_detected_at;
    ELSIF NEW.state = 'resolved' AND OLD.state <> 'resolved' THEN
        event_name := 'routes.insight.resolved';
        transition_id := NEW.resolved_at;
    ELSE
        RETURN NEW;
    END IF;

    INSERT INTO app_webhook_deliveries (webhook_id, app_id, account_id, event, payload)
    SELECT h.id, NEW.app_id, h.account_id, event_name, jsonb_build_object(
               'app_id', NEW.app_id,
               'kind', NEW.kind,
               'method', NEW.method,
               'route', NEW.route,
               'message', NEW.message,
               'evidence', NEW.evidence,
               'state', NEW.state,
               'first_detected_at', NEW.first_detected_at,
               'last_detected_at', NEW.last_detected_at,
               'resolved_at', NEW.resolved_at,
               'transition_id', transition_id)
      FROM app_webhooks h
      JOIN apps a ON a.id = NEW.app_id AND a.account_id = h.account_id
     WHERE h.scope = 'app'
       AND h.app_id = NEW.app_id
       AND h.enabled
       AND (cardinality(h.event_filter) = 0 OR event_name = ANY(h.event_filter))
    ON CONFLICT DO NOTHING;
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_route_policy_checks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_route_policy_checks(p_app uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE target uuid;
BEGIN
    FOR target IN SELECT d.id FROM deployments d JOIN apps a ON a.id = d.app_id
        JOIN saved_route_requirements s ON s.app_id = a.id AND s.account_id = a.account_id
        WHERE a.id = p_app AND a.status <> 'deleted' AND d.status = 'live'
          AND (EXISTS (SELECT 1 FROM deployment_openapi_docs c WHERE c.deployment_id = d.id AND c.app_id = a.id AND c.account_id = a.account_id)
            OR EXISTS (SELECT 1 FROM automatic_route_checks j WHERE j.deployment_id = d.id))
        ORDER BY d.id
    LOOP
        PERFORM enqueue_automatic_route_check(p_app, target, true);
    END LOOP;
END;
$$;


--
-- Name: environment_binding_artifact_inputs(public.deployments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_binding_artifact_inputs(d public.deployments) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT jsonb_build_object('rootfs_key',coalesce(d.rootfs_key,''),'rootfs_bytes',coalesce(d.rootfs_bytes,0),
 'kind',d.kind,'image_digest',coalesce(d.image_digest,''),'build_id',coalesce(d.build_id::text,''),
 'source_path',coalesce(d.source_path,''),'source_sha256',coalesce(d.source_sha256,''),'source_bytes',coalesce(d.source_bytes,0),
 'source_root',coalesce(d.source_root,''),'log_path',coalesce(d.log_path,''),'source_url',coalesce(d.source_url,''),
 'commit_sha',coalesce(d.commit_sha,''),'handler',coalesce(d.handler,''),'deployment_inputs',environment_workload_deployment_inputs(d));
$$;


--
-- Name: environment_binding_catalog_supported(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_binding_catalog_supported(target_app uuid, target_scope text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT NOT EXISTS(SELECT 1 FROM managed_postgres_bindings WHERE app_id=target_app AND scope=target_scope AND state<>'deleted')
 AND NOT EXISTS(SELECT 1 FROM object_storage_s3_credentials WHERE managed_app_id=target_app AND managed_scope=target_scope AND status='active')
 AND NOT EXISTS(SELECT 1 FROM outbound_app_bindings WHERE app_id=target_app)
 AND NOT EXISTS(SELECT 1 FROM outbound_integration_apps WHERE app_id=target_app);
$$;


--
-- Name: environment_binding_qualification_deadline(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_binding_qualification_deadline(target_graph uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    AS $$
DECLARE g environment_workload_graphs%ROWTYPE; s environment_git_sources%ROWTYPE; e project_environments%ROWTYPE;
 q environment_workload_qualification_requests%ROWTYPE; p app_binding_release_policies%ROWTYPE;
 smoke environment_qualification_smoke_receipts%ROWTYPE; edge record; target environment_workload_qualification_requests%ROWTYPE;
 receipt environment_qualification_service_receipts%ROWTYPE; until_at timestamptz; deadline timestamptz; count_members integer:=0;
BEGIN
 SELECT * INTO g FROM environment_workload_graphs WHERE id=target_graph;
 SELECT * INTO s FROM active_environment_git_sources WHERE id=g.source_id;
 SELECT * INTO e FROM project_environments WHERE id=g.environment_id;
 IF g.id IS NULL OR s.id IS NULL OR s.mode<>'enforce' OR s.suspended OR g.generation<>s.generation OR
 g.intent_version<>s.intent_version OR g.revision_id<>s.approved_revision_id OR g.phase<>'prepared' THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(g.members) m WHERE coalesce(m->>'candidate_deployment_id','')='') THEN RETURN NULL; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(g.members))<>(SELECT count(*) FROM environment_workload_qualification_requests WHERE graph_id=g.id) THEN RETURN NULL; END IF;
 FOR q IN SELECT * FROM environment_workload_qualification_requests WHERE graph_id=g.id ORDER BY app_id LOOP
  count_members:=count_members+1;
  SELECT * INTO p FROM app_binding_release_policies WHERE app_id=q.app_id AND scope=e.slug;
  SELECT * INTO smoke FROM environment_qualification_smoke_receipts WHERE request_id=q.id AND attempt=q.attempt;
  IF q.binding_context IS NULL OR p.app_id IS NULL OR p.mode<>'enforce' OR p.require_application_ack OR p.object_storage_requirements<>'{}'::jsonb OR
   q.binding_context->'policy'->>'revision' IS DISTINCT FROM p.revision::text OR q.binding_context->'policy'->>'mode' IS DISTINCT FROM p.mode OR
   q.binding_context->'policy'->>'scope' IS DISTINCT FROM e.slug OR q.binding_context->'policy'->>'app_id' IS DISTINCT FROM q.app_id::text OR
   coalesce(q.binding_context->'policy'->'queue_requirements','{}'::jsonb) IS DISTINCT FROM p.queue_requirements OR
   coalesce(q.binding_context->'policy'->'object_storage_requirements','{}'::jsonb) IS DISTINCT FROM p.object_storage_requirements OR
   NOT environment_binding_catalog_supported(q.app_id,e.slug) OR NOT environment_workload_qualification_evidence_current(q.id) OR
   q.binding_context->'artifact_inputs' IS DISTINCT FROM (SELECT environment_binding_artifact_inputs(d) FROM deployments d WHERE d.id=q.deployment_id) OR
   q.binding_context->>'service_revision' IS DISTINCT FROM (SELECT epoch::text||':'||service_revision::text FROM app_binding_promotion_revisions WHERE app_id=q.app_id) OR
   EXISTS(SELECT 1 FROM queue_bindings b WHERE b.app_id=q.app_id AND coalesce(nullif(b.deployment_scope,''),'default') IN (e.slug,'default') AND b.retired_at IS NULL AND NOT EXISTS(SELECT 1 FROM jsonb_each(coalesce(q.frozen_inputs->'queue_bindings','{}'::jsonb)) f WHERE f.value->>'binding_id'=b.id::text)) OR
   q.execution_mode NOT IN ('request','service','worker') OR q.frozen_inputs->>'workload_class' NOT IN ('http','worker') OR
   smoke.request_id IS NULL OR smoke.recorded_at>clock_timestamp() OR q.lease_until IS NULL THEN RETURN NULL; END IF;
  IF NOT EXISTS(SELECT 1 FROM environment_qualification_snapshot_receipts capture
   JOIN environment_qualification_executions original ON original.instance_id=capture.instance_id
   JOIN environment_qualification_restore_receipts restored ON restored.request_id=q.id AND restored.attempt=q.attempt AND restored.capture_instance_id=capture.instance_id
   JOIN environment_qualification_executions runtime ON runtime.instance_id=restored.instance_id
   JOIN environment_qualification_framework_ready_receipts ready ON ready.request_id=q.id AND ready.attempt=q.attempt AND ready.instance_id=restored.instance_id
   JOIN environment_qualification_config_receipts source_config ON source_config.instance_id=capture.instance_id
   JOIN environment_qualification_config_receipts restore_config ON restore_config.instance_id=restored.instance_id
   WHERE capture.instance_id=q.reserved_instance_id AND restored.instance_id=smoke.instance_id AND smoke.graph_id=g.id AND smoke.capture_instance_id=q.reserved_instance_id
    AND original.dispatch_started AND runtime.dispatch_started AND original.retired_at IS NOT NULL AND runtime.retired_at IS NOT NULL
    AND original.retirement->>'kind'='native_retired' AND runtime.retirement->>'kind'='native_retired'
    AND environment_runtime_inputs_fresh(q.app_id,e.slug,(capture.inputs->>'boundary')::timestamptz,capture.inputs->'variables',capture.inputs->'secret_versions',(capture.inputs->>'all_secrets')::boolean,capture.inputs->'secret_refs',coalesce(capture.inputs->'sidecar_secret_versions','{}'::jsonb))
    AND environment_runtime_inputs_fresh(q.app_id,e.slug,(restored.runtime_inputs->>'boundary')::timestamptz,restored.runtime_inputs->'variables',restored.runtime_inputs->'secret_versions',(restored.runtime_inputs->>'all_secrets')::boolean,restored.runtime_inputs->'secret_refs',coalesce(restored.runtime_inputs->'sidecar_secret_versions','{}'::jsonb))) THEN RETURN NULL; END IF;
  IF coalesce(q.frozen_inputs->'service_bindings','{}'::jsonb)<>'{}'::jsonb AND
   coalesce(nullif(q.frozen_inputs->'runtime'->>'service_binding_transport',''),q.frozen_inputs->'baseline'->>'service_binding_transport','http')<>'https' THEN RETURN NULL; END IF;
  IF (SELECT count(*) FROM jsonb_each(coalesce(q.frozen_inputs->'queue_bindings','{}'::jsonb)))<>(SELECT count(*) FROM jsonb_each(p.queue_requirements)) OR
   EXISTS(SELECT 1 FROM jsonb_each(coalesce(q.frozen_inputs->'queue_bindings','{}'::jsonb)) b
    WHERE q.execution_mode<>'worker' OR b.value->'contract'->>'mode'<>'push' OR b.value->'contract'->>'enabled' IS DISTINCT FROM 'true' OR
     p.queue_requirements->>b.key IS DISTINCT FROM 'handler_completion' OR NOT coalesce(q.frozen_inputs->'queue_smoke','{}'::jsonb) ? b.key) THEN RETURN NULL; END IF;
  deadline:=least(q.lease_until,smoke.recorded_at+p.max_age_seconds*interval '1 second');
  FOR edge IN SELECT key,value FROM jsonb_each(coalesce(q.frozen_inputs->'service_bindings','{}'::jsonb)) LOOP
   SELECT * INTO target FROM environment_workload_qualification_requests WHERE graph_id=g.id AND app_id=(edge.value->>'target_app_id')::uuid;
   SELECT * INTO receipt FROM environment_qualification_service_receipts WHERE request_id=q.id AND attempt=q.attempt AND binding=edge.key;
   IF target.id IS NULL OR receipt.request_id IS NULL OR receipt.recorded_at>smoke.recorded_at OR receipt.route->>'RequireHTTPS' IS DISTINCT FROM 'true' OR
    receipt.route->'Caller'->>'request_id' IS DISTINCT FROM q.id::text OR receipt.route->'Caller'->>'attempt' IS DISTINCT FROM q.attempt::text OR
    receipt.route->'Caller'->>'instance_id' IS DISTINCT FROM smoke.instance_id::text OR receipt.route->'Caller'->>'capture_instance_id' IS DISTINCT FROM q.reserved_instance_id::text OR
    receipt.route->'Target'->>'request_id' IS DISTINCT FROM target.id::text OR receipt.route->'Target'->>'attempt' IS DISTINCT FROM target.attempt::text OR
    receipt.route->'Target'->>'capture_instance_id' IS DISTINCT FROM target.reserved_instance_id::text OR
    receipt.route->'Target'->>'deployment_id' IS DISTINCT FROM target.deployment_id::text OR
    receipt.route->'Target'->>'instance_id' IS DISTINCT FROM (SELECT instance_id::text FROM environment_qualification_restore_receipts WHERE request_id=target.id AND attempt=target.attempt)
    THEN RETURN NULL; END IF;
   deadline:=least(deadline,(receipt.route->>'Deadline')::timestamptz,receipt.recorded_at+p.max_age_seconds*interval '1 second');
  END LOOP;
  until_at:=least(until_at,deadline);
 END LOOP;
 IF count_members=0 OR until_at<=clock_timestamp() THEN RETURN NULL; END IF;
 RETURN until_at;
END $$;


--
-- Name: environment_binding_retirement_receipts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.environment_binding_retirement_receipts (
    release_id uuid NOT NULL,
    source_id uuid NOT NULL,
    revision_id uuid NOT NULL,
    generation bigint NOT NULL,
    intent_version bigint NOT NULL,
    plan_hash text NOT NULL,
    prior_release text NOT NULL,
    retirement_ids uuid[] NOT NULL,
    policies jsonb NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT environment_binding_retirement_receipts_generation_check CHECK ((generation > 0)),
    CONSTRAINT environment_binding_retirement_receipts_intent_version_check CHECK ((intent_version > 0)),
    CONSTRAINT environment_binding_retirement_receipts_plan_hash_check CHECK ((plan_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT environment_binding_retirement_receipts_policies_check CHECK ((jsonb_typeof(policies) = 'object'::text)),
    CONSTRAINT environment_binding_retirement_receipts_prior_release_check CHECK (((prior_release = ''::text) OR (prior_release ~ '^[a-f0-9-]{36}$'::text))),
    CONSTRAINT environment_binding_retirement_receipts_retirement_ids_check CHECK (((cardinality(retirement_ids) > 0) AND (array_position(retirement_ids, NULL::uuid) IS NULL)))
);


--
-- Name: environment_binding_retirement_current(public.environment_binding_retirement_receipts); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_binding_retirement_current(audit public.environment_binding_retirement_receipts) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE s environment_git_sources%ROWTYPE; rev environment_desired_revisions%ROWTYPE; release_scope text;
 r environment_workload_retirements%ROWTYPE; ids uuid[]; policy_map jsonb;
BEGIN
 SELECT * INTO s FROM active_environment_git_sources WHERE id=audit.source_id;
 SELECT * INTO rev FROM environment_desired_revisions WHERE id=s.approved_revision_id AND source_id=s.id;
 SELECT slug INTO release_scope FROM project_environments WHERE id=s.environment_id;
 IF s.id IS NULL OR s.mode<>'enforce' OR s.suspended OR NOT s.prune OR rev.id IS DISTINCT FROM audit.revision_id OR
  s.generation<>audit.generation OR s.intent_version<>audit.intent_version OR audit.valid_until<=clock_timestamp() OR
  rev.definition->'workloads' IS DISTINCT FROM '{}'::jsonb OR rev.definition->>'workload_pruning_policy' IS DISTINCT FROM 'retain' OR
  NOT EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=s.id AND j.desired_generation=s.generation
   AND j.claimed_generation=s.generation AND j.lease_token=current_setting('gregale.gitops_lease',true) AND j.lease_until>clock_timestamp()) THEN RETURN false; END IF;
 SELECT array_agg(id ORDER BY id),jsonb_object_agg(id::text,binding_policy_context) INTO ids,policy_map
 FROM environment_workload_retirements WHERE source_id=s.id AND revision_id=rev.id AND generation=s.generation AND phase='retiring';
 IF ids IS DISTINCT FROM audit.retirement_ids OR policy_map IS DISTINCT FROM audit.policies THEN RETURN false; END IF;
 FOR r IN SELECT * FROM environment_workload_retirements WHERE id=ANY(audit.retirement_ids) LOOP
  IF r.binding_policy_context IS DISTINCT FROM environment_binding_retirement_policy(r.app_id,release_scope) OR
   ROW(r.account_id,r.project_id,r.environment_id) IS DISTINCT FROM ROW(s.account_id,s.project_id,s.environment_id) OR
   NOT EXISTS(SELECT 1 FROM environment_gitops_resources WHERE source_id=s.id AND logical_name=r.resource AND app_id=r.app_id) OR
   NOT EXISTS(SELECT 1 FROM environment_managed_fields WHERE source_id=s.id AND manager_id=s.id::text AND resource=r.resource AND field_path='presence') OR
   EXISTS(SELECT 1 FROM environment_managed_fields WHERE environment_id=s.environment_id AND resource=r.resource AND manager_id<>s.id::text) OR
   EXISTS(SELECT 1 FROM environment_external_field_owners WHERE environment_id=s.environment_id AND resource IN (r.resource,'app/'||r.app_id::text)) OR
   EXISTS(SELECT 1 FROM environment_management_overrides WHERE environment_id=s.environment_id AND resource=r.resource AND expires_at>clock_timestamp()) OR
   r.deployment_ids IS DISTINCT FROM ARRAY(SELECT id FROM deployments WHERE app_id=r.app_id AND scope=release_scope AND environment_workload_runtime->>'source_id'=s.id::text ORDER BY id) OR
   r.queue_binding_ids IS DISTINCT FROM ARRAY(SELECT binding_id FROM environment_gitops_queue_bindings WHERE source_id=s.id AND resource=r.resource AND binding_id IS NOT NULL ORDER BY binding_id) OR
   r.job_id IS DISTINCT FROM (SELECT job_id FROM app_environment_workload_intents WHERE app_id=r.app_id AND environment_id=s.environment_id) OR
   EXISTS(SELECT 1 FROM deployments WHERE app_id=r.app_id AND scope=release_scope AND status='live' AND (environment_workload_runtime->>'source_id' IS DISTINCT FROM s.id::text OR traffic_percent<>0)) OR
   EXISTS(SELECT 1 FROM queue_bindings WHERE app_id=r.app_id AND environment_id=s.environment_id AND NOT(id=ANY(r.queue_binding_ids))) THEN RETURN false; END IF;
 END LOOP;
 -- Complete removal only. Any surviving caller or recipient needs a separately
 -- qualified replacement graph; this path cannot retain or redistribute traffic.
 IF EXISTS(SELECT 1 FROM apps a WHERE a.project_id=s.project_id AND a.account_id=s.account_id AND a.status<>'deleted' AND coalesce(a.preview_of_slug,'')=''
  AND NOT EXISTS(SELECT 1 FROM environment_workload_retirements owned WHERE owned.source_id=s.id AND owned.app_id=a.id AND owned.environment_id=s.environment_id
   AND (owned.id=ANY(audit.retirement_ids) AND owned.phase='retiring' OR owned.phase='retired'))) THEN RETURN false; END IF;
 RETURN true;
END $$;


--
-- Name: environment_binding_retirement_policy(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_binding_retirement_policy(target_app uuid, target_scope text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 SELECT coalesce((SELECT jsonb_build_object('revision',revision,'mode',mode)
  FROM app_binding_release_policies WHERE app_id=target_app AND scope=target_scope),jsonb_build_object('revision',0,'mode','off'));
$$;


--
-- Name: environment_gitops_guard_app_presence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_guard_app_presence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE src environment_git_sources%ROWTYPE;
BEGIN
    IF pg_trigger_depth() > 1 THEN
        IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.status = 'deleted') = (OLD.status = 'deleted') THEN RETURN NEW; END IF;
    FOR src IN SELECT s.* FROM active_environment_git_sources s
        JOIN environment_gitops_resources r ON r.source_id = s.id
        WHERE r.app_id = OLD.id ORDER BY s.id FOR UPDATE OF s
    LOOP
        IF (TG_OP = 'DELETE' OR NEW.status = 'deleted') AND src.mode = 'enforce' AND EXISTS (
            SELECT 1 FROM environment_managed_fields f JOIN environment_gitops_resources r
            ON r.source_id = f.source_id AND r.logical_name = f.resource
            WHERE f.source_id = src.id AND r.app_id = OLD.id AND f.field_path = 'presence'
              AND NOT EXISTS (SELECT 1 FROM environment_management_overrides o
                  WHERE o.environment_id = f.environment_id AND o.resource = f.resource AND o.field_path = 'presence'
                    AND o.expires_at > clock_timestamp())) THEN
            RAISE EXCEPTION 'workload membership is managed by the environment Git source'
                USING ERRCODE = '23514', CONSTRAINT = 'environment_gitops_field_owned';
        END IF;
        UPDATE environment_git_sources SET intent_version = intent_version + 1, updated_at = now() WHERE id = src.id;
        IF src.generation > 0 THEN
            INSERT INTO environment_gitops_jobs(source_id, desired_generation, next_attempt_at)
            VALUES (src.id, src.generation, now()) ON CONFLICT (source_id) DO UPDATE
            SET next_attempt_at = least(environment_gitops_jobs.next_attempt_at, excluded.next_attempt_at);
        END IF;
    END LOOP;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


--
-- Name: environment_gitops_guard_config_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_guard_config_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF pg_trigger_depth() <= 1 AND EXISTS (
        SELECT 1 FROM active_environment_git_sources s JOIN project_environments e ON e.id = s.environment_id
        WHERE s.project_id = OLD.project_id AND s.account_id = OLD.account_id AND e.slug = OLD.environment_slug) THEN
        RAISE EXCEPTION 'managed configuration history is append-only'
            USING ERRCODE = '23514', CONSTRAINT = 'environment_gitops_field_owned';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


--
-- Name: environment_gitops_guard_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_guard_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (to_jsonb(NEW) - ARRAY['value', 'updated_at', 'only_allow_declared_routes', 'declared_routes', 'rules'])
       IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['value', 'updated_at', 'only_allow_declared_routes', 'declared_routes', 'rules'])
       AND EXISTS (SELECT 1 FROM environment_gitops_resources r JOIN active_environment_git_sources s ON s.id = r.source_id
           JOIN project_environments e ON e.id = s.environment_id
           WHERE r.app_id = OLD.app_id AND s.account_id = OLD.account_id
           AND e.slug = coalesce(to_jsonb(OLD)->>'scope', to_jsonb(OLD)->>'environment_slug')) THEN
        RAISE EXCEPTION 'environment resource identity cannot be moved'
            USING ERRCODE = '23514', CONSTRAINT = 'environment_gitops_field_owned';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: environment_gitops_guard_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_guard_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    row_value jsonb;
    src environment_git_sources%ROWTYPE;
    resource_name text;
    paths text[];
    prior_config jsonb;
    controller boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN row_value := to_jsonb(OLD); ELSE row_value := to_jsonb(NEW); END IF;
    IF TG_TABLE_NAME = 'project_environment_config_versions' THEN
        SELECT s.* INTO src FROM active_environment_git_sources s JOIN project_environments e ON e.id = s.environment_id
        WHERE s.account_id = (row_value->>'account_id')::uuid AND s.project_id = (row_value->>'project_id')::uuid
          AND e.slug = row_value->>'environment_slug' FOR UPDATE OF s;
        resource_name := 'environment';
        SELECT config_json INTO prior_config FROM project_environment_config_versions
        WHERE project_id = (row_value->>'project_id')::uuid AND environment_slug = row_value->>'environment_slug'
        ORDER BY version DESC LIMIT 1;
        SELECT array_agg('configuration/' || k) INTO paths FROM (
            SELECT key AS k FROM jsonb_each(coalesce(prior_config, '{}'))
            UNION SELECT key FROM jsonb_each(coalesce(row_value->'config_json', '{}'))
        ) keys WHERE (prior_config->k) IS DISTINCT FROM (row_value->'config_json'->k);
    ELSE
        SELECT s.* INTO src
        FROM active_environment_git_sources s JOIN project_environments e ON e.id = s.environment_id
        JOIN environment_gitops_resources r ON r.source_id = s.id
        WHERE s.account_id = (row_value->>'account_id')::uuid AND r.app_id = (row_value->>'app_id')::uuid
          AND e.slug = coalesce(row_value->>'scope', row_value->>'environment_slug') FOR UPDATE OF s;
        SELECT logical_name INTO resource_name FROM environment_gitops_resources
        WHERE source_id = src.id AND app_id = (row_value->>'app_id')::uuid;
        IF TG_TABLE_NAME = 'app_envs' THEN paths := ARRAY['variables/' || (row_value->>'key')];
        ELSIF TG_TABLE_NAME = 'project_environment_route_policies' THEN paths := ARRAY['routes'];
        ELSE paths := ARRAY['policies']; END IF;
    END IF;
    IF src.id IS NOT NULL THEN
        controller := EXISTS (SELECT 1 FROM environment_gitops_jobs j
            WHERE j.source_id = src.id AND j.desired_generation = src.generation AND j.claimed_generation = src.generation
              AND j.lease_until > clock_timestamp() AND j.lease_token <> ''
              AND j.lease_token = current_setting('gregale.gitops_lease', true)
              AND src.approved_revision_id IS NOT NULL AND NOT src.suspended);
        IF src.mode = 'enforce' AND NOT controller AND EXISTS (
            SELECT 1 FROM environment_managed_fields f
            WHERE f.environment_id = src.environment_id AND f.resource = resource_name AND f.field_path = ANY(paths)
              AND f.source_id = src.id AND NOT EXISTS (
                  SELECT 1 FROM environment_management_overrides o
                  WHERE o.environment_id = f.environment_id AND o.resource = f.resource AND o.field_path = f.field_path
                    AND o.expires_at > clock_timestamp())) THEN
            RAISE EXCEPTION 'setting is managed by the environment Git source'
                USING ERRCODE = '23514', CONSTRAINT = 'environment_gitops_field_owned';
        END IF;
        UPDATE environment_git_sources SET intent_version = intent_version + 1, updated_at = now() WHERE id = src.id;
        IF src.generation > 0 THEN
            INSERT INTO environment_gitops_jobs(source_id, desired_generation, next_attempt_at)
            VALUES (src.id, src.generation, now()) ON CONFLICT (source_id) DO UPDATE
            SET next_attempt_at = least(environment_gitops_jobs.next_attempt_at, excluded.next_attempt_at);
        END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


--
-- Name: environment_gitops_queue_recovery_authorized(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_queue_recovery_authorized(target_binding uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE src environment_git_sources%ROWTYPE;
BEGIN
 -- Legacy SQL writers may acquire the binding first. Serialize authority on
 -- the source too; a deadlock aborts the whole transaction rather than granting
 -- a stale approved generation permission to release retained work.
 SELECT s.* INTO src FROM active_environment_git_sources s JOIN queue_bindings b ON b.environment_id=s.environment_id
  JOIN apps a ON a.id=b.app_id AND a.account_id=s.account_id AND a.project_id=s.project_id
  WHERE b.id=target_binding AND b.account_id=s.account_id FOR UPDATE OF s;
 IF src.id IS NULL OR src.mode<>'enforce' OR src.suspended THEN RETURN false; END IF;
 RETURN environment_gitops_queue_recovery_declared(src.id,target_binding) AND EXISTS(
  SELECT 1 FROM environment_gitops_jobs j
   JOIN environment_gitops_queue_bindings q ON q.source_id=j.source_id AND q.binding_id=target_binding
   JOIN environment_managed_fields f ON f.source_id=q.source_id AND f.resource=q.resource AND f.field_path=q.field_path
  WHERE j.source_id=src.id AND j.desired_generation=src.generation AND j.claimed_generation=src.generation
   AND j.lease_until>clock_timestamp() AND j.lease_token<>'' AND j.lease_token=current_setting('gregale.gitops_lease',true)
   AND NOT EXISTS(SELECT 1 FROM environment_management_overrides o WHERE o.environment_id=src.environment_id
    AND o.resource=f.resource AND o.field_path=f.field_path AND o.expires_at>clock_timestamp()));
END;
$$;


--
-- Name: environment_gitops_queue_recovery_declared(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_queue_recovery_declared(target_source uuid, target_binding uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM active_environment_git_sources s
  JOIN environment_desired_revisions v ON v.id=s.approved_revision_id AND v.source_id=s.id
  JOIN environment_gitops_resources r ON r.source_id=s.id
  JOIN queue_bindings b ON b.id=target_binding AND b.app_id=r.app_id AND b.account_id=s.account_id AND b.environment_id=s.environment_id
  JOIN project_environments e ON e.id=s.environment_id AND e.account_id=s.account_id AND e.project_id=s.project_id
  WHERE s.id=target_source AND r.logical_name LIKE 'workload/%'
   AND v.definition->'workloads'->substr(r.logical_name,10)->'queue_recoveries'->>b.name=b.id::text
   AND v.definition->'workloads'->substr(r.logical_name,10)->'queue_bindings' ? b.name);
$$;


--
-- Name: environment_workload_qualification_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.environment_workload_qualification_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    graph_id uuid NOT NULL,
    deployment_id uuid NOT NULL,
    app_id uuid NOT NULL,
    resource text NOT NULL,
    artifact jsonb NOT NULL,
    frozen_inputs jsonb NOT NULL,
    execution_mode text NOT NULL,
    phase text DEFAULT 'queued'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    worker_id text DEFAULT ''::text NOT NULL,
    lease_token text DEFAULT ''::text NOT NULL,
    lease_until timestamp with time zone,
    attempt bigint DEFAULT 0 NOT NULL,
    reserved_instance_id uuid,
    binding_context jsonb,
    CONSTRAINT environment_workload_qualification_reques_binding_context_check CHECK (((binding_context IS NULL) OR (((jsonb_typeof(binding_context) = 'object'::text) AND (jsonb_typeof((binding_context -> 'policy'::text)) = 'object'::text) AND (jsonb_typeof((binding_context -> 'artifact_inputs'::text)) = 'object'::text) AND ((binding_context ->> 'artifact_revision'::text) ~ '^[a-f0-9]{64}$'::text) AND (length((binding_context ->> 'service_revision'::text)) > 0)) IS TRUE))),
    CONSTRAINT environment_workload_qualification_request_execution_mode_check CHECK ((execution_mode = ANY (ARRAY['request'::text, 'service'::text, 'worker'::text, 'job'::text]))),
    CONSTRAINT environment_workload_qualification_requests_artifact_check CHECK ((jsonb_typeof(artifact) = 'object'::text)),
    CONSTRAINT environment_workload_qualification_requests_attempt_check CHECK ((attempt >= 0)),
    CONSTRAINT environment_workload_qualification_requests_check CHECK ((((phase = 'queued'::text) AND (worker_id = ''::text) AND (lease_token = ''::text) AND (lease_until IS NULL) AND (attempt = 0)) OR ((phase = 'claimed'::text) AND (worker_id <> ''::text) AND (lease_token <> ''::text) AND (lease_until IS NOT NULL) AND (attempt > 0)))),
    CONSTRAINT environment_workload_qualification_requests_frozen_inputs_check CHECK ((jsonb_typeof(frozen_inputs) = 'object'::text)),
    CONSTRAINT environment_workload_qualification_requests_phase_check CHECK ((phase = ANY (ARRAY['queued'::text, 'claimed'::text]))),
    CONSTRAINT environment_workload_qualification_requests_resource_check CHECK ((resource ~ '^workload/[a-z0-9][a-z0-9-]*$'::text)),
    CONSTRAINT environment_workload_qualification_requests_worker_id_check CHECK ((octet_length(worker_id) <= 256)),
    CONSTRAINT environment_workload_qualification_reserved_instance_shape CHECK ((((phase = 'queued'::text) AND (reserved_instance_id IS NULL)) OR ((phase = 'claimed'::text) AND (((execution_mode = 'job'::text) AND (reserved_instance_id IS NULL)) OR ((execution_mode <> 'job'::text) AND (reserved_instance_id IS NOT NULL))))))
);


--
-- Name: environment_qualification_execution_frame(public.environment_workload_qualification_requests, public.instances); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_qualification_execution_frame(q public.environment_workload_qualification_requests, i public.instances) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT jsonb_build_object('instance_id',i.id,'request_id',q.id,'graph_id',q.graph_id,'app_id',i.app_id,'deployment_id',i.deployment_id,
  'node_id',i.node_id,'wake_id',i.wake_id,'source_id',q.frozen_inputs->>'source_id','environment_id',q.frozen_inputs->>'environment_id',
  'revision_id',q.frozen_inputs->>'revision_id','resource',q.resource,'scope',q.frozen_inputs->>'scope','plan_hash',q.frozen_inputs->>'plan_hash',
  'generation',(q.frozen_inputs->>'generation')::bigint,'intent_version',(q.frozen_inputs->>'intent_version')::bigint,
  'attempt',q.attempt,'ram_mb',i.ram_mb,'artifact',q.artifact);
$$;


--
-- Name: environment_qualification_restore_current(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_qualification_restore_current(request uuid, capture uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM environment_workload_qualification_requests q
  JOIN environment_qualification_executions e ON e.instance_id=capture
  JOIN environment_qualification_snapshot_receipts r ON r.instance_id=e.instance_id
  WHERE q.id=request AND q.reserved_instance_id=capture AND q.phase='claimed' AND q.execution_mode<>'job'
   AND q.lease_until>clock_timestamp() AND q.lease_token=current_setting('gregale.gitops_qualification',true)
   AND e.request_id=q.id AND (e.frame->>'attempt')::bigint=q.attempt AND e.capture_instance_id IS NULL
   AND e.dispatch_started AND e.retired_at IS NOT NULL AND e.retirement->>'kind'='native_retired'
   AND e.retirement->>'native_generation'=r.snapshot->>'native_generation' AND e.retirement->>'kernel_boot_id'=r.snapshot->>'kernel_boot_id'
   AND e.frame->'artifact'=q.artifact AND e.frame->>'app_id'=q.app_id::text AND e.frame->>'deployment_id'=q.deployment_id::text
   AND environment_workload_qualification_inputs_current(q.id)
   AND environment_runtime_inputs_fresh(q.app_id,r.inputs->>'scope',(r.inputs->>'boundary')::timestamptz,
    r.inputs->'variables',r.inputs->'secret_versions',(r.inputs->>'all_secrets')::boolean,r.inputs->'secret_refs',coalesce(r.inputs->'sidecar_secret_versions','{}')));
$$;


--
-- Name: environment_runtime_base_inputs_fresh(uuid, text, timestamp with time zone, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_runtime_base_inputs_fresh(target_app uuid, target_scope text, boundary timestamp with time zone, observed_variables jsonb, observed_secrets jsonb, observed_all_secrets boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT
    NOT EXISTS (SELECT 1 FROM app_runtime_config_changes c WHERE c.app_id = target_app AND c.changed_at > boundary)
    AND NOT EXISTS (SELECT 1 FROM app_runtime_config_scope_changes c WHERE c.app_id = target_app
        AND c.scope IN ('default', target_scope) AND c.changed_at > boundary)
    AND observed_variables = coalesce((SELECT jsonb_object_agg(v.key, v.value) FROM app_envs v
        WHERE v.app_id = target_app AND v.scope = target_scope), '{}'::jsonb)
    AND NOT EXISTS (SELECT 1 FROM jsonb_each_text(observed_secrets) r WHERE NOT EXISTS (
        SELECT 1 FROM app_secrets v WHERE v.app_id = target_app AND v.scope = target_scope
        AND v.scope || '/' || v.key = r.key AND v.delivery_version::text = r.value))
    AND (NOT observed_all_secrets OR observed_secrets = coalesce((SELECT jsonb_object_agg(v.scope || '/' || v.key, v.delivery_version)
        FROM app_secrets v WHERE v.app_id = target_app AND v.scope = target_scope), '{}'::jsonb));
$$;


--
-- Name: environment_runtime_inputs_fresh(uuid, text, timestamp with time zone, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_runtime_inputs_fresh(target_app uuid, target_scope text, boundary timestamp with time zone, observed_variables jsonb, observed_secrets jsonb, observed_all_secrets boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT environment_runtime_inputs_fresh(target_app,target_scope,boundary,observed_variables,observed_secrets,observed_all_secrets,'{}'::jsonb);
$$;


--
-- Name: environment_runtime_inputs_fresh(uuid, text, timestamp with time zone, jsonb, jsonb, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_runtime_inputs_fresh(target_app uuid, target_scope text, boundary timestamp with time zone, observed_variables jsonb, observed_secrets jsonb, observed_all_secrets boolean, observed_secret_refs jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT environment_runtime_inputs_fresh(target_app,target_scope,boundary,observed_variables,observed_secrets,
  observed_all_secrets,observed_secret_refs,'{}'::jsonb);
$$;


--
-- Name: environment_runtime_inputs_fresh(uuid, text, timestamp with time zone, jsonb, jsonb, boolean, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_runtime_inputs_fresh(target_app uuid, target_scope text, boundary timestamp with time zone, observed_variables jsonb, observed_secrets jsonb, observed_all_secrets boolean, observed_secret_refs jsonb, observed_sidecar_secrets jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 WITH managed AS (SELECT environment_scoped_secret_refs(target_app,target_scope) AS refs),
 suppressed AS (SELECT environment_scoped_secret_suppressions(target_app,target_scope) AS keys),
 eligible AS (
  SELECT s.key,s.scope,s.delivery_version FROM app_secrets s
  WHERE s.app_id=target_app AND s.scope=target_scope AND
   (s.managed_postgres_binding_id IS NULL OR EXISTS (
    SELECT 1 FROM managed_postgres_bindings b WHERE b.id=s.managed_postgres_binding_id
     AND b.account_id=s.account_id AND b.app_id=s.app_id AND b.scope=s.scope
     AND b.environment_key=s.key AND b.access IN ('read_write','read_only','data_api','auth')))
 ),
 baseline AS (SELECT coalesce(jsonb_object_agg(s.key,'secret:'||s.key),'{}'::jsonb) AS refs,
  coalesce(jsonb_object_agg(s.scope||'/'||s.key,s.delivery_version),'{}'::jsonb) AS versions FROM eligible s)
 SELECT environment_runtime_base_inputs_fresh(target_app,target_scope,boundary,observed_variables,observed_secrets,false)
  AND observed_sidecar_secrets <@ observed_secrets
  AND managed.refs <@ observed_secret_refs
  AND NOT observed_secret_refs ?| suppressed.keys
  AND NOT EXISTS (SELECT 1 FROM jsonb_each_text(observed_secrets) v WHERE NOT EXISTS (
   SELECT 1 FROM eligible s WHERE v.key=s.scope||'/'||s.key AND v.value=s.delivery_version::text))
  AND (cardinality(suppressed.keys)=0 OR observed_secrets=(coalesce((SELECT jsonb_object_agg(s.scope||'/'||s.key,s.delivery_version)
   FROM eligible s WHERE EXISTS (
    SELECT 1 FROM jsonb_each_text(observed_secret_refs) r WHERE r.value='secret:'||s.key)),'{}'::jsonb)||observed_sidecar_secrets))
  AND NOT EXISTS(SELECT 1 FROM jsonb_each(managed.refs) r WHERE observed_variables ? r.key)
  AND NOT EXISTS (SELECT 1 FROM jsonb_each_text(observed_secret_refs) r WHERE
   NOT EXISTS (SELECT 1 FROM eligible s WHERE r.value='secret:'||s.key
    AND observed_secrets->>(target_scope||'/'||s.key)=s.delivery_version::text))
  AND (NOT observed_all_secrets OR
   CASE WHEN observed_secret_refs='{}'::jsonb AND managed.refs='{}'::jsonb AND cardinality(suppressed.keys)=0
    THEN observed_secrets=baseline.versions
    ELSE observed_secret_refs=((baseline.refs - suppressed.keys)||managed.refs) END)
 FROM managed,baseline,suppressed;
$$;


--
-- Name: environment_runtime_receipt_required(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_runtime_receipt_required(target_app uuid, target_scope text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT environment_scoped_secret_refs(target_app,target_scope)<>'{}'::jsonb
  OR cardinality(environment_scoped_secret_suppressions(target_app,target_scope))>0 OR EXISTS (
  SELECT 1 FROM active_environment_git_sources s JOIN project_environments e ON e.id=s.environment_id
  JOIN environment_gitops_resources r ON r.source_id=s.id WHERE r.app_id=target_app AND e.slug=target_scope
  AND (EXISTS (SELECT 1 FROM environment_managed_fields f WHERE f.source_id=s.id AND f.resource=r.logical_name
   AND (f.field_path LIKE 'variables/%' OR f.field_path LIKE 'secret_refs/%'))
   OR EXISTS (SELECT 1 FROM environment_gitops_runtime_effects x WHERE x.source_id=s.id AND x.app_id=r.app_id AND x.completed_at IS NULL)));
$$;


--
-- Name: environment_scoped_secret_refs(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_scoped_secret_refs(target_app uuid, target_scope text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 SELECT coalesce(jsonb_object_agg(r.key,'secret:'||r.secret_name),'{}'::jsonb)
 FROM app_environment_secret_refs r JOIN project_environments e ON e.id=r.environment_id
 JOIN apps a ON a.id=r.app_id AND a.account_id=r.account_id AND a.project_id=r.project_id
 WHERE r.app_id=target_app AND e.slug=target_scope AND e.account_id=r.account_id AND e.project_id=r.project_id;
$$;


--
-- Name: environment_scoped_secret_suppressions(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_scoped_secret_suppressions(target_app uuid, target_scope text) RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
 SELECT coalesce(array_agg(r.key ORDER BY r.key),ARRAY[]::text[])
 FROM app_environment_secret_ref_suppressions r JOIN project_environments e ON e.id=r.environment_id
 JOIN apps a ON a.id=r.app_id AND a.account_id=r.account_id AND a.project_id=r.project_id
 WHERE r.app_id=target_app AND e.slug=target_scope AND e.account_id=r.account_id AND e.project_id=r.project_id;
$$;


--
-- Name: environment_workload_activation_authorized(public.deployments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_activation_authorized(candidate public.deployments) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE frozen jsonb; token text; source_uuid uuid; source_generation bigint; source_intent bigint; environment_uuid uuid; revision_uuid uuid;
BEGIN
    frozen:=candidate.environment_workload_runtime;
    IF frozen IS NULL OR candidate.environment_workload_held OR candidate.status<>'live' THEN RETURN false; END IF;
    token:=nullif(current_setting('gregale.gitops_activation',true),'');
    IF token IS NULL OR token IS DISTINCT FROM current_setting('gregale.gitops_lease',true) THEN RETURN false; END IF;
    BEGIN
        source_uuid:=(frozen->>'source_id')::uuid;
        source_generation:=(frozen->>'generation')::bigint;
        source_intent:=(frozen->>'intent_version')::bigint;
        environment_uuid:=(frozen->>'environment_id')::uuid;
        revision_uuid:=(frozen->>'revision_id')::uuid;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN false;
    END;
    RETURN EXISTS (
        SELECT 1
        FROM active_environment_git_sources source
        JOIN environment_gitops_jobs job ON job.source_id=source.id
        JOIN environment_workload_graphs graph ON graph.source_id=source.id
        CROSS JOIN LATERAL jsonb_array_elements(graph.members) AS graph_member(value)
        WHERE source.id=source_uuid AND source.mode='enforce' AND NOT source.suspended
            AND source.generation=source_generation AND source.intent_version=source_intent
            AND source.environment_id=environment_uuid AND source.approved_revision_id=revision_uuid
            AND graph.environment_id=source.environment_id AND graph.revision_id=source.approved_revision_id
            AND graph.generation=source.generation AND graph.intent_version=source.intent_version
            AND graph.plan_hash=frozen->>'plan_hash' AND graph.phase='prepared'
            AND environment_workload_graph_serving_supported(graph.id)
            AND graph_member.value->>'resource'=frozen->>'resource'
            AND graph_member.value->>'app_id'=candidate.app_id::text
            AND graph_member.value->>'candidate_deployment_id'=candidate.id::text
            AND job.desired_generation=source.generation AND job.claimed_generation=source.generation
            AND job.lease_until>clock_timestamp() AND job.lease_token=token AND token<>''
    );
END $$;


--
-- Name: environment_workload_admission_retired(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_admission_retired(application uuid, deployment_scope text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM environment_workload_retirements r
  JOIN project_environments e ON e.id=r.environment_id
  WHERE r.app_id=application AND e.slug=CASE WHEN coalesce(deployment_scope,'') IN ('','default') THEN 'production' ELSE deployment_scope END AND r.phase IN ('retiring','retired','recovering'))
$$;


--
-- Name: environment_workload_artifact(public.deployments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_artifact(d public.deployments) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT jsonb_build_object('rootfs_path',coalesce((d).rootfs_path,''),'rootfs_key',coalesce((d).rootfs_key,''),
  'rootfs_bytes',coalesce((d).rootfs_bytes,0),'image_digest',coalesce((d).image_digest,''),
  'build_id',coalesce((d).build_id::text,''),'kind',(d).kind,'commit_sha',coalesce((d).commit_sha,''));
$$;


--
-- Name: environment_workload_candidate_applied_removal_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_candidate_applied_removal_valid(input_value jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE source_uuid uuid; revision_uuid uuid; source_generation bigint; resource_name text;
BEGIN
 BEGIN
  source_uuid:=(input_value->>'source_id')::uuid;
  revision_uuid:=(input_value->>'revision_id')::uuid;
  source_generation:=(input_value->>'generation')::bigint;
  resource_name:=input_value->>'resource';
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RETURN false;
 END;
 IF source_uuid IS NULL OR revision_uuid IS NULL OR source_generation IS NULL OR resource_name IS NULL THEN RETURN false; END IF;
 RETURN EXISTS(
  SELECT 1 FROM environment_gitops_runs run CROSS JOIN LATERAL jsonb_array_elements(run.steps) step
  WHERE run.source_id=source_uuid AND run.revision_id=revision_uuid AND run.generation=source_generation
   AND step->>'resource'=resource_name AND step->>'status'='applied' AND step->>'action'='remove'
   AND (step->>'path' IN ('source','source_revision') OR starts_with(step->>'path','runtime/') OR
    starts_with(step->>'path','service_bindings/') OR starts_with(step->>'path','queue_bindings/') OR
    starts_with(step->>'path','variables/') OR starts_with(step->>'path','secret_refs/') OR step->>'path'='schedule')
 );
END $$;


--
-- Name: environment_workload_candidate_queue_bindings_valid(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_candidate_queue_bindings_valid(input_value jsonb, candidate_app_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE source_row environment_git_sources%ROWTYPE; revision_row environment_desired_revisions%ROWTYPE;
        approved_bindings jsonb; frozen_bindings jsonb; workload_name text; entry record;
BEGIN
 BEGIN
  SELECT * INTO source_row FROM environment_git_sources WHERE id=(input_value->>'source_id')::uuid;
  SELECT * INTO revision_row FROM environment_desired_revisions
   WHERE id=(input_value->>'revision_id')::uuid AND source_id=source_row.id;
 EXCEPTION WHEN invalid_text_representation THEN
  RETURN false;
 END;
 IF source_row.id IS NULL OR revision_row.id IS NULL THEN RETURN false; END IF;
 IF coalesce(input_value->>'resource','') !~ '^workload/[a-z0-9][a-z0-9-]*$' THEN RETURN false; END IF;
 workload_name:=substring(input_value->>'resource' from 10);
 approved_bindings:=coalesce(revision_row.definition->'workloads'->workload_name->'queue_bindings','{}'::jsonb);
 frozen_bindings:=coalesce(input_value->'queue_bindings','{}'::jsonb);
 IF jsonb_typeof(approved_bindings) IS DISTINCT FROM 'object' OR jsonb_typeof(frozen_bindings) IS DISTINCT FROM 'object' THEN
  RETURN false;
 END IF;
 IF (SELECT count(*) FROM jsonb_each(approved_bindings)) <>
    (SELECT count(*) FROM jsonb_each(frozen_bindings)) THEN RETURN false; END IF;
 FOR entry IN SELECT key,value FROM jsonb_each(frozen_bindings) LOOP
  IF jsonb_typeof(entry.value) IS DISTINCT FROM 'object' OR NOT (entry.value ?& ARRAY['binding_id','contract']) OR
     jsonb_typeof(entry.value->'contract') IS DISTINCT FROM 'object' OR
     coalesce(entry.value->>'binding_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR
     entry.value->'contract' IS DISTINCT FROM approved_bindings->entry.key THEN RETURN false; END IF;
  IF NOT EXISTS(
   SELECT 1 FROM environment_gitops_queue_bindings identity
   JOIN environment_managed_fields owner ON owner.source_id=identity.source_id AND owner.environment_id=source_row.environment_id
    AND owner.resource=identity.resource AND owner.field_path=identity.field_path
   JOIN queue_bindings binding ON binding.id=identity.binding_id
   JOIN apps app ON app.id=binding.app_id
   WHERE identity.source_id=source_row.id AND identity.resource=input_value->>'resource'
    AND identity.field_path='queue_bindings/'||entry.key AND identity.binding_id=(entry.value->>'binding_id')::uuid
    AND binding.id=(entry.value->>'binding_id')::uuid AND binding.account_id=source_row.account_id
    AND binding.app_id=candidate_app_id AND binding.environment_id=source_row.environment_id
    AND binding.deployment_scope=input_value->>'scope' AND binding.name=entry.key AND binding.retired_at IS NULL
    AND binding.workload_class=app.workload_class AND binding.workload_class=entry.value->'contract'->>'workload_class'
    AND entry.value->'contract'=(jsonb_build_object('queue_name',binding.queue_name,'mode',binding.mode,
      'workload_class',binding.workload_class,'enabled',binding.enabled,'max_concurrency',binding.max_concurrency)
      || CASE WHEN binding.retry_policy='{}'::jsonb THEN '{}'::jsonb ELSE jsonb_build_object('retry_policy',binding.retry_policy) END)
  ) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END $_$;


--
-- Name: environment_workload_candidate_secret_refs_valid(jsonb, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_candidate_secret_refs_valid(input_value jsonb, target_app uuid, target_scope text, desired_refs jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE frozen_refs jsonb; reviewed_refs jsonb;
BEGIN
 frozen_refs:=coalesce(input_value->'secret_refs','{}'::jsonb);
 reviewed_refs:=coalesce(desired_refs,'{}'::jsonb);
 IF jsonb_typeof(frozen_refs)<>'object' OR jsonb_typeof(reviewed_refs)<>'object' OR
    jsonb_typeof(coalesce(input_value->'variables','{}'::jsonb))<>'object' OR
    jsonb_typeof(coalesce(input_value->'service_bindings','{}'::jsonb))<>'object' THEN
  RETURN false;
 END IF;
 IF frozen_refs IS DISTINCT FROM reviewed_refs OR
    frozen_refs IS DISTINCT FROM environment_scoped_secret_refs(target_app,target_scope) THEN
  RETURN false;
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each_text(frozen_refs) entry
   WHERE entry.key !~ '^[A-Z][A-Z0-9_]{0,127}$' OR entry.value !~ '^secret:[A-Z][A-Z0-9_]{0,127}$') OR
    EXISTS(SELECT 1 FROM jsonb_object_keys(frozen_refs) secret_key(key)
      JOIN jsonb_object_keys(coalesce(input_value->'variables','{}'::jsonb)) variable_key(key) USING(key)) OR
    EXISTS(SELECT 1 FROM jsonb_object_keys(frozen_refs) secret_key(key)
      JOIN jsonb_each(coalesce(input_value->'service_bindings','{}'::jsonb)) binding ON binding.value->>'env_key'=secret_key.key) THEN
  RETURN false;
 END IF;
 RETURN true;
END $_$;


--
-- Name: environment_workload_deployment_inputs(public.deployments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_deployment_inputs(d public.deployments) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT jsonb_build_object(
  'override_entrypoint',coalesce((d).override_entrypoint,ARRAY[]::text[]),'override_cmd',coalesce((d).override_cmd,ARRAY[]::text[]),
  'override_env',coalesce(nullif((d).override_env,'null'::jsonb),'{}'::jsonb),'override_env_secrets',coalesce(nullif((d).override_env_secrets,'null'::jsonb),'{}'::jsonb),
  'override_port',coalesce((d).override_port,0),'override_healthcheck',coalesce(nullif((d).override_healthcheck,'null'::jsonb),'{}'::jsonb),
  'override_liveness_probe',coalesce(nullif((d).override_liveness_probe,'null'::jsonb),'{}'::jsonb),'override_readiness_probe',coalesce(nullif((d).override_readiness_probe,'null'::jsonb),'{}'::jsonb),
  'override_main_depends_on',(d).override_main_depends_on,
  'sidecars',coalesce((SELECT jsonb_agg(sc-'secret_reload_signal' ORDER BY position) FROM jsonb_array_elements((d).sidecars) WITH ORDINALITY AS s(sc,position)),'[]'::jsonb),
  'workflows',(d).workflows,
  'full_rootfs_allow_auto',(d).full_rootfs_allow_auto,'full_rootfs_override',(d).full_rootfs_override,
  'min_instances',(d).min_instances,'release_command',(d).release_command,'release_command_shell',(d).release_command_shell,
  'disable_startup_cpu_boost',(d).disable_startup_cpu_boost,
  'rollback_on_5xx',(d).rollback_on_5xx);
$$;


--
-- Name: environment_workload_graph_service_bindings_supported(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_graph_service_bindings_supported(target_graph uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
SELECT EXISTS (
    SELECT 1 FROM environment_workload_graphs graph
    WHERE graph.id=target_graph AND CASE WHEN jsonb_typeof(graph.members)='array'
        THEN jsonb_array_length(graph.members)>0 ELSE false END
        AND NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements(CASE WHEN jsonb_typeof(graph.members)='array' THEN graph.members ELSE '[]'::jsonb END) AS caller(value)
            CROSS JOIN LATERAL (SELECT CASE WHEN jsonb_typeof(caller.value->'service_bindings')='object'
                THEN caller.value->'service_bindings' ELSE '{}'::jsonb END AS bindings) frozen
            WHERE coalesce(jsonb_typeof(caller.value->'service_bindings'),'null') NOT IN ('object','null')
                OR coalesce(caller.value->>'service_bindings_configured','false')<>
                    (frozen.bindings<>'{}'::jsonb)::text
                OR (frozen.bindings<>'{}'::jsonb AND caller.value->>'execution_mode' NOT IN ('request','service','worker','job'))
                OR (caller.value->>'execution_mode'='job' AND frozen.bindings<>'{}'::jsonb AND
                    (coalesce(caller.value->>'schedule_configured','false')<>'true' OR coalesce(caller.value->>'job_smoke_configured','false')<>'true' OR
                     coalesce(caller.value->>'queue_bindings_configured','false')<>'false' OR
                     coalesce(nullif(caller.value->'queue_bindings','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb OR
                     coalesce(nullif(caller.value->'queue_modes','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb))
                OR EXISTS (
                    SELECT 1 FROM jsonb_each(frozen.bindings) AS binding(name,value)
                    WHERE binding.name !~ '^[a-z0-9]([a-z0-9-]{1,38})[a-z0-9]$'
                        OR binding.name ~ '^tag-'
                        OR jsonb_typeof(binding.value)<>'object'
                        OR coalesce(binding.value->>'workload','') !~ '^[a-z0-9]([a-z0-9-]{1,38})[a-z0-9]$'
                        OR coalesce(binding.value->>'workload','') ~ '^tag-'
                        OR coalesce(binding.value->>'env_key','') !~ '^[A-Z][A-Z0-9_]*$'
                        OR octet_length(coalesce(binding.value->>'env_key',''))>128
                        OR coalesce(binding.value->>'target_app_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                        OR binding.value->>'target_app_id'=caller.value->>'app_id'
                        OR NOT EXISTS (
                            SELECT 1
                            FROM jsonb_array_elements(CASE WHEN jsonb_typeof(graph.members)='array' THEN graph.members ELSE '[]'::jsonb END) AS target(value)
                            WHERE target.value->>'resource'='workload/'||(binding.value->>'workload')
                                AND target.value->>'app_id'=binding.value->>'target_app_id'
                                AND target.value->>'app_id'<>caller.value->>'app_id'
                                AND target.value->>'execution_mode' IN ('request','service')
                                AND ((nullif(target.value->>'candidate_deployment_id','') IS NULL)=
                                    (nullif(caller.value->>'candidate_deployment_id','') IS NULL))
                        )
                )
                OR (SELECT count(*)<>count(DISTINCT binding.value->>'env_key')
                    FROM jsonb_each(frozen.bindings) AS binding(name,value))
        )
)
$_$;


--
-- Name: environment_workload_graph_serving_supported(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_graph_serving_supported(target_graph uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
SELECT EXISTS (
    SELECT 1 FROM environment_workload_graphs graph
    WHERE graph.id=target_graph AND CASE WHEN jsonb_typeof(graph.members)='array'
        THEN jsonb_array_length(graph.members)>0 ELSE false END
        AND environment_workload_graph_service_bindings_supported(target_graph)
        AND NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements(graph.members) AS graph_member(value)
            WHERE NOT coalesce((
                (
                    graph_member.value->>'execution_mode' IN ('request','service')
                    AND coalesce(nullif(graph_member.value->'queue_modes','null'::jsonb),'{}'::jsonb)='{}'::jsonb
                    AND NOT EXISTS (
                        SELECT 1 FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
                        WHERE queue_binding.value->'contract'->>'enabled'='true'
                    )
                ) OR (
                    graph_member.value->>'execution_mode'='request'
                    AND graph_member.value->>'function'='true'
                    AND jsonb_typeof(graph_member.value->'queue_modes')='object'
                    AND (SELECT count(*) FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_modes','null'::jsonb),'{}'::jsonb)))>0
                    AND (SELECT count(*) FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_modes','null'::jsonb),'{}'::jsonb)))=(
                        SELECT count(*) FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
                        WHERE queue_binding.value->'contract'->>'enabled'='true'
                    )
                    AND NOT EXISTS (
                        SELECT 1
                        FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_modes','null'::jsonb),'{}'::jsonb)) AS queue_mode(name,value)
                        WHERE queue_mode.value<>'"push"'::jsonb OR NOT EXISTS (
                            SELECT 1
                            FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
                            WHERE queue_binding.name=queue_mode.name
                                AND queue_binding.value->'contract'->>'enabled'='true'
                                AND queue_binding.value->'contract'->>'mode'='push'
                                AND queue_binding.value->'contract'->>'workload_class'='http'
                                AND coalesce(queue_binding.value->>'binding_id','') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                                AND coalesce(queue_binding.value->>'trigger_id','') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                        )
                    )
                    AND NOT EXISTS (
                        SELECT 1
                        FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
                        WHERE queue_binding.value->'contract'->>'enabled'='true'
                            AND NOT (coalesce(nullif(graph_member.value->'queue_modes','null'::jsonb),'{}'::jsonb) ? queue_binding.name)
                    )
                ) OR (
                    graph_member.value->>'execution_mode'='worker'
                    AND jsonb_typeof(graph_member.value->'queue_modes')='object'
                    AND (SELECT count(*) FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_modes','null'::jsonb),'{}'::jsonb)))>0
                    AND (SELECT count(*) FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_modes','null'::jsonb),'{}'::jsonb)))=(
                        SELECT count(*) FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
                        WHERE queue_binding.value->'contract'->>'enabled'='true'
                    )
                    AND NOT EXISTS (
                        SELECT 1
                        FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_modes','null'::jsonb),'{}'::jsonb)) AS queue_mode(name,value)
                        WHERE queue_mode.value NOT IN ('"push"'::jsonb,'"pull"'::jsonb) OR NOT EXISTS (
                            SELECT 1
                            FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
                            WHERE queue_binding.name=queue_mode.name
                                AND queue_binding.value->'contract'->>'enabled'='true'
                                AND queue_binding.value->'contract'->>'mode'=queue_mode.value#>>'{}'
                                AND queue_binding.value->'contract'->>'workload_class'='worker'
                                AND coalesce(queue_binding.value->>'binding_id','') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                                AND ((queue_mode.value='"push"'::jsonb AND coalesce(queue_binding.value->>'trigger_id','') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
                                    OR (queue_mode.value='"pull"'::jsonb AND coalesce(queue_binding.value->>'trigger_id','')=''))
                        )
                    )
                    AND NOT EXISTS (
                        SELECT 1
                        FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
                        WHERE queue_binding.value->'contract'->>'enabled'='true'
                            AND NOT (coalesce(nullif(graph_member.value->'queue_modes','null'::jsonb),'{}'::jsonb) ? queue_binding.name)
                    )
                ) OR (
                    graph_member.value->>'execution_mode'='job'
                    AND graph_member.value->>'schedule_configured'='true'
                    AND graph_member.value->>'job_smoke_configured'='true'
                    AND coalesce(graph_member.value->>'job_id','') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    AND coalesce(graph_member.value->>'queue_bindings_configured','false')='false'
                    AND coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)='{}'::jsonb
                    AND coalesce(nullif(graph_member.value->'queue_modes','null'::jsonb),'{}'::jsonb)='{}'::jsonb
                    AND NOT EXISTS (
                        SELECT 1 FROM jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
                        WHERE queue_binding.value->'contract'->>'enabled'='true'
                    )
                )
            ),false)
        )
        AND NOT EXISTS (
            SELECT 1
            FROM active_environment_git_sources source
            JOIN project_environments environment ON environment.id=source.environment_id
            CROSS JOIN LATERAL jsonb_array_elements(graph.members) AS graph_member(value)
            CROSS JOIN LATERAL jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
            LEFT JOIN queue_bindings binding ON binding.id::text=queue_binding.value->>'binding_id'
            LEFT JOIN triggers queue_trigger ON queue_trigger.id::text=queue_binding.value->>'trigger_id'
            WHERE source.id=graph.source_id
                AND graph.id=target_graph
                AND (graph_member.value->>'execution_mode'='worker' OR
                    (graph_member.value->>'execution_mode'='request' AND graph_member.value->>'function'='true'))
                AND queue_binding.value->'contract'->>'enabled'='true'
                AND (binding.id IS NULL
                    OR binding.app_id::text IS DISTINCT FROM graph_member.value->>'app_id'
                    OR binding.account_id IS DISTINCT FROM source.account_id
                    OR binding.environment_id IS DISTINCT FROM source.environment_id
                    OR binding.deployment_scope IS DISTINCT FROM environment.slug
                    OR binding.name IS DISTINCT FROM queue_binding.name
                    OR binding.queue_name IS DISTINCT FROM queue_binding.value->'contract'->>'queue_name'
                    OR binding.mode IS DISTINCT FROM queue_binding.value->'contract'->>'mode'
                    OR binding.workload_class IS DISTINCT FROM queue_binding.value->'contract'->>'workload_class'
                    OR binding.enabled IS DISTINCT FROM (queue_binding.value->'contract'->>'enabled')::boolean
                    OR binding.max_concurrency::text IS DISTINCT FROM queue_binding.value->'contract'->>'max_concurrency'
                    OR binding.retry_policy IS DISTINCT FROM coalesce(nullif(queue_binding.value->'contract'->'retry_policy','null'::jsonb),'{}'::jsonb)
                    OR binding.retired_at IS NOT NULL
                    OR (binding.mode='push' AND (queue_trigger.id IS NULL
                        OR queue_trigger.app_id IS DISTINCT FROM binding.app_id
                        OR queue_trigger.account_id IS DISTINCT FROM source.account_id
                        OR queue_trigger.queue_binding_id IS DISTINCT FROM binding.id
                        OR NOT queue_trigger.enabled
                        OR queue_trigger.kind IS DISTINCT FROM 'queue'
                        OR queue_trigger.source IS DISTINCT FROM 'queue'
                        OR queue_trigger.slug IS DISTINCT FROM queue_binding.value->'contract'->>'queue_name'
                        OR queue_trigger.queue_binding_scope IS DISTINCT FROM environment.slug
                        OR queue_trigger.queue_binding_environment_id IS DISTINCT FROM source.environment_id))
                    OR (binding.mode='pull' AND (coalesce(queue_binding.value->>'trigger_id','')<>'' OR queue_trigger.id IS NOT NULL))
                    OR binding.mode NOT IN ('push','pull'))
        )
)
$_$;


--
-- Name: environment_workload_qualification_evidence_current(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_qualification_evidence_current(request_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM environment_workload_qualification_requests target
  JOIN environment_workload_graphs g ON g.id=target.graph_id JOIN active_environment_git_sources s ON s.id=g.source_id
  JOIN project_environments e ON e.id=g.environment_id JOIN accounts c ON c.id=s.account_id
  WHERE target.id=request_id AND g.phase='prepared' AND s.mode='enforce' AND NOT s.suspended
   AND c.status='active' AND c.abuse_hold_at IS NULL
   AND g.generation=s.generation AND g.intent_version=s.intent_version AND g.revision_id=s.approved_revision_id
   AND g.environment_id=s.environment_id AND e.account_id=s.account_id AND e.project_id=s.project_id
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.members) m LEFT JOIN apps a ON a.id=(m->>'app_id')::uuid
    WHERE a.id IS NULL OR a.status NOT IN ('active','evicted_cold') OR a.account_id<>s.account_id OR a.project_id<>s.project_id
     OR m->'retained_deployments' IS DISTINCT FROM (SELECT coalesce(jsonb_agg(d.id::text ORDER BY d.id),'[]'::jsonb)
      FROM deployments d WHERE d.app_id=a.id AND d.scope=e.slug AND d.status='live'
       AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.members) candidate
        WHERE candidate->>'candidate_deployment_id'=d.id::text)))
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.members) m
    LEFT JOIN environment_workload_qualification_requests q ON q.graph_id=g.id AND q.resource=m->>'resource'
     AND q.app_id=(m->>'app_id')::uuid AND q.deployment_id=(m->>'candidate_deployment_id')::uuid
    LEFT JOIN deployments d ON d.id=q.deployment_id LEFT JOIN apps a ON a.id=q.app_id
    WHERE m ? 'candidate_deployment_id' AND (q.id IS NULL
     OR NOT ((d.status='snapshotting' AND d.environment_workload_held)
      OR (d.status='live' AND NOT d.environment_workload_held AND EXISTS(
       SELECT 1 FROM project_release_sets release
       JOIN project_release_members member ON member.release_id=release.id
       WHERE release.project_id=s.project_id AND release.environment_slug=e.slug AND release.active
        AND member.app_id=d.app_id AND member.deployment_id=d.id)))
     OR coalesce(d.rootfs_bytes,0)<=0 OR q.artifact IS DISTINCT FROM environment_workload_artifact(d)
     OR q.frozen_inputs IS DISTINCT FROM d.environment_workload_runtime OR d.scope IS DISTINCT FROM e.slug OR d.app_id IS DISTINCT FROM a.id
     OR jsonb_strip_nulls(q.frozen_inputs->'baseline') IS DISTINCT FROM jsonb_strip_nulls(a.manifest)
     OR q.frozen_inputs->>'start_command' IS DISTINCT FROM coalesce(a.start_command,'') OR q.frozen_inputs->>'app_type' IS DISTINCT FROM a.type
     OR q.frozen_inputs->>'runtime_base' IS DISTINCT FROM coalesce(a.runtime,'') OR q.frozen_inputs->>'workload_class' IS DISTINCT FROM a.workload_class
     OR q.frozen_inputs ? 'deployment_inputs' AND EXISTS(SELECT 1 FROM deployments original
      WHERE original.app_id=a.id AND original.scope=e.slug AND original.status='live'
       AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.members) candidate
        WHERE candidate->>'candidate_deployment_id'=original.id::text)
       AND environment_workload_deployment_inputs(original) IS DISTINCT FROM q.frozen_inputs->'deployment_inputs'))));
$$;


--
-- Name: environment_workload_qualification_inputs_current(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_qualification_inputs_current(request_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM environment_workload_qualification_requests target
  JOIN environment_workload_graphs g ON g.id=target.graph_id JOIN active_environment_git_sources s ON s.id=g.source_id
  JOIN project_environments e ON e.id=g.environment_id JOIN accounts c ON c.id=s.account_id
  WHERE target.id=request_id AND g.phase='prepared' AND s.mode='enforce' AND NOT s.suspended
   AND c.status='active' AND c.abuse_hold_at IS NULL
   AND g.generation=s.generation AND g.intent_version=s.intent_version AND g.revision_id=s.approved_revision_id
   AND g.environment_id=s.environment_id AND e.account_id=s.account_id AND e.project_id=s.project_id
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.members) m LEFT JOIN apps a ON a.id=(m->>'app_id')::uuid
    WHERE a.id IS NULL OR a.status NOT IN ('active','evicted_cold') OR a.account_id<>s.account_id OR a.project_id<>s.project_id
     OR m->'retained_deployments' IS DISTINCT FROM (SELECT coalesce(jsonb_agg(d.id::text ORDER BY d.id),'[]'::jsonb)
      FROM deployments d WHERE d.app_id=a.id AND d.scope=e.slug AND d.status='live'))
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.members) m
    LEFT JOIN environment_workload_qualification_requests q ON q.graph_id=g.id AND q.resource=m->>'resource'
     AND q.app_id=(m->>'app_id')::uuid AND q.deployment_id=(m->>'candidate_deployment_id')::uuid
    LEFT JOIN deployments d ON d.id=q.deployment_id LEFT JOIN apps a ON a.id=q.app_id
    WHERE m ? 'candidate_deployment_id' AND (q.id IS NULL OR d.status IS DISTINCT FROM 'snapshotting' OR coalesce(d.rootfs_bytes,0)<=0
     OR q.artifact IS DISTINCT FROM environment_workload_artifact(d) OR q.frozen_inputs IS DISTINCT FROM d.environment_workload_runtime
     OR d.scope IS DISTINCT FROM e.slug OR d.app_id IS DISTINCT FROM a.id
     OR jsonb_strip_nulls(q.frozen_inputs->'baseline') IS DISTINCT FROM jsonb_strip_nulls(a.manifest)
     OR q.frozen_inputs->>'start_command' IS DISTINCT FROM coalesce(a.start_command,'') OR q.frozen_inputs->>'app_type' IS DISTINCT FROM a.type
     OR q.frozen_inputs->>'runtime_base' IS DISTINCT FROM coalesce(a.runtime,'') OR q.frozen_inputs->>'workload_class' IS DISTINCT FROM a.workload_class
     OR q.frozen_inputs ? 'deployment_inputs' AND EXISTS(SELECT 1 FROM deployments original
      WHERE original.app_id=a.id AND original.scope=e.slug AND original.status='live'
       AND environment_workload_deployment_inputs(original) IS DISTINCT FROM q.frozen_inputs->'deployment_inputs'))));
$$;


--
-- Name: environment_workload_queue_serving_ack_authorized(uuid, uuid, text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_queue_serving_ack_authorized(target_graph uuid, target_binding uuid, target_mode text, target_trigger uuid, target_app uuid, target_deployment uuid, target_invocation uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT EXISTS (
    SELECT 1
    FROM environment_workload_graphs graph
    JOIN active_environment_git_sources source ON source.id=graph.source_id
    JOIN project_environments environment ON environment.id=source.environment_id
    JOIN project_release_sets release ON release.project_id=source.project_id
        AND release.environment_slug=environment.slug AND release.active
    JOIN project_release_members release_member ON release_member.release_id=release.id
        AND release_member.app_id=target_app AND release_member.deployment_id=target_deployment
    JOIN deployments deployment ON deployment.id=target_deployment AND deployment.app_id=target_app
        AND deployment.status='live' AND NOT deployment.environment_workload_held
        AND deployment.scope=environment.slug
    JOIN invocations invocation ON invocation.id=target_invocation AND invocation.app_id=target_app
        AND invocation.source='queue' AND invocation.state='completed'
        AND invocation.completed_at>=release.created_at AND invocation.deployment_scope=environment.slug
        AND invocation.queue_binding_id=target_binding
    CROSS JOIN LATERAL jsonb_array_elements(graph.members) AS graph_member(value)
    CROSS JOIN LATERAL jsonb_each(coalesce(graph_member.value->'queue_bindings','{}'::jsonb)) AS queue_binding(name,value)
    JOIN queue_bindings binding ON binding.id=target_binding
        AND binding.app_id=target_app AND binding.account_id=source.account_id AND binding.environment_id=source.environment_id
        AND binding.deployment_scope=environment.slug AND binding.name=queue_binding.name
        AND binding.mode=target_mode AND binding.enabled
        AND ((binding.workload_class='worker' AND graph_member.value->>'execution_mode'='worker') OR
            (binding.workload_class='http' AND graph_member.value->>'execution_mode'='request'
                AND graph_member.value->>'function'='true'))
        AND binding.retired_at IS NULL
    WHERE graph.id=target_graph AND graph.phase='prepared'
        AND source.mode='enforce' AND NOT source.suspended
        AND source.generation=graph.generation AND source.intent_version=graph.intent_version
        AND source.approved_revision_id=graph.revision_id
        AND graph.environment_id=source.environment_id
        AND ((graph_member.value->>'execution_mode'='worker' AND binding.workload_class='worker'
                AND target_mode IN ('push','pull')) OR
            (graph_member.value->>'execution_mode'='request' AND graph_member.value->>'function'='true'
                AND binding.workload_class='http' AND target_mode='push'))
        AND graph_member.value->>'app_id'=target_app::text
        AND coalesce(queue_binding.value->>'binding_id','')=binding.id::text
        AND queue_binding.value->'contract'->>'mode'=target_mode
        AND queue_binding.value->'contract'->>'workload_class'=binding.workload_class
        AND queue_binding.value->'contract'->>'enabled'='true'
        AND queue_binding.value->'contract'->>'queue_name'=binding.queue_name
        AND queue_binding.value->'contract'->>'max_concurrency'=binding.max_concurrency::text
        AND coalesce(nullif(queue_binding.value->'contract'->'retry_policy','null'::jsonb),'{}'::jsonb)=binding.retry_policy
        AND ((target_mode='push' AND target_trigger IS NOT NULL
                AND coalesce(queue_binding.value->>'trigger_id','')=target_trigger::text
                AND EXISTS (
                    SELECT 1 FROM triggers queue_trigger
                    JOIN trigger_records record ON record.trigger_id=queue_trigger.id
                        AND record.item_identifier=invocation.id::text AND record.state='succeeded'
                    WHERE queue_trigger.id=target_trigger AND queue_trigger.account_id=source.account_id
                        AND queue_trigger.app_id=target_app AND queue_trigger.queue_binding_id=binding.id
                        AND queue_trigger.enabled AND queue_trigger.kind='queue' AND queue_trigger.source='queue'
                        AND queue_trigger.slug=queue_binding.value->'contract'->>'queue_name'
                        AND queue_trigger.queue_binding_scope=environment.slug
                        AND queue_trigger.queue_binding_environment_id=source.environment_id)) OR
            (target_mode='pull' AND target_trigger IS NULL
                AND coalesce(queue_binding.value->>'trigger_id','')=''))
        AND (graph_member.value->>'candidate_deployment_id'=target_deployment::text OR
            (nullif(graph_member.value->>'candidate_deployment_id','') IS NULL AND
             coalesce(graph_member.value->'retained_deployments','[]'::jsonb) ? target_deployment::text))
)
$$;


--
-- Name: environment_workload_retirements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.environment_workload_retirements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_id uuid NOT NULL,
    account_id uuid NOT NULL,
    project_id uuid NOT NULL,
    environment_id uuid NOT NULL,
    app_id uuid NOT NULL,
    resource text NOT NULL,
    revision_id uuid NOT NULL,
    generation bigint NOT NULL,
    plan_hash text NOT NULL,
    phase text DEFAULT 'planned'::text NOT NULL,
    deployment_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    queue_binding_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    job_id uuid,
    route_deployment_id uuid,
    route_generation bigint DEFAULT 0 NOT NULL,
    expected_gateways text[] DEFAULT '{}'::text[] NOT NULL,
    acknowledged_gateways text[] DEFAULT '{}'::text[] NOT NULL,
    requested_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    retired_at timestamp with time zone,
    recovery_revision_id uuid,
    recovery_generation bigint DEFAULT 0 NOT NULL,
    recovered_at timestamp with time zone,
    binding_policy_context jsonb,
    CONSTRAINT environment_workload_retirements_binding_policy_context_check CHECK (((binding_policy_context IS NULL) OR (jsonb_typeof(binding_policy_context) = 'object'::text))),
    CONSTRAINT environment_workload_retirements_check CHECK (((array_position(acknowledged_gateways, NULL::text) IS NULL) AND (acknowledged_gateways <@ expected_gateways))),
    CONSTRAINT environment_workload_retirements_check1 CHECK (((route_deployment_id IS NULL) OR (route_deployment_id = ANY (deployment_ids)))),
    CONSTRAINT environment_workload_retirements_check2 CHECK (((phase = ANY (ARRAY['planned'::text, 'retiring'::text, 'cancelled'::text])) = (retired_at IS NULL))),
    CONSTRAINT environment_workload_retirements_check3 CHECK (((retired_at IS NULL) OR (retired_at >= requested_at))),
    CONSTRAINT environment_workload_retirements_check4 CHECK (((phase = ANY (ARRAY['recovering'::text, 'recovered'::text])) = (recovery_revision_id IS NOT NULL))),
    CONSTRAINT environment_workload_retirements_check5 CHECK (((recovery_revision_id IS NULL) = (recovery_generation = 0))),
    CONSTRAINT environment_workload_retirements_check6 CHECK (((recovery_generation = 0) OR (recovery_generation > generation))),
    CONSTRAINT environment_workload_retirements_check7 CHECK (((phase = 'recovered'::text) = (recovered_at IS NOT NULL))),
    CONSTRAINT environment_workload_retirements_check8 CHECK (((recovered_at IS NULL) OR (recovered_at >= retired_at))),
    CONSTRAINT environment_workload_retirements_deployment_ids_check CHECK ((array_position(deployment_ids, NULL::uuid) IS NULL)),
    CONSTRAINT environment_workload_retirements_expected_gateways_check CHECK ((array_position(expected_gateways, NULL::text) IS NULL)),
    CONSTRAINT environment_workload_retirements_generation_check CHECK ((generation > 0)),
    CONSTRAINT environment_workload_retirements_phase_check CHECK ((phase = ANY (ARRAY['planned'::text, 'retiring'::text, 'retired'::text, 'recovering'::text, 'recovered'::text, 'cancelled'::text]))),
    CONSTRAINT environment_workload_retirements_plan_hash_check CHECK ((plan_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT environment_workload_retirements_queue_binding_ids_check CHECK ((array_position(queue_binding_ids, NULL::uuid) IS NULL)),
    CONSTRAINT environment_workload_retirements_recovery_generation_check CHECK ((recovery_generation >= 0)),
    CONSTRAINT environment_workload_retirements_resource_check CHECK ((resource ~ '^workload/[a-z0-9][a-z0-9-]*$'::text)),
    CONSTRAINT environment_workload_retirements_route_generation_check CHECK ((route_generation >= 0))
);


--
-- Name: environment_workload_retirement_cutover_authorized(public.environment_workload_retirements); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_retirement_cutover_authorized(r public.environment_workload_retirements) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT nullif(current_setting('gregale.gitops_activation',true),'')=nullif(current_setting('gregale.gitops_lease',true),'')
 AND EXISTS(SELECT 1 FROM active_environment_git_sources s JOIN environment_desired_revisions rev ON rev.id=s.approved_revision_id
  JOIN environment_gitops_jobs j ON j.source_id=s.id
  WHERE s.id=(r).source_id AND s.mode='enforce' AND NOT s.suspended AND s.generation=(r).generation AND rev.id=(r).revision_id
   AND j.desired_generation=s.generation AND j.claimed_generation=s.generation AND j.lease_token=current_setting('gregale.gitops_lease',true)
   AND j.lease_until>clock_timestamp() AND (rev.definition->'workloads'='{}'::jsonb OR EXISTS(
    SELECT 1 FROM environment_workload_graphs g WHERE g.source_id=s.id AND g.revision_id=rev.id AND g.generation=s.generation
     AND g.intent_version=s.intent_version AND g.phase='prepared' AND environment_workload_graph_serving_supported(g.id)
     AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.members) m WHERE NOT (
      CASE WHEN coalesce(m->>'candidate_deployment_id','')<>'' THEN EXISTS(
       SELECT 1 FROM deployments d WHERE d.id=(m->>'candidate_deployment_id')::uuid AND environment_workload_activation_authorized(d))
      ELSE EXISTS(SELECT 1 FROM project_release_sets rs JOIN project_release_members rm ON rm.release_id=rs.id
       JOIN deployments d ON d.id=rm.deployment_id JOIN project_environments e ON e.id=s.environment_id
       WHERE rs.project_id=s.project_id AND rs.environment_slug=e.slug AND rs.active AND rm.app_id=(m->>'app_id')::uuid
        AND m->'retained_deployments' ? d.id::text AND d.status='live' AND NOT d.environment_workload_held) END)))))
$$;


--
-- Name: environment_workload_retirement_drain_authorized(public.deployments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_retirement_drain_authorized(d public.deployments) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM environment_workload_retirements r JOIN active_environment_git_sources s ON s.id=r.source_id
  JOIN environment_gitops_jobs j ON j.source_id=s.id JOIN project_environments e ON e.id=r.environment_id
  WHERE r.phase='retiring' AND r.app_id=(d).app_id AND e.slug=(d).scope AND (d).id=ANY(r.deployment_ids)
   AND environment_workload_retirement_routes_withdrawn(r) AND j.desired_generation=s.generation AND j.claimed_generation=s.generation
   AND j.lease_until>clock_timestamp() AND j.lease_token=current_setting('gregale.gitops_lease',true))
$$;


--
-- Name: environment_workload_retirement_drained(public.environment_workload_retirements); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_retirement_drained(r public.environment_workload_retirements) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT environment_workload_retirement_routes_withdrawn(r)
 AND ((r).job_id IS NULL OR EXISTS(SELECT 1 FROM jobs j WHERE j.id=(r).job_id AND j.status IN ('paused','deleted')))
 AND NOT EXISTS(SELECT 1 FROM unnest((r).queue_binding_ids) original(id) WHERE NOT EXISTS(
  SELECT 1 FROM queue_bindings b WHERE b.id=original.id AND b.app_id=(r).app_id AND b.environment_id=(r).environment_id AND NOT b.enabled AND b.retired_at IS NOT NULL))
 AND NOT EXISTS(SELECT 1 FROM triggers consumer WHERE consumer.queue_binding_id=ANY((r).queue_binding_ids) AND consumer.enabled)

 AND NOT EXISTS(SELECT 1 FROM instances i WHERE (i.deployment_id=ANY((r).deployment_ids) OR i.job_id=(r).job_id) AND i.state NOT IN ('parked','stopped','failed'))
 AND NOT EXISTS(SELECT 1 FROM deployments d WHERE d.id=ANY((r).deployment_ids) AND d.status NOT IN ('superseded','cancelled','failed'))
 AND NOT EXISTS(SELECT 1 FROM environment_qualification_executions x
  WHERE (x.frame->>'deployment_id')::uuid=ANY((r).deployment_ids) AND x.retired_at IS NULL)
 AND NOT EXISTS(SELECT 1 FROM invocations i WHERE i.app_id=(r).app_id AND (i.environment_id=(r).environment_id OR CASE WHEN coalesce(i.deployment_scope,'') IN ('','default') THEN 'production' ELSE i.deployment_scope END=(SELECT slug FROM project_environments WHERE id=(r).environment_id)) AND i.state='dispatching')
 AND NOT EXISTS(SELECT 1 FROM trigger_records receipt JOIN triggers consumer ON consumer.id=receipt.trigger_id
  WHERE consumer.queue_binding_id=ANY((r).queue_binding_ids) AND receipt.state='claimed' AND receipt.claim_expires_at>clock_timestamp())
 AND NOT EXISTS(SELECT 1 FROM job_tasks t JOIN job_runs j ON j.id=t.run_id WHERE j.job_id=(r).job_id AND t.status='claimed')
$$;


--
-- Name: environment_workload_retirement_gateway_roster(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_retirement_gateway_roster() RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
 SELECT ARRAY(SELECT name FROM compute_nodes WHERE active AND role IN ('compute-only','compute-node')
  AND nullif(btrim(gateway_target_url),'') IS NOT NULL ORDER BY name)
$$;


--
-- Name: environment_workload_retirement_routes_withdrawn(public.environment_workload_retirements); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_retirement_routes_withdrawn(r public.environment_workload_retirements) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT (r).route_deployment_id IS NULL OR ((r).route_generation>0 AND cardinality((r).expected_gateways)>0
  AND (r).expected_gateways=environment_workload_retirement_gateway_roster()
  AND (r).expected_gateways <@ (r).acknowledged_gateways)
$$;


--
-- Name: environment_workload_retirement_withdrawal_authorized(public.deployments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_retirement_withdrawal_authorized(d public.deployments) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM environment_workload_retirements r JOIN project_environments e ON e.id=r.environment_id
  WHERE r.phase='retiring' AND r.app_id=(d).app_id AND e.slug=(d).scope AND (d).id=ANY(r.deployment_ids)
   AND environment_workload_retirement_cutover_authorized(r))
$$;


--
-- Name: environment_workload_scheduled_job_acks(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_scheduled_job_acks(target_graph uuid, target_release uuid) RETURNS TABLE(app_id text, job_id text, job_run_id text, occurrence_id text, acknowledged_at timestamp with time zone, service_bindings jsonb)
    LANGUAGE sql STABLE
    AS $_$
SELECT member.value->>'app_id',managed_job.id::text,proof.run_id::text,proof.occurrence_id::text,proof.finished_at,
    coalesce(intent.service_bindings,'{}'::jsonb)
FROM environment_workload_graphs graph
JOIN active_environment_git_sources source ON source.id=graph.source_id
JOIN project_environments environment ON environment.id=source.environment_id
JOIN project_release_sets release ON release.id=target_release AND release.project_id=source.project_id
CROSS JOIN LATERAL jsonb_array_elements(graph.members) AS member(value)
JOIN app_environment_workload_intents intent ON intent.account_id=source.account_id
    AND intent.environment_id=source.environment_id AND intent.app_id::text=member.value->>'app_id'
    AND intent.job_id::text=member.value->>'job_id'
JOIN jobs managed_job ON managed_job.id=intent.job_id
JOIN project_release_members release_member ON release_member.release_id=release.id
    AND release_member.app_id=intent.app_id
JOIN deployments deployment ON deployment.id=release_member.deployment_id
    AND deployment.app_id=release_member.app_id AND deployment.status='live'
    AND NOT deployment.environment_workload_held AND deployment.scope=environment.slug
JOIN LATERAL (
    SELECT occurrence.id AS occurrence_id,run.id AS run_id,occurrence.finished_at
    FROM schedule_occurrences occurrence
    JOIN job_runs run ON run.id=occurrence.job_run_id AND run.job_id=managed_job.id
    WHERE occurrence.job_id=managed_job.id
        AND occurrence.schedule_revision=managed_job.schedule_revision
        AND occurrence.status='succeeded' AND occurrence.finished_at IS NOT NULL
        AND occurrence.created_at>=release.created_at
        AND occurrence.started_at IS NOT NULL AND occurrence.started_at>=release.created_at
        AND run.occurrence_id=occurrence.id AND run.trigger_kind='scheduled'
        AND run.aggregate_status='succeeded' AND run.finished_at IS NOT NULL
        AND run.created_at>=release.created_at AND run.started_at IS NOT NULL AND run.started_at>=release.created_at
        AND run.finished_at>=release.created_at
        AND occurrence.finished_at>=run.finished_at
        AND run.image_ref_snapshot=managed_job.image_ref
        AND run.image_resolved_digest_snapshot=managed_job.image_resolved_digest
        AND run.image_storage_key_snapshot=managed_job.image_storage_key
        AND run.retry_max=managed_job.retry_max
        AND run.task_timeout_s=managed_job.task_timeout_s
        AND run.parallelism=managed_job.max_parallelism
        AND run.command=managed_job.command
        AND run.ram_mb_snapshot=managed_job.ram_mb
        AND run.env_overrides=managed_job.env_overrides
        AND run.effective_env_snapshot=managed_job.env_overrides || run.env_overrides
        AND run.failure_rules IS NOT DISTINCT FROM managed_job.failure_rules
        AND run.execution_class='standard' AND run.failure_policy='continue' AND run.tasks=1
        AND run.input_manifest_version=0 AND coalesce(run.input_digest,'')=''
        AND run.input_manifest_uri IS NULL AND run.input_manifest_sha256 IS NULL
    ORDER BY occurrence.finished_at,occurrence.id
    LIMIT 1
) proof ON true
WHERE graph.id=target_graph AND graph.phase='prepared'
    AND source.mode='enforce' AND NOT source.suspended
    AND source.generation=graph.generation AND source.intent_version=graph.intent_version
    AND source.approved_revision_id=graph.revision_id
    AND release.active AND release.environment_slug=environment.slug
    AND member.value->>'execution_mode'='job'
    AND member.value->>'schedule_configured'='true'
    AND member.value->>'job_smoke_configured'='true'
    AND managed_job.id::text=member.value->>'job_id'
    AND managed_job.account_id=source.account_id AND managed_job.kind='recurring' AND managed_job.status='active'
    AND managed_job.image_materialization_status='ready'
    AND coalesce(managed_job.image_storage_key,'')<>''
    AND managed_job.image_resolved_digest=substring(intent.source->>'image' FROM '@(sha256:[a-f0-9]{64})$')
    AND intent.source->>'kind'='image' AND managed_job.image_ref=intent.source->>'image'
    AND intent.schedule IS NOT NULL AND managed_job.cron_schedule=intent.schedule->>'cron'
    AND managed_job.cron_timezone=intent.schedule->>'timezone'
    AND managed_job.schedule_policy IS NOT DISTINCT FROM NULLIF(intent.schedule->'schedule_policy','null'::jsonb)
    AND managed_job.failure_rules IS NOT DISTINCT FROM NULLIF(intent.schedule->'failure_rules','null'::jsonb)
    AND managed_job.max_parallelism=1 AND managed_job.retry_max=0
    AND managed_job.ram_mb>0 AND managed_job.task_timeout_s>0 AND cardinality(managed_job.command)=0
    AND managed_job.env_overrides=coalesce(nullif(member.value->'variables','null'::jsonb),'{}'::jsonb)
    AND coalesce(nullif(intent.variables,'null'::jsonb),'{}'::jsonb)=coalesce(nullif(member.value->'variables','null'::jsonb),'{}'::jsonb)
    AND coalesce(nullif(member.value->'service_bindings','null'::jsonb),'{}'::jsonb)=coalesce(intent.service_bindings,'{}'::jsonb)
    AND coalesce(member.value->>'service_bindings_configured','false')=(coalesce(intent.service_bindings,'{}'::jsonb)<>'{}'::jsonb)::text
    AND coalesce(member.value->>'queue_bindings_configured','false')='false'
    AND coalesce(nullif(member.value->'queue_modes','null'::jsonb),'{}'::jsonb)='{}'::jsonb
    AND (member.value->>'candidate_deployment_id'=deployment.id::text OR
        (nullif(member.value->>'candidate_deployment_id','') IS NULL
            AND coalesce(member.value->'retained_deployments','[]'::jsonb) ? deployment.id::text))
$_$;


--
-- Name: environment_workload_scheduled_jobs_ready(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_scheduled_jobs_ready(target_graph uuid, target_release uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT (SELECT count(*) FROM environment_workload_graphs graph
    CROSS JOIN LATERAL jsonb_array_elements(graph.members) AS member(value)
    WHERE graph.id=target_graph AND member.value->>'execution_mode'='job') =
    (SELECT count(*) FROM environment_workload_scheduled_job_acks(target_graph,target_release))
$$;


--
-- Name: environment_workload_serving_authorized(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_serving_authorized(target_source uuid, target_graph uuid, target_release uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS (
  SELECT 1
  FROM active_environment_git_sources src
  JOIN environment_gitops_jobs job ON job.source_id=src.id
  JOIN environment_workload_graphs graph ON graph.id=target_graph AND graph.source_id=src.id
  JOIN project_environments env ON env.id=src.environment_id
  JOIN project_release_sets release ON release.id=target_release AND release.project_id=src.project_id
      AND release.environment_slug=env.slug AND release.active
  WHERE src.id=target_source AND src.mode='enforce' AND NOT src.suspended
    AND src.generation=graph.generation AND src.intent_version=graph.intent_version
    AND src.approved_revision_id=graph.revision_id AND graph.phase='prepared'
    AND job.desired_generation=src.generation AND job.claimed_generation=src.generation
    AND job.lease_until>clock_timestamp() AND job.lease_token<>''
    AND job.lease_token=current_setting('gregale.gitops_lease',true)
    AND current_setting('gregale.gitops_serving',true)=job.lease_token
 )
$$;


--
-- Name: environment_workload_serving_gateway_roster_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_serving_gateway_roster_ready(target_graph uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT EXISTS (
    SELECT 1
    FROM environment_workload_serving_receipts receipt
    WHERE receipt.graph_id=target_graph
        AND cardinality(receipt.expected_gateways)=(
            SELECT count(DISTINCT gateway.name)
            FROM unnest(receipt.expected_gateways) AS gateway(name)
        )
        AND NOT EXISTS (
            SELECT 1 FROM unnest(receipt.expected_gateways) AS gateway(name)
            WHERE gateway.name IS NULL OR btrim(gateway.name)=''
        )
        AND (
            (NOT EXISTS (
                SELECT 1 FROM environment_workload_serving_routes route
                WHERE route.graph_id=target_graph
            ) AND cardinality(receipt.expected_gateways)=0)
            OR (EXISTS (
                SELECT 1 FROM environment_workload_serving_routes route
                WHERE route.graph_id=target_graph
            ) AND cardinality(receipt.expected_gateways)=(
                SELECT count(*) FROM compute_nodes node
                WHERE node.active AND node.role IN ('compute-only','compute-node')
                    AND nullif(btrim(node.gateway_target_url),'') IS NOT NULL
            ) AND NOT EXISTS (
                SELECT 1 FROM compute_nodes node
                WHERE node.active AND node.role IN ('compute-only','compute-node')
                    AND nullif(btrim(node.gateway_target_url),'') IS NOT NULL
                    AND NOT (node.name=ANY(receipt.expected_gateways))
            ))
        )
        AND NOT EXISTS (
            SELECT 1
            FROM environment_workload_serving_routes route
            CROSS JOIN LATERAL unnest(receipt.expected_gateways) AS gateway(name)
            WHERE route.graph_id=target_graph AND NOT EXISTS (
                SELECT 1 FROM environment_workload_serving_route_acks ack
                WHERE ack.graph_id=route.graph_id AND ack.route_generation=route.route_generation
                    AND ack.node_name=gateway.name
            )
        )
        AND NOT EXISTS (
            SELECT 1
            FROM environment_workload_serving_route_acks ack
            WHERE ack.graph_id=target_graph
                AND NOT (ack.node_name=ANY(receipt.expected_gateways))
        )
)
$$;


--
-- Name: environment_workload_serving_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_serving_ready(target_graph uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT environment_workload_serving_ready_without_scheduled_jobs(target_graph)
    AND environment_workload_serving_gateway_roster_ready(target_graph)
    AND EXISTS (
        SELECT 1 FROM environment_workload_serving_receipts receipt
        JOIN project_release_sets release ON release.id=receipt.release_set_id AND release.active
        WHERE receipt.graph_id=target_graph
            AND environment_workload_scheduled_jobs_ready(target_graph,release.id)
    )
$$;


--
-- Name: environment_workload_serving_ready_without_scheduled_jobs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_serving_ready_without_scheduled_jobs(target_graph uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT EXISTS (
    SELECT 1
    FROM environment_workload_serving_receipts receipt
    JOIN environment_workload_graphs graph ON graph.id=receipt.graph_id
    JOIN active_environment_git_sources source ON source.id=receipt.source_id
    JOIN project_environments environment ON environment.id=source.environment_id
    JOIN project_release_sets release ON release.id=receipt.release_set_id AND release.active
    WHERE receipt.graph_id=target_graph AND source.mode='enforce' AND NOT source.suspended
        AND source.generation=graph.generation AND source.intent_version=graph.intent_version
        AND source.approved_revision_id=graph.revision_id
        AND environment_workload_graph_serving_supported(graph.id)
        AND (SELECT count(*) FROM environment_workload_serving_routes route WHERE route.graph_id=graph.id)=(
            SELECT count(*) FROM jsonb_array_elements(graph.members) AS graph_member(value)
            WHERE graph_member.value->>'execution_mode' IN ('request','service')
        )
        AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(graph.members) AS graph_member(value)
            WHERE graph_member.value->>'execution_mode' IN ('request','service')
                AND NOT EXISTS (
                    SELECT 1 FROM environment_workload_serving_routes route
                    JOIN project_release_members release_member ON release_member.release_id=release.id
                        AND release_member.app_id=route.app_id AND release_member.deployment_id=route.deployment_id
                    WHERE route.graph_id=graph.id AND route.app_id::text=graph_member.value->>'app_id'
                        AND ((route.cutover_required AND route.deployment_id::text=graph_member.value->>'candidate_deployment_id') OR
                            (NOT route.cutover_required AND nullif(graph_member.value->>'candidate_deployment_id','') IS NULL
                                AND coalesce(graph_member.value->'retained_deployments','[]'::jsonb) ? route.deployment_id::text))
                )
        )
        AND (NOT EXISTS (SELECT 1 FROM environment_workload_serving_routes route WHERE route.graph_id=graph.id)
            OR cardinality(receipt.expected_gateways)>0)
        AND NOT EXISTS (
            SELECT 1 FROM environment_workload_serving_routes route
            WHERE route.graph_id=graph.id AND (SELECT count(*) FROM environment_workload_serving_route_acks ack
                WHERE ack.graph_id=route.graph_id AND ack.route_generation=route.route_generation)<>cardinality(receipt.expected_gateways)
        )
        AND NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements(graph.members) AS graph_member(value)
            CROSS JOIN LATERAL jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
            LEFT JOIN queue_bindings binding ON binding.id::text=queue_binding.value->>'binding_id'
            WHERE (graph_member.value->>'execution_mode'='worker' OR
                (graph_member.value->>'execution_mode'='request' AND graph_member.value->>'function'='true'))
                AND queue_binding.value->'contract'->>'enabled'='true'
                AND (binding.id IS NULL OR binding.app_id::text<>graph_member.value->>'app_id'
                    OR binding.account_id<>source.account_id
                    OR binding.environment_id<>source.environment_id OR binding.deployment_scope<>environment.slug
                    OR binding.name<>queue_binding.name OR binding.queue_name<>queue_binding.value->'contract'->>'queue_name'
                    OR binding.mode<>queue_binding.value->'contract'->>'mode'
                    OR binding.workload_class<>queue_binding.value->'contract'->>'workload_class'
                    OR binding.enabled IS DISTINCT FROM (queue_binding.value->'contract'->>'enabled')::boolean
                    OR binding.max_concurrency::text<>queue_binding.value->'contract'->>'max_concurrency'
                    OR coalesce(nullif(queue_binding.value->'contract'->'retry_policy','null'::jsonb),'{}'::jsonb)<>binding.retry_policy
                    OR binding.retired_at IS NOT NULL
                    OR (binding.mode='push' AND NOT EXISTS (
                        SELECT 1 FROM triggers queue_trigger
                        WHERE queue_trigger.id::text=queue_binding.value->>'trigger_id'
                            AND queue_trigger.app_id=binding.app_id AND queue_trigger.queue_binding_id=binding.id
                            AND queue_trigger.account_id=source.account_id
                            AND queue_trigger.enabled AND queue_trigger.kind='queue' AND queue_trigger.source='queue'
                            AND queue_trigger.slug=queue_binding.value->'contract'->>'queue_name'
                            AND queue_trigger.queue_binding_scope=environment.slug
                            AND queue_trigger.queue_binding_environment_id=source.environment_id
                    ))
                    OR (binding.mode='pull' AND coalesce(queue_binding.value->>'trigger_id','')<>'')
                    OR binding.mode NOT IN ('push','pull'))
        )
        AND (SELECT count(*) FROM environment_workload_serving_queue_acks ack WHERE ack.graph_id=graph.id)=(
            SELECT count(*)
            FROM jsonb_array_elements(graph.members) AS graph_member(value)
            CROSS JOIN LATERAL jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
            WHERE (graph_member.value->>'execution_mode'='worker' OR
                (graph_member.value->>'execution_mode'='request' AND graph_member.value->>'function'='true'))
                AND queue_binding.value->'contract'->>'enabled'='true'
        )
        AND NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements(graph.members) AS graph_member(value)
            CROSS JOIN LATERAL jsonb_each(coalesce(nullif(graph_member.value->'queue_bindings','null'::jsonb),'{}'::jsonb)) AS queue_binding(name,value)
            LEFT JOIN environment_workload_serving_queue_acks ack ON ack.graph_id=graph.id
                AND ack.binding_id::text=queue_binding.value->>'binding_id'
            WHERE (graph_member.value->>'execution_mode'='worker' OR
                (graph_member.value->>'execution_mode'='request' AND graph_member.value->>'function'='true'))
                AND queue_binding.value->'contract'->>'enabled'='true'
                AND (ack.graph_id IS NULL OR ack.mode<>queue_binding.value->'contract'->>'mode'
                    OR ack.app_id::text<>graph_member.value->>'app_id'
                    OR (ack.mode='push' AND ack.trigger_id::text<>queue_binding.value->>'trigger_id')
                    OR (ack.mode='pull' AND ack.trigger_id IS NOT NULL)
                    OR NOT EXISTS (
                        SELECT 1 FROM project_release_members release_member
                        JOIN deployments deployment ON deployment.id=release_member.deployment_id
                            AND deployment.app_id=release_member.app_id AND deployment.status='live'
                            AND NOT deployment.environment_workload_held AND deployment.scope=environment.slug
                        WHERE release_member.release_id=release.id AND release_member.app_id=ack.app_id
                            AND release_member.deployment_id=ack.deployment_id
                            AND (graph_member.value->>'candidate_deployment_id'=ack.deployment_id::text OR
                                (nullif(graph_member.value->>'candidate_deployment_id','') IS NULL
                                    AND coalesce(graph_member.value->'retained_deployments','[]'::jsonb) ? ack.deployment_id::text))
                    ))
        )
)
$$;


--
-- Name: environment_workload_serving_traffic_authorized(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_serving_traffic_authorized(target_app uuid, target_scope text, target_deployment uuid, target_traffic integer) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS (
  SELECT 1
  FROM active_environment_git_sources src
  JOIN environment_gitops_jobs job ON job.source_id=src.id
  JOIN project_environments env ON env.id=src.environment_id AND env.slug=target_scope
  JOIN environment_workload_graphs graph ON graph.source_id=src.id AND graph.phase='prepared'
  JOIN environment_workload_serving_receipts receipt ON receipt.graph_id=graph.id AND receipt.phase='pending'
  JOIN environment_workload_serving_routes route ON route.graph_id=receipt.graph_id AND route.app_id=target_app
  JOIN project_release_sets release ON release.id=receipt.release_set_id AND release.active
  JOIN project_release_members rm ON rm.release_id=release.id AND rm.app_id=route.app_id AND rm.deployment_id=route.deployment_id
  CROSS JOIN LATERAL jsonb_array_elements(graph.members) member
  WHERE src.id=receipt.source_id AND src.mode='enforce' AND NOT src.suspended
    AND src.generation=graph.generation AND src.intent_version=graph.intent_version
    AND src.approved_revision_id=graph.revision_id AND graph.plan_hash=receipt.plan_hash
    AND member->>'app_id'=target_app::text AND member->>'execution_mode' IN ('request','service')
    AND coalesce(member->'queue_modes','{}'::jsonb) IN ('{}'::jsonb,'null'::jsonb)
    AND route.cutover_required AND member->>'candidate_deployment_id'=route.deployment_id::text
    AND job.desired_generation=src.generation AND job.claimed_generation=src.generation
    AND job.lease_until>clock_timestamp() AND job.lease_token<>''
    AND job.lease_token=current_setting('gregale.gitops_lease',true)
    AND current_setting('gregale.gitops_serving',true)=job.lease_token
    AND ((target_deployment=route.deployment_id AND target_traffic=100) OR
         (target_deployment<>route.deployment_id AND target_traffic=0))
 )
$$;


--
-- Name: event_backlog_waiting_reason(text, text, text, timestamp with time zone, timestamp with time zone, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_backlog_waiting_reason(routing_state text, capacity_scope text, routing_mode text, lease_until timestamp with time zone, next_attempt_at timestamp with time zone, consumer_kind text, blocker jsonb, observed_at timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
SELECT CASE
 WHEN routing_state = 'processing' THEN 'routing_in_progress'
 WHEN blocker IS NOT NULL THEN 'ordering_blocked'
 WHEN routing_state = 'pending' AND capacity_scope <> '' THEN 'capacity_' || capacity_scope
 WHEN routing_mode = 'event' AND lease_until > observed_at THEN 'receipt_processing'
 WHEN next_attempt_at > observed_at THEN 'retry_backoff'
 WHEN consumer_kind = 'workflow' THEN 'workflow_routing'
 ELSE 'ready' END;
$$;


--
-- Name: event_fanout_pattern_matches(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_fanout_pattern_matches(pattern text, value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT CASE
        WHEN pattern = '*' THEN true
        WHEN left(pattern, 1) = '*' AND right(pattern, 1) = '*' THEN
            position(substring(pattern, 2, greatest(length(pattern) - 2, 0)) in value) > 0
        WHEN left(pattern, 1) = '*' THEN
            right(value, greatest(length(pattern) - 1, 0)) = right(pattern, greatest(length(pattern) - 1, 0))
        WHEN right(pattern, 1) = '*' THEN
            left(value, greatest(length(pattern) - 1, 0)) = left(pattern, greatest(length(pattern) - 1, 0))
        ELSE pattern = value
    END
$$;


--
-- Name: event_order_lane_active(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_order_lane_active(lane_app_id text, lane_policy_name text, configured_ordered boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT coalesce(configured_ordered, false) OR EXISTS (
    SELECT 1 FROM event_subscription_work_bindings b
    WHERE b.app_id = lane_app_id::uuid
      AND b.policy_name = lane_policy_name
      AND b.ordered
);
$$;


--
-- Name: event_order_lane_lock_id(text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_order_lane_lock_id(lane_app_id text, lane_policy_name text, event_payload jsonb, key_selector text) RETURNS bigint
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
WITH selected AS (
    SELECT event_payload #> string_to_array(key_selector, '.') AS value
), canonical AS (
    SELECT CASE jsonb_typeof(value)
        WHEN 'string' THEN 's:' || (value #>> '{}')
        WHEN 'number' THEN 'n:' || trim_scale((value #>> '{}')::numeric)::text
        WHEN 'boolean' THEN 'b:' || (value #>> '{}')
        ELSE NULL
    END AS key
    FROM selected
)
SELECT CASE WHEN key IS NULL OR key = 's:' THEN NULL
    ELSE hashtextextended(jsonb_build_array(lane_app_id, lane_policy_name, key)::text, 0)
    END
FROM canonical;
$$;


--
-- Name: event_receipt_retention_hold(uuid, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_receipt_retention_hold(p_account uuid, p_outbox bigint, p_accepted timestamp with time zone, p_job_cutoff timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    AS $$
 SELECT event_receipt_retention_hold(p_account,p_outbox,p_accepted,p_job_cutoff,CURRENT_TIMESTAMP);
$$;


--
-- Name: event_receipt_retention_hold(uuid, bigint, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_receipt_retention_hold(p_account uuid, p_outbox bigint, p_accepted timestamp with time zone, p_job_cutoff timestamp with time zone, p_now timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE
 WHEN EXISTS (SELECT 1 FROM event_replay_jobs j WHERE j.account_id=p_account AND j.state='running'
  AND p_accepted>=j.from_at AND p_accepted<j.cutoff_at) THEN 'backfill_running'
 WHEN EXISTS (SELECT 1 FROM event_replay_jobs j WHERE j.account_id=p_account AND j.state='completed_with_failures'
  AND j.completed_at>=p_job_cutoff AND EXISTS (SELECT 1 FROM event_replay_job_items i
   WHERE i.job_id=j.id AND i.outbox_id=p_outbox AND i.state='failed' AND i.retryable)) THEN 'backfill_retryable'
 WHEN EXISTS (SELECT 1 FROM event_recovery_items i JOIN event_recovery_jobs j ON j.id=i.job_id
  WHERE i.outbox_id=p_outbox AND i.state='pending' AND j.account_id=p_account
   AND j.selection->'protect_receipts'='true'::jsonb AND j.state IN ('running','paused') AND j.expires_at>p_now) THEN 'recovery_pending'
 ELSE '' END;
$$;


--
-- Name: event_recipient_delivery_deadline(jsonb, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_recipient_delivery_deadline(recipient jsonb, accepted_at timestamp with time zone, progress jsonb) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN recipient ? 'workflow' OR recipient ? 'object_notification'
 OR coalesce((recipient->'work'->>'ordered')::boolean,false)
 OR coalesce((progress->>'delivery_age_override')::boolean,false)
 OR coalesce((recipient->>'delivery_age_override')::boolean,false)
 OR coalesce((recipient->'routing_retry_policy'->>'max_delivery_age_ms')::bigint,0)=0 THEN NULL
 ELSE accepted_at + ((recipient->'routing_retry_policy'->>'max_delivery_age_ms')::bigint * interval '1 millisecond') END;
$$;


--
-- Name: event_recipient_order_blocked(bigint, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_recipient_order_blocked(target_outbox_id bigint, target_subscription_id text, target_recipient jsonb, include_same_receipt boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT event_recipient_order_blocker(target_outbox_id, target_subscription_id, target_recipient, include_same_receipt) IS NOT NULL;
$$;


--
-- Name: event_recipient_order_blocker(bigint, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_recipient_order_blocker(target_outbox_id bigint, target_subscription_id text, target_recipient jsonb, include_same_receipt boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
WITH current_event AS (
    SELECT o.id, o.account_id, o.payload,
        (SELECT item.position
         FROM jsonb_array_elements(coalesce(o.recipient_snapshot, '[]'::jsonb))
              WITH ORDINALITY AS item(recipient, position)
         WHERE item.recipient->>'id' = target_subscription_id
         LIMIT 1) AS position,
        (SELECT coalesce((item.recipient->'work'->>'routing_order')::bigint, o.id)
         FROM jsonb_array_elements(coalesce(o.recipient_snapshot, '[]'::jsonb))
              WITH ORDINALITY AS item(recipient, position)
         WHERE item.recipient->>'id' = target_subscription_id
         LIMIT 1) AS routing_order
    FROM event_fanout_outbox o
    WHERE o.id = target_outbox_id
)
SELECT (
    SELECT jsonb_build_object(
        'event_source', prior.source, 'event_id', prior.event_id,
        'subscription_id', item.recipient->>'id', 'accepted_at', prior.created_at,
        'state', coalesce(routed.state, prior.recipient_progress->(item.recipient->>'id')->>'state', 'pending'),
        'next_attempt_at', CASE WHEN routed.state = 'pending' THEN routed.available_at
          WHEN routed.state IS NULL AND coalesce(prior.recipient_progress->(item.recipient->>'id')->>'state','pending') = 'pending'
          THEN coalesce((prior.recipient_progress->(item.recipient->>'id')->>'next_attempt_at')::timestamptz, prior.available_at) ELSE NULL END)
    FROM current_event current
    JOIN event_fanout_outbox prior ON prior.account_id = current.account_id
    CROSS JOIN LATERAL jsonb_array_elements(coalesce(prior.recipient_snapshot, '[]'::jsonb))
        WITH ORDINALITY AS item(recipient, position)
    LEFT JOIN event_fanout_recipients routed
      ON routed.outbox_id = prior.id AND routed.subscription_id = item.recipient->>'id'
    WHERE ((prior.id <> current.id AND
            (coalesce((item.recipient->'work'->>'routing_order')::bigint, prior.id) < current.routing_order OR
             (item.recipient->'work'->>'routing_order' IS NULL AND
              target_recipient->'work'->>'routing_order' IS NOT NULL AND prior.id < current.id))) OR
           (include_same_receipt AND prior.id = current.id AND item.position < current.position))
      AND prior.state <> 'delivered'
      AND item.recipient->>'app_id' = target_recipient->>'app_id'
      AND item.recipient->'work'->>'policy_name' = target_recipient->'work'->>'policy_name'
      AND item.recipient->'work'->>'policy_name' <> ''
      AND event_order_lane_lock_id(item.recipient->>'app_id',
          item.recipient->'work'->>'policy_name', prior.payload,
          item.recipient->'work'->>'key_selector') IS NOT NULL
      AND event_order_lane_lock_id(target_recipient->>'app_id',
          target_recipient->'work'->>'policy_name', current.payload,
          target_recipient->'work'->>'key_selector') IS NOT NULL
      AND (coalesce((item.recipient->'work'->>'ordered')::boolean, false) OR
           item.recipient->'work'->>'routing_order' IS NOT NULL OR
           coalesce((target_recipient->'work'->>'ordered')::boolean, false) OR
           target_recipient->'work'->>'routing_order' IS NOT NULL)
      AND prior.payload #> string_to_array(item.recipient->'work'->>'key_selector', '.')
          IS NOT DISTINCT FROM
          current.payload #> string_to_array(target_recipient->'work'->>'key_selector', '.')
      AND coalesce(routed.state,
          (prior.recipient_progress->(item.recipient->>'id'))->>'state', 'pending')
          NOT IN ('enqueued', 'filtered', 'failed')
    ORDER BY coalesce((item.recipient->'work'->>'routing_order')::bigint, prior.id), prior.id, item.position
    LIMIT 1
);
$$;


--
-- Name: event_recipient_schema_version_mismatch(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_recipient_schema_version_mismatch(recipient jsonb, payload jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT NOT recipient ? 'workflow' AND NOT recipient ? 'object_notification' AND jsonb_array_length(coalesce(recipient->'schema_versions','[]'::jsonb))>0 AND NOT (recipient->'schema_versions' ? coalesce(payload->>'schemaversion',''));
$$;


--
-- Name: event_recovery_failure_identity(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_recovery_failure_identity(progress jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
SELECT jsonb_build_object('state',progress->'state','attempts',progress->'attempts',
 'updated_at',progress->'updated_at','failure_code',progress->'failure_code','retryable',progress->'retryable');
$$;


--
-- Name: event_subscription_delivery_waiting_reason(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_subscription_delivery_waiting_reason(account uuid, app uuid, subscription text, observed_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    AS $$
SELECT coalesce((SELECT CASE WHEN c.paused THEN 'subscription_paused'
 WHEN b.state_data->>'state'='open' AND (b.state_data->>'cooldown_until')::timestamptz>observed_at THEN 'circuit_open'
 WHEN b.state_data->>'state'='half_open' AND ((coalesce(b.state_data->>'probe_token','')<>'' AND (b.state_data->>'probe_until')::timestamptz>observed_at) OR (b.state_data->>'next_probe_at')::timestamptz>observed_at) THEN 'circuit_probe_wait'
 WHEN b.state_data->>'state'='draining' AND (b.state_data->>'recovery_window')::timestamptz+interval '1 second'>observed_at
 AND (b.state_data->>'recovery_count')::integer>=least((b.policy->>'recovery_max_rate_per_second')::integer,
 power(2,least(7,greatest(0,floor(extract(epoch FROM observed_at-(b.state_data->>'changed_at')::timestamptz)/10))))::integer) THEN 'circuit_recovery_rate_limited'
 WHEN c.rate_enabled AND (c.rate_refilled_at>observed_at OR c.rate_credit_ms+greatest(0,floor(extract(epoch FROM observed_at-c.rate_refilled_at)*1000))<c.rate_interval_ms) THEN 'subscription_rate_limited'
 WHEN c.rate_per_second>0 AND c.window_count>=c.rate_per_second AND c.window_started_at+interval '1 second'>observed_at THEN 'subscription_rate_limited' ELSE '' END
 FROM event_subscription_delivery_controls c JOIN apps a ON a.id=c.app_id AND a.account_id=c.account_id AND a.status<>'deleted'
 LEFT JOIN event_subscription_circuit_breakers b ON b.subscription_id=c.subscription_id AND b.account_id=c.account_id AND b.app_id=c.app_id
 WHERE c.account_id=account AND c.app_id=app AND c.subscription_id::text=subscription),'');
$$;


--
-- Name: exclusive_work_instance_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exclusive_work_instance_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE old_incarnation text;
BEGIN
  old_incarnation := old.id::text || '/' || old.wake_id::text || '/' || old.node_id::text;
  IF new.state IN ('snapshotting','parked') AND new.state IS DISTINCT FROM old.state
     AND EXISTS(SELECT 1 FROM exclusive_work_operations WHERE state='running'
       AND incarnation_id=old_incarnation AND lease_expires_at>clock_timestamp()
       AND attempt_deadline>clock_timestamp()) THEN
    RAISE EXCEPTION 'active exclusive operation prevents parking' USING errcode='55000';
  END IF;
  IF new.wake_id IS DISTINCT FROM old.wake_id OR new.node_id IS DISTINCT FROM old.node_id
     OR new.state IS DISTINCT FROM old.state THEN
    UPDATE exclusive_work_operations SET state='pending',claim_token=NULL,
      lease_expires_at=NULL,attempt_deadline=NULL,last_error='runtime incarnation revoked',
      due_at=clock_timestamp()
    WHERE state='running' AND incarnation_id=old_incarnation;
    NEW.exclusive_capture_blocked := false;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: exclusive_work_release_quota(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exclusive_work_release_quota() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.quota_reserved AND NEW.state<>'running' THEN
    UPDATE account_async_quota SET current_inflight=greatest(0,current_inflight-1),updated_at=clock_timestamp()
      WHERE account_id=OLD.account_id;
    NEW.quota_reserved := false;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: faas_advance_realtime_inbox_cursor(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_advance_realtime_inbox_cursor(ep uuid, pk text, device text, requested bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE previous bigint; current_seq bigint;
BEGIN
 SELECT sequence INTO previous FROM managed_realtime_inbox_cursors
 WHERE endpoint_id=ep AND principal=pk AND subscription=device AND channel=pk FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 current_seq:=faas_advance_realtime_inbox_cursor_before_push(ep,pk,device,requested);
 UPDATE managed_realtime_push_deliveries SET status='cancelled',code='acknowledged',updated_at=clock_timestamp(),lease=NULL,lease_until=NULL
 WHERE endpoint_id=ep AND principal=pk AND sequence>previous AND sequence<=current_seq AND status IN ('pending','sending');
 RETURN current_seq;
END $$;


--
-- Name: faas_advance_realtime_inbox_cursor_before_fallback(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_advance_realtime_inbox_cursor_before_fallback(ep uuid, pk text, device text, requested bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE previous bigint; current_seq bigint; mid text; floor_seq bigint;
BEGIN
  SELECT sequence INTO previous FROM managed_realtime_inbox_cursors
    WHERE endpoint_id = ep AND principal = pk AND subscription = device AND channel = pk FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  current_seq := greatest(previous, requested);
  SELECT greatest(h.oldest_sequence, coalesce((SELECT max(m.sequence) + 1
    FROM managed_realtime_inbox_messages m WHERE m.endpoint_id = ep AND m.channel = pk
      AND m.created_at < clock_timestamp() - interval '24 hours'), 1))
    INTO floor_seq FROM managed_realtime_inbox_heads h WHERE h.endpoint_id = ep AND h.channel = pk;
  UPDATE managed_realtime_inbox_cursors SET sequence = current_seq, updated_at = clock_timestamp(),
    gap_reported = CASE WHEN current_seq >= floor_seq - 1 THEN false ELSE gap_reported END
    WHERE endpoint_id = ep AND principal = pk AND subscription = device AND channel = pk;
  IF current_seq > previous THEN
    SELECT target_message_id INTO mid FROM managed_realtime_inbox_messages
      WHERE endpoint_id = ep AND channel = pk AND sequence = current_seq;
    PERFORM faas_capture_realtime_inbox_webhook(ep, pk, device, 'realtime.inbox.acknowledged',
      jsonb_build_object('previous_sequence', previous, 'sequence', current_seq, 'message_id', mid));
  END IF;
  RETURN current_seq;
END $$;


--
-- Name: faas_advance_realtime_inbox_cursor_before_push(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_advance_realtime_inbox_cursor_before_push(ep uuid, pk text, device text, requested bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE previous bigint; current_seq bigint; pending record;
BEGIN
 SELECT sequence INTO previous FROM managed_realtime_inbox_cursors
   WHERE endpoint_id = ep AND principal = pk AND subscription = device AND channel = pk FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 current_seq := faas_advance_realtime_inbox_cursor_before_fallback(ep,pk,device,requested);
 IF current_seq > previous THEN
   FOR pending IN SELECT sequence FROM managed_realtime_inbox_fallbacks
     WHERE endpoint_id = ep AND principal = pk AND sequence > previous AND sequence <= current_seq
     ORDER BY deadline, sequence FOR UPDATE
   LOOP
     DELETE FROM managed_realtime_inbox_fallbacks WHERE endpoint_id = ep AND principal = pk AND sequence = pending.sequence;
   END LOOP;
 END IF;
 RETURN current_seq;
END $$;


--
-- Name: faas_capture_app_webhook_dead_letter_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_app_webhook_dead_letter_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'dead' AND OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO dead_letter_events (
            account_id, app_id, source, source_id, origin, event_payload,
            headers, error_kind, error_detail, retry_count,
            first_failed_at, last_failed_at, created_at
        ) VALUES (
            NEW.account_id, NEW.app_id, 'webhook_delivery', NEW.id, NEW.event,
            COALESCE(NEW.payload, '{}'::jsonb), '{}'::jsonb,
            CASE WHEN NEW.last_response_code IS NULL
                 THEN 'delivery_failed'
                 ELSE 'http_' || NEW.last_response_code::text END,
            jsonb_build_object(
                'last_error', COALESCE(NEW.last_error, ''),
                'last_response_code', NEW.last_response_code
            ),
            NEW.attempt, COALESCE(NEW.updated_at, NOW()),
            COALESCE(NEW.updated_at, NOW()), COALESCE(NEW.created_at, NOW())
        )
        ON CONFLICT (source, source_id) DO UPDATE SET
            origin = EXCLUDED.origin,
            event_payload = EXCLUDED.event_payload,
            headers = EXCLUDED.headers,
            error_kind = EXCLUDED.error_kind,
            error_detail = EXCLUDED.error_detail,
            retry_count = EXCLUDED.retry_count,
            last_failed_at = EXCLUDED.last_failed_at,
            replayed_at = NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: faas_capture_invocation_dead_letter_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_invocation_dead_letter_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state = 'dead_letter' AND OLD.state IS DISTINCT FROM NEW.state THEN
        INSERT INTO dead_letter_events (
            account_id, app_id, source, source_id, origin, event_payload,
            headers, error_kind, error_detail, retry_count,
            first_failed_at, last_failed_at, created_at
        ) VALUES (
            NEW.account_id, NEW.app_id, 'invocation', NEW.id,
            CASE
                WHEN COALESCE(NEW.headers->>'x-gregale-event-id', '') <> ''
                    THEN 'event_subscription'
                ELSE NEW.source
            END,
            COALESCE(NEW.payload, '{}'::jsonb),
            COALESCE(NEW.headers, '{}'::jsonb),
            COALESCE(NULLIF(NEW.outcome, ''), 'dead_letter'),
            jsonb_build_object('last_error', COALESCE(NEW.last_error, '')),
            NEW.attempts,
            COALESCE(NEW.completed_at, NOW()),
            COALESCE(NEW.completed_at, NOW()),
            COALESCE(NEW.completed_at, NOW())
        )
        ON CONFLICT (source, source_id) DO UPDATE SET
            origin = EXCLUDED.origin,
            event_payload = EXCLUDED.event_payload,
            headers = EXCLUDED.headers,
            error_kind = EXCLUDED.error_kind,
            error_detail = EXCLUDED.error_detail,
            retry_count = EXCLUDED.retry_count,
            last_failed_at = EXCLUDED.last_failed_at,
            replayed_at = NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: faas_capture_job_dead_letter_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_job_dead_letter_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.dead_letter_count > COALESCE(OLD.dead_letter_count, 0) THEN
        INSERT INTO dead_letter_events (
            account_id, app_id, source, source_id, origin, event_payload,
            headers, error_kind, error_detail, retry_count,
            first_failed_at, last_failed_at, created_at
        ) VALUES (
            NEW.account_id, NULL, 'job_run', NEW.id, NEW.trigger_kind,
            jsonb_build_object(
                'job_id', NEW.job_id::text,
                'trigger_kind', NEW.trigger_kind,
                'tasks', NEW.tasks,
                'tasks_failed', NEW.tasks_failed,
                'dead_letter_count', NEW.dead_letter_count
            ),
            '{}'::jsonb,
            'job_run_dead_letter',
            jsonb_build_object(
                'dead_letter_count', NEW.dead_letter_count,
                'tasks_failed', NEW.tasks_failed
            ),
            NEW.dead_letter_count,
            COALESCE(NEW.finished_at, NOW()),
            COALESCE(NEW.finished_at, NOW()),
            COALESCE(NEW.finished_at, NOW())
        )
        ON CONFLICT (source, source_id) DO UPDATE SET
            event_payload = EXCLUDED.event_payload,
            error_detail = EXCLUDED.error_detail,
            retry_count = EXCLUDED.retry_count,
            last_failed_at = EXCLUDED.last_failed_at,
            replayed_at = NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: faas_capture_realtime_inbox_webhook(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_realtime_inbox_webhook(ep uuid, principal_key text, consumer text, event_name text, details jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE a uuid; account uuid; recipients uuid[]; eid uuid := gen_random_uuid();
BEGIN
  SELECT app_id, account_id INTO a, account FROM managed_realtime_endpoints WHERE id = ep;
  SELECT array_agg(id ORDER BY id) INTO recipients FROM app_webhooks
    WHERE app_id = a AND account_id = account AND scope = 'app' AND enabled
      AND (cardinality(event_filter) = 0 OR event_name = ANY(event_filter));
  IF coalesce(cardinality(recipients), 0) = 0 THEN RETURN; END IF;
  INSERT INTO app_webhook_event_outbox(id, account_id, app_id, event, source_id, payload, recipient_webhook_ids)
    VALUES(eid, account, a, event_name, eid,
      details || jsonb_build_object('event_id', eid, 'app_id', a, 'endpoint_id', ep,
        'principal_key', principal_key, 'consumer', consumer, 'occurred_at', clock_timestamp()), recipients);
END $$;


--
-- Name: faas_capture_trigger_dead_letter_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_trigger_dead_letter_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO dead_letter_events (
        account_id, app_id, source, source_id, origin, trigger_id,
        event_payload, headers, error_kind, error_detail, retry_count,
        first_failed_at, last_failed_at, created_at
    )
    SELECT t.account_id, t.app_id, 'trigger_record', NEW.record_id,
           t.kind, NEW.trigger_id,
           COALESCE(r.payload, '{}'::jsonb),
           COALESCE(r.headers, '{}'::jsonb),
           NEW.reason, COALESCE(NEW.detail, '{}'::jsonb),
           COALESCE(r.attempts, 0), NEW.created_at, NEW.created_at, NEW.created_at
      FROM triggers t
      JOIN trigger_records r ON r.id = NEW.record_id
     WHERE t.id = NEW.trigger_id
    ON CONFLICT (source, source_id) DO UPDATE SET
        origin = EXCLUDED.origin,
        trigger_id = EXCLUDED.trigger_id,
        event_payload = EXCLUDED.event_payload,
        headers = EXCLUDED.headers,
        error_kind = EXCLUDED.error_kind,
        error_detail = EXCLUDED.error_detail,
        retry_count = EXCLUDED.retry_count,
        last_failed_at = EXCLUDED.last_failed_at,
        replayed_at = NULL;
    RETURN NEW;
END;
$$;


--
-- Name: faas_capture_workflow_dead_letter_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_workflow_dead_letter_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'dead' AND OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO dead_letter_events (
            account_id, app_id, source, source_id, origin, event_payload,
            headers, error_kind, error_detail, retry_count,
            first_failed_at, last_failed_at, created_at
        )
        SELECT a.account_id, NEW.app_id, 'workflow_run', NEW.id,
               NEW.workflow_name,
               jsonb_build_object(
                   'workflow_name', NEW.workflow_name,
                   'input', COALESCE(NEW.input, '{}'::jsonb),
                   'current_step', NEW.current_step
               ),
               '{}'::jsonb,
               'workflow_run_dead',
               jsonb_build_object('last_error', COALESCE(NEW.last_error, '')),
               COALESCE((
                   SELECT MAX(ws.attempt) FROM workflow_steps ws
                    WHERE ws.run_id = NEW.id
               ), 0),
               COALESCE(NEW.finished_at, NOW()),
               COALESCE(NEW.finished_at, NOW()),
               COALESCE(NEW.finished_at, NOW())
          FROM apps a
         WHERE a.id = NEW.app_id
        ON CONFLICT (source, source_id) DO UPDATE SET
            event_payload = EXCLUDED.event_payload,
            error_detail = EXCLUDED.error_detail,
            retry_count = EXCLUDED.retry_count,
            last_failed_at = EXCLUDED.last_failed_at,
            replayed_at = NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: faas_capture_workflow_finished_webhook_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_workflow_finished_webhook_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_account_id uuid;
    recipient_ids uuid[];
    event_finished_at timestamptz;
BEGIN
    IF OLD.status IS NOT DISTINCT FROM NEW.status
       OR OLD.status IN ('succeeded', 'failed', 'dead')
       OR NEW.status NOT IN ('succeeded', 'failed', 'dead') THEN
        RETURN NEW;
    END IF;

    SELECT a.account_id,
           COALESCE(
               array_agg(h.id ORDER BY h.id) FILTER (WHERE h.id IS NOT NULL),
               ARRAY[]::uuid[]
           )
      INTO event_account_id, recipient_ids
      FROM apps a
      LEFT JOIN app_webhooks h
        ON h.app_id = NEW.app_id
       AND h.account_id = a.account_id
       AND h.scope = 'app'
       AND h.enabled
       AND (cardinality(h.event_filter) = 0 OR 'workflow.finished' = ANY(h.event_filter))
     WHERE a.id = NEW.app_id
     GROUP BY a.account_id;

    IF COALESCE(cardinality(recipient_ids), 0) = 0 THEN
        RETURN NEW;
    END IF;

    event_finished_at := COALESCE(NEW.finished_at, clock_timestamp());
    INSERT INTO app_webhook_event_outbox (
        account_id, app_id, event, source_id, payload, recipient_webhook_ids
    ) VALUES (
        event_account_id,
        NEW.app_id,
        'workflow.finished',
        gen_random_uuid(),
        jsonb_build_object(
            'app_id', NEW.app_id::text,
            'run_id', NEW.id::text,
            'workflow_name', NEW.workflow_name,
            'status', NEW.status,
            'finished_at', event_finished_at,
            'resume_count', NEW.resume_count
        ),
        recipient_ids
    ) ON CONFLICT (event, source_id) DO NOTHING;

    RETURN NEW;
END;
$$;


--
-- Name: faas_drain_realtime_inbox_fallbacks(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_drain_realtime_inbox_fallbacks(batch_size integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE f record; recipients uuid[]; devices jsonb; processed integer:=0; total integer; eid uuid;
BEGIN
 FOR f IN SELECT pending.*,ep.app_id,ep.account_id FROM managed_realtime_inbox_fallbacks pending
 JOIN managed_realtime_endpoints ep ON ep.id=pending.endpoint_id AND ep.enabled
 WHERE pending.deadline<=clock_timestamp() AND (
 EXISTS(SELECT 1 FROM app_webhooks h WHERE h.app_id=ep.app_id AND h.account_id=ep.account_id AND h.scope='app' AND h.enabled AND (cardinality(h.event_filter)=0 OR 'realtime.inbox.fallback_required'=ANY(h.event_filter)))
 OR EXISTS(SELECT 1 FROM managed_realtime_push_devices d JOIN managed_realtime_push_providers p USING(endpoint_id,provider) WHERE d.endpoint_id=ep.id AND d.principal=pending.principal AND d.enabled AND p.enabled))
 AND (SELECT count(*) FROM managed_realtime_push_deliveries j WHERE j.endpoint_id=ep.id AND j.status IN ('pending','sending'))
   +(SELECT count(*) FROM managed_realtime_push_devices d JOIN managed_realtime_push_providers p USING(endpoint_id,provider) WHERE d.endpoint_id=ep.id AND d.principal=pending.principal AND d.enabled AND p.enabled)<=4096
 ORDER BY pending.deadline,pending.endpoint_id,pending.principal,pending.sequence
 LIMIT batch_size FOR UPDATE OF pending SKIP LOCKED
 LOOP
   -- A separate advisory lock serializes queue capacity without locking endpoint
   -- rows after inbox/fallback rows (append acquires these in the opposite order).
   IF NOT pg_try_advisory_xact_lock(hashtextextended('realtime-push:'||f.endpoint_id::text,0)) THEN CONTINUE; END IF;
   SELECT array_agg(h.id ORDER BY h.id) INTO recipients FROM app_webhooks h
   WHERE h.app_id=f.app_id AND h.account_id=f.account_id AND h.scope='app' AND h.enabled
   AND (cardinality(h.event_filter)=0 OR 'realtime.inbox.fallback_required'=ANY(h.event_filter));
   SELECT coalesce(jsonb_agg(jsonb_build_object('device',d.device,'provider',d.provider,'version',d.version)),'[]'::jsonb) INTO devices
   FROM managed_realtime_push_devices d JOIN managed_realtime_push_providers p USING(endpoint_id,provider)
   WHERE d.endpoint_id=f.endpoint_id AND d.principal=f.principal AND d.enabled AND p.enabled;
   IF coalesce(cardinality(recipients),0)=0 AND jsonb_array_length(devices)=0 THEN CONTINUE; END IF;
   SELECT count(*) INTO total FROM managed_realtime_push_deliveries WHERE endpoint_id=f.endpoint_id;
   IF total+jsonb_array_length(devices)>4096 THEN
     DELETE FROM managed_realtime_push_deliveries WHERE id IN (
       SELECT id FROM managed_realtime_push_deliveries WHERE endpoint_id=f.endpoint_id AND status IN ('sent','failed','cancelled')
       ORDER BY updated_at,id LIMIT total+jsonb_array_length(devices)-4096 FOR UPDATE SKIP LOCKED);
     SELECT count(*) INTO total FROM managed_realtime_push_deliveries WHERE endpoint_id=f.endpoint_id;
     IF total+jsonb_array_length(devices)>4096 THEN CONTINUE; END IF;
   END IF;
   INSERT INTO managed_realtime_push_deliveries(endpoint_id,principal,device,provider,version,message_id,sequence,category,group_key,group_label,priority,expires_at,hard_expires_at,collapse_key,not_before,next_attempt,code)
   SELECT f.endpoint_id,f.principal,x->>'device',x->>'provider',(x->>'version')::bigint,f.message_id,f.sequence,f.category,f.group_key,f.group_label,f.priority,coalesce(f.expires_at,greatest(clock_timestamp()+interval '24 hours',f.not_before+interval '1 hour')),f.expires_at,f.collapse_key,f.not_before,greatest(clock_timestamp(),f.not_before),case when f.not_before>clock_timestamp() then 'scheduled' else '' end FROM jsonb_array_elements(devices) x
   ON CONFLICT(endpoint_id,principal,sequence,device) DO NOTHING;
   -- Endpoint queue advisory lock serializes collapse decisions with insertion.
   -- Sequence defines freshness even when fallback timers drain out of order.
   IF f.collapse_key<>'' AND (f.expires_at IS NULL OR f.expires_at>clock_timestamp()) THEN
     UPDATE managed_realtime_push_deliveries older
       SET status='cancelled',code='superseded',lease=NULL,lease_until=NULL,updated_at=clock_timestamp()
       WHERE older.endpoint_id=f.endpoint_id AND older.principal=f.principal
         AND older.collapse_key=f.collapse_key AND older.category=f.category AND older.priority=f.priority
         AND older.status IN ('pending','sending')
         AND EXISTS(SELECT 1 FROM managed_realtime_push_deliveries newer
           WHERE newer.endpoint_id=older.endpoint_id AND newer.principal=older.principal
             AND newer.device=older.device AND newer.collapse_key=older.collapse_key
             AND newer.category=older.category AND newer.priority=older.priority
             AND newer.sequence>older.sequence);
   END IF;
   IF coalesce(cardinality(recipients),0)>0 AND (f.expires_at IS NULL OR f.expires_at>clock_timestamp()) THEN
     eid:=gen_random_uuid();
     INSERT INTO app_webhook_event_outbox(id,account_id,app_id,event,source_id,payload,recipient_webhook_ids)
     VALUES(eid,f.account_id,f.app_id,'realtime.inbox.fallback_required',eid,
       jsonb_build_object('event_id',eid,'app_id',f.app_id,'endpoint_id',f.endpoint_id,'principal_key',f.principal,'consumer','','occurred_at',clock_timestamp(),'message_id',f.message_id,'sequence',f.sequence,'deadline',f.deadline,'notification_not_before',f.not_before),recipients);
   END IF;
   DELETE FROM managed_realtime_inbox_fallbacks WHERE endpoint_id=f.endpoint_id AND principal=f.principal AND sequence=f.sequence;
   processed:=processed+1;
 END LOOP;
 RETURN processed;
END $$;


--
-- Name: faas_drain_realtime_inbox_fallbacks_before_collapse(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_drain_realtime_inbox_fallbacks_before_collapse(batch_size integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE f record; recipients uuid[]; devices jsonb; processed integer:=0; total integer; eid uuid;
BEGIN
 FOR f IN SELECT pending.*,ep.app_id,ep.account_id FROM managed_realtime_inbox_fallbacks pending
 JOIN managed_realtime_endpoints ep ON ep.id=pending.endpoint_id AND ep.enabled
 WHERE pending.deadline<=clock_timestamp() AND (
 EXISTS(SELECT 1 FROM app_webhooks h WHERE h.app_id=ep.app_id AND h.account_id=ep.account_id AND h.scope='app' AND h.enabled AND (cardinality(h.event_filter)=0 OR 'realtime.inbox.fallback_required'=ANY(h.event_filter)))
