   END IF;
   DELETE FROM managed_realtime_inbox_fallbacks WHERE endpoint_id=f.endpoint_id AND principal=f.principal AND sequence=f.sequence;
   processed:=processed+1;
 END LOOP;
 RETURN processed;
END $$;


