--
-- Name: guard_environment_external_field_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_external_field_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE src active_environment_git_sources%ROWTYPE;
BEGIN
 IF NEW.resource<>'environment' AND NOT EXISTS(SELECT 1 FROM apps a JOIN project_environments e ON e.account_id=a.account_id AND e.project_id=a.project_id
  WHERE e.id=NEW.environment_id AND NEW.resource='app/'||a.id::text AND a.status<>'deleted') THEN
  RAISE EXCEPTION 'External field ownership must target the scoped app' USING ERRCODE='23514';
 END IF;
 SELECT * INTO src FROM active_environment_git_sources WHERE environment_id=NEW.environment_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM environment_managed_fields f LEFT JOIN environment_gitops_resources r ON r.source_id=f.source_id AND r.logical_name=f.resource
  WHERE f.source_id=src.id AND (NEW.resource='environment' AND f.resource='environment' OR NEW.resource='app/'||r.app_id::text)
   AND (f.field_path=NEW.field_path OR starts_with(NEW.field_path,'variables/') AND f.field_path='secret_refs/'||substring(NEW.field_path FROM 11))) THEN
  RAISE EXCEPTION 'Field already has a Git owner' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;


--
-- Name: guard_environment_git_field_foreign_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_git_field_foreign_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE app uuid;
BEGIN
 IF NEW.manager_kind<>'git' THEN RETURN NEW; END IF;
 PERFORM id FROM active_environment_git_sources WHERE id=NEW.source_id FOR UPDATE;
 SELECT app_id INTO app FROM environment_gitops_resources WHERE source_id=NEW.source_id AND logical_name=NEW.resource;
 IF EXISTS(SELECT 1 FROM environment_external_field_owners f WHERE f.environment_id=NEW.environment_id
  AND (NEW.resource='environment' AND f.resource='environment' OR f.resource='app/'||app::text)
  AND (f.field_path=NEW.field_path OR starts_with(NEW.field_path,'secret_refs/') AND f.field_path='variables/'||substring(NEW.field_path FROM 13))) THEN
  RAISE EXCEPTION 'Field already has an external owner' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;


--
-- Name: guard_environment_git_revision_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_git_revision_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  src environment_git_sources%ROWTYPE;
  rev environment_desired_revisions%ROWTYPE;
  proof jsonb;
  policy jsonb;
  checked timestamptz;
  policy_checked timestamptz;
  merged timestamptz;
  observed timestamptz := clock_timestamp();
  required_reviews integer;
  review jsonb;
  review_ids bigint[] := '{}';
  reviewer_ids bigint[] := '{}';
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF EXISTS (SELECT 1 FROM environment_git_sources WHERE id=OLD.source_id) THEN
      RAISE EXCEPTION 'Git approval provenance is immutable' USING ERRCODE='23514';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'Git approval provenance is immutable' USING ERRCODE='23514';
  END IF;
  SELECT * INTO STRICT src FROM environment_git_sources WHERE id=NEW.source_id FOR UPDATE;
  SELECT * INTO STRICT rev FROM environment_desired_revisions WHERE source_id=src.id AND id=NEW.revision_id;
  proof := NEW.evidence;
  policy := proof->'policy';
  checked := (proof->>'checked_at')::timestamptz;
  policy_checked := (policy->>'checked_at')::timestamptz;
  merged := (proof->>'merged_at')::timestamptz;
  required_reviews := (policy->>'required_review_count')::integer;
  IF src.approval_policy <> 'protected_branch' OR src.suspended
    OR proof->>'reviewed_definition_digest' IS DISTINCT FROM NEW.definition_digest
    OR NEW.definition_digest <> rev.definition_digest OR rev.commit_sha !~ '^[a-f0-9]{40}$'
    OR NEW.approved_generation NOT IN (src.generation, src.generation+1)
    OR proof->>'qualified' IS DISTINCT FROM 'true' OR coalesce(proof->>'reason','') <> ''
    OR proof->>'profile' IS DISTINCT FROM 'reviewed_merge/v1'
    OR policy->>'qualified' IS DISTINCT FROM 'true' OR coalesce(policy->>'reason','') <> ''
    OR policy->>'profile' IS DISTINCT FROM 'classic_reviewed_branch/v1'
    OR policy->>'installation_id' IS DISTINCT FROM src.installation_id::text
    OR policy->>'repository_id' IS DISTINCT FROM src.repository_id::text
    OR policy->>'repository' IS DISTINCT FROM src.repository
    OR src.source_ref NOT LIKE 'refs/heads/%'
    OR policy->>'branch' IS DISTINCT FROM substring(src.source_ref FROM 12)
    OR policy->>'commit_sha' IS DISTINCT FROM rev.commit_sha
    OR coalesce(policy->>'policy_digest','') !~ '^[a-f0-9]{64}$'
    OR coalesce(proof->>'head_sha','') !~ '^[a-f0-9]{40}$'
    OR coalesce((proof->>'pull_request_id')::bigint,0) <= 0
    OR coalesce((proof->>'pull_request_number')::bigint,0) <= 0
    OR coalesce((proof->>'author_id')::bigint,0) <= 0
    OR checked IS NULL OR policy_checked IS NULL OR merged IS NULL
    OR checked > observed OR policy_checked > checked OR merged > checked
    OR policy_checked < observed-interval '1 minute'
    OR coalesce(required_reviews,0) <= 0
    OR jsonb_typeof(proof->'reviews') IS DISTINCT FROM 'array'
    OR NOT EXISTS (SELECT 1 FROM environment_git_source_polls WHERE source_id=src.id
      AND lease_token=NEW.poll_lease_token AND lease_until > observed)
  THEN
    RAISE EXCEPTION 'Git approval evidence does not qualify for this source' USING ERRCODE='23514';
  END IF;
  FOR review IN SELECT value FROM jsonb_array_elements(proof->'reviews') LOOP
    IF coalesce((review->>'id')::bigint,0) <= 0 OR coalesce((review->>'reviewer_id')::bigint,0) <= 0
      OR (review->>'reviewer_id')::bigint = (proof->>'author_id')::bigint
      OR coalesce(review->>'reviewer','') = '' OR review->>'head_sha' IS DISTINCT FROM proof->>'head_sha'
      OR (review->>'submitted_at')::timestamptz IS NULL OR (review->>'submitted_at')::timestamptz >= merged
      OR (review->>'id')::bigint = ANY(review_ids) OR (review->>'reviewer_id')::bigint = ANY(reviewer_ids)
    THEN
      RAISE EXCEPTION 'Git approval review does not qualify' USING ERRCODE='23514';
    END IF;
    review_ids := array_append(review_ids,(review->>'id')::bigint);
    reviewer_ids := array_append(reviewer_ids,(review->>'reviewer_id')::bigint);
  END LOOP;
  IF cardinality(review_ids) < required_reviews THEN
    RAISE EXCEPTION 'Git approval reviews are insufficient' USING ERRCODE='23514';
  END IF;
  NEW.recorded_at := observed;
  RETURN NEW;
END;
$_$;


--
-- Name: guard_environment_git_source_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_git_source_retirement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.detached AND NOT NEW.detached THEN
  RAISE EXCEPTION 'Retired Git bindings cannot be reactivated' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;


--
-- Name: guard_environment_gitops_queue_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_gitops_queue_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.source_id IS DISTINCT FROM OLD.source_id OR NEW.resource IS DISTINCT FROM OLD.resource
  OR NEW.field_path IS DISTINCT FROM OLD.field_path OR (OLD.binding_id IS NOT NULL AND NEW.binding_id IS NOT NULL AND NEW.binding_id IS DISTINCT FROM OLD.binding_id)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_queue_identity',MESSAGE='Git queue identity requires reviewed recovery';
 END IF;
 IF NEW.binding_id IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM queue_bindings b JOIN active_environment_git_sources s ON s.id=NEW.source_id
   JOIN environment_gitops_resources r ON r.source_id=s.id AND r.logical_name=NEW.resource
  WHERE b.id=NEW.binding_id AND b.app_id=r.app_id AND b.account_id=s.account_id
   AND b.environment_id=s.environment_id AND NEW.field_path='queue_bindings/'||b.name
   AND (b.retired_at IS NULL OR environment_gitops_queue_recovery_declared(s.id,b.id)) FOR SHARE OF b) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_queue_identity',MESSAGE='Git queue ownership requires its original scoped binding and reviewed recovery';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_environment_gitops_queue_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_gitops_queue_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
 binding queue_bindings%ROWTYPE;
 src environment_git_sources%ROWTYPE;
 resource_name text;
 paths text[];
 controller boolean;
BEGIN
 IF TG_TABLE_NAME='queue_bindings' THEN
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-'updated_at'-'created_at')=(to_jsonb(OLD)-'updated_at'-'created_at') THEN RETURN NEW; END IF;
  IF TG_OP='DELETE' THEN binding:=OLD; ELSE binding:=NEW; END IF;
  paths:=ARRAY['queue_bindings/'||binding.name];
  IF TG_OP='UPDATE' THEN paths:=paths||ARRAY['queue_bindings/'||OLD.name]; END IF;
 ELSE
  IF TG_OP='UPDATE' AND OLD.queue_binding_id IS NOT NULL AND NEW.id IS DISTINCT FROM OLD.id THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='queue_consumer_binding_identity',MESSAGE='private consumer UUID is immutable';
  END IF;
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-'updated_at'-'created_at')=(to_jsonb(OLD)-'updated_at'-'created_at') THEN RETURN NEW; END IF;
  IF TG_OP='DELETE' THEN
   SELECT b.* INTO binding FROM queue_bindings b WHERE b.id=OLD.queue_binding_id;
  ELSE
   SELECT b.* INTO binding FROM queue_bindings b WHERE b.id=NEW.queue_binding_id;
  END IF;
  paths:=ARRAY['queue_bindings/'||binding.name];
 END IF;
 IF binding.environment_id IS NULL THEN
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 END IF;
 SELECT s.* INTO src FROM active_environment_git_sources s JOIN apps a ON a.project_id=s.project_id AND a.account_id=s.account_id
  WHERE s.environment_id=binding.environment_id AND s.account_id=binding.account_id AND a.id=binding.app_id FOR UPDATE OF s;
 IF src.id IS NOT NULL THEN
  SELECT logical_name INTO resource_name FROM environment_gitops_resources WHERE source_id=src.id AND app_id=binding.app_id;
  SELECT paths||coalesce(array_agg(q.field_path),'{}'::text[]) INTO paths FROM environment_gitops_queue_bindings q
   WHERE q.source_id=src.id AND q.binding_id=binding.id;
  controller:=EXISTS (SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id
   AND j.desired_generation=src.generation AND j.claimed_generation=src.generation AND j.lease_until>clock_timestamp()
   AND j.lease_token<>'' AND j.lease_token=current_setting('gregale.gitops_lease',true)
   AND src.approved_revision_id IS NOT NULL AND NOT src.suspended);
  IF src.mode='enforce' AND NOT controller AND EXISTS (
   SELECT 1 FROM environment_managed_fields f WHERE f.environment_id=src.environment_id AND f.resource=resource_name
    AND f.field_path=ANY(paths) AND f.source_id=src.id AND NOT EXISTS (
     SELECT 1 FROM environment_management_overrides o WHERE o.environment_id=f.environment_id AND o.resource=f.resource
      AND o.field_path=f.field_path AND o.expires_at>clock_timestamp())) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_field_owned',MESSAGE='setting is managed by the environment Git source';
  END IF;
  UPDATE environment_git_sources SET intent_version=intent_version+1,updated_at=now() WHERE id=src.id;
  IF src.generation>0 THEN
   INSERT INTO environment_gitops_jobs(source_id,desired_generation,next_attempt_at) VALUES(src.id,src.generation,now())
    ON CONFLICT(source_id) DO UPDATE SET next_attempt_at=least(environment_gitops_jobs.next_attempt_at,excluded.next_attempt_at);
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


--
-- Name: guard_environment_protected_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_protected_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (OLD.approval_policy='protected_branch' OR NEW.approval_policy='protected_branch') AND
    (NEW.account_id,NEW.project_id,NEW.environment_id,NEW.repository_id,NEW.installation_id,NEW.repository,NEW.source_ref,NEW.manifest_path,NEW.approval_policy)
    IS DISTINCT FROM
    (OLD.account_id,OLD.project_id,OLD.environment_id,OLD.repository_id,OLD.installation_id,OLD.repository,OLD.source_ref,OLD.manifest_path,OLD.approval_policy)
  THEN
    RAISE EXCEPTION 'Protected Git source identity is immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.approval_policy='protected_branch' AND NEW.generation < OLD.generation THEN
    RAISE EXCEPTION 'Protected Git generations cannot move backwards' USING ERRCODE='23514';
  END IF;
  IF NEW.approval_policy='protected_branch' AND NEW.approved_revision_id IS DISTINCT FROM OLD.approved_revision_id THEN
    IF NEW.generation <> OLD.generation+1 OR NOT EXISTS (
      SELECT 1 FROM environment_git_revision_approvals a
      WHERE a.source_id=NEW.id AND a.revision_id=NEW.approved_revision_id AND a.approved_generation=NEW.generation
        AND a.id::text=current_setting('faas.environment_git_approval_id',true)
        AND a.recorded_at >= clock_timestamp()-interval '1 minute')
    THEN
      RAISE EXCEPTION 'Protected Git approval requires verified merge provenance' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_environment_protected_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_protected_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM environment_git_sources WHERE id=OLD.source_id AND approval_policy='protected_branch') THEN
    IF TG_OP='DELETE' OR NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'Protected Git definition is immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_environment_qualification_attempt_replacement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_attempt_replacement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.reserved_instance_id IS DISTINCT FROM OLD.reserved_instance_id AND EXISTS(
  SELECT 1 FROM environment_qualification_executions WHERE request_id=OLD.id AND retired_at IS NULL) THEN
  RAISE EXCEPTION 'qualification attempt replacement requires physical retirement' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_capture_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_capture_retirement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE capture jsonb;
BEGIN
 IF NEW.retired_at IS NOT NULL AND OLD.retired_at IS NULL THEN
  SELECT snapshot INTO capture FROM environment_qualification_snapshot_receipts WHERE instance_id=NEW.instance_id;
  IF capture IS NOT NULL AND (NEW.retirement->>'kind' IS DISTINCT FROM 'native_retired'
   OR NEW.retirement->>'receipt_id' IS DISTINCT FROM capture->>'capture_id'
   OR NEW.retirement->>'native_generation' IS DISTINCT FROM capture->>'native_generation'
   OR NEW.retirement->>'kernel_boot_id' IS DISTINCT FROM capture->>'kernel_boot_id') THEN
   RAISE EXCEPTION 'qualification retirement disagrees with original capture producer' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_config_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_config_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q environment_workload_qualification_requests%ROWTYPE;
        e environment_qualification_executions%ROWTYPE;
        i instances%ROWTYPE;
        d deployments%ROWTYPE;
        runtime instance_runtime_config_receipts%ROWTYPE;
        reservation environment_qualification_restore_reservations%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'qualification guest config evidence is immutable' USING ERRCODE='23514';
 END IF;
 SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=NEW.request_id FOR UPDATE;
 SELECT * INTO e FROM environment_qualification_executions WHERE instance_id=NEW.instance_id;
 SELECT * INTO i FROM instances WHERE id=NEW.instance_id;
 SELECT * INTO d FROM deployments WHERE id=i.deployment_id;
 SELECT * INTO runtime FROM instance_runtime_config_receipts WHERE instance_id=NEW.instance_id AND wake_id=i.wake_id;
 IF e.capture_instance_id IS NOT NULL THEN
  SELECT * INTO reservation FROM environment_qualification_restore_reservations WHERE instance_id=NEW.instance_id;
 END IF;
 IF q.id IS NULL OR q.phase<>'claimed' OR q.attempt<>NEW.attempt OR q.graph_id<>NEW.graph_id
  OR q.lease_until<=clock_timestamp() OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
  OR NOT environment_workload_qualification_inputs_current(q.id)
  OR e.instance_id IS NULL OR e.request_id<>q.id OR e.capture_instance_id IS DISTINCT FROM NEW.capture_instance_id
  OR NOT e.dispatch_started OR e.retired_at IS NOT NULL
  OR e.frame->>'instance_id' IS DISTINCT FROM i.id::text OR e.frame->>'request_id' IS DISTINCT FROM q.id::text
  OR e.frame->>'graph_id' IS DISTINCT FROM q.graph_id::text OR e.frame->>'attempt' IS DISTINCT FROM q.attempt::text
  OR e.frame->>'app_id' IS DISTINCT FROM q.app_id::text OR e.frame->>'deployment_id' IS DISTINCT FROM q.deployment_id::text
  OR i.app_id<>q.app_id OR i.deployment_id<>q.deployment_id OR i.state<>'running'
  OR i.wake_id IS DISTINCT FROM (e.frame->>'wake_id')::uuid OR d.environment_workload_runtime IS DISTINCT FROM q.frozen_inputs
  OR runtime.instance_id IS NULL OR runtime.wake_id<>i.wake_id OR runtime.scope IS DISTINCT FROM q.frozen_inputs->>'scope'
  OR NOT environment_runtime_inputs_fresh(i.app_id,runtime.scope,runtime.boundary_at,runtime.variables,
      runtime.secret_versions,runtime.all_secrets,runtime.secret_refs,runtime.sidecar_secret_versions)
  OR NEW.capture_instance_id IS NULL AND i.id<>q.reserved_instance_id
  OR NEW.capture_instance_id IS NOT NULL AND (reservation.instance_id IS NULL OR reservation.request_id<>q.id
      OR reservation.attempt<>q.attempt OR reservation.capture_instance_id<>q.reserved_instance_id)
 THEN
  RAISE EXCEPTION 'guest config receipt requires the current acknowledged private graph runtime' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_execution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_execution() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q environment_workload_qualification_requests%ROWTYPE; i instances%ROWTYPE; b environment_qualification_restore_reservations%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'qualification execution retention requires explicit collection' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=NEW.request_id;
  SELECT * INTO i FROM instances WHERE id=NEW.instance_id;
  SELECT * INTO b FROM environment_qualification_restore_reservations WHERE instance_id=NEW.instance_id;
  IF q.id IS NULL OR i.id IS NULL OR (q.reserved_instance_id IS DISTINCT FROM i.id AND (b.instance_id IS NULL OR b.request_id IS DISTINCT FROM q.id
    OR b.attempt IS DISTINCT FROM q.attempt OR NOT environment_qualification_restore_current(q.id,b.capture_instance_id)))
   OR NEW.capture_instance_id IS DISTINCT FROM b.capture_instance_id OR q.app_id IS DISTINCT FROM i.app_id
   OR q.deployment_id IS DISTINCT FROM i.deployment_id OR NEW.frame IS DISTINCT FROM (environment_qualification_execution_frame(q,i)||CASE WHEN b.capture_instance_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('capture_instance_id',b.capture_instance_id) END)
   OR NEW.retirement IS NOT NULL OR NEW.retired_at IS NOT NULL THEN
   RAISE EXCEPTION 'qualification execution requires its original admitted attempt' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF ROW(NEW.instance_id,NEW.request_id,NEW.frame,NEW.cleanup_token,NEW.created_at,NEW.capture_instance_id)
  IS DISTINCT FROM ROW(OLD.instance_id,OLD.request_id,OLD.frame,OLD.cleanup_token,OLD.created_at,OLD.capture_instance_id)
  OR OLD.dispatch_started AND NOT NEW.dispatch_started OR OLD.retired_at IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'qualification execution identity and retirement are immutable' USING ERRCODE='23514';
 END IF;
 IF NOT OLD.dispatch_started AND NEW.dispatch_started THEN
  SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=NEW.request_id;
  IF OLD.retired_at IS NOT NULL OR q.id IS NULL OR q.phase<>'claimed' OR q.lease_until<=clock_timestamp()
   OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
   OR (NEW.capture_instance_id IS NULL AND q.reserved_instance_id IS DISTINCT FROM NEW.instance_id)
   OR (NEW.capture_instance_id IS NOT NULL AND NOT environment_qualification_restore_current(q.id,NEW.capture_instance_id)) OR q.attempt IS DISTINCT FROM (NEW.frame->>'attempt')::bigint
   OR NOT environment_workload_qualification_inputs_current(q.id) THEN
   RAISE EXCEPTION 'qualification dispatch requires its current execution lease' USING ERRCODE='23514';
  END IF;
 END IF;
 IF OLD.retired_at IS NULL AND NEW.retired_at IS NOT NULL THEN
  IF NEW.cleanup_token::text IS DISTINCT FROM current_setting('gregale.gitops_qualification_cleanup',true)
   OR NEW.dispatch_started IS DISTINCT FROM OLD.dispatch_started THEN
   RAISE EXCEPTION 'qualification retirement requires its original cleanup capability' USING ERRCODE='23514';
  END IF;
  IF NOT OLD.dispatch_started THEN
   IF NEW.retirement IS DISTINCT FROM '{"kind":"never_dispatched"}'::jsonb THEN
    RAISE EXCEPTION 'unstarted qualification requires exact no-dispatch evidence' USING ERRCODE='23514';
   END IF;
  ELSIF NEW.retirement->>'kind'='native_retired' THEN
   IF NEW.retirement->'processes_exited' IS DISTINCT FROM 'true'::jsonb OR NEW.retirement->'resources_removed' IS DISTINCT FROM 'true'::jsonb
    OR coalesce((NEW.retirement->>'receipt_id')::uuid,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000'
    OR coalesce((NEW.retirement->>'native_generation')::uuid,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000'
    OR coalesce((NEW.retirement->>'kernel_boot_id')::uuid,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000'
    OR NEW.retirement-(ARRAY['kind','receipt_id','native_generation','kernel_boot_id','processes_exited','resources_removed'])<>'{}'::jsonb THEN
    RAISE EXCEPTION 'qualification retirement requires complete native evidence' USING ERRCODE='23514';
   END IF;
  ELSIF NEW.retirement->>'kind'='native_effects_absent' THEN
   IF NEW.retirement->'processes_exited' IS DISTINCT FROM 'true'::jsonb OR NEW.retirement->'resources_removed' IS DISTINCT FROM 'true'::jsonb
    OR coalesce((NEW.retirement->>'receipt_id')::uuid,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000'
    OR coalesce((NEW.retirement->>'kernel_boot_id')::uuid,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000'
    OR NEW.retirement ? 'native_generation'
    OR NEW.retirement-(ARRAY['kind','receipt_id','kernel_boot_id','processes_exited','resources_removed'])<>'{}'::jsonb THEN
    RAISE EXCEPTION 'qualification no-effects evidence is incomplete' USING ERRCODE='23514';
   END IF;
  ELSE
   RAISE EXCEPTION 'qualification retirement kind is unsupported' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_framework_ready_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_framework_ready_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q environment_workload_qualification_requests%ROWTYPE;
        graph environment_workload_graphs%ROWTYPE;
        target_exec environment_qualification_executions%ROWTYPE;
        target_instance instances%ROWTYPE;
        target_runtime instance_runtime_config_receipts%ROWTYPE;
        reservation environment_qualification_restore_reservations%ROWTYPE;
        capture environment_qualification_snapshot_receipts%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'qualification framework-ready evidence is immutable' USING ERRCODE='23514';
 END IF;
 SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=NEW.request_id FOR UPDATE;
 SELECT * INTO graph FROM environment_workload_graphs WHERE id=NEW.graph_id;
 SELECT * INTO target_exec FROM environment_qualification_executions WHERE instance_id=NEW.instance_id;
 SELECT * INTO target_instance FROM instances WHERE id=NEW.instance_id;
 SELECT * INTO target_runtime FROM instance_runtime_config_receipts WHERE instance_id=NEW.instance_id AND wake_id=target_instance.wake_id;
 SELECT * INTO reservation FROM environment_qualification_restore_reservations WHERE instance_id=NEW.instance_id;
 SELECT * INTO capture FROM environment_qualification_snapshot_receipts WHERE instance_id=NEW.capture_instance_id;
 IF q.id IS NULL OR q.phase<>'claimed' OR q.lease_until<=clock_timestamp() OR q.attempt<>NEW.attempt
  OR q.graph_id<>NEW.graph_id OR q.reserved_instance_id<>NEW.capture_instance_id
  OR coalesce(q.frozen_inputs->>'runtime_base','')<>'' AND NEW.runtime IS DISTINCT FROM q.frozen_inputs->>'runtime_base'
  OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
  OR NOT environment_workload_qualification_inputs_current(q.id)
  OR graph.id IS NULL OR graph.phase<>'prepared' OR graph.revision_id::text<>q.frozen_inputs->>'revision_id'
  OR graph.generation::text<>q.frozen_inputs->>'generation' OR graph.plan_hash<>q.frozen_inputs->>'plan_hash'
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(graph.members) member
      WHERE member->>'resource'=q.resource AND member->>'app_id'=q.app_id::text
       AND member->>'candidate_deployment_id'=q.deployment_id::text)
  OR target_exec.instance_id IS NULL OR target_exec.request_id<>q.id
  OR target_exec.capture_instance_id<>NEW.capture_instance_id OR NOT target_exec.dispatch_started OR target_exec.retired_at IS NOT NULL
  OR target_exec.frame->>'instance_id' IS DISTINCT FROM NEW.instance_id::text
  OR target_exec.frame->>'request_id' IS DISTINCT FROM q.id::text
  OR target_exec.frame->>'graph_id' IS DISTINCT FROM q.graph_id::text
  OR target_exec.frame->>'attempt' IS DISTINCT FROM q.attempt::text
  OR target_exec.frame->>'app_id' IS DISTINCT FROM q.app_id::text
  OR target_exec.frame->>'deployment_id' IS DISTINCT FROM q.deployment_id::text
  OR target_instance.id IS NULL OR target_instance.app_id<>q.app_id OR target_instance.deployment_id<>q.deployment_id
  OR target_instance.state<>'running' OR target_instance.wake_id IS DISTINCT FROM (target_exec.frame->>'wake_id')::uuid
  OR target_runtime.instance_id IS NULL OR target_runtime.wake_id<>target_instance.wake_id
  OR capture.instance_id IS NULL OR target_runtime.scope IS DISTINCT FROM capture.inputs->>'scope'
  OR target_runtime.variables IS DISTINCT FROM capture.inputs->'variables'
  OR target_runtime.secret_versions IS DISTINCT FROM capture.inputs->'secret_versions'
  OR target_runtime.secret_refs IS DISTINCT FROM capture.inputs->'secret_refs'
  OR coalesce(target_runtime.sidecar_secret_versions,'{}'::jsonb) IS DISTINCT FROM coalesce(capture.inputs->'sidecar_secret_versions','{}'::jsonb)
  OR target_runtime.all_secrets IS DISTINCT FROM (capture.inputs->>'all_secrets')::boolean
  OR reservation.instance_id IS NULL OR reservation.request_id<>q.id OR reservation.attempt<>q.attempt
  OR reservation.capture_instance_id<>NEW.capture_instance_id
  OR NOT environment_runtime_inputs_fresh(target_instance.app_id,target_runtime.scope,target_runtime.boundary_at,
      target_runtime.variables,target_runtime.secret_versions,target_runtime.all_secrets,target_runtime.secret_refs,
      target_runtime.sidecar_secret_versions) THEN
  RAISE EXCEPTION 'framework-ready receipt requires the current live restored graph target' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_job_smoke_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_job_smoke_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE q environment_workload_qualification_requests%ROWTYPE;
        g environment_workload_graphs%ROWTYPE;
        e environment_qualification_executions%ROWTYPE;
        i instances%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'qualification job smoke evidence is immutable' USING ERRCODE='23514';
 END IF;
 SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=NEW.request_id FOR UPDATE;
 SELECT * INTO g FROM environment_workload_graphs WHERE id=NEW.graph_id;
 SELECT * INTO e FROM environment_qualification_executions WHERE instance_id=NEW.instance_id;
 SELECT * INTO i FROM instances WHERE id=NEW.instance_id;
 IF q.id IS NULL OR q.phase<>'claimed' OR q.lease_until<=clock_timestamp() OR q.attempt<>NEW.attempt
  OR q.graph_id<>NEW.graph_id OR q.reserved_instance_id<>NEW.instance_id OR q.resource<>NEW.resource
  OR q.execution_mode<>'job' OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
  OR q.frozen_inputs->'job_smoke' IS NULL OR jsonb_typeof(q.frozen_inputs->'job_smoke')<>'object'
  OR coalesce(nullif(q.frozen_inputs->'queue_bindings','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb
  OR NOT environment_workload_qualification_inputs_current(q.id)
  OR g.id IS NULL OR g.phase<>'prepared' OR g.revision_id::text IS DISTINCT FROM q.frozen_inputs->>'revision_id'
  OR g.generation::text IS DISTINCT FROM q.frozen_inputs->>'generation' OR g.plan_hash IS DISTINCT FROM q.frozen_inputs->>'plan_hash'
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.members) member
      WHERE member->>'resource'=q.resource AND member->>'app_id'=q.app_id::text
       AND member->>'candidate_deployment_id'=q.deployment_id::text AND member->>'execution_mode'='job'
       AND coalesce((member->>'job_smoke_configured')::boolean,false)
       AND coalesce(nullif(member->'service_bindings','null'::jsonb),'{}'::jsonb)=coalesce(nullif(q.frozen_inputs->'service_bindings','null'::jsonb),'{}'::jsonb)
       AND coalesce((member->>'service_bindings_configured')::boolean,false)=(coalesce(nullif(q.frozen_inputs->'service_bindings','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb)
       AND coalesce(member->>'queue_bindings_configured','false')='false'
       AND coalesce(nullif(member->'queue_bindings','null'::jsonb),'{}'::jsonb)='{}'::jsonb
       AND coalesce(nullif(member->'queue_modes','null'::jsonb),'{}'::jsonb)='{}'::jsonb)
  OR e.instance_id IS NULL OR e.request_id IS DISTINCT FROM q.id OR e.frame->>'graph_id' IS DISTINCT FROM q.graph_id::text
  OR e.frame->>'attempt' IS DISTINCT FROM q.attempt::text OR e.frame->>'resource' IS DISTINCT FROM q.resource
  OR e.frame->'artifact' IS DISTINCT FROM q.artifact OR NOT e.dispatch_started OR e.retired_at IS NULL
  OR e.retirement->>'kind' IS DISTINCT FROM 'native_retired' OR e.retirement->'processes_exited' IS DISTINCT FROM 'true'::jsonb
  OR e.retirement->'resources_removed' IS DISTINCT FROM 'true'::jsonb
  OR NOT EXISTS(SELECT 1 FROM environment_qualification_config_receipts c
      WHERE c.request_id=q.id AND c.attempt=q.attempt AND c.graph_id=q.graph_id AND c.instance_id=NEW.instance_id
       AND c.capture_instance_id IS NULL AND c.api_env_sha256 ~ '^[0-9a-f]{64}$')
  OR i.id IS NULL OR i.state<>'stopped' OR i.wake_id IS DISTINCT FROM (e.frame->>'wake_id')::uuid THEN
  RAISE EXCEPTION 'job smoke receipt requires a successful sanitized result for the current retired Git-owned job attempt' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_environment_qualification_physical_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_physical_retirement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE e environment_qualification_executions%ROWTYPE;
BEGIN
 SELECT * INTO e FROM environment_qualification_executions WHERE instance_id=OLD.id;
 IF e.instance_id IS NOT NULL THEN
  IF TG_OP='UPDATE' AND NEW.state='running' AND (NOT e.dispatch_started OR e.retired_at IS NOT NULL) THEN
   RAISE EXCEPTION 'qualification runtime requires a dispatched unretired attempt' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' AND e.retired_at IS NULL OR TG_OP='UPDATE' AND NEW.state NOT IN ('cold_booting','waking','running','draining','warm') AND e.retired_at IS NULL THEN
   RAISE EXCEPTION 'qualification reservation requires attempt-bound physical retirement' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.app_id,NEW.deployment_id,NEW.node_id,NEW.wake_id,NEW.ram_mb)
   IS DISTINCT FROM ROW(OLD.id,OLD.app_id,OLD.deployment_id,OLD.node_id,OLD.wake_id,OLD.ram_mb) THEN
   RAISE EXCEPTION 'qualification placement survives parent removal' USING ERRCODE='23514';
  END IF;
 ELSIF EXISTS(SELECT 1 FROM deployments WHERE id=OLD.deployment_id AND environment_workload_runtime IS NOT NULL)
  AND (TG_OP='DELETE' OR NEW.state NOT IN ('cold_booting','waking','running','draining','warm')) THEN
  RAISE EXCEPTION 'legacy qualification has no recoverable execution frame' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_restore_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_restore_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q environment_workload_qualification_requests%ROWTYPE;
        source_exec environment_qualification_executions%ROWTYPE;
        target_exec environment_qualification_executions%ROWTYPE;
        capture environment_qualification_snapshot_receipts%ROWTYPE;
        runtime instance_runtime_config_receipts%ROWTYPE;
        target_instance instances%ROWTYPE;
        reservation environment_qualification_restore_reservations%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'qualification restore evidence is immutable' USING ERRCODE='23514';
 END IF;
 SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=NEW.request_id FOR UPDATE;
 SELECT * INTO source_exec FROM environment_qualification_executions WHERE instance_id=NEW.capture_instance_id;
 SELECT * INTO capture FROM environment_qualification_snapshot_receipts WHERE instance_id=NEW.capture_instance_id;
 SELECT * INTO target_exec FROM environment_qualification_executions WHERE instance_id=NEW.instance_id;
 SELECT * INTO reservation FROM environment_qualification_restore_reservations WHERE instance_id=NEW.instance_id;
 SELECT * INTO target_instance FROM instances WHERE id=NEW.instance_id;
 SELECT * INTO runtime FROM instance_runtime_config_receipts WHERE instance_id=NEW.instance_id AND wake_id=target_instance.wake_id;
 IF q.id IS NULL OR q.phase<>'claimed' OR q.attempt<>NEW.attempt OR q.reserved_instance_id<>NEW.capture_instance_id
  OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
  OR NOT environment_workload_qualification_inputs_current(q.id)
  OR capture.instance_id IS NULL OR source_exec.instance_id IS NULL OR target_exec.instance_id IS NULL
  OR reservation.instance_id IS NULL OR reservation.request_id<>q.id OR reservation.attempt<>q.attempt
  OR reservation.capture_instance_id<>NEW.capture_instance_id
  OR source_exec.request_id<>q.id OR source_exec.capture_instance_id IS NOT NULL OR NOT source_exec.dispatch_started
  OR source_exec.retired_at IS NULL OR source_exec.retirement->>'kind'<>'native_retired'
  OR source_exec.retirement->>'receipt_id' IS DISTINCT FROM capture.snapshot->>'capture_id'
  OR source_exec.retirement->>'native_generation' IS DISTINCT FROM capture.snapshot->>'native_generation'
  OR source_exec.retirement->>'kernel_boot_id' IS DISTINCT FROM capture.snapshot->>'kernel_boot_id'
  OR target_exec.request_id<>q.id OR target_exec.capture_instance_id<>NEW.capture_instance_id
  OR NOT target_exec.dispatch_started OR target_exec.retired_at IS NULL OR target_exec.retirement->>'kind'<>'native_retired'
  OR target_exec.retirement->'processes_exited' IS DISTINCT FROM 'true'::jsonb
  OR target_exec.retirement->'resources_removed' IS DISTINCT FROM 'true'::jsonb
  OR target_exec.retirement->>'native_generation' IS NOT DISTINCT FROM capture.snapshot->>'native_generation'
  OR target_exec.retirement->>'kernel_boot_id' IS DISTINCT FROM capture.snapshot->>'kernel_boot_id'
  OR target_exec.retirement->>'receipt_id' IS NOT DISTINCT FROM source_exec.retirement->>'receipt_id'
  OR target_exec.frame->>'instance_id' IS NOT DISTINCT FROM source_exec.frame->>'instance_id'
  OR target_exec.frame->>'wake_id' IS NOT DISTINCT FROM source_exec.frame->>'wake_id'
  OR (target_exec.frame-ARRAY['instance_id','wake_id','capture_instance_id'])
    IS DISTINCT FROM (source_exec.frame-ARRAY['instance_id','wake_id'])
  OR NEW.runtime_inputs->>'scope' IS DISTINCT FROM capture.inputs->>'scope'
  OR NEW.runtime_inputs->'variables' IS DISTINCT FROM capture.inputs->'variables'
  OR NEW.runtime_inputs->'secret_versions' IS DISTINCT FROM capture.inputs->'secret_versions'
  OR NEW.runtime_inputs->'secret_refs' IS DISTINCT FROM capture.inputs->'secret_refs'
  OR coalesce(NEW.runtime_inputs->'sidecar_secret_versions','{}'::jsonb) IS DISTINCT FROM coalesce(capture.inputs->'sidecar_secret_versions','{}'::jsonb)
  OR NEW.runtime_inputs->>'all_secrets' IS DISTINCT FROM capture.inputs->>'all_secrets'
  OR runtime.instance_id IS NULL OR target_instance.app_id<>q.app_id OR target_instance.deployment_id<>q.deployment_id
  OR target_instance.node_id IS DISTINCT FROM (source_exec.frame->>'node_id')::uuid
  OR target_instance.wake_id IS DISTINCT FROM (target_exec.frame->>'wake_id')::uuid OR target_instance.state<>'stopped'
  OR runtime.scope IS DISTINCT FROM NEW.runtime_inputs->>'scope'
  OR runtime.boundary_at IS DISTINCT FROM (NEW.runtime_inputs->>'boundary')::timestamptz
  OR runtime.variables IS DISTINCT FROM NEW.runtime_inputs->'variables'
  OR runtime.secret_versions IS DISTINCT FROM NEW.runtime_inputs->'secret_versions'
  OR runtime.secret_refs IS DISTINCT FROM NEW.runtime_inputs->'secret_refs'
  OR runtime.sidecar_secret_versions IS DISTINCT FROM coalesce(NEW.runtime_inputs->'sidecar_secret_versions','{}'::jsonb)
  OR runtime.all_secrets IS DISTINCT FROM (NEW.runtime_inputs->>'all_secrets')::boolean
  OR NEW.runtime_inputs-ARRAY['scope','boundary','variables','secret_versions','secret_refs','sidecar_secret_versions','all_secrets']<>'{}'::jsonb
  OR NOT environment_runtime_inputs_fresh(target_instance.app_id,runtime.scope,runtime.boundary_at,runtime.variables,
      runtime.secret_versions,runtime.all_secrets,runtime.secret_refs,runtime.sidecar_secret_versions)
  OR NOT environment_runtime_inputs_fresh(target_instance.app_id,capture.inputs->>'scope',(capture.inputs->>'boundary')::timestamptz,
      capture.inputs->'variables',capture.inputs->'secret_versions',(capture.inputs->>'all_secrets')::boolean,
      capture.inputs->'secret_refs',coalesce(capture.inputs->'sidecar_secret_versions','{}'::jsonb)) THEN
  RAISE EXCEPTION 'restore receipt requires the current capture, successful distinct restore, and fresh target inputs' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_restore_reservation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_restore_reservation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'INSERT' OR NOT environment_qualification_restore_current(NEW.request_id,NEW.capture_instance_id)
  OR NOT EXISTS(SELECT 1 FROM environment_workload_qualification_requests WHERE id=NEW.request_id AND attempt=NEW.attempt)
  OR EXISTS(SELECT 1 FROM instances WHERE id=NEW.instance_id) OR EXISTS(SELECT 1 FROM environment_qualification_executions WHERE instance_id=NEW.instance_id) THEN
  RAISE EXCEPTION 'restore reservation requires its current retired original capture' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_restore_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_restore_retirement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE capture environment_qualification_snapshot_receipts%ROWTYPE;
        original environment_qualification_executions%ROWTYPE;
BEGIN
 IF OLD.retired_at IS NULL AND NEW.retired_at IS NOT NULL AND NEW.capture_instance_id IS NOT NULL
  AND NEW.retirement->>'kind'='native_retired' THEN
  SELECT * INTO capture FROM environment_qualification_snapshot_receipts WHERE instance_id=NEW.capture_instance_id;
  SELECT * INTO original FROM environment_qualification_executions WHERE instance_id=NEW.capture_instance_id;
  IF capture.instance_id IS NULL OR original.retirement IS NULL
   OR NEW.retirement->>'native_generation' IS NOT DISTINCT FROM capture.snapshot->>'native_generation'
   OR NEW.retirement->>'kernel_boot_id' IS DISTINCT FROM capture.snapshot->>'kernel_boot_id'
   OR NEW.retirement->>'receipt_id' IS NOT DISTINCT FROM original.retirement->>'receipt_id' THEN
   RAISE EXCEPTION 'restore target requires distinct native retirement on the capture kernel' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_runtime_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_runtime_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q environment_workload_qualification_requests%ROWTYPE; i instances%ROWTYPE;
        b environment_qualification_restore_reservations%ROWTYPE; restoring boolean:=false;
BEGIN
 SELECT * INTO i FROM instances WHERE id=NEW.instance_id;
	IF i.id IS NULL OR NOT EXISTS(SELECT 1 FROM deployments WHERE id=i.deployment_id AND environment_workload_runtime IS NOT NULL) THEN RETURN NEW; END IF;
 SELECT * INTO q FROM environment_workload_qualification_requests WHERE reserved_instance_id=i.id;
 IF q.id IS NULL THEN
  SELECT * INTO b FROM environment_qualification_restore_reservations WHERE instance_id=i.id;
  IF b.instance_id IS NOT NULL THEN
   SELECT * INTO q FROM environment_workload_qualification_requests
    WHERE id=b.request_id AND reserved_instance_id=b.capture_instance_id AND attempt=b.attempt;
   restoring:=q.id IS NOT NULL;
  END IF;
 END IF;
 IF q.id IS NOT NULL THEN
  PERFORM s.id FROM environment_git_sources s JOIN environment_workload_graphs g ON g.source_id=s.id WHERE g.id=q.graph_id FOR UPDATE OF s;
  PERFORM a.id FROM apps a JOIN environment_workload_graphs g ON g.id=q.graph_id
   JOIN LATERAL jsonb_array_elements(g.members) m ON a.id=(m->>'app_id')::uuid ORDER BY a.id FOR UPDATE OF a;
  SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=q.id FOR UPDATE;
  PERFORM n.id FROM compute_nodes n WHERE n.id=i.node_id FOR SHARE OF n;
  PERFORM c.id FROM accounts c JOIN apps a ON a.account_id=c.id WHERE a.id=i.app_id FOR SHARE OF c;
  SELECT * INTO i FROM instances WHERE id=NEW.instance_id FOR UPDATE;
 END IF;
 IF restoring AND NOT EXISTS(SELECT 1 FROM environment_qualification_executions e
	   WHERE e.instance_id=i.id AND e.request_id=q.id AND e.capture_instance_id=b.capture_instance_id
	    AND e.frame=(environment_qualification_execution_frame(q,i)||jsonb_build_object('capture_instance_id',b.capture_instance_id))
    AND e.dispatch_started AND e.retired_at IS NULL AND environment_qualification_restore_current(q.id,b.capture_instance_id)) THEN
  RAISE EXCEPTION 'restored runtime receipt requires its live dispatched target' USING ERRCODE='23514';
 END IF;
 IF q.id IS NULL OR q.phase<>'claimed' OR q.lease_until<=clock_timestamp()
  OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
  OR q.app_id<>i.app_id OR q.deployment_id<>i.deployment_id OR i.state<>'running'
  OR i.ram_mb IS DISTINCT FROM (SELECT a.ram_mb FROM apps a WHERE a.id=i.app_id)
  OR NOT EXISTS(SELECT 1 FROM compute_nodes n WHERE n.id=i.node_id AND n.active AND n.lifecycle='active')
  OR NEW.wake_id IS DISTINCT FROM i.wake_id OR NEW.scope IS DISTINCT FROM q.frozen_inputs->>'scope'
  OR NOT environment_workload_qualification_inputs_current(q.id)
  OR NOT environment_runtime_inputs_fresh(i.app_id,NEW.scope,NEW.boundary_at,NEW.variables,NEW.secret_versions,NEW.all_secrets,NEW.secret_refs,NEW.sidecar_secret_versions) THEN
  RAISE EXCEPTION 'environment runtime evidence requires its current qualification attempt and delivered inputs' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_service_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_service_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN
  IF TG_OP='DELETE' AND pg_trigger_depth()>1 THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'candidate service receipts are immutable' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM environment_workload_qualification_requests q
  JOIN environment_qualification_executions caller ON caller.request_id=q.id AND caller.instance_id=(NEW.route->'Caller'->>'instance_id')::uuid
  JOIN environment_qualification_executions target ON target.instance_id=(NEW.route->'Target'->>'instance_id')::uuid
  JOIN environment_workload_qualification_requests t ON t.id=target.request_id
  WHERE q.id=NEW.request_id AND q.attempt=NEW.attempt AND q.graph_id=t.graph_id AND caller.frame=NEW.route->'Caller' AND target.frame=NEW.route->'Target'
   AND caller.dispatch_started AND target.dispatch_started AND caller.retired_at IS NULL AND target.retired_at IS NULL
   AND q.lease_until>clock_timestamp() AND t.lease_until>clock_timestamp() AND environment_workload_qualification_inputs_current(q.id)
   AND NEW.route->>'RequireHTTPS'='true' AND NEW.route->'Caller'->>'capture_instance_id'=q.reserved_instance_id::text
   AND NEW.route->'Target'->>'capture_instance_id'=t.reserved_instance_id::text
   AND q.frozen_inputs->'service_bindings'->NEW.binding->>'target_app_id'=t.app_id::text
   AND (NEW.route->>'Deadline')::timestamptz<=least(q.lease_until,t.lease_until) AND (NEW.route->>'Deadline')::timestamptz>clock_timestamp()) THEN
  RAISE EXCEPTION 'candidate service receipt requires the original restored graph endpoints' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_smoke_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_smoke_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q environment_workload_qualification_requests%ROWTYPE;
        graph environment_workload_graphs%ROWTYPE;
        capture environment_qualification_snapshot_receipts%ROWTYPE;
        source_exec environment_qualification_executions%ROWTYPE;
        target_exec environment_qualification_executions%ROWTYPE;
        restored environment_qualification_restore_receipts%ROWTYPE;
        target_instance instances%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'qualification smoke evidence is immutable' USING ERRCODE='23514';
 END IF;
 SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=NEW.request_id FOR UPDATE;
 SELECT * INTO graph FROM environment_workload_graphs WHERE id=NEW.graph_id;
 SELECT * INTO capture FROM environment_qualification_snapshot_receipts WHERE instance_id=NEW.capture_instance_id;
 SELECT * INTO source_exec FROM environment_qualification_executions WHERE instance_id=NEW.capture_instance_id;
 SELECT * INTO target_exec FROM environment_qualification_executions WHERE instance_id=NEW.instance_id;
 SELECT * INTO restored FROM environment_qualification_restore_receipts WHERE request_id=NEW.request_id AND attempt=NEW.attempt;
 SELECT * INTO target_instance FROM instances WHERE id=NEW.instance_id;
 IF q.id IS NULL OR q.phase<>'claimed' OR q.lease_until<=clock_timestamp() OR q.attempt<>NEW.attempt
  OR q.graph_id<>NEW.graph_id OR q.reserved_instance_id<>NEW.capture_instance_id OR q.resource<>NEW.resource
  OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
  OR NOT environment_workload_qualification_inputs_current(q.id)
  OR graph.id IS NULL OR graph.phase<>'prepared' OR graph.revision_id::text<>q.frozen_inputs->>'revision_id'
  OR graph.generation::text<>q.frozen_inputs->>'generation' OR graph.plan_hash<>q.frozen_inputs->>'plan_hash'
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(graph.members) member
      WHERE member->>'resource'=q.resource AND member->>'app_id'=q.app_id::text
       AND member->>'candidate_deployment_id'=q.deployment_id::text)
  OR capture.instance_id IS NULL OR source_exec.instance_id IS NULL OR target_exec.instance_id IS NULL
  OR restored.request_id IS NULL OR restored.capture_instance_id<>NEW.capture_instance_id OR restored.instance_id<>NEW.instance_id
  OR source_exec.request_id<>q.id OR source_exec.capture_instance_id IS NOT NULL OR NOT source_exec.dispatch_started
  OR source_exec.retired_at IS NULL OR source_exec.retirement->>'kind'<>'native_retired'
  OR source_exec.retirement->>'receipt_id' IS DISTINCT FROM capture.snapshot->>'capture_id'
  OR source_exec.retirement->>'native_generation' IS DISTINCT FROM capture.snapshot->>'native_generation'
  OR source_exec.retirement->>'kernel_boot_id' IS DISTINCT FROM capture.snapshot->>'kernel_boot_id'
  OR target_exec.request_id<>q.id OR target_exec.capture_instance_id<>NEW.capture_instance_id
  OR NOT target_exec.dispatch_started OR target_exec.retired_at IS NULL OR target_exec.retirement->>'kind'<>'native_retired'
  OR target_exec.retirement->'processes_exited' IS DISTINCT FROM 'true'::jsonb
  OR target_exec.retirement->'resources_removed' IS DISTINCT FROM 'true'::jsonb
  OR target_exec.retirement->>'native_generation' IS NOT DISTINCT FROM capture.snapshot->>'native_generation'
  OR target_exec.retirement->>'kernel_boot_id' IS DISTINCT FROM capture.snapshot->>'kernel_boot_id'
  OR target_exec.retirement->>'receipt_id' IS NOT DISTINCT FROM source_exec.retirement->>'receipt_id'
  OR restored.runtime_inputs->>'scope' IS DISTINCT FROM capture.inputs->>'scope'
  OR restored.runtime_inputs->'variables' IS DISTINCT FROM capture.inputs->'variables'
  OR restored.runtime_inputs->'secret_versions' IS DISTINCT FROM capture.inputs->'secret_versions'
  OR restored.runtime_inputs->'secret_refs' IS DISTINCT FROM capture.inputs->'secret_refs'
  OR coalesce(restored.runtime_inputs->'sidecar_secret_versions','{}'::jsonb) IS DISTINCT FROM coalesce(capture.inputs->'sidecar_secret_versions','{}'::jsonb)
  OR restored.runtime_inputs->>'all_secrets' IS DISTINCT FROM capture.inputs->>'all_secrets'
  OR target_instance.id IS NULL OR target_instance.state<>'stopped' OR target_instance.wake_id IS DISTINCT FROM (target_exec.frame->>'wake_id')::uuid
  OR NOT environment_runtime_inputs_fresh(target_instance.app_id,restored.runtime_inputs->>'scope',
      (restored.runtime_inputs->>'boundary')::timestamptz,restored.runtime_inputs->'variables',restored.runtime_inputs->'secret_versions',
      (restored.runtime_inputs->>'all_secrets')::boolean,restored.runtime_inputs->'secret_refs',
      coalesce(restored.runtime_inputs->'sidecar_secret_versions','{}'::jsonb)) THEN
  RAISE EXCEPTION 'smoke receipt requires explicit policy/result digests for the current graph member and its fresh, retired restore target' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_snapshot_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_snapshot_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE e environment_qualification_executions%ROWTYPE; q environment_workload_qualification_requests%ROWTYPE;
 capture uuid; native uuid; kernel uuid; mem text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'qualification capture evidence is immutable' USING ERRCODE='23514'; END IF;
 SELECT * INTO e FROM environment_qualification_executions WHERE instance_id=NEW.instance_id FOR UPDATE;
 SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=e.request_id;
 IF e.instance_id IS NULL OR NOT e.dispatch_started OR e.retired_at IS NOT NULL OR q.phase IS DISTINCT FROM 'claimed'
  OR q.lease_until<=clock_timestamp() OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
  OR q.reserved_instance_id IS DISTINCT FROM e.instance_id OR q.attempt IS DISTINCT FROM (e.frame->>'attempt')::bigint
  OR NOT environment_workload_qualification_inputs_current(q.id) THEN
  RAISE EXCEPTION 'qualification capture requires current original execution authority' USING ERRCODE='23514';
 END IF;
 capture:=(NEW.snapshot->>'capture_id')::uuid; native:=(NEW.snapshot->>'native_generation')::uuid; kernel:=(NEW.snapshot->>'kernel_boot_id')::uuid;
 mem:='snap/'||(e.frame->>'deployment_id')||'/warm/captures/'||capture::text||'/v2/mem';
 IF capture IS NULL OR native IS NULL OR kernel IS NULL OR capture=native
  OR NEW.snapshot->>'capture_id' IS DISTINCT FROM capture::text OR NEW.snapshot->>'native_generation' IS DISTINCT FROM native::text OR NEW.snapshot->>'kernel_boot_id' IS DISTINCT FROM kernel::text
  OR capture::text='00000000-0000-0000-0000-000000000000' OR native::text='00000000-0000-0000-0000-000000000000' OR kernel::text='00000000-0000-0000-0000-000000000000'
  OR NEW.snapshot->>'storage_key' IS DISTINCT FROM mem OR NEW.snapshot->>'vmstate_storage_key' IS DISTINCT FROM replace(mem,'/mem','/vmstate')
  OR NEW.snapshot->>'drive_storage_key' IS DISTINCT FROM replace(mem,'/mem','/drive') OR NEW.snapshot->>'backing_storage_key' IS DISTINCT FROM replace(mem,'/mem','/backing')
  OR NOT NEW.snapshot ?& ARRAY['mem_bytes','vmstate_bytes','stored_bytes'] OR coalesce((NEW.snapshot->>'mem_bytes')::bigint,0)<=0
  OR coalesce((NEW.snapshot->>'vmstate_bytes')::bigint,0)<=0 OR coalesce((NEW.snapshot->>'stored_bytes')::bigint,0)<=0 THEN
  RAISE EXCEPTION 'qualification capture namespace or outputs are invalid' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM instances i JOIN instance_runtime_config_receipts c ON c.instance_id=i.id AND c.wake_id=i.wake_id
  WHERE i.id=e.instance_id AND i.state='running' AND i.node_id=(e.frame->>'node_id')::uuid AND i.wake_id=(e.frame->>'wake_id')::uuid
   AND c.scope=NEW.inputs->>'scope' AND c.boundary_at=(NEW.inputs->>'boundary')::timestamptz
   AND c.variables=NEW.inputs->'variables' AND c.secret_versions=NEW.inputs->'secret_versions' AND c.secret_refs=NEW.inputs->'secret_refs'
   AND c.sidecar_secret_versions=coalesce(NEW.inputs->'sidecar_secret_versions','{}') AND c.all_secrets=(NEW.inputs->>'all_secrets')::boolean
   AND environment_runtime_inputs_fresh(i.app_id,c.scope,c.boundary_at,c.variables,c.secret_versions,c.all_secrets,c.secret_refs,c.sidecar_secret_versions)) THEN
  RAISE EXCEPTION 'qualification capture requires fresh runtime input evidence' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_secret_ref_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_secret_ref_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE row_value record; src environment_git_sources%ROWTYPE;
 resource_name text; controller boolean; stamp timestamptz;
BEGIN
 IF TG_OP='DELETE' THEN row_value:=OLD; ELSE row_value:=NEW; END IF;
 -- Parent cascades have already removed their catalog/app identity. Ordinary
 -- row deletion still passes through ownership enforcement below.
 IF TG_OP='DELETE' AND NOT EXISTS (SELECT 1 FROM apps a JOIN project_environments e ON e.id=row_value.environment_id
  WHERE a.id=row_value.app_id AND a.account_id=row_value.account_id AND a.project_id=row_value.project_id
   AND e.project_id=a.project_id AND e.account_id=a.account_id AND e.slug=row_value.scope) THEN
  -- Removing catalog intent also invalidates caches captured under its UUID.
  -- The surviving app can retain deployments/sealed provider credentials.
  IF EXISTS(SELECT 1 FROM apps WHERE id=row_value.app_id FOR UPDATE) THEN
   stamp:=clock_timestamp();
   INSERT INTO app_runtime_config_scope_changes(app_id,scope,changed_at) VALUES(row_value.app_id,row_value.scope,stamp)
    ON CONFLICT(app_id,scope) DO UPDATE SET changed_at=greatest(app_runtime_config_scope_changes.changed_at,excluded.changed_at);
   UPDATE snapshots p SET stale=true FROM deployments d WHERE p.deployment_id=d.id AND d.app_id=row_value.app_id
    AND d.scope=row_value.scope AND NOT p.stale;
  END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.project_id IS DISTINCT FROM OLD.project_id
  OR NEW.environment_id IS DISTINCT FROM OLD.environment_id OR NEW.app_id IS DISTINCT FROM OLD.app_id
  OR NEW.scope IS DISTINCT FROM OLD.scope OR NEW.key IS DISTINCT FROM OLD.key) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_secret_ref_identity',MESSAGE='secret reference identity is immutable';
 END IF;
 SELECT s.* INTO src FROM active_environment_git_sources s
 WHERE s.environment_id=row_value.environment_id AND s.account_id=row_value.account_id FOR UPDATE OF s;
 IF TG_OP<>'DELETE' AND NOT EXISTS (SELECT 1 FROM apps a JOIN project_environments e ON e.id=row_value.environment_id
  WHERE a.id=row_value.app_id AND a.account_id=row_value.account_id AND a.project_id=row_value.project_id
   AND a.status<>'deleted' AND e.project_id=a.project_id AND e.account_id=a.account_id AND e.slug=row_value.scope
  FOR SHARE OF a,e) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_secret_ref_scope',MESSAGE='secret reference requires its account-owned project environment';
 END IF;
 IF src.id IS NOT NULL THEN
  SELECT logical_name INTO resource_name FROM environment_gitops_resources WHERE source_id=src.id AND app_id=row_value.app_id;
  controller:=EXISTS (SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id
   AND j.desired_generation=src.generation AND j.claimed_generation=src.generation AND j.lease_until>clock_timestamp()
   AND j.lease_token<>'' AND j.lease_token=current_setting('gregale.gitops_lease',true)
   AND src.approved_revision_id IS NOT NULL AND NOT src.suspended);
  IF src.mode='enforce' AND NOT controller AND EXISTS (
   SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.resource=resource_name
    AND f.field_path='secret_refs/'||row_value.key AND NOT EXISTS (SELECT 1 FROM environment_management_overrides o
     WHERE o.environment_id=f.environment_id AND o.resource=f.resource AND o.field_path=f.field_path AND o.expires_at>clock_timestamp())) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_field_owned',MESSAGE='setting is managed by the environment Git source';
  END IF;
  UPDATE environment_git_sources SET intent_version=intent_version+1,updated_at=now() WHERE id=src.id;
  IF src.generation>0 THEN
   INSERT INTO environment_gitops_jobs(source_id,desired_generation,next_attempt_at) VALUES(src.id,src.generation,now())
   ON CONFLICT(source_id) DO UPDATE SET next_attempt_at=least(environment_gitops_jobs.next_attempt_at,excluded.next_attempt_at);
  END IF;
 END IF;
 -- Publication and every ordinary writer share the app lock and scoped stamp.
 IF EXISTS(SELECT 1 FROM apps WHERE id=row_value.app_id FOR UPDATE) THEN
  stamp:=clock_timestamp();
  INSERT INTO app_runtime_config_scope_changes(app_id,scope,changed_at) VALUES(row_value.app_id,row_value.scope,stamp)
   ON CONFLICT(app_id,scope) DO UPDATE SET changed_at=greatest(app_runtime_config_scope_changes.changed_at,excluded.changed_at);
  UPDATE snapshots p SET stale=true FROM deployments d WHERE p.deployment_id=d.id AND d.app_id=row_value.app_id
   AND d.scope=row_value.scope AND NOT p.stale;
 END IF;
 -- Both kinds of intent share the same app lock. Direct SQL cannot retain
 -- a positive reference and a suppression for the same destination.
 IF TG_OP<>'DELETE' THEN
  IF (TG_TABLE_NAME='app_environment_secret_refs' AND EXISTS(SELECT 1 FROM app_environment_secret_ref_suppressions
    WHERE app_id=row_value.app_id AND environment_id=row_value.environment_id AND key=row_value.key))
   OR (TG_TABLE_NAME='app_environment_secret_ref_suppressions' AND EXISTS(SELECT 1 FROM app_environment_secret_refs
    WHERE app_id=row_value.app_id AND environment_id=row_value.environment_id AND key=row_value.key)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_secret_ref_exclusive',MESSAGE='reference and suppression are mutually exclusive';
  END IF;
  -- Mirrored by api.EnvironmentSecretReferenceSuppressionsMaxPerApp.
  IF TG_TABLE_NAME='app_environment_secret_ref_suppressions' AND TG_OP='INSERT'
   AND NOT EXISTS(SELECT 1 FROM app_environment_secret_ref_suppressions WHERE app_id=row_value.app_id AND environment_id=row_value.environment_id AND key=row_value.key)
   AND (SELECT count(*) FROM app_environment_secret_ref_suppressions WHERE app_id=row_value.app_id)>=1024 THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_secret_ref_suppression_quota',MESSAGE='secret reference suppression limit reached';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE NEW.updated_at:=stamp; RETURN NEW; END IF;
END;
$$;


--
-- Name: guard_environment_secret_reference_baseline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_secret_reference_baseline() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE old_app uuid; new_app uuid; old_scope text; new_scope text; src environment_git_sources%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' AND OLD.environment_workload_runtime IS NOT NULL AND NEW.environment_workload_runtime IS NOT NULL
  AND OLD.environment_workload_held AND OLD.status='snapshotting'
  AND NOT NEW.environment_workload_held AND NEW.status='live'
  AND environment_workload_activation_authorized(NEW) THEN
  RETURN NEW;
 END IF;
 IF TG_OP<>'INSERT' AND OLD.status='live' THEN old_app:=OLD.app_id; old_scope:=OLD.scope; END IF;
 IF TG_OP<>'DELETE' AND NEW.status='live' THEN new_app:=NEW.app_id; new_scope:=NEW.scope; END IF;
 IF old_app IS NULL AND new_app IS NULL THEN
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 END IF;
 FOR src IN SELECT s.* FROM environment_git_sources s JOIN project_environments e ON e.id=s.environment_id
  JOIN apps a ON a.project_id=s.project_id AND a.account_id=s.account_id
  WHERE (a.id=old_app AND e.slug=old_scope) OR (a.id=new_app AND e.slug=new_scope)
  ORDER BY s.id FOR UPDATE OF s LOOP
  PERFORM 1 FROM apps a WHERE (a.id=old_app OR a.id=new_app) AND a.project_id=src.project_id ORDER BY a.id FOR UPDATE;
  UPDATE environment_git_sources SET intent_version=intent_version+1,updated_at=now() WHERE id=src.id;
  IF src.generation>0 THEN
   INSERT INTO environment_gitops_jobs(source_id,desired_generation,next_attempt_at) VALUES(src.id,src.generation,now())
   ON CONFLICT(source_id) DO UPDATE SET next_attempt_at=least(environment_gitops_jobs.next_attempt_at,excluded.next_attempt_at);
  END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


--
-- Name: guard_environment_secret_reference_shadow(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_secret_reference_shadow() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE src environment_git_sources%ROWTYPE; resource_name text;
BEGIN
 SELECT s.* INTO src FROM active_environment_git_sources s JOIN project_environments e ON e.id=s.environment_id
 JOIN apps a ON a.project_id=s.project_id AND a.account_id=s.account_id
 WHERE a.id=NEW.app_id AND a.account_id=NEW.account_id AND e.slug=NEW.scope FOR UPDATE OF s;
 IF src.id IS NULL OR src.mode<>'enforce' THEN RETURN NEW; END IF;
 SELECT logical_name INTO resource_name FROM environment_gitops_resources WHERE source_id=src.id AND app_id=NEW.app_id;
 IF EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.resource=resource_name
  AND f.field_path='secret_refs/'||NEW.key AND NOT EXISTS(SELECT 1 FROM environment_management_overrides o
   WHERE o.environment_id=f.environment_id AND o.resource=f.resource AND o.field_path=f.field_path AND o.expires_at>clock_timestamp()))
 AND NOT EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id AND j.desired_generation=src.generation
  AND j.claimed_generation=src.generation AND j.lease_token=current_setting('gregale.gitops_lease',true)
  AND j.lease_token<>'' AND j.lease_until>clock_timestamp() AND NOT src.suspended AND src.approved_revision_id IS NOT NULL) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_field_owned',MESSAGE='setting is managed by the environment Git source';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_environment_service_binding_env_key(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_service_binding_env_key() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE row_value jsonb; src environment_git_sources%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN row_value:=to_jsonb(OLD); ELSE row_value:=to_jsonb(NEW); END IF;
 SELECT s.* INTO src FROM active_environment_git_sources s JOIN project_environments e ON e.id=s.environment_id
  JOIN environment_gitops_resources r ON r.source_id=s.id
 WHERE s.account_id=(row_value->>'account_id')::uuid AND r.app_id=(row_value->>'app_id')::uuid
  AND (e.id=nullif(row_value->>'environment_id','')::uuid OR e.slug=row_value->>'scope') FOR UPDATE OF s;
 IF src.id IS NOT NULL AND src.mode='enforce' AND EXISTS(SELECT 1 FROM app_environment_workload_intents w,
  jsonb_each(w.service_bindings) b WHERE w.app_id=(row_value->>'app_id')::uuid AND w.environment_id=src.environment_id
   AND b.value->>'env_key'=row_value->>'key') THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_field_owned',MESSAGE='environment key is reserved by a scoped service binding';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


--
-- Name: guard_environment_workload_candidate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_candidate() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE frozen jsonb; src environment_git_sources%ROWTYPE; allowed boolean;
BEGIN
 frozen:=NEW.environment_workload_runtime;
 IF NEW.status='live' THEN
  IF TG_OP='INSERT' THEN
   IF EXISTS(SELECT 1 FROM deployments d WHERE d.app_id=NEW.app_id AND d.scope=NEW.scope AND d.environment_workload_runtime IS NOT NULL)
    AND NOT environment_workload_activation_authorized(NEW) THEN
    RAISE EXCEPTION 'GitOps-managed workload promotion requires graph activation' USING ERRCODE='23514';
   END IF;
  ELSIF TG_OP='UPDATE' THEN
   IF OLD.status IS DISTINCT FROM 'live' AND
    EXISTS(SELECT 1 FROM deployments d WHERE d.app_id=NEW.app_id AND d.scope=NEW.scope AND d.environment_workload_runtime IS NOT NULL)
    AND NOT environment_workload_activation_authorized(NEW) THEN
    RAISE EXCEPTION 'GitOps-managed workload promotion requires graph activation' USING ERRCODE='23514';
   END IF;
  END IF;
 END IF;
 IF TG_OP='UPDATE' AND OLD.environment_workload_runtime IS NOT NULL AND OLD.status='live' AND
  NEW.status NOT IN ('live','failed') AND NOT (NEW.status='superseded' AND environment_workload_retirement_drain_authorized(OLD)) THEN
  RAISE EXCEPTION 'activated environment workload status is immutable' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND OLD.environment_workload_runtime IS NOT NULL AND OLD.status='live' AND
  ROW(NEW.rootfs_path,NEW.rootfs_key,NEW.rootfs_bytes) IS DISTINCT FROM ROW(OLD.rootfs_path,OLD.rootfs_key,OLD.rootfs_bytes) THEN
  RAISE EXCEPTION 'activated environment workload artifact is immutable' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND OLD.environment_workload_runtime IS NOT NULL THEN
  IF NEW.environment_workload_runtime IS DISTINCT FROM OLD.environment_workload_runtime OR
   (OLD.environment_workload_runtime ? 'source_archive' AND ROW(NEW.source_bytes,NEW.source_url,NEW.log_path,NEW.inferred_profile,NEW.github_source_ref,NEW.github_installation_id)
    IS DISTINCT FROM ROW(OLD.source_bytes,OLD.source_url,OLD.log_path,OLD.inferred_profile,OLD.github_source_ref,OLD.github_installation_id)) OR
   (NEW.build_id IS DISTINCT FROM OLD.build_id AND (OLD.build_id IS NOT NULL OR frozen->'source_archive' IS NULL OR
    NEW.build_id IS DISTINCT FROM (frozen->'source_archive'->>'build_id')::uuid OR NOT EXISTS(
     SELECT 1 FROM builds b WHERE b.id=NEW.build_id AND b.deployment_id=NEW.id AND b.kind='github' AND b.source_bytes=NEW.source_bytes))) OR
   environment_workload_deployment_inputs(NEW) IS DISTINCT FROM environment_workload_deployment_inputs(OLD) OR
   ROW(NEW.app_id,NEW.scope,NEW.kind,NEW.image_digest,NEW.commit_sha,NEW.source_path,NEW.source_root,NEW.source_sha256,NEW.handler,
       NEW.override_entrypoint,NEW.override_cmd,NEW.override_env,NEW.override_env_secrets,NEW.override_port,NEW.override_healthcheck,
       NEW.override_liveness_probe,NEW.override_readiness_probe,NEW.override_main_depends_on,NEW.release_command,NEW.release_command_shell)
   IS DISTINCT FROM
   ROW(OLD.app_id,OLD.scope,OLD.kind,OLD.image_digest,OLD.commit_sha,OLD.source_path,OLD.source_root,OLD.source_sha256,OLD.handler,
       OLD.override_entrypoint,OLD.override_cmd,OLD.override_env,OLD.override_env_secrets,OLD.override_port,OLD.override_healthcheck,
       OLD.override_liveness_probe,OLD.override_readiness_probe,OLD.override_main_depends_on,OLD.release_command,OLD.release_command_shell) THEN
   RAISE EXCEPTION 'frozen environment workload inputs are immutable' USING ERRCODE='23514';
  END IF;
 ELSIF frozen IS NOT NULL THEN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'environment workload inputs must be created atomically' USING ERRCODE='23514'; END IF;
  SELECT * INTO src FROM active_environment_git_sources WHERE id=(frozen->>'source_id')::uuid FOR UPDATE;
  allowed:=src.id IS NOT NULL AND src.mode='enforce' AND NOT src.suspended AND src.generation=(frozen->>'generation')::bigint
   AND src.intent_version=(frozen->>'intent_version')::bigint AND src.environment_id=(frozen->>'environment_id')::uuid
   AND src.approved_revision_id=(frozen->>'revision_id')::uuid AND EXISTS(SELECT 1 FROM environment_gitops_jobs j
    WHERE j.source_id=src.id AND j.desired_generation=src.generation AND j.claimed_generation=src.generation
     AND j.lease_until>clock_timestamp() AND j.lease_token<>'' AND j.lease_token=current_setting('gregale.gitops_lease',true));
  IF NOT allowed OR NOT EXISTS(SELECT 1 FROM environment_gitops_resources r JOIN apps a ON a.id=r.app_id
   JOIN project_environments e ON e.id=src.environment_id LEFT JOIN app_environment_workload_intents w ON w.app_id=a.id AND w.environment_id=e.id
   JOIN environment_desired_revisions rev ON rev.id=src.approved_revision_id AND rev.source_id=src.id
   WHERE r.source_id=src.id AND r.logical_name=frozen->>'resource' AND r.app_id=NEW.app_id AND a.status IN ('active','evicted_cold') AND (a.type='app' OR a.type='function' AND coalesce(a.runtime,'') IN ('node22','python312','go124','go124-alpine','node24','python313'))
    AND a.account_id=src.account_id AND a.project_id=src.project_id AND e.account_id=src.account_id AND e.project_id=src.project_id
    AND NEW.app_id=(frozen->>'app_id')::uuid AND NEW.scope=frozen->>'scope' AND NEW.scope=e.slug AND NEW.status='pending' AND (
     (NEW.kind='image' AND (
       (w.source->>'kind'='image' AND NEW.image_digest=w.source->>'image') OR
       (w.source IS NULL AND frozen ? 'deployment_inputs' AND jsonb_array_length(coalesce(frozen->'source_deployments','[]'::jsonb))>0
        AND NOT EXISTS(SELECT 1 FROM deployments d WHERE d.app_id=a.id AND d.scope=e.slug AND d.status='live'
         AND (d.kind<>'image' OR d.image_digest IS DISTINCT FROM NEW.image_digest))))
      AND NEW.image_digest ~ '^[^[:space:]]+@sha256:[a-f0-9]{64}$') OR
     (NEW.kind='github' AND w.source->>'kind' IN ('source','dockerfile','function') AND
      (w.source->>'kind'<>'function' OR a.type='function' AND a.runtime=w.source->>'runtime') AND w.source_revision=rev.commit_sha
      AND EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.resource=r.logical_name AND f.field_path='source') AND frozen->'source'=w.source AND
      jsonb_typeof(frozen->'source_archive')='object' AND frozen->'source_archive' ?& ARRAY['build_id','path','sha256','bytes','log_path','revision_id','commit_sha','definition_digest'] AND
      frozen->'source_archive'->>'revision_id'=rev.id::text AND frozen->'source_archive'->>'commit_sha'=rev.commit_sha AND
      frozen->'source_archive'->>'definition_digest'=rev.definition_digest AND frozen->>'definition_digest'=rev.definition_digest AND
      (frozen->'source_archive'->>'build_id')::uuid IS NOT NULL AND substring(frozen->'source_archive'->>'build_id',15,1)='7' AND
      NEW.source_root=w.source->>'directory' AND NEW.source_path=frozen->'source_archive'->>'path' AND NEW.source_path LIKE '/%' AND
      NEW.source_sha256=frozen->'source_archive'->>'sha256' AND NEW.source_sha256 ~ '^[a-f0-9]{64}$' AND
      NEW.source_bytes=(frozen->'source_archive'->>'bytes')::bigint AND NEW.source_bytes>0 AND
      NEW.log_path=frozen->'source_archive'->>'log_path' AND NEW.log_path LIKE '/%' AND
      NEW.source_url='github://'||src.repository||'@'||rev.commit_sha AND NEW.build_id IS NULL AND NEW.inferred_profile IS NULL AND
      coalesce(NEW.github_source_ref,'')='' AND coalesce(NEW.image_digest,'')=''))
    AND NEW.commit_sha=rev.commit_sha AND frozen->'runtime'=coalesce(w.runtime,'{}'::jsonb) AND coalesce(frozen->'service_bindings','{}'::jsonb)=coalesce(w.service_bindings,'{}'::jsonb)
    AND coalesce(frozen->'variables','{}'::jsonb)=coalesce(w.variables,'{}'::jsonb)
    AND coalesce(frozen->'schedule','null'::jsonb)=coalesce(w.schedule,'null'::jsonb)
    AND jsonb_strip_nulls(frozen->'baseline')=jsonb_strip_nulls(a.manifest)
    AND frozen->>'start_command'=coalesce(a.start_command,'')
    AND frozen->>'app_type'=a.type AND frozen->>'runtime_base'=coalesce(a.runtime,'') AND frozen->>'workload_class'=a.workload_class
    AND coalesce(a.manifest->'env','{}'::jsonb) IN ('{}'::jsonb,'null'::jsonb) AND coalesce(a.manifest->'service_bindings','[]'::jsonb) IN ('[]'::jsonb,'null'::jsonb)
    AND environment_workload_candidate_queue_bindings_valid(frozen, NEW.app_id)
    AND environment_workload_candidate_secret_refs_valid(frozen, NEW.app_id, NEW.scope, rev.definition->'workloads'->substr(r.logical_name,10)->'secret_refs')
    AND (EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.resource=r.logical_name AND (f.field_path IN ('source','source_revision','schedule') OR starts_with(f.field_path,'runtime/') OR starts_with(f.field_path,'service_bindings/') OR starts_with(f.field_path,'queue_bindings/') OR starts_with(f.field_path,'variables/') OR starts_with(f.field_path,'secret_refs/')))
     OR environment_workload_candidate_applied_removal_valid(frozen))) THEN
   RAISE EXCEPTION 'environment workload preparation lost its reviewed authority' USING ERRCODE='23514';
  END IF;
  IF frozen ? 'deployment_inputs' AND (
   jsonb_typeof(frozen->'deployment_inputs') IS DISTINCT FROM 'object' OR
   frozen->'deployment_inputs' IS DISTINCT FROM environment_workload_deployment_inputs(NEW) OR
   frozen->'source_deployments' IS DISTINCT FROM coalesce((SELECT jsonb_agg(d.id::text ORDER BY d.id)
    FROM deployments d WHERE d.app_id=NEW.app_id AND d.scope=NEW.scope AND d.status='live'),'[]'::jsonb) OR
   NOT EXISTS(SELECT 1 FROM deployments d WHERE d.app_id=NEW.app_id AND d.scope=NEW.scope AND d.status='live') OR
   EXISTS(SELECT 1 FROM deployments d WHERE d.app_id=NEW.app_id AND d.scope=NEW.scope AND d.status='live'
    AND environment_workload_deployment_inputs(d) IS DISTINCT FROM frozen->'deployment_inputs')) THEN
   RAISE EXCEPTION 'inherited environment workload inputs changed after review' USING ERRCODE='23514';
  END IF;
 END IF;
 IF frozen IS NOT NULL AND NEW.status='live' THEN
  IF TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'live' THEN
   IF NOT environment_workload_activation_authorized(NEW) THEN
    RAISE EXCEPTION 'environment workload graph is not qualified for activation' USING ERRCODE='23514';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_environment_workload_graph(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_graph() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE src environment_git_sources%ROWTYPE; rev environment_desired_revisions%ROWTYPE;
 member jsonb; member_count integer; names jsonb; allowed boolean;
 binding queue_bindings%ROWTYPE; consumer_ids jsonb; binding_resource text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF NOT EXISTS(SELECT 1 FROM active_environment_git_sources s JOIN project_environments e ON e.id=s.environment_id
   WHERE s.id=OLD.source_id AND e.id=OLD.environment_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'environment graph journal is retained with its original source' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.source_id,NEW.environment_id,NEW.revision_id,NEW.generation,NEW.intent_version,
  NEW.plan_hash,NEW.definition_digest,NEW.members,NEW.resource_ids,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.id,OLD.source_id,OLD.environment_id,OLD.revision_id,OLD.generation,OLD.intent_version,
  OLD.plan_hash,OLD.definition_digest,OLD.members,OLD.resource_ids,OLD.created_at) THEN
  RAISE EXCEPTION 'reviewed environment graph inputs are immutable' USING ERRCODE='23514';
 END IF;
 SELECT * INTO src FROM active_environment_git_sources WHERE id=NEW.source_id FOR UPDATE;
 allowed:=src.id IS NOT NULL AND src.environment_id=NEW.environment_id AND src.mode='enforce' AND NOT src.suspended
  AND src.generation=NEW.generation AND src.intent_version=NEW.intent_version AND src.approved_revision_id=NEW.revision_id
  AND EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id AND j.desired_generation=src.generation
   AND j.claimed_generation=src.generation AND j.lease_until>clock_timestamp() AND j.lease_token<>''
   AND j.lease_token=current_setting('gregale.gitops_lease',true));
 SELECT * INTO rev FROM environment_desired_revisions WHERE id=NEW.revision_id AND source_id=NEW.source_id;
 IF NOT coalesce(allowed,false) OR rev.definition_digest IS DISTINCT FROM NEW.definition_digest THEN
  RAISE EXCEPTION 'environment graph preparation lost reviewed authority' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' AND (NEW.phase<>'preparing' OR NEW.prepared_at IS NOT NULL OR NEW.error_code<>'') THEN
  RAISE EXCEPTION 'environment graph must begin in preparation' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND (OLD.phase='failed' AND ROW(NEW.phase,NEW.error_code,NEW.prepared_at) IS DISTINCT FROM ROW(OLD.phase,OLD.error_code,OLD.prepared_at)
  OR OLD.phase='prepared' AND NEW.phase='preparing'
  OR OLD.phase=NEW.phase AND ROW(NEW.error_code,NEW.prepared_at) IS DISTINCT FROM ROW(OLD.error_code,OLD.prepared_at)) THEN
  RAISE EXCEPTION 'environment graph preparation transition is invalid' USING ERRCODE='23514';
 END IF;
 SELECT count(DISTINCT value->>'resource'),coalesce(jsonb_agg(value->>'resource' ORDER BY value->>'resource'),'[]')
  INTO member_count,names FROM jsonb_array_elements(NEW.members);
 IF member_count<>jsonb_array_length(NEW.members) OR names IS DISTINCT FROM
  (SELECT coalesce(jsonb_agg('workload/'||key ORDER BY key),'[]') FROM jsonb_object_keys(rev.definition->'workloads') key) THEN
  RAISE EXCEPTION 'environment graph must include every reviewed workload exactly once' USING ERRCODE='23514';
 END IF;
 FOR member IN SELECT value FROM jsonb_array_elements(NEW.members) LOOP
  IF jsonb_typeof(member) IS DISTINCT FROM 'object' OR NOT member ?& ARRAY['resource','app_id','retained_deployments']
   OR jsonb_typeof(member->'retained_deployments') IS DISTINCT FROM 'array' OR NOT EXISTS(
    SELECT 1 FROM environment_gitops_resources r JOIN apps a ON a.id=r.app_id JOIN project_environments e ON e.id=src.environment_id
    WHERE r.source_id=src.id AND r.logical_name=member->>'resource' AND a.id=(member->>'app_id')::uuid
     AND a.account_id=src.account_id AND a.project_id=src.project_id AND a.status IN ('active','evicted_cold')
     AND e.account_id=src.account_id AND e.project_id=src.project_id
     AND NEW.resource_ids->>r.logical_name=a.id::text) OR
   member->'retained_deployments' IS DISTINCT FROM (SELECT coalesce(jsonb_agg(d.id::text ORDER BY d.id),'[]')
    FROM deployments d JOIN project_environments e ON e.id=src.environment_id
    WHERE d.app_id=(member->>'app_id')::uuid AND d.scope=e.slug AND d.status='live') THEN
   RAISE EXCEPTION 'environment graph original workload identities changed' USING ERRCODE='23514';
  END IF;
  IF member ? 'candidate_deployment_id' THEN
   IF NOT EXISTS(SELECT 1 FROM deployments d WHERE d.id=(member->>'candidate_deployment_id')::uuid
    AND d.app_id=(member->>'app_id')::uuid AND d.environment_workload_runtime->>'source_id'=src.id::text
    AND d.environment_workload_runtime->>'environment_id'=src.environment_id::text
    AND d.environment_workload_runtime->>'revision_id'=rev.id::text
    AND d.environment_workload_runtime->>'generation'=NEW.generation::text
    AND d.environment_workload_runtime->>'intent_version'=NEW.intent_version::text
    AND d.environment_workload_runtime->>'resource'=member->>'resource'
    AND d.environment_workload_runtime->>'plan_hash'=NEW.plan_hash
    AND (NEW.phase<>'prepared' OR d.status='snapshotting' AND (coalesce(d.rootfs_path,'')<>'' OR coalesce(d.rootfs_key,'')<>''))) THEN
    RAISE EXCEPTION 'environment graph candidate does not match its reviewed inputs or artifact phase' USING ERRCODE='23514';
   END IF;
  ELSIF EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.resource=member->>'resource'
   AND (f.field_path='source' OR starts_with(f.field_path,'runtime/'))) THEN
   RAISE EXCEPTION 'environment graph is missing a managed workload candidate' USING ERRCODE='23514';
  END IF;
  FOR binding IN SELECT b.* FROM queue_bindings b WHERE b.app_id=(member->>'app_id')::uuid
   AND b.account_id=src.account_id AND b.environment_id=src.environment_id LOOP
   binding_resource:=(member->>'resource')||'/queue_bindings/'||binding.name;
   SELECT coalesce(jsonb_agg(t.id::text ORDER BY t.id),'[]') INTO consumer_ids FROM triggers t WHERE t.queue_binding_id=binding.id;
   IF NEW.resource_ids->>binding_resource IS DISTINCT FROM binding.id::text OR
    jsonb_array_length(consumer_ids)=1 AND NEW.resource_ids->>(binding_resource||'/consumer') IS DISTINCT FROM consumer_ids->>0 OR
    jsonb_array_length(consumer_ids)<>1 AND NEW.resource_ids ? (binding_resource||'/consumer') THEN
    RAISE EXCEPTION 'environment graph original queue and consumer identities changed' USING ERRCODE='23514';
   END IF;
  END LOOP;
 END LOOP;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_hold_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_hold_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.environment_workload_runtime IS NOT NULL AND NOT NEW.environment_workload_held THEN
   RAISE EXCEPTION 'environment workload candidates must start held' USING ERRCODE='23514';
  END IF;
 ELSIF OLD.environment_workload_runtime IS NOT NULL AND
   NEW.environment_workload_held IS DISTINCT FROM OLD.environment_workload_held THEN
  IF NOT (OLD.environment_workload_held AND NOT NEW.environment_workload_held AND
   environment_workload_activation_authorized(NEW)) THEN
   RAISE EXCEPTION 'environment workload hold requires graph activation' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_image_full_rootfs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_image_full_rootfs() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE reviewed_source jsonb;
BEGIN
 IF NEW.environment_workload_runtime IS NULL OR NEW.kind <> 'image' THEN
  RETURN NEW;
 END IF;
 SELECT w.source INTO reviewed_source
 FROM app_environment_workload_intents w
 JOIN project_environments e ON e.id=w.environment_id
 WHERE w.app_id=NEW.app_id AND e.slug=NEW.scope;
 IF reviewed_source IS NULL OR reviewed_source->>'kind' <> 'image' THEN
  RETURN NEW;
 END IF;
 IF NEW.environment_workload_runtime->'source' IS DISTINCT FROM reviewed_source OR
    coalesce(reviewed_source->>'full_rootfs','false') NOT IN ('true','false') THEN
  RAISE EXCEPTION 'frozen image source differs from reviewed workload intent' USING ERRCODE='23514';
 END IF;
 IF reviewed_source->>'full_rootfs'='true' THEN
  IF NEW.full_rootfs_override IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'reviewed image requires full-rootfs opt-in' USING ERRCODE='23514';
  END IF;
 ELSIF NOT (NEW.environment_workload_runtime ? 'deployment_inputs') AND NEW.full_rootfs_override IS NOT NULL THEN
  RAISE EXCEPTION 'image full-rootfs override is not reviewed' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_instance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_instance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q environment_workload_qualification_requests%ROWTYPE; app_ram integer; may_deploy boolean; b environment_qualification_restore_reservations%ROWTYPE;
BEGIN
 IF TG_OP='INSERT' AND EXISTS(SELECT 1 FROM environment_qualification_executions WHERE instance_id=NEW.id) THEN
  RAISE EXCEPTION 'retained qualification instance cannot be reused' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM deployments d
   JOIN environment_git_sources s ON s.id=(d.environment_workload_runtime->>'source_id')::uuid
   JOIN project_environments e ON e.id=(d.environment_workload_runtime->>'environment_id')::uuid WHERE d.id=OLD.deployment_id) THEN
   SELECT * INTO q FROM environment_workload_qualification_requests WHERE reserved_instance_id=OLD.id OR id=(SELECT request_id FROM environment_qualification_restore_reservations WHERE instance_id=OLD.id) FOR UPDATE;
   IF OLD.state NOT IN ('parked','stopped','failed') OR (q.id IS NOT NULL AND q.lease_until>clock_timestamp()) THEN
    RAISE EXCEPTION 'environment qualification reservation must remain until retired and its attempt released' USING ERRCODE='23514';
   END IF;
  END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM deployments WHERE id=OLD.deployment_id AND environment_workload_runtime IS NOT NULL)
  AND ROW(NEW.id,NEW.app_id,NEW.deployment_id,NEW.node_id,NEW.wake_id,NEW.mode,NEW.ram_mb,NEW.kind,NEW.job_id)
   IS DISTINCT FROM ROW(OLD.id,OLD.app_id,OLD.deployment_id,OLD.node_id,OLD.wake_id,OLD.mode,OLD.ram_mb,OLD.kind,OLD.job_id) THEN
  RAISE EXCEPTION 'environment qualification instance identity is immutable' USING ERRCODE='23514';
 END IF;
 SELECT * INTO b FROM environment_qualification_restore_reservations WHERE instance_id=NEW.id;
 SELECT * INTO q FROM environment_workload_qualification_requests WHERE reserved_instance_id=NEW.id OR
  (b.instance_id IS NOT NULL AND id=b.request_id AND reserved_instance_id=b.capture_instance_id AND attempt=b.attempt);
 IF q.id IS NOT NULL AND (q.app_id IS DISTINCT FROM NEW.app_id OR q.deployment_id IS DISTINCT FROM NEW.deployment_id) THEN
  RAISE EXCEPTION 'environment qualification reservation cannot be reassigned' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND q.id IS NULL AND NEW.state IN ('draining','snapshotting','parked','stopped','failed','evicting_account_deleting') AND
  EXISTS(SELECT 1 FROM environment_workload_retirements r JOIN deployments d ON d.id=OLD.deployment_id
   WHERE d.id=ANY(r.deployment_ids) AND d.status='superseded' AND NOT d.environment_workload_held AND r.phase NOT IN ('planned','cancelled')) THEN RETURN NEW; END IF;
 IF q.id IS NULL AND EXISTS(SELECT 1 FROM deployments WHERE id=NEW.deployment_id AND app_id=NEW.app_id
  AND environment_workload_runtime IS NOT NULL AND NOT environment_workload_held AND status='live') THEN RETURN NEW; END IF;
 IF NOT EXISTS(SELECT 1 FROM deployments WHERE id=NEW.deployment_id AND environment_workload_runtime IS NOT NULL) THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NOT EXISTS(SELECT 1 FROM deployments WHERE id=OLD.deployment_id AND environment_workload_runtime IS NOT NULL) THEN
  RAISE EXCEPTION 'environment qualification instances must be created under their attempt' USING ERRCODE='23514';
 END IF;
 -- Retirement must remain available after expiry, supersession and parent
 -- deletion. It cannot grant execution or qualification evidence.
 IF TG_OP='UPDATE' AND NEW.state IN ('parked','stopped','failed','evicting_account_deleting') THEN RETURN NEW; END IF;
 IF q.id IS NOT NULL THEN
  PERFORM s.id FROM environment_git_sources s JOIN environment_workload_graphs g ON g.source_id=s.id
   WHERE g.id=q.graph_id FOR UPDATE OF s;
  PERFORM a.id FROM apps a JOIN environment_workload_graphs g ON g.id=q.graph_id
   JOIN LATERAL jsonb_array_elements(g.members) m ON a.id=(m->>'app_id')::uuid ORDER BY a.id FOR UPDATE OF a;
  SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=q.id AND deployment_id=NEW.deployment_id FOR UPDATE;
 END IF;
 IF q.id IS NULL OR q.phase<>'claimed' OR (q.execution_mode='job' AND
    (coalesce(jsonb_typeof(q.frozen_inputs->'job_smoke'),'null')<>'object' OR
     coalesce(nullif(q.frozen_inputs->'queue_bindings','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb
     OR NOT EXISTS(SELECT 1 FROM environment_workload_graphs g, jsonb_array_elements(g.members) member
       WHERE g.id=q.graph_id AND member->>'resource'=q.resource AND member->>'execution_mode'='job'
        AND coalesce((member->>'job_smoke_configured')::boolean,false)
        AND coalesce(nullif(member->'service_bindings','null'::jsonb),'{}'::jsonb)=coalesce(nullif(q.frozen_inputs->'service_bindings','null'::jsonb),'{}'::jsonb)
        AND coalesce((member->>'service_bindings_configured')::boolean,false)=(coalesce(nullif(q.frozen_inputs->'service_bindings','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb)
        AND coalesce(member->>'queue_bindings_configured','false')='false'
        AND coalesce(nullif(member->'queue_bindings','null'::jsonb),'{}'::jsonb)='{}'::jsonb
        AND coalesce(nullif(member->'queue_modes','null'::jsonb),'{}'::jsonb)='{}'::jsonb))) OR q.lease_until<=clock_timestamp()
  OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
  OR q.app_id<>NEW.app_id OR NEW.kind<>'wake' OR NEW.job_id IS NOT NULL
  OR NEW.mode IS DISTINCT FROM (CASE q.execution_mode WHEN 'worker' THEN 'worker' WHEN 'service' THEN 'service' ELSE 'normal' END)
  OR (b.instance_id IS NOT NULL AND (NOT environment_qualification_restore_current(q.id,b.capture_instance_id)
   OR NEW.wake_id=(SELECT (frame->>'wake_id')::uuid FROM environment_qualification_executions WHERE instance_id=b.capture_instance_id)))
  OR NOT environment_workload_qualification_inputs_current(q.id) THEN
  RAISE EXCEPTION 'environment workload execution requires its current qualification attempt' USING ERRCODE='23514';
 END IF;
 SELECT a.ram_mb,c.status='active' AND c.abuse_hold_at IS NULL INTO app_ram,may_deploy
  FROM apps a JOIN app_resource_accounts c ON c.app_id=a.id WHERE a.id=NEW.app_id FOR SHARE OF a;
 IF NOT coalesce(may_deploy,false) OR NEW.ram_mb IS DISTINCT FROM app_ram OR NOT EXISTS(
  SELECT 1 FROM compute_nodes WHERE id=NEW.node_id AND active AND lifecycle='active') OR
  (TG_OP='INSERT' AND (NEW.state<>'cold_booting' OR coalesce(NEW.netns,'')<>'' OR NEW.host_ip IS NOT NULL
   OR coalesce(NEW.guest_uid,0)<>0 OR NEW.framework_ready_at IS NOT NULL)) THEN
  RAISE EXCEPTION 'environment qualification admission shape is invalid' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
 row_value jsonb; prior jsonb; src environment_git_sources%ROWTYPE;
 resource_name text; paths text[]; controller boolean;
BEGIN
 IF TG_OP='DELETE' THEN row_value:=to_jsonb(OLD); ELSE row_value:=to_jsonb(NEW); END IF;
 IF TG_OP='DELETE' AND NOT EXISTS(SELECT 1 FROM apps a JOIN app_resource_accounts c ON c.app_id=a.id
  JOIN project_environments e ON e.account_id=a.account_id AND e.project_id=a.project_id
  WHERE a.id=OLD.app_id AND a.account_id=OLD.account_id AND e.id=OLD.environment_id) THEN
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.app_id IS DISTINCT FROM OLD.app_id OR NEW.environment_id IS DISTINCT FROM OLD.environment_id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_workload_intent_identity',MESSAGE='scoped workload identity is immutable';
 END IF;
 IF TG_OP<>'DELETE' AND NOT EXISTS(SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
  WHERE a.id=NEW.app_id AND a.account_id=NEW.account_id AND e.id=NEW.environment_id AND a.status<>'deleted') THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_workload_intent_identity',MESSAGE='scoped workload requires its original project environment';
 END IF;
 SELECT s.* INTO src FROM active_environment_git_sources s WHERE s.account_id=(row_value->>'account_id')::uuid
  AND s.environment_id=(row_value->>'environment_id')::uuid FOR UPDATE OF s;
 IF TG_OP='INSERT' THEN
  SELECT to_jsonb(w) INTO prior FROM app_environment_workload_intents w
   WHERE w.app_id=NEW.app_id AND w.environment_id=NEW.environment_id FOR UPDATE OF w;
  prior:=coalesce(prior,'{}');
 ELSE prior:=to_jsonb(OLD); END IF;
 IF TG_OP='DELETE' THEN row_value:=row_value||jsonb_build_object('source',NULL,'source_revision',NULL,'runtime','{}'::jsonb,'service_bindings','{}'::jsonb,'schedule',NULL,'variables','{}'::jsonb); END IF;
 SELECT array_agg('runtime/'||k) INTO paths FROM (
  SELECT key k FROM jsonb_each(coalesce(prior->'runtime','{}')) UNION SELECT key FROM jsonb_each(row_value->'runtime')
 ) keys WHERE (prior->'runtime'->k) IS DISTINCT FROM (row_value->'runtime'->k);
 IF coalesce(prior->'source','null'::jsonb) IS DISTINCT FROM coalesce(row_value->'source','null'::jsonb) THEN paths:=coalesce(paths,'{}')||ARRAY['source']; END IF;
 IF coalesce(prior->'source_revision','null'::jsonb) IS DISTINCT FROM coalesce(row_value->'source_revision','null'::jsonb) THEN paths:=coalesce(paths,'{}')||ARRAY['source_revision','source']; END IF;
 SELECT coalesce(paths,'{}')||coalesce(array_agg('service_bindings/'||k),'{}') INTO paths FROM (
  SELECT key k FROM jsonb_each(coalesce(prior->'service_bindings','{}')) UNION SELECT key FROM jsonb_each(row_value->'service_bindings')
 ) keys WHERE (prior->'service_bindings'->k) IS DISTINCT FROM (row_value->'service_bindings'->k);
 IF prior->'schedule' IS DISTINCT FROM row_value->'schedule' THEN paths:=coalesce(paths,'{}')||ARRAY['schedule']; END IF;
 SELECT coalesce(paths,'{}')||coalesce(array_agg('variables/'||k),'{}') INTO paths FROM (
  SELECT key k FROM jsonb_each(coalesce(prior->'variables','{}')) UNION SELECT key FROM jsonb_each(row_value->'variables')
 ) keys WHERE (prior->'variables'->k) IS DISTINCT FROM (row_value->'variables'->k);
 IF TG_OP<>'DELETE' AND EXISTS(SELECT 1 FROM jsonb_each(NEW.service_bindings) b WHERE
  b.key !~ '^[a-z0-9][a-z0-9-]*$' OR jsonb_typeof(b.value)<>'object' OR
  NOT b.value ?& ARRAY['workload','env_key','target_app_id'] OR b.value->>'env_key' !~ '^[A-Za-z_][A-Za-z0-9_]*$' OR
  NOT EXISTS(SELECT 1 FROM environment_gitops_resources r JOIN apps a ON a.id=r.app_id
   WHERE r.source_id=src.id AND r.logical_name='workload/'||(b.value->>'workload') AND a.id=(b.value->>'target_app_id')::uuid
   AND a.id<>NEW.app_id AND a.account_id=NEW.account_id AND a.project_id=src.project_id AND a.status<>'deleted')) THEN
  RAISE EXCEPTION 'scoped service binding requires its original environment target' USING ERRCODE='23514';
 END IF;
 IF TG_OP<>'DELETE' AND EXISTS(SELECT 1 FROM jsonb_each(NEW.variables) v WHERE
  v.key !~ '^[A-Z][A-Z0-9_]*$' OR length(v.key)>128 OR jsonb_typeof(v.value)<>'string' OR
  octet_length(v.value #>> '{}')>32768) THEN
  RAISE EXCEPTION 'scoped workload variables require valid keys and string values' USING ERRCODE='23514';
 END IF;
 IF TG_OP<>'DELETE' AND (SELECT count(*) FROM jsonb_object_keys(NEW.variables))>256 THEN
  RAISE EXCEPTION 'scoped workload variable count exceeds the platform limit' USING ERRCODE='23514';
 END IF;
 IF TG_OP<>'DELETE' AND ((SELECT count(*) FROM jsonb_object_keys(NEW.service_bindings))>100 OR EXISTS(
  SELECT 1 FROM jsonb_each(NEW.service_bindings) GROUP BY value->>'env_key' HAVING count(*)>1)) THEN
  RAISE EXCEPTION 'scoped service binding count or environment keys are invalid' USING ERRCODE='23514';
 END IF;
 IF TG_OP<>'DELETE' AND NEW.source->>'kind'='function' AND NOT EXISTS(SELECT 1 FROM apps a
  WHERE a.id=NEW.app_id AND a.type='function' AND a.runtime=NEW.source->>'runtime') THEN
  RAISE EXCEPTION 'function source requires its original supported runner' USING ERRCODE='23514';
 END IF;
 IF TG_OP<>'DELETE' AND NEW.schedule IS NOT NULL AND NOT EXISTS(SELECT 1 FROM apps a WHERE a.id=NEW.app_id
  AND (NEW.runtime->>'execution_mode'='job' OR a.manifest->>'execution_mode'='job')) THEN
  RAISE EXCEPTION 'scheduled workload requires job execution mode' USING ERRCODE='23514';
 END IF;
 IF TG_OP<>'DELETE' AND EXISTS(SELECT 1 FROM jsonb_each(NEW.service_bindings) b
  JOIN project_environments e ON e.id=NEW.environment_id WHERE
   EXISTS(SELECT 1 FROM app_envs v WHERE v.app_id=NEW.app_id AND v.scope=e.slug AND v.key=b.value->>'env_key') OR
   EXISTS(SELECT 1 FROM app_environment_secret_refs r WHERE r.app_id=NEW.app_id AND r.environment_id=e.id AND r.key=b.value->>'env_key') OR
   NEW.variables ? (b.value->>'env_key')) THEN
  RAISE EXCEPTION 'scoped service binding environment key is already occupied' USING ERRCODE='23514';
 END IF;
 IF coalesce(cardinality(paths),0)=0 THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
 IF src.id IS NOT NULL THEN
  SELECT logical_name INTO resource_name FROM environment_gitops_resources WHERE source_id=src.id AND app_id=(row_value->>'app_id')::uuid;
  controller:=EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id AND j.desired_generation=src.generation
   AND j.claimed_generation=src.generation AND j.lease_until>clock_timestamp() AND j.lease_token<>''
   AND j.lease_token=current_setting('gregale.gitops_lease',true) AND src.approved_revision_id IS NOT NULL AND NOT src.suspended);
  IF src.mode='enforce' AND NOT controller AND EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id
   AND f.environment_id=src.environment_id AND f.resource=resource_name AND f.field_path=ANY(paths)
   AND NOT EXISTS(SELECT 1 FROM environment_management_overrides o WHERE o.environment_id=f.environment_id
    AND o.resource=f.resource AND o.field_path=f.field_path AND o.expires_at>clock_timestamp())) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_field_owned',MESSAGE='setting is managed by the environment Git source';
  END IF;
  UPDATE environment_git_sources SET intent_version=intent_version+1,updated_at=now() WHERE id=src.id;
  IF src.generation>0 THEN INSERT INTO environment_gitops_jobs(source_id,desired_generation,next_attempt_at) VALUES(src.id,src.generation,now())
   ON CONFLICT(source_id) DO UPDATE SET next_attempt_at=least(environment_gitops_jobs.next_attempt_at,excluded.next_attempt_at); END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$_$;


--
-- Name: guard_environment_workload_job(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_job() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    managed boolean;
    controller boolean;
    deleting_account boolean;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM app_environment_workload_intents i
        WHERE i.job_id=OLD.id
    ) INTO managed;
    IF NOT managed THEN
        IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM app_environment_workload_intents i
        JOIN active_environment_git_sources s
          ON s.account_id=i.account_id AND s.environment_id=i.environment_id
        JOIN environment_gitops_resources r
          ON r.source_id=s.id AND r.app_id=i.app_id
        JOIN environment_gitops_jobs j ON j.source_id=s.id
        WHERE i.job_id=OLD.id AND s.mode='enforce' AND NOT s.suspended
          AND s.approved_revision_id IS NOT NULL
          AND j.desired_generation=s.generation AND j.claimed_generation=s.generation
          AND j.lease_until>clock_timestamp() AND j.lease_token<>''
          AND j.lease_token=current_setting('gregale.gitops_lease',true)
    ) INTO controller;
    SELECT EXISTS (
        SELECT 1 FROM accounts WHERE id=OLD.account_id AND status='deleted_pending'
    ) INTO deleting_account;

    IF TG_OP='DELETE' THEN
        IF NOT controller AND NOT deleting_account THEN
            RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='environment_gitops_job_managed',
                MESSAGE='Job settings are managed by the environment Git source';
        END IF;
        RETURN OLD;
    END IF;

    IF ROW(NEW.account_id,NEW.kind,NEW.name,NEW.image_ref,NEW.ram_mb,NEW.task_timeout_s,
           NEW.max_parallelism,NEW.retry_max,NEW.env_overrides,NEW.status,NEW.command,
           NEW.cron_schedule,NEW.cron_timezone,NEW.schedule_policy,NEW.failure_rules)
       IS DISTINCT FROM
       ROW(OLD.account_id,OLD.kind,OLD.name,OLD.image_ref,OLD.ram_mb,OLD.task_timeout_s,
           OLD.max_parallelism,OLD.retry_max,OLD.env_overrides,OLD.status,OLD.command,
           OLD.cron_schedule,OLD.cron_timezone,OLD.schedule_policy,OLD.failure_rules)
       AND NOT controller AND NOT deleting_account THEN
        RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='environment_gitops_job_managed',
            MESSAGE='Job settings are managed by the environment Git source';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_environment_workload_job_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_job_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP<>'DELETE' AND NEW.job_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM jobs j
        WHERE j.id=NEW.job_id AND j.account_id=NEW.account_id
          AND j.kind='recurring' AND j.status IN ('paused','active')
          AND NEW.schedule IS NOT NULL AND NEW.source->>'kind'='image'
          AND j.image_ref=NEW.source->>'image'
          AND j.env_overrides=NEW.variables
          AND j.cron_schedule=NEW.schedule->>'cron'
          AND j.cron_timezone=NEW.schedule->>'timezone'
          AND j.schedule_policy IS NOT DISTINCT FROM NULLIF(NEW.schedule->'schedule_policy','null'::jsonb)
          AND j.failure_rules IS NOT DISTINCT FROM NULLIF(NEW.schedule->'failure_rules','null'::jsonb)
    ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='environment_gitops_job_link_contract',
            MESSAGE='GitOps Job binding does not match the reviewed image and schedule';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_environment_workload_qualification_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_qualification_request() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE graph environment_workload_graphs%ROWTYPE; src environment_git_sources%ROWTYPE; dep deployments%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN
  IF NOT EXISTS(SELECT 1 FROM environment_workload_graphs WHERE id=OLD.graph_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'qualification work is retained with its reviewed graph' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.graph_id,NEW.deployment_id,NEW.app_id,NEW.resource,NEW.artifact,NEW.frozen_inputs,NEW.execution_mode,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.id,OLD.graph_id,OLD.deployment_id,OLD.app_id,OLD.resource,OLD.artifact,OLD.frozen_inputs,OLD.execution_mode,OLD.created_at) THEN
  RAISE EXCEPTION 'environment qualification inputs are immutable' USING ERRCODE='23514';
 END IF;
 -- The state store takes source, then sorted app locks, before this row.
 SELECT s.* INTO src FROM active_environment_git_sources s JOIN environment_workload_graphs g ON g.source_id=s.id WHERE g.id=NEW.graph_id FOR UPDATE OF s;
 SELECT * INTO graph FROM environment_workload_graphs WHERE id=NEW.graph_id;
 SELECT * INTO dep FROM deployments WHERE id=NEW.deployment_id;
 IF src.id IS NULL OR src.mode<>'enforce' OR src.suspended OR graph.phase<>'prepared' OR graph.generation<>src.generation OR
  graph.intent_version<>src.intent_version OR graph.revision_id IS DISTINCT FROM src.approved_revision_id OR graph.environment_id<>src.environment_id OR
  dep.status<>'snapshotting' OR coalesce(dep.rootfs_bytes,0)<=0 OR coalesce(dep.rootfs_key,'')='' AND coalesce(dep.rootfs_path,'')='' OR
  NEW.artifact IS DISTINCT FROM environment_workload_artifact(dep) OR NEW.frozen_inputs IS DISTINCT FROM dep.environment_workload_runtime OR
  NEW.execution_mode IS DISTINCT FROM (CASE WHEN NEW.frozen_inputs->'runtime' ? 'execution_mode'
   THEN coalesce(nullif(NEW.frozen_inputs->'runtime'->>'execution_mode',''),'request')
   ELSE coalesce(nullif(NEW.frozen_inputs->'baseline'->>'execution_mode',''),'request') END) OR
  NOT EXISTS(SELECT 1 FROM jsonb_array_elements(graph.members) m WHERE m->>'resource'=NEW.resource AND m->>'app_id'=NEW.app_id::text
   AND m->>'candidate_deployment_id'=NEW.deployment_id::text) OR NOT EXISTS(
   SELECT 1 FROM apps a JOIN project_environments e ON e.id=graph.environment_id
   WHERE a.id=NEW.app_id AND a.id=dep.app_id AND a.status IN ('active','evicted_cold') AND a.account_id=src.account_id AND a.project_id=src.project_id
    AND e.account_id=src.account_id AND e.project_id=src.project_id AND dep.scope=e.slug
    AND jsonb_strip_nulls(NEW.frozen_inputs->'baseline')=jsonb_strip_nulls(a.manifest)
    AND NEW.frozen_inputs->>'start_command'=coalesce(a.start_command,'')
    AND NEW.frozen_inputs->>'app_type'=a.type AND NEW.frozen_inputs->>'runtime_base'=coalesce(a.runtime,'')
    AND NEW.frozen_inputs->>'workload_class'=a.workload_class) THEN
  RAISE EXCEPTION 'environment qualification lost its reviewed graph or artifact' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.phase<>'queued' OR NOT EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id AND j.desired_generation=src.generation
   AND j.claimed_generation=src.generation AND j.lease_until>clock_timestamp() AND j.lease_token<>''
   AND j.lease_token=current_setting('gregale.gitops_lease',true)) THEN
   RAISE EXCEPTION 'environment qualification publication requires the issued intent lease' USING ERRCODE='23514';
  END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(graph.members) m LEFT JOIN environment_workload_qualification_requests q
   ON q.graph_id=graph.id AND q.resource=m->>'resource' AND q.deployment_id=(m->>'candidate_deployment_id')::uuid
   LEFT JOIN deployments d ON d.id=q.deployment_id LEFT JOIN apps a ON a.id=d.app_id
   WHERE m ? 'candidate_deployment_id' AND (q.id IS NULL OR d.status IS DISTINCT FROM 'snapshotting'
    OR q.artifact IS DISTINCT FROM environment_workload_artifact(d) OR q.frozen_inputs IS DISTINCT FROM d.environment_workload_runtime
    OR a.status IS NULL OR a.status NOT IN ('active','evicted_cold')
    OR jsonb_strip_nulls(q.frozen_inputs->'baseline') IS DISTINCT FROM jsonb_strip_nulls(a.manifest)
    OR q.frozen_inputs->>'start_command' IS DISTINCT FROM coalesce(a.start_command,'')
    OR q.frozen_inputs->>'app_type' IS DISTINCT FROM a.type OR q.frozen_inputs->>'runtime_base' IS DISTINCT FROM coalesce(a.runtime,'')
    OR q.frozen_inputs->>'workload_class' IS DISTINCT FROM a.workload_class)) THEN
   RAISE EXCEPTION 'environment qualification requires the complete unchanged artifact cohort' USING ERRCODE='23514';
  END IF;
  IF NEW.phase<>'claimed' OR NEW.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true) OR
   NEW.lease_until<=clock_timestamp() OR NEW.lease_until>clock_timestamp()+interval '15 minutes' OR
   (OLD.phase='claimed' AND OLD.lease_until>clock_timestamp() AND
    (NEW.lease_token<>OLD.lease_token OR NEW.worker_id<>OLD.worker_id OR NEW.attempt<>OLD.attempt OR NEW.lease_until<OLD.lease_until
     OR NEW.reserved_instance_id IS DISTINCT FROM OLD.reserved_instance_id)) OR
   ((OLD.phase='queued' OR OLD.lease_until<=clock_timestamp()) AND
    (NEW.attempt<>OLD.attempt+1 OR NEW.lease_token=OLD.lease_token OR
     OLD.reserved_instance_id IS NOT NULL AND NEW.execution_mode<>'job' AND NEW.reserved_instance_id=OLD.reserved_instance_id OR
     EXISTS(SELECT 1 FROM instances i WHERE i.id=OLD.reserved_instance_id AND i.state NOT IN ('parked','stopped','failed')))) THEN
   RAISE EXCEPTION 'environment qualification execution lease is stale' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_queue_serving_ack(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_queue_serving_ack() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        IF EXISTS (SELECT 1 FROM environment_workload_graphs WHERE id=OLD.graph_id) THEN
            RAISE EXCEPTION 'environment queue serving acknowledgements are retained' USING ERRCODE='23514';
        END IF;
        RETURN OLD;
    END IF;
    IF TG_OP='UPDATE' AND ROW(NEW.graph_id,NEW.binding_id,NEW.mode,NEW.trigger_id,NEW.app_id,NEW.deployment_id,NEW.invocation_id)
        IS DISTINCT FROM ROW(OLD.graph_id,OLD.binding_id,OLD.mode,OLD.trigger_id,OLD.app_id,OLD.deployment_id,OLD.invocation_id) THEN
        RAISE EXCEPTION 'environment queue serving acknowledgement identity is immutable' USING ERRCODE='23514';
    END IF;
    IF NOT environment_workload_graph_serving_supported(NEW.graph_id) OR
        NOT environment_workload_queue_serving_ack_authorized(NEW.graph_id,NEW.binding_id,NEW.mode,NEW.trigger_id,
            NEW.app_id,NEW.deployment_id,NEW.invocation_id) THEN
        RAISE EXCEPTION 'environment queue serving acknowledgement is outside the supported active graph' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_retirement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE src environment_git_sources%ROWTYPE; rev environment_desired_revisions%ROWTYPE; token text; original_app uuid;
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM accounts WHERE id=OLD.account_id AND status<>'deleted_pending') THEN
   RAISE EXCEPTION 'workload retirement history must be retained' USING ERRCODE='23514';
  END IF;
  RETURN OLD;
 END IF;
 SELECT * INTO src FROM active_environment_git_sources WHERE id=NEW.source_id FOR UPDATE;
 token:=nullif(current_setting('gregale.gitops_lease',true),'');
 IF src.id IS NULL OR src.mode<>'enforce' OR src.suspended OR token IS NULL OR
  ROW(src.account_id,src.project_id,src.environment_id) IS DISTINCT FROM ROW(NEW.account_id,NEW.project_id,NEW.environment_id) OR
  NOT EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id AND j.desired_generation=src.generation
   AND j.claimed_generation=src.generation AND j.lease_token=token AND j.lease_until>clock_timestamp()) THEN
  RAISE EXCEPTION 'workload retirement requires its current scoped lease' USING ERRCODE='23514';
 END IF;
 SELECT * INTO rev FROM environment_desired_revisions WHERE id=src.approved_revision_id AND source_id=src.id;
 SELECT app_id INTO original_app FROM environment_gitops_resources WHERE source_id=src.id AND logical_name=NEW.resource;
 IF rev.id IS NULL OR original_app IS DISTINCT FROM NEW.app_id OR NOT EXISTS(
  SELECT 1 FROM apps WHERE id=NEW.app_id AND account_id=src.account_id AND project_id=src.project_id AND status<>'deleted') THEN
  RAISE EXCEPTION 'workload retirement lost its original identity' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NOT src.prune OR jsonb_typeof(rev.definition->'workloads') IS DISTINCT FROM 'object' OR
   rev.definition->>'workload_pruning_policy' IS DISTINCT FROM 'retain' OR
   rev.definition->'workloads' ? substring(NEW.resource from 10) OR NEW.revision_id<>rev.id OR NEW.generation<>src.generation OR
   NEW.route_deployment_id IS DISTINCT FROM (SELECT d.id FROM deployments d JOIN project_environments e ON e.id=src.environment_id
    WHERE d.app_id=NEW.app_id AND d.scope=e.slug AND d.environment_workload_runtime->>'source_id'=src.id::text
     AND NOT d.environment_workload_held
     AND coalesce(d.environment_workload_runtime->'runtime'->>'execution_mode',d.environment_workload_runtime->'baseline'->>'execution_mode','request')<>'job'
    ORDER BY d.id LIMIT 1) OR
   NEW.phase<>'planned' OR
   NEW.deployment_ids IS DISTINCT FROM ARRAY(SELECT d.id FROM deployments d JOIN project_environments e ON e.id=src.environment_id
    WHERE d.app_id=NEW.app_id AND d.scope=e.slug AND d.environment_workload_runtime->>'source_id'=src.id::text ORDER BY d.id) OR
   NEW.queue_binding_ids IS DISTINCT FROM ARRAY(SELECT q.binding_id FROM environment_gitops_queue_bindings q
    WHERE q.source_id=src.id AND q.resource=NEW.resource AND q.binding_id IS NOT NULL ORDER BY q.binding_id) OR
   NEW.job_id IS DISTINCT FROM (SELECT w.job_id FROM app_environment_workload_intents w WHERE w.app_id=NEW.app_id AND w.environment_id=src.environment_id) OR
   NEW.route_generation<>0 OR cardinality(NEW.expected_gateways)<>0 OR cardinality(NEW.acknowledged_gateways)<>0 OR
   NOT EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.manager_id=src.id::text
    AND f.resource=NEW.resource AND f.field_path='presence') OR
   EXISTS(SELECT 1 FROM environment_management_overrides o WHERE o.environment_id=src.environment_id AND o.resource=NEW.resource AND o.expires_at>clock_timestamp()) THEN
   RAISE EXCEPTION 'workload retirement has no reviewed retain authority' USING ERRCODE='23514';
  END IF;
 ELSE
  IF ROW(NEW.id,NEW.source_id,NEW.account_id,NEW.project_id,NEW.environment_id,NEW.app_id,NEW.resource,NEW.revision_id,
   NEW.generation,NEW.plan_hash,NEW.deployment_ids,NEW.queue_binding_ids,NEW.job_id,NEW.route_deployment_id,NEW.requested_at)
   IS DISTINCT FROM ROW(OLD.id,OLD.source_id,OLD.account_id,OLD.project_id,OLD.environment_id,OLD.app_id,OLD.resource,OLD.revision_id,
   OLD.generation,OLD.plan_hash,OLD.deployment_ids,OLD.queue_binding_ids,OLD.job_id,OLD.route_deployment_id,OLD.requested_at) OR
   OLD.retired_at IS NOT NULL AND NEW.retired_at IS DISTINCT FROM OLD.retired_at OR
   OLD.recovered_at IS NOT NULL AND NEW.recovered_at IS DISTINCT FROM OLD.recovered_at THEN
   RAISE EXCEPTION 'original workload retirement records are immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.phase IS DISTINCT FROM OLD.phase AND NOT (
   OLD.phase='planned' AND NEW.phase IN ('retiring','cancelled') OR
   OLD.phase='retiring' AND NEW.phase='retired' OR OLD.phase='retired' AND NEW.phase='recovering' OR
   OLD.phase='recovering' AND NEW.phase IN ('recovered','retired')) THEN
   RAISE EXCEPTION 'invalid workload retirement transition' USING ERRCODE='23514';
  END IF;
  IF NEW.phase='recovering' AND (OLD.phase IS DISTINCT FROM 'recovering' OR
   ROW(NEW.recovery_revision_id,NEW.recovery_generation) IS DISTINCT FROM ROW(OLD.recovery_revision_id,OLD.recovery_generation)) AND (
   rev.definition->'workload_recoveries'->>substring(NEW.resource from 10) IS DISTINCT FROM NEW.app_id::text OR
   NOT (rev.definition->'workloads' ? substring(NEW.resource from 10)) OR NEW.recovery_revision_id<>rev.id OR NEW.recovery_generation<>src.generation) THEN
   RAISE EXCEPTION 'workload recovery must review the original retained app identity' USING ERRCODE='23514';
  END IF;
  IF NEW.phase='retiring' AND OLD.phase='planned' AND (
   NOT environment_workload_retirement_cutover_authorized(NEW) OR NOT src.prune OR
   rev.definition->>'workload_pruning_policy' IS DISTINCT FROM 'retain' OR rev.definition->'workloads' ? substring(NEW.resource from 10) OR
   NEW.generation<>src.generation OR NEW.revision_id<>rev.id OR
   NOT EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.manager_id=src.id::text AND f.resource=NEW.resource AND f.field_path='presence') OR
   EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.environment_id=src.environment_id AND f.resource=NEW.resource AND f.manager_id<>src.id::text) OR
   EXISTS(SELECT 1 FROM environment_external_field_owners f WHERE f.environment_id=src.environment_id AND f.resource IN (NEW.resource,'app/'||NEW.app_id::text)) OR
   EXISTS(SELECT 1 FROM deployments d JOIN project_environments e ON e.id=src.environment_id WHERE d.app_id=NEW.app_id AND d.scope=e.slug
    AND d.status='live' AND d.environment_workload_runtime->>'source_id' IS DISTINCT FROM src.id::text) OR
   NEW.deployment_ids IS DISTINCT FROM ARRAY(SELECT d.id FROM deployments d JOIN project_environments e ON e.id=src.environment_id
    WHERE d.app_id=NEW.app_id AND d.scope=e.slug AND d.environment_workload_runtime->>'source_id'=src.id::text ORDER BY d.id) OR
   NEW.queue_binding_ids IS DISTINCT FROM ARRAY(SELECT q.binding_id FROM environment_gitops_queue_bindings q
    WHERE q.source_id=src.id AND q.resource=NEW.resource AND q.binding_id IS NOT NULL ORDER BY q.binding_id) OR
   EXISTS(SELECT 1 FROM queue_bindings b WHERE b.app_id=NEW.app_id AND b.environment_id=src.environment_id
    AND NOT (b.id=ANY(NEW.queue_binding_ids))) OR
   EXISTS(SELECT 1 FROM environment_management_overrides o WHERE o.environment_id=src.environment_id AND o.resource=NEW.resource AND o.expires_at>clock_timestamp())) THEN
   RAISE EXCEPTION 'retirement requires the current qualified cutover' USING ERRCODE='23514';
  END IF;
  IF NEW.phase='cancelled' AND OLD.phase='planned' AND NEW.generation>=src.generation THEN
   RAISE EXCEPTION 'current retirement reservation cannot be cancelled' USING ERRCODE='23514';
  END IF;
  IF NEW.phase='retired' AND OLD.phase='retiring' AND NOT environment_workload_retirement_drained(NEW) THEN
   RAISE EXCEPTION 'retirement requires route withdrawal and original execution drain' USING ERRCODE='23514';
  END IF;
  IF NEW.phase='retired' AND OLD.phase='recovering' AND (src.generation<=OLD.recovery_generation OR rev.definition->'workloads' ? substring(NEW.resource from 10)) THEN
   RAISE EXCEPTION 'only a superseding removal can abandon recovery' USING ERRCODE='23514';
  END IF;
  IF NEW.route_generation IS DISTINCT FROM OLD.route_generation OR NEW.expected_gateways IS DISTINCT FROM OLD.expected_gateways THEN
   IF NEW.route_generation<=OLD.route_generation OR cardinality(NEW.acknowledged_gateways)<>0 OR
    NEW.expected_gateways IS DISTINCT FROM environment_workload_retirement_gateway_roster() THEN
    RAISE EXCEPTION 'route withdrawal requires a fresh generation and current gateway roster' USING ERRCODE='23514';
   END IF;
  ELSIF NOT OLD.acknowledged_gateways <@ NEW.acknowledged_gateways THEN
   RAISE EXCEPTION 'withdrawal acknowledgements cannot be removed' USING ERRCODE='23514';
  END IF;
  IF NEW.phase='recovered' AND OLD.phase='recovering' AND NOT EXISTS(
   SELECT 1 FROM deployments d WHERE d.app_id=NEW.app_id AND d.scope=(SELECT slug FROM project_environments WHERE id=NEW.environment_id)
    AND d.environment_workload_runtime->>'source_id'=src.id::text AND d.environment_workload_runtime->>'revision_id'=rev.id::text
    AND d.environment_workload_runtime->>'generation'=src.generation::text AND environment_workload_activation_authorized(d)) THEN
   RAISE EXCEPTION 'workload recovery requires fresh qualified activation' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_serving_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_serving_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE completion_only boolean;
BEGIN
    IF TG_OP='DELETE' THEN
        IF EXISTS (SELECT 1 FROM environment_workload_graphs WHERE id=OLD.graph_id) AND
            NOT environment_workload_serving_authorized(OLD.source_id,OLD.graph_id,OLD.release_set_id) THEN
            RAISE EXCEPTION 'environment workload serving receipts are immutable' USING ERRCODE='23514';
        END IF;
        RETURN OLD;
    END IF;
    completion_only:=false;
    IF TG_OP='UPDATE' THEN
        completion_only:=OLD.phase='pending' AND NEW.phase='served'
            AND ROW(NEW.graph_id,NEW.source_id,NEW.source_generation,NEW.intent_version,NEW.revision_id,NEW.plan_hash,
                NEW.release_set_id,NEW.expected_gateways,NEW.started_at)
                IS NOT DISTINCT FROM ROW(OLD.graph_id,OLD.source_id,OLD.source_generation,OLD.intent_version,OLD.revision_id,
                    OLD.plan_hash,OLD.release_set_id,OLD.expected_gateways,OLD.started_at)
            AND environment_workload_serving_ready(NEW.graph_id);
    END IF;
    IF (NOT environment_workload_serving_authorized(NEW.source_id,NEW.graph_id,NEW.release_set_id) AND NOT completion_only) OR
        NOT EXISTS (SELECT 1 FROM environment_workload_graphs graph
            WHERE graph.id=NEW.graph_id AND graph.source_id=NEW.source_id AND graph.generation=NEW.source_generation
                AND graph.intent_version=NEW.intent_version AND graph.revision_id=NEW.revision_id AND graph.plan_hash=NEW.plan_hash) OR
        NOT environment_workload_graph_serving_supported(NEW.graph_id) THEN
        RAISE EXCEPTION 'environment workload serving receipt requires its current supported graph and lease' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' AND ROW(NEW.graph_id,NEW.source_id,NEW.source_generation,NEW.intent_version,NEW.revision_id,NEW.plan_hash,NEW.started_at)
        IS DISTINCT FROM ROW(OLD.graph_id,OLD.source_id,OLD.source_generation,OLD.intent_version,OLD.revision_id,OLD.plan_hash,OLD.started_at) THEN
        RAISE EXCEPTION 'environment workload serving receipt identity is immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.phase='served' AND NOT environment_workload_serving_ready(NEW.graph_id) THEN
        RAISE EXCEPTION 'environment workload serving receipt lacks complete gateway and queue acknowledgements' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_serving_route(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_serving_route() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE receipt environment_workload_serving_receipts%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM environment_workload_serving_receipts WHERE graph_id=OLD.graph_id) THEN
   SELECT * INTO receipt FROM environment_workload_serving_receipts WHERE graph_id=OLD.graph_id;
   IF NOT environment_workload_serving_authorized(receipt.source_id,receipt.graph_id,receipt.release_set_id) THEN
    RAISE EXCEPTION 'environment workload serving routes are immutable' USING ERRCODE='23514';
   END IF;
  END IF;
  RETURN OLD;
 END IF;
 SELECT * INTO receipt FROM environment_workload_serving_receipts WHERE graph_id=NEW.graph_id FOR UPDATE;
 IF receipt.graph_id IS NULL OR NOT environment_workload_serving_authorized(receipt.source_id,receipt.graph_id,receipt.release_set_id) OR
    receipt.phase<>'pending' OR NOT EXISTS(
      SELECT 1 FROM project_release_sets release
      JOIN project_release_members rm ON rm.release_id=release.id AND rm.app_id=NEW.app_id AND rm.deployment_id=NEW.deployment_id
      JOIN environment_workload_graphs graph ON graph.id=receipt.graph_id
      CROSS JOIN LATERAL jsonb_array_elements(graph.members) member
      WHERE release.id=receipt.release_set_id AND release.active
        AND member->>'app_id'=NEW.app_id::text AND member->>'execution_mode' IN ('request','service')
        AND coalesce(member->'queue_modes','{}'::jsonb) IN ('{}'::jsonb,'null'::jsonb)
        AND ((NEW.cutover_required AND member->>'candidate_deployment_id'=NEW.deployment_id::text) OR
             (NOT NEW.cutover_required AND nullif(member->>'candidate_deployment_id','') IS NULL AND
              coalesce(member->'retained_deployments','[]'::jsonb) ? NEW.deployment_id::text))) THEN
  RAISE EXCEPTION 'environment workload serving route is outside the reviewed active graph' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_serving_route_ack(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_serving_route_ack() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE receipt environment_workload_serving_receipts%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN
  SELECT * INTO receipt FROM environment_workload_serving_receipts WHERE graph_id=OLD.graph_id;
  IF receipt.graph_id IS NOT NULL AND NOT environment_workload_serving_authorized(receipt.source_id,receipt.graph_id,receipt.release_set_id) THEN
   RAISE EXCEPTION 'environment workload serving acknowledgements are immutable' USING ERRCODE='23514';
  END IF;
  RETURN OLD;
 END IF;
 SELECT * INTO receipt FROM environment_workload_serving_receipts WHERE graph_id=NEW.graph_id FOR UPDATE;
 IF receipt.graph_id IS NULL OR receipt.phase<>'pending' OR
    NOT environment_workload_serving_authorized(receipt.source_id,receipt.graph_id,receipt.release_set_id) OR
    NOT (NEW.node_name=ANY(receipt.expected_gateways)) OR
    NOT EXISTS(SELECT 1 FROM environment_workload_serving_routes WHERE graph_id=NEW.graph_id AND route_generation=NEW.route_generation) THEN
  RAISE EXCEPTION 'environment workload serving acknowledgement is not expected' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_serving_traffic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_serving_traffic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.traffic_percent IS DISTINCT FROM OLD.traffic_percent AND
    EXISTS(SELECT 1 FROM deployments managed WHERE managed.app_id=OLD.app_id AND managed.scope=OLD.scope AND managed.environment_workload_runtime IS NOT NULL) AND
    NOT environment_workload_serving_traffic_authorized(NEW.app_id,NEW.scope,NEW.id,NEW.traffic_percent) AND
    NOT (NEW.traffic_percent=0 AND NEW.traffic_percent_explicit AND environment_workload_retirement_withdrawal_authorized(OLD)) AND
    NOT (NEW.traffic_percent=0 AND OLD.environment_workload_held AND NOT NEW.environment_workload_held AND
      environment_workload_activation_authorized(NEW)) THEN
  RAISE EXCEPTION 'GitOps-managed workload traffic requires a current serving transition' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_event_delivery_replay(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_event_delivery_replay() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE slot event_delivery_slots%ROWTYPE; caps event_delivery_capacity%ROWTYPE;
 consumer_count bigint; app_count bigint; account_count bigint; scope text; consumer_limit integer;
BEGIN
 IF NEW.state NOT IN ('pending','dispatching') THEN RETURN NEW; END IF;
 IF TG_OP = 'UPDATE' AND OLD.state IN ('pending','dispatching') THEN RETURN NEW; END IF;
 SELECT * INTO slot FROM event_delivery_slots WHERE invocation_id=NEW.id;
 IF NOT FOUND AND NEW.replayed_from_invocation_id IS NOT NULL THEN
  SELECT * INTO slot FROM event_delivery_slots WHERE invocation_id=NEW.replayed_from_invocation_id;
 END IF;
 IF slot.invocation_id IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO STRICT caps FROM event_delivery_capacity WHERE account_id=slot.account_id FOR UPDATE;
 SELECT count(*), count(*) FILTER (WHERE s.app_id=slot.app_id),
   count(*) FILTER (WHERE s.app_id=slot.app_id AND s.subscription_id=slot.subscription_id)
 INTO account_count, app_count, consumer_count
 FROM event_delivery_slots s JOIN invocations i ON i.id=s.invocation_id
 WHERE s.account_id=slot.account_id AND i.state IN ('pending','dispatching') AND i.id<>NEW.id;
 SELECT CASE WHEN c.max_pending_deliveries>0 THEN least(c.max_pending_deliveries,caps.consumer_limit) ELSE caps.consumer_limit END INTO consumer_limit
 FROM event_subscription_delivery_controls c WHERE c.account_id=slot.account_id AND c.app_id=slot.app_id AND c.subscription_id::text=slot.subscription_id;
 consumer_limit := coalesce(consumer_limit,caps.consumer_limit);
 scope := CASE WHEN consumer_count>=consumer_limit THEN 'consumer'
   WHEN app_count>=caps.app_limit THEN 'app' WHEN account_count>=caps.account_limit THEN 'account' END;
 IF scope IS NOT NULL THEN
  RAISE EXCEPTION 'event delivery capacity exhausted: %',scope USING ERRCODE='23514', CONSTRAINT='event_delivery_capacity', DETAIL=scope;
 END IF;
 INSERT INTO event_delivery_slots VALUES (NEW.id,slot.account_id,slot.app_id,slot.subscription_id) ON CONFLICT DO NOTHING;
 RETURN NEW;
END $$;


--
-- Name: guard_held_queue_consumer_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_held_queue_consumer_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE can_claim boolean;
BEGIN
  IF NEW.state='claimed' AND (OLD.state IS DISTINCT FROM 'claimed'
    OR NEW.claim_generation IS DISTINCT FROM OLD.claim_generation) THEN
    SELECT b.enabled AND b.mode='push' AND b.retired_at IS NULL AND (b.deployment_scope='' OR EXISTS (
      SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
        WHERE a.id=b.app_id AND e.id=b.environment_id AND e.slug=b.deployment_scope)) INTO can_claim
      FROM queue_bindings b JOIN triggers t ON t.queue_binding_id=b.id WHERE t.id=NEW.trigger_id FOR SHARE OF b;
    IF can_claim IS FALSE THEN RETURN NULL; END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_instance_layer_artifacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_instance_layer_artifacts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.deployment_id IS NOT NULL AND NEW.state IN ('pending', 'waking', 'cold_booting', 'running', 'snapshotting', 'migrating', 'warm', 'frozen', 'draining') THEN
        PERFORM require_deployment_layer_artifacts(NEW.deployment_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_instance_migration_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_instance_migration_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE r migration_admissions%ROWTYPE; n compute_nodes%ROWTYPE; used record; pending boolean;
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') THEN
  SELECT * INTO r FROM migration_admissions WHERE instance_id=OLD.id AND phase NOT IN ('cleaned','committed') FOR UPDATE;
  IF FOUND THEN
   IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'instance has unresolved incoming migration' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
   END IF;
   IF (NEW.node_id,NEW.wake_id,NEW.state,NEW.lease_token,NEW.app_id,NEW.deployment_id) IS DISTINCT FROM (OLD.node_id,OLD.wake_id,OLD.state,OLD.lease_token,OLD.app_id,OLD.deployment_id)
    AND NOT (r.phase='adopted' AND OLD.node_id=r.source_node_id AND OLD.wake_id=r.source_wake_id AND NEW.node_id=r.destination_node_id AND NEW.wake_id=r.destination_wake_id AND NEW.state='running' AND NEW.lease_token IS NOT DISTINCT FROM r.lease_token AND NEW.app_id IS NOT DISTINCT FROM OLD.app_id AND NEW.deployment_id IS NOT DISTINCT FROM OLD.deployment_id) THEN
    RAISE EXCEPTION 'source has unresolved incoming migration' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
   END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 END IF;
 IF TG_OP='UPDATE' AND NEW.node_id IS DISTINCT FROM OLD.node_id THEN
  SELECT * INTO r FROM migration_admissions WHERE instance_id=OLD.id AND source_node_id=OLD.node_id AND destination_node_id=NEW.node_id AND lease_token=OLD.lease_token FOR UPDATE;
  IF FOUND THEN
   SELECT * INTO n FROM compute_nodes WHERE id=NEW.node_id FOR SHARE;
   IF r.phase<>'adopted' OR OLD.wake_id<>r.source_wake_id OR NEW.wake_id<>r.destination_wake_id OR NEW.state<>'running' OR n.lifecycle_generation<>r.destination_generation THEN
    RAISE EXCEPTION 'migration adoption is not current' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
   END IF;
   NEW.capacity_ram_mb=greatest(NEW.capacity_ram_mb,r.ram_mb);
   NEW.capacity_cpu_millicores=greatest(NEW.capacity_cpu_millicores,r.cpu_millicores);
   NEW.capacity_vcpu=greatest(NEW.capacity_vcpu,r.vcpu);
  END IF;
 END IF;
 IF NEW.state NOT IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm','frozen') THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.node_id=OLD.node_id AND OLD.state IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm','frozen')
  AND NEW.ram_mb<=OLD.ram_mb AND NEW.capacity_ram_mb<=OLD.capacity_ram_mb AND NEW.capacity_cpu_millicores<=OLD.capacity_cpu_millicores AND NEW.capacity_vcpu<=OLD.capacity_vcpu THEN RETURN NEW; END IF;
 SELECT EXISTS(SELECT 1 FROM migration_admissions WHERE destination_node_id=NEW.node_id AND phase NOT IN ('cleaned','committed')) OR EXISTS(SELECT 1 FROM migration_sources WHERE source_node_id=NEW.node_id AND phase IN ('bound','retiring')) INTO pending;
 IF NOT pending THEN RETURN NEW; END IF;
 SELECT * INTO n FROM compute_nodes WHERE id=NEW.node_id FOR SHARE;
 PERFORM pg_advisory_xact_lock(1852793957,hashtext(NEW.node_id::text));
 SELECT * INTO used FROM migration_admission_node_usage(NEW.node_id,NEW.id);
 IF (n.admission_ceiling_mb>0 AND used.ram+greatest(NEW.capacity_ram_mb,NEW.ram_mb+(SELECT overhead_mb FROM service_capacity_policy WHERE singleton))>n.admission_ceiling_mb)
  OR (n.vpcpus>0 AND used.cpu+NEW.capacity_cpu_millicores>n.vpcpus::bigint*1000)
  OR (n.vcpu_budget>0 AND used.vcpu+NEW.capacity_vcpu>n.vcpu_budget) THEN
  RAISE EXCEPTION 'capacity reserved for incoming migration' USING ERRCODE='23514',CONSTRAINT='migration_admission_capacity';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_instance_migration_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_instance_migration_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE r migration_sources%ROWTYPE;
BEGIN
 IF NEW.state='migrating' AND (OLD.state,OLD.lease_token) IS DISTINCT FROM (NEW.state,NEW.lease_token) THEN
  SELECT * INTO r FROM migration_sources WHERE lease_token=NEW.lease_token FOR SHARE;
  IF FOUND THEN
   IF r.phase<>'bound' OR r.instance_id<>NEW.id OR r.source_node_id<>NEW.node_id OR r.source_wake_id<>NEW.wake_id THEN
    RAISE EXCEPTION 'migration source dispatch authority ended' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
   END IF;
   PERFORM 1 FROM migration_leases WHERE lease_token=r.lease_token AND NOT resume_fenced AND lease_expires_at>clock_timestamp() FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'migration source dispatch lease ended' USING ERRCODE='23514',CONSTRAINT='migration_source_current'; END IF;
  END IF;
 END IF;
 SELECT * INTO r FROM migration_sources WHERE instance_id=OLD.id AND source_node_id=OLD.node_id AND source_wake_id=OLD.wake_id AND phase='bound' FOR UPDATE;
 IF NOT FOUND THEN RETURN NEW; END IF;
 IF NEW.node_id IS DISTINCT FROM OLD.node_id OR NEW.wake_id IS DISTINCT FROM OLD.wake_id THEN
  IF NEW.node_id=OLD.node_id OR NEW.state<>'running' OR NEW.lease_token IS DISTINCT FROM r.lease_token OR NOT EXISTS(
   SELECT 1 FROM migration_admissions WHERE instance_id=OLD.id AND lease_token=r.lease_token AND source_node_id=r.source_node_id AND source_wake_id=r.source_wake_id AND destination_node_id=NEW.node_id AND destination_wake_id=NEW.wake_id AND phase='adopted'
  ) THEN RAISE EXCEPTION 'migration source physical owner cannot change' USING ERRCODE='23514',CONSTRAINT='migration_source_current'; END IF;
 END IF;
 NEW.capacity_ram_mb=greatest(NEW.capacity_ram_mb,r.ram_mb);
 NEW.capacity_cpu_millicores=greatest(NEW.capacity_cpu_millicores,r.cpu_millicores);
 NEW.capacity_vcpu=greatest(NEW.capacity_vcpu,r.vcpu);
 RETURN NEW;
END $$;


--
-- Name: guard_invocation_deployment_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_invocation_deployment_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND (NEW.deployment_scope IS NULL OR NEW.deployment_scope = '') THEN
    SELECT CASE WHEN a.project_id IS NOT NULL AND coalesce(a.preview_of_slug, '') = ''
      THEN 'production' ELSE 'default' END INTO NEW.deployment_scope
      FROM apps a WHERE a.id = NEW.app_id FOR SHARE OF a;
  ELSIF TG_OP = 'UPDATE' AND NEW.deployment_scope IS DISTINCT FROM OLD.deployment_scope THEN
    RAISE EXCEPTION 'invocation deployment scope is immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'invocation_deployment_scope_identity';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_invocation_platform_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_invocation_platform_tenant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE tenant_status text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.platform_tenant_id IS DISTINCT FROM OLD.platform_tenant_id OR
       (OLD.platform_tenant_id IS NOT NULL AND
        (NEW.app_id IS DISTINCT FROM OLD.app_id OR NEW.account_id IS DISTINCT FROM OLD.account_id)) THEN
      RAISE EXCEPTION 'invocation tenant identity is immutable'
        USING ERRCODE = '23514', CONSTRAINT = 'invocation_platform_tenant_identity';
    END IF;
  END IF;
  IF NEW.platform_tenant_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' OR (OLD.state = 'pending' AND NEW.state = 'dispatching') THEN
    SELECT t.status INTO tenant_status FROM platform_tenants t JOIN apps a ON a.account_id = t.account_id
      WHERE t.id = NEW.platform_tenant_id AND t.account_id = NEW.account_id
        AND a.id = NEW.app_id
      FOR SHARE OF t, a;
    IF NOT FOUND THEN
      IF TG_OP = 'UPDATE' THEN RETURN NULL; END IF;
      RAISE EXCEPTION 'invocation tenant must be active and own the app account'
        USING ERRCODE = '23514', CONSTRAINT = 'invocation_platform_tenant_identity';
    END IF;
    IF tenant_status <> 'active' THEN
      IF TG_OP = 'UPDATE' THEN RETURN NULL; END IF;
      RAISE EXCEPTION 'invocation platform tenant is suspended'
        USING ERRCODE = '23514', CONSTRAINT = 'invocation_platform_tenant_active';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_invocation_queue_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_invocation_queue_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='UPDATE' THEN
    IF NEW.queue_binding_id IS DISTINCT FROM OLD.queue_binding_id OR
      (OLD.queue_binding_id IS NOT NULL AND (NEW.app_id IS DISTINCT FROM OLD.app_id
        OR NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.source IS DISTINCT FROM OLD.source
        OR NEW.queue_name IS DISTINCT FROM OLD.queue_name)) THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_queue_binding_identity',
        MESSAGE='accepted queue binding identity is immutable';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.queue_binding_id IS NOT NULL AND NEW.source<>'queue' THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_queue_binding_source',
      MESSAGE='binding identity requires a queue invocation';
  END IF;
  IF NEW.environment_id IS NOT NULL AND NEW.source='queue' THEN
    IF NEW.queue_binding_id IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_private_queue_binding',
        MESSAGE='private queue work cannot capture a public binding';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.source='queue' THEN
    IF NEW.queue_binding_id IS NULL AND NEW.queue_name<>'' THEN
      SELECT b.id INTO NEW.queue_binding_id FROM queue_bindings b
        WHERE b.app_id=NEW.app_id AND b.account_id=NEW.account_id AND b.queue_name=NEW.queue_name
          AND (b.deployment_scope='' OR (b.deployment_scope=NEW.deployment_scope AND EXISTS
            (SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
              WHERE a.id=NEW.app_id AND e.id=b.environment_id AND e.slug=b.deployment_scope)))
        ORDER BY (b.deployment_scope<>'') DESC LIMIT 1;
    ELSIF NEW.queue_binding_id IS NULL AND NEW.work_policy_name IS NULL THEN
      SELECT b.id INTO NEW.queue_binding_id FROM queue_bindings b JOIN triggers t ON t.queue_binding_id=b.id
        WHERE b.app_id=NEW.app_id AND b.account_id=NEW.account_id AND b.enabled
          AND (b.deployment_scope='' OR (b.deployment_scope=NEW.deployment_scope AND EXISTS
            (SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
              WHERE a.id=NEW.app_id AND e.id=b.environment_id AND e.slug=b.deployment_scope)))
          AND b.mode='push' AND b.retired_at IS NULL AND t.enabled AND t.kind='queue' AND t.source='queue'
          AND NOT EXISTS (SELECT 1 FROM triggers other WHERE other.app_id=NEW.app_id
            AND other.kind='queue' AND other.source='queue' AND other.enabled AND other.id<>t.id
            AND (other.queue_binding_scope='' OR (other.queue_binding_scope=NEW.deployment_scope AND EXISTS
              (SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
                WHERE a.id=NEW.app_id AND e.id=other.queue_binding_environment_id AND e.slug=other.queue_binding_scope))));
    END IF;
    IF NEW.queue_binding_id IS NOT NULL THEN
      PERFORM 1 FROM queue_bindings b WHERE b.id=NEW.queue_binding_id
        AND b.app_id=NEW.app_id AND b.account_id=NEW.account_id
        AND (b.deployment_scope='' OR (b.deployment_scope=NEW.deployment_scope AND EXISTS
            (SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
              WHERE a.id=NEW.app_id AND e.id=b.environment_id AND e.slug=b.deployment_scope))) FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_queue_binding_tenant',
          MESSAGE='queue binding must belong to the admitted app, account and environment';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_invocation_replay_generation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_invocation_replay_generation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    NEW.replay_generation=0;
  ELSIF OLD.state='dead_letter' AND NEW.state='pending' THEN
    NEW.replay_generation=OLD.replay_generation+1;
  ELSIF NEW.replay_generation IS DISTINCT FROM OLD.replay_generation THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_replay_generation_identity',
      MESSAGE='invocation replay generation is owned by the delivery ledger';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_issue_group_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_issue_group_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM id FROM apps WHERE id=NEW.app_id FOR UPDATE;
 IF EXISTS (SELECT 1 FROM issue_group_links WHERE issue_id=NEW.canonical_issue_id)
 OR EXISTS (SELECT 1 FROM issue_group_links WHERE canonical_issue_id=NEW.issue_id) THEN
  RAISE EXCEPTION 'issue links must reference a canonical root' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_issue_split_rule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_issue_split_rule() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM id FROM apps WHERE id=NEW.app_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM app_issues WHERE id=NEW.source_issue_id AND split_source_issue_id IS NOT NULL)
 OR NOT EXISTS(SELECT 1 FROM app_issues WHERE id=NEW.target_issue_id AND split_source_issue_id=NEW.source_issue_id) THEN
  RAISE EXCEPTION 'split rules require an original source and its derived branch' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND (NEW.id,NEW.app_id,NEW.environment,NEW.source_issue_id,NEW.target_issue_id,NEW.priority,NEW.exception_type,NEW.error_code,NEW.route,NEW.source_kind,NEW.initial_moved_event_count,NEW.unavailable_history_event_count,NEW.created_at)
 IS DISTINCT FROM (OLD.id,OLD.app_id,OLD.environment,OLD.source_issue_id,OLD.target_issue_id,OLD.priority,OLD.exception_type,OLD.error_code,OLD.route,OLD.source_kind,OLD.initial_moved_event_count,OLD.unavailable_history_event_count,OLD.created_at) THEN
  RAISE EXCEPTION 'split rule definitions are immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_accounting_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_accounting_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.accounting_required AND NOT NEW.accounting_required THEN
        RAISE EXCEPTION 'managed postgres accounting obligation cannot be cleared'
            USING ERRCODE = '23514', CONSTRAINT = 'managed_postgres_accounting_intent_retained';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_admission_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_admission_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE intent managed_postgres_cutovers%ROWTYPE; checked_at timestamptz;
BEGIN
 IF NEW.managed_postgres_admission_cutover_id IS NOT DISTINCT FROM OLD.managed_postgres_admission_cutover_id THEN
  IF NEW.managed_postgres_admission_fenced_at IS DISTINCT FROM OLD.managed_postgres_admission_fenced_at
   OR (OLD.managed_postgres_admission_cutover_id IS NOT NULL AND ROW(NEW.id,NEW.account_id) IS DISTINCT FROM ROW(OLD.id,OLD.account_id)) THEN
   RAISE EXCEPTION 'admission fence is immutable' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.managed_postgres_admission_cutover_id IS NOT NULL THEN
  SELECT * INTO intent FROM managed_postgres_cutovers WHERE id=OLD.managed_postgres_admission_cutover_id FOR SHARE;
  IF NEW.managed_postgres_admission_cutover_id IS NOT NULL OR intent.state IS DISTINCT FROM 'cancelled' THEN
   RAISE EXCEPTION 'admission fence cannot be released' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
 ELSE
  SELECT * INTO intent FROM managed_postgres_cutovers WHERE id=NEW.managed_postgres_admission_cutover_id FOR SHARE;
  checked_at := clock_timestamp();
  IF intent.app_id IS DISTINCT FROM NEW.id OR intent.account_id IS DISTINCT FROM NEW.account_id
   OR intent.state IS DISTINCT FROM 'verified' OR intent.lease_token IS NOT NULL
   OR intent.verified_at IS NULL OR intent.verified_at>checked_at OR intent.verified_at<checked_at-interval '5 minutes'
   OR NEW.status NOT IN ('active','evicted_cold')
   OR NOT EXISTS (SELECT 1 FROM managed_postgres_cutover_credentials WHERE cutover_id=intent.id)
   OR EXISTS (SELECT 1 FROM managed_postgres_cutover_credentials WHERE cutover_id=intent.id
    AND (state<>'sealed' OR verified_at IS NULL OR verified_at>checked_at OR verified_at<checked_at-interval '5 minutes')) THEN
   RAISE EXCEPTION 'cutover verification is not fresh' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
  NEW.managed_postgres_admission_fenced_at := checked_at;
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_app_task_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_app_task_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE pinned uuid;
BEGIN
 IF NEW.status NOT IN ('restoring','running') THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.app_id,NEW.status) IS NOT DISTINCT FROM ROW(OLD.app_id,OLD.status) THEN
  RETURN NEW;
 END IF;
 -- Same tuple barrier as ordinary instances; old repeatable-read claims
 -- abort rather than admitting commands from a pre-fence snapshot.
 SELECT managed_postgres_admission_cutover_id INTO pinned FROM apps WHERE id=NEW.app_id FOR SHARE;
 IF pinned IS NOT NULL THEN
  RAISE EXCEPTION 'app task admission is fenced by a database cutover' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_admission_fenced';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_binding_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_binding_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='UPDATE' AND (NEW.account_id<>OLD.account_id OR NEW.database_id<>OLD.database_id OR NEW.app_id<>OLD.app_id
       OR NEW.database_account_id IS DISTINCT FROM OLD.database_account_id) THEN
        RAISE EXCEPTION 'binding ownership is immutable' USING ERRCODE='23514', CONSTRAINT='managed_postgres_binding_owner';
    END IF;
    SELECT account_id INTO NEW.database_account_id FROM managed_postgres_databases WHERE id=NEW.database_id;
    IF NOT EXISTS (
        SELECT 1
        FROM managed_postgres_databases database
        JOIN apps app ON app.id = NEW.app_id
        WHERE database.id = NEW.database_id
          AND database.account_id = NEW.database_account_id
          AND database.org_id = app.org_id
          AND app.account_id = NEW.account_id
          AND database.state <> 'deleted'
          AND app.status <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'managed postgres binding owner mismatch or parent is deleted'
            USING ERRCODE = '23514', CONSTRAINT = 'managed_postgres_binding_owner';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_cutover_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_cutover_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE pinned uuid;
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') AND OLD.cutover_id IS NOT NULL THEN
  IF TG_OP='DELETE' OR (to_jsonb(NEW)-'cutover_id') IS DISTINCT FROM (to_jsonb(OLD)-'cutover_id')
   OR (NEW.cutover_id IS DISTINCT FROM OLD.cutover_id AND (NEW.cutover_id IS NOT NULL OR NOT EXISTS (SELECT 1 FROM managed_postgres_cutovers WHERE id=OLD.cutover_id AND state='cancelled'))) THEN
   RAISE EXCEPTION 'binding is pinned by a cutover' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
 END IF;
 IF TG_OP='INSERT' OR (TG_OP='UPDATE' AND ROW(NEW.database_id,NEW.app_id,NEW.scope,NEW.environment_key) IS DISTINCT FROM ROW(OLD.database_id,OLD.app_id,OLD.scope,OLD.environment_key)) THEN
  SELECT cutover_id INTO pinned FROM managed_postgres_databases WHERE id=NEW.database_id FOR KEY SHARE;
  IF pinned IS NOT NULL THEN
   RAISE EXCEPTION 'database is pinned by a cutover' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_cutover_database(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_cutover_database() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.cutover_id IS NOT NULL THEN
  IF TG_OP='DELETE' OR ROW(NEW.account_id,NEW.state,NEW.backend_id,NEW.backend_fingerprint,NEW.provider_resource_id,NEW.desired_generation,NEW.region,NEW.postgres_major,NEW.service_class,NEW.availability,NEW.scale_to_zero,NEW.storage_limit_bytes,NEW.restore_window_seconds)
     IS DISTINCT FROM ROW(OLD.account_id,OLD.state,OLD.backend_id,OLD.backend_fingerprint,OLD.provider_resource_id,OLD.desired_generation,OLD.region,OLD.postgres_major,OLD.service_class,OLD.availability,OLD.scale_to_zero,OLD.storage_limit_bytes,OLD.restore_window_seconds)
     OR (NEW.cutover_id IS DISTINCT FROM OLD.cutover_id AND (NEW.cutover_id IS NOT NULL OR NOT EXISTS (SELECT 1 FROM managed_postgres_cutovers WHERE id=OLD.cutover_id AND state='cancelled'))) THEN
   RAISE EXCEPTION 'database is pinned by a cutover' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_cutover_drain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_cutover_drain() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF ROW(NEW.id,NEW.cutover_id,NEW.app_id,NEW.deployment_id,NEW.instance_id,NEW.node_id,NEW.wake_id,NEW.owner_node_id,NEW.owner_revision,NEW.fenced_at,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.id,OLD.cutover_id,OLD.app_id,OLD.deployment_id,OLD.instance_id,OLD.node_id,OLD.wake_id,OLD.owner_node_id,OLD.owner_revision,OLD.fenced_at,OLD.created_at)
  OR (OLD.state='retired' AND NEW IS DISTINCT FROM OLD) THEN
  RAISE EXCEPTION 'drain identity and receipts are immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_database_bindings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_database_bindings() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state = 'deleted' AND EXISTS (
        SELECT 1 FROM managed_postgres_bindings WHERE database_id = NEW.id AND state <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'managed postgres database has active bindings'
            USING ERRCODE = '23514', CONSTRAINT = 'managed_postgres_database_has_bindings';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_drain_plan_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_drain_plan_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 RAISE EXCEPTION 'cutover drain plans are immutable' USING ERRCODE='23514';
END;
$$;


--
-- Name: guard_managed_postgres_drain_plan_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_drain_plan_inventory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE selected uuid;
BEGIN
 IF TG_OP='INSERT' THEN
  selected := current_managed_postgres_drain_plan(NEW.app_id);
 ELSIF TG_OP='DELETE' THEN
  selected := current_managed_postgres_drain_plan(OLD.app_id);
  IF selected IS NULL THEN RETURN OLD; END IF;
  IF EXISTS (SELECT 1 FROM managed_postgres_cutover_drain_plan_members m
   JOIN managed_postgres_cutover_drain_plans p ON p.id=m.plan_id
   JOIN managed_postgres_cutover_drains d ON d.id=m.drain_id
   WHERE m.plan_id=selected AND m.instance_id=OLD.id AND d.state='retired'
    AND d.cutover_id=p.cutover_id AND d.app_id=p.app_id AND d.owner_node_id=p.owner_node_id
    AND d.owner_revision=p.owner_revision AND d.fenced_at=p.fenced_at
    AND d.instance_id=OLD.id AND d.deployment_id=OLD.deployment_id AND d.node_id=OLD.node_id AND d.wake_id=OLD.wake_id
    AND OLD.state='stopped') THEN RETURN OLD; END IF;
 ELSE
  -- Ordinary runtime counters and terminal transitions do not change catalog
  -- membership. Avoid adding an app lock to those hot paths.
  IF ROW(NEW.id,NEW.app_id,NEW.deployment_id,NEW.node_id,NEW.wake_id,NEW.kind,NEW.mode,NEW.migrated_from_node_id)
    IS NOT DISTINCT FROM ROW(OLD.id,OLD.app_id,OLD.deployment_id,OLD.node_id,OLD.wake_id,OLD.kind,OLD.mode,OLD.migrated_from_node_id)
    AND (NEW.state <> 'migrating' OR NEW.state=OLD.state) THEN RETURN NEW; END IF;
  selected := current_managed_postgres_drain_plan(OLD.app_id);
  IF selected IS NULL AND NEW.app_id IS DISTINCT FROM OLD.app_id THEN
   selected := current_managed_postgres_drain_plan(NEW.app_id);
  END IF;
 END IF;
 IF selected IS NOT NULL THEN
  RAISE EXCEPTION 'cutover drain inventory is fenced' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_admission_fenced';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


--
-- Name: guard_managed_postgres_drain_plan_inventory_truncate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_drain_plan_inventory_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 -- TRUNCATE covers every app, including fenced apps created after a stale
 -- transaction snapshot. Reject stale isolation before consulting that snapshot.
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION 'drain inventory truncation requires a current snapshot' USING ERRCODE='40001';
 END IF;
 IF EXISTS (SELECT 1 FROM apps a JOIN managed_postgres_cutover_drain_plans p ON p.app_id=a.id
  AND p.cutover_id=a.managed_postgres_admission_cutover_id AND p.fenced_at=a.managed_postgres_admission_fenced_at
  AND p.owner_node_id=a.node_id AND p.owner_revision=a.scaling_policy_revision) THEN
  RAISE EXCEPTION 'cutover drain inventory is fenced' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_admission_fenced';
 END IF;
 RETURN NULL;
END;
$$;


--
-- Name: guard_managed_postgres_instance_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_instance_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE pinned uuid;
BEGIN
 IF NEW.app_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state IN ('parked','stopped','failed') THEN RETURN NEW; END IF;
 ELSIF ROW(NEW.app_id,NEW.state) IS NOT DISTINCT FROM ROW(OLD.app_id,OLD.state)
  OR NEW.state NOT IN ('waking','cold_booting','running','warm') THEN
  RETURN NEW;
 END IF;
 -- A SHARE lock conflicts with the app UPDATE that installs the fence.
 -- The updated app tuple also fences transactions using repeatable-read.
 SELECT managed_postgres_admission_cutover_id INTO pinned FROM apps WHERE id=NEW.app_id FOR SHARE;
 IF pinned IS NOT NULL THEN
  RAISE EXCEPTION 'instance admission is fenced by a database cutover' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_admission_fenced';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_resize_database(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_resize_database() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM managed_postgres_resizes WHERE database_id=OLD.id AND state='pending') THEN
  IF TG_OP='DELETE' THEN
   RAISE EXCEPTION 'database has an unresolved resize' USING ERRCODE='23514', CONSTRAINT='managed_postgres_resize_conflict';
  END IF;
  IF ROW(NEW.account_id,NEW.backend_id,NEW.backend_fingerprint,NEW.provider_resource_id,NEW.data_resource_id,
      NEW.region,NEW.postgres_major,NEW.service_class,NEW.availability,NEW.scale_to_zero,NEW.storage_limit_bytes,NEW.restore_window_seconds,
      NEW.desired_generation,NEW.observed_generation,NEW.cutover_id,NEW.environment_clone_operation_id,NEW.clone_resource_role)
      IS DISTINCT FROM ROW(OLD.account_id,OLD.backend_id,OLD.backend_fingerprint,OLD.provider_resource_id,OLD.data_resource_id,
      OLD.region,OLD.postgres_major,OLD.service_class,OLD.availability,OLD.scale_to_zero,OLD.storage_limit_bytes,OLD.restore_window_seconds,
      OLD.desired_generation,OLD.observed_generation,OLD.cutover_id,OLD.environment_clone_operation_id,OLD.clone_resource_role)
      OR NEW.state<>'updating' THEN
   RAISE EXCEPTION 'database has an unresolved resize' USING ERRCODE='23514', CONSTRAINT='managed_postgres_resize_conflict';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_resize_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_resize_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.state='pending' AND EXISTS(SELECT 1 FROM managed_postgres_databases WHERE id=OLD.database_id) THEN
   RAISE EXCEPTION 'pending resize intent cannot be removed' USING ERRCODE='23514', CONSTRAINT='managed_postgres_resize_conflict';
  END IF;
  RETURN OLD;
 END IF;
 IF (to_jsonb(NEW)-'state'-'completed_at') IS DISTINCT FROM (to_jsonb(OLD)-'state'-'completed_at')
  OR (OLD.state='succeeded' AND NEW IS DISTINCT FROM OLD) THEN
  RAISE EXCEPTION 'resize intent is immutable' USING ERRCODE='23514', CONSTRAINT='managed_postgres_resize_conflict';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_restore_sources(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_restore_sources() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state = 'deleted' AND EXISTS (
        SELECT 1 FROM managed_postgres_databases
        WHERE restore_source_database_id = NEW.id AND state <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'managed postgres database has active restore descendants'
            USING ERRCODE = '23514', CONSTRAINT = 'managed_postgres_database_has_restore_descendants';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_secret_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_secret_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.managed_postgres_binding_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM managed_postgres_bindings binding
        WHERE binding.id = NEW.managed_postgres_binding_id
          AND binding.account_id = NEW.account_id
          AND binding.app_id = NEW.app_id
          AND binding.scope = NEW.scope
          AND binding.environment_key = NEW.key
          AND binding.credential_generation = NEW.managed_credential_generation
          AND binding.state <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'managed app secret owner does not match its binding'
            USING ERRCODE = '23514', CONSTRAINT = 'app_secret_managed_postgres_owner';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_source_fence_cancellation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_source_fence_cancellation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.state='cancelling' AND OLD.state<>'cancelling' THEN
  UPDATE managed_postgres_cutover_source_fences SET state='abandoning',lease_token=NULL,lease_until=NULL,
   retry_at=clock_timestamp(),updated_at=clock_timestamp() WHERE cutover_id=NEW.id AND state<>'released';
 END IF;
 IF NEW.state='cancelled' AND EXISTS(SELECT 1 FROM managed_postgres_cutover_source_fences WHERE cutover_id=NEW.id AND state<>'released') THEN
  RAISE EXCEPTION 'source SQL fence cleanup is incomplete' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_managed_postgres_source_fence_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_source_fence_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') THEN
  RAISE EXCEPTION 'source fence recovery evidence is retained' USING ERRCODE='55000';
 END IF;
 IF OLD.state='released' OR ROW(NEW.cutover_id,NEW.owner_token,NEW.maintenance_id,NEW.source_database_id,
   NEW.backend_id,NEW.backend_fingerprint,NEW.source_provider_resource_id,NEW.source_data_resource_id,NEW.source_generation,
   NEW.source_spec,NEW.owner_node_id,NEW.owner_revision,NEW.admission_fenced_at,NEW.runtime_fingerprint,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.cutover_id,OLD.owner_token,OLD.maintenance_id,OLD.source_database_id,
   OLD.backend_id,OLD.backend_fingerprint,OLD.source_provider_resource_id,OLD.source_data_resource_id,OLD.source_generation,
   OLD.source_spec,OLD.owner_node_id,OLD.owner_revision,OLD.admission_fenced_at,OLD.runtime_fingerprint,OLD.created_at)
  OR (cardinality(OLD.database_names)>0 AND NEW.database_names IS DISTINCT FROM OLD.database_names)
  OR (OLD.close_requested_at IS NOT NULL AND NEW.close_requested_at IS DISTINCT FROM OLD.close_requested_at)
  OR (OLD.state='abandoning' AND NEW.state NOT IN ('abandoning','released'))
  OR (OLD.state IN ('closing','closed') AND NEW.state='pending') THEN
  RAISE EXCEPTION 'source fence identity or terminal state changed' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_managed_postgres_source_fence_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_source_fence_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.state='released' THEN RETURN NEW; END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'source fence insertion requires read committed' USING ERRCODE='55000';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.backend_id||':'||NEW.backend_fingerprint||':'||NEW.source_data_resource_id,1334));
 IF TG_TABLE_NAME='managed_postgres_cutover_source_fences' THEN
  IF EXISTS(SELECT 1 FROM project_environment_clone_postgres_write_fences
    WHERE backend_id=NEW.backend_id AND backend_fingerprint=NEW.backend_fingerprint
      AND source_data_resource_id=NEW.source_data_resource_id AND state<>'released') THEN
   RAISE EXCEPTION 'source dataset already held' USING ERRCODE='55000';
  END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM managed_postgres_cutover_source_fences
    WHERE backend_id=NEW.backend_id AND backend_fingerprint=NEW.backend_fingerprint
      AND source_data_resource_id=NEW.source_data_resource_id AND state<>'released') THEN
   RAISE EXCEPTION 'source dataset already held' USING ERRCODE='55000';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_managed_postgres_writer_catalog_baseline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_writer_catalog_baseline() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND ((OLD.catalog_fingerprint<>'' AND NEW.catalog_fingerprint IS DISTINCT FROM OLD.catalog_fingerprint)
  OR (OLD.catalog_invalidated_at IS NOT NULL AND NEW.catalog_invalidated_at IS DISTINCT FROM OLD.catalog_invalidated_at)) THEN
  RAISE EXCEPTION 'original source writer catalog is retained' USING ERRCODE='55000';
 END IF;
 IF NEW.catalog_fingerprint<>'' AND (TG_OP='INSERT' OR OLD.catalog_fingerprint='') AND (
  NEW.state<>'closed' OR NEW.closure IS NULL OR
  NEW.closure->'writer_inventory'->>'catalog_fingerprint' IS DISTINCT FROM NEW.catalog_fingerprint OR
  NEW.closure->'writer_inventory'->>'catalog_complete' IS DISTINCT FROM 'true' OR
  NEW.closure->>'unselected_databases' IS DISTINCT FROM '0') THEN
  RAISE EXCEPTION 'original source writer catalog is incomplete' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_mcp_readiness_alert_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_mcp_readiness_alert_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
 BEGIN
  IF NEW.mcp_readiness_scope IS DISTINCT FROM OLD.mcp_readiness_scope THEN RAISE EXCEPTION 'readiness alert environment cannot change; create a new rule' USING ERRCODE='23514',CONSTRAINT='alert_rules_mcp_readiness_scope_immutable'; END IF;
  RETURN NEW;
 END; $$;


--
-- Name: guard_migration_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_migration_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE n compute_nodes%ROWTYPE; source_instance instances%ROWTYPE; used record;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'migration admission receipts must be retained' USING ERRCODE='23514',CONSTRAINT='migration_admission_current'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.phase<>'reserved' OR NEW.adoption_receipt<>''::bytea OR NEW.cleanup_proof<>'' OR NEW.expires_at<=clock_timestamp() THEN
   RAISE EXCEPTION 'invalid initial migration admission' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
  END IF;
  SELECT * INTO n FROM compute_nodes WHERE id=NEW.destination_node_id FOR SHARE;
  IF NOT FOUND OR n.lifecycle NOT IN ('active','recovering') OR n.lifecycle_generation<>NEW.destination_generation THEN
   RAISE EXCEPTION 'stale migration destination' USING ERRCODE='23514',CONSTRAINT='instance_node_admission_current';
  END IF;
  PERFORM pg_advisory_xact_lock(1852793957,hashtext(NEW.destination_node_id::text));
  SELECT * INTO source_instance FROM instances WHERE id=NEW.instance_id FOR UPDATE;
  IF NOT FOUND OR source_instance.node_id<>NEW.source_node_id OR source_instance.wake_id<>NEW.source_wake_id OR source_instance.state<>'migrating' OR source_instance.lease_token IS DISTINCT FROM NEW.lease_token
   OR NEW.ram_mb<greatest(source_instance.ram_mb+(SELECT overhead_mb FROM service_capacity_policy WHERE singleton),source_instance.capacity_ram_mb)
   OR NEW.cpu_millicores<source_instance.capacity_cpu_millicores OR NEW.vcpu<source_instance.capacity_vcpu THEN
   RAISE EXCEPTION 'migration source or resource shape changed' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
  END IF;
  IF EXISTS(SELECT 1 FROM migration_admissions WHERE instance_id=NEW.instance_id AND phase NOT IN ('cleaned','committed')) THEN
   RAISE EXCEPTION 'instance already has an incoming migration' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
  END IF;
  PERFORM 1 FROM migration_leases l WHERE l.instance_id=NEW.instance_id AND l.lease_token=NEW.lease_token
   AND l.source_node_id=NEW.source_node_id::text AND NOT l.pending AND NOT l.resume_fenced AND l.lease_expires_at>clock_timestamp() AND NEW.expires_at<=l.lease_expires_at
   AND l.mem_storage_key=NEW.mem_storage_key AND l.vmstate_storage_key=NEW.vmstate_storage_key FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'migration source lease is not current' USING ERRCODE='23514',CONSTRAINT='migration_admission_current'; END IF;
  PERFORM 1 FROM migration_sources WHERE lease_token=NEW.lease_token AND instance_id=NEW.instance_id AND source_node_id=NEW.source_node_id AND source_wake_id=NEW.source_wake_id AND phase='bound' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'migration source physical binding is unavailable' USING ERRCODE='23514',CONSTRAINT='migration_source_current'; END IF;
  SELECT * INTO used FROM migration_admission_node_usage(NEW.destination_node_id);
  IF (n.admission_ceiling_mb>0 AND used.ram+NEW.ram_mb>n.admission_ceiling_mb) OR
     (n.vpcpus>0 AND used.cpu+NEW.cpu_millicores>n.vpcpus::bigint*1000) OR
     (n.vcpu_budget>0 AND used.vcpu+NEW.vcpu>n.vcpu_budget) THEN
   RAISE EXCEPTION 'migration destination capacity exhausted' USING ERRCODE='23514',CONSTRAINT='migration_admission_capacity';
  END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['phase','adoption_receipt','cleanup_proof','active_lease_token']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['phase','adoption_receipt','cleanup_proof','active_lease_token'])
  OR (OLD.adoption_receipt<>''::bytea AND OLD.adoption_receipt IS DISTINCT FROM NEW.adoption_receipt)
  OR (OLD.cleanup_proof<>'' AND OLD.cleanup_proof IS DISTINCT FROM NEW.cleanup_proof) THEN
  RAISE EXCEPTION 'migration admission identity and receipts are immutable' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
 END IF;
 IF NEW.phase=OLD.phase THEN
  IF NEW.adoption_receipt IS DISTINCT FROM OLD.adoption_receipt OR NEW.cleanup_proof IS DISTINCT FROM OLD.cleanup_proof THEN RAISE EXCEPTION 'migration receipt requires its phase transition' USING ERRCODE='23514',CONSTRAINT='migration_admission_current'; END IF;
  RETURN NEW;
 END IF;
 IF NOT ((OLD.phase='reserved' AND NEW.phase IN ('adopting','cleaned')) OR
         (OLD.phase='adopting' AND NEW.phase IN ('adopted','cleaning')) OR
         (OLD.phase='adopted' AND NEW.phase IN ('cleaning','committed')) OR
         (OLD.phase='cleaning' AND NEW.phase='cleaned')) THEN
  RAISE EXCEPTION 'invalid migration admission transition' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
 END IF;
 IF NEW.phase='adopting' THEN
  SELECT * INTO n FROM compute_nodes WHERE id=NEW.destination_node_id FOR SHARE;
  IF NOT FOUND OR n.lifecycle NOT IN ('active','recovering') OR n.lifecycle_generation<>NEW.destination_generation OR NEW.expires_at<=clock_timestamp() THEN
   RAISE EXCEPTION 'stale migration destination' USING ERRCODE='23514',CONSTRAINT='instance_node_admission_current';
  END IF;
 END IF;
 IF OLD.phase='reserved' AND NEW.phase='cleaned' AND NEW.cleanup_proof<>'no_dispatch' THEN
  RAISE EXCEPTION 'unstarted cancellation requires no-dispatch proof' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
 END IF;
 IF NEW.phase='committed' AND NOT EXISTS(SELECT 1 FROM instances owned WHERE owned.id=NEW.instance_id AND owned.node_id=NEW.destination_node_id AND owned.wake_id=NEW.destination_wake_id AND owned.lease_token=NEW.lease_token AND owned.state='running') THEN
  RAISE EXCEPTION 'migration admission has no committed owner' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_migration_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_migration_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE i instances%ROWTYPE; l migration_leases%ROWTYPE; n compute_nodes%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'migration source receipts must be retained' USING ERRCODE='23514',CONSTRAINT='migration_source_current'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO n FROM compute_nodes WHERE id=NEW.source_node_id FOR SHARE;
  IF NOT FOUND OR n.lifecycle IN ('maintenance','retired') THEN
   RAISE EXCEPTION 'migration source node is closed' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
  END IF;
  PERFORM pg_advisory_xact_lock(1852793957,hashtext(NEW.source_node_id::text));
  SELECT * INTO i FROM instances WHERE id=NEW.instance_id FOR UPDATE;
  IF NOT FOUND OR i.node_id<>NEW.source_node_id OR i.wake_id<>NEW.source_wake_id
   OR i.state NOT IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm','frozen') THEN
   RAISE EXCEPTION 'migration source wake changed' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
  END IF;
  SELECT * INTO l FROM migration_leases WHERE lease_token=NEW.lease_token FOR UPDATE;
  IF NOT FOUND OR l.instance_id<>NEW.instance_id OR l.source_node_id<>NEW.source_node_id::text OR l.resume_fenced OR NEW.phase<>'bound' OR NEW.proof<>''
   OR NEW.ram_mb<greatest(i.capacity_ram_mb,i.ram_mb+(SELECT overhead_mb FROM service_capacity_policy WHERE singleton))
   OR NEW.cpu_millicores<i.capacity_cpu_millicores OR NEW.vcpu<i.capacity_vcpu THEN
   RAISE EXCEPTION 'migration source lease changed' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
  END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['phase','proof','active_lease_token']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['phase','proof','active_lease_token']) THEN
  RAISE EXCEPTION 'migration source identity is immutable' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
 END IF;
 IF NEW.phase=OLD.phase THEN
  IF NEW.proof<>OLD.proof THEN RAISE EXCEPTION 'migration source receipt changed' USING ERRCODE='23514',CONSTRAINT='migration_source_current'; END IF;
  RETURN NEW;
 END IF;
 IF NOT ((OLD.phase='bound' AND NEW.phase IN ('retiring','resumed','retired')) OR (OLD.phase='retiring' AND NEW.phase='retired')) THEN
  RAISE EXCEPTION 'invalid migration source transition' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
 END IF;
 IF OLD.phase='bound' THEN
  SELECT * INTO l FROM migration_leases WHERE lease_token=NEW.lease_token FOR UPDATE;
  IF NEW.phase='resumed' AND (NOT l.resume_fenced OR EXISTS(SELECT 1 FROM migration_admissions WHERE lease_token=NEW.lease_token AND phase<>'cleaned')) THEN
   RAISE EXCEPTION 'migration source resume is not fenced' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
  END IF;
  IF NEW.phase='resumed' AND NOT EXISTS(SELECT 1 FROM instances WHERE id=NEW.instance_id AND node_id=NEW.source_node_id AND wake_id=NEW.source_wake_id AND state IN ('running','draining')) THEN
   RAISE EXCEPTION 'migration source has no serving owner to resume' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
  END IF;
  IF NEW.phase='retired' AND NOT l.resume_fenced THEN
   RAISE EXCEPTION 'migration source retirement is not fenced' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
  END IF;
  IF NEW.phase='retiring' THEN
   IF EXISTS(SELECT 1 FROM migration_admissions WHERE lease_token=NEW.lease_token AND phase NOT IN ('cleaned','committed'))
    OR EXISTS(SELECT 1 FROM instances WHERE id=NEW.instance_id AND node_id=NEW.source_node_id AND wake_id=NEW.source_wake_id AND state IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm','frozen')) THEN
    RAISE EXCEPTION 'migration source still owns its wake' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_node_migration_admissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_node_migration_admissions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF (TG_OP='DELETE' OR NEW.lifecycle IN ('maintenance','retired')) AND EXISTS(SELECT 1 FROM migration_admissions WHERE destination_node_id=OLD.id AND phase NOT IN ('cleaned','committed')) THEN
  RAISE EXCEPTION 'node has unresolved incoming migrations' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_node_migration_sources(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_node_migration_sources() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF (TG_OP='DELETE' OR NEW.lifecycle IN ('maintenance','retired')) AND (EXISTS(SELECT 1 FROM migration_sources WHERE source_node_id=OLD.id AND phase IN ('bound','retiring')) OR EXISTS(SELECT 1 FROM migration_leases WHERE source_node_id=OLD.id::text)) THEN
  RAISE EXCEPTION 'node has unresolved source migrations' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_object_multipart_initiation_dispatch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_object_multipart_initiation_dispatch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE u object_storage_multipart_uploads%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM object_bucket_mutations WHERE multipart_upload_id=OLD.multipart_upload_id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_live',MESSAGE='Retain original initiation evidence while the provider receipt is outstanding';
  END IF;
  RETURN OLD;
 END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_isolation',MESSAGE='Initiation dispatch requires READ COMMITTED';
 END IF;
 SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.multipart_upload_id;
 PERFORM id FROM resource_namespaces WHERE id=u.account_id FOR UPDATE;
 PERFORM id FROM object_buckets WHERE id=u.bucket_id FOR UPDATE;
 SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.multipart_upload_id FOR UPDATE;
 IF u.id IS NULL OR u.state<>'initiating' OR u.provider_upload_id<>'' OR NOT EXISTS(
  SELECT 1 FROM object_bucket_mutations m JOIN object_buckets b ON b.id=m.bucket_id
  WHERE m.multipart_upload_id=u.id AND m.kind='request' AND b.id=u.bucket_id AND b.account_id=u.account_id AND b.app_id=u.app_id
  AND b.state='ready' AND b.backend_id=m.backend_id AND b.backend_fingerprint=m.backend_fingerprint AND b.physical_name=m.physical_name
 ) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_original',MESSAGE='Initiation requires the original session receipt and placement';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.dispatched OR NEW.dispatch_token<>'' OR NEW.provider_upload_id<>'' OR u.lease_token IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_reserved',MESSAGE='Initialize dispatch evidence only with a new reservation';
  END IF;
 ELSIF NEW.multipart_upload_id<>OLD.multipart_upload_id OR u.lease_token IS NULL OR u.lease_token='' OR u.lease_until IS NULL OR u.lease_until<=clock_timestamp() OR NOT (
  (NOT OLD.dispatched AND NEW.dispatched AND NEW.dispatch_token=u.lease_token AND NEW.provider_upload_id='') OR
  (OLD.dispatched AND NEW.dispatched AND OLD.dispatch_token=u.lease_token AND NEW.dispatch_token=OLD.dispatch_token AND OLD.provider_upload_id='' AND btrim(NEW.provider_upload_id)<>'' AND NEW.provider_upload_id !~ '[[:cntrl:]]')
 ) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_immutable',MESSAGE='Dispatch is once-only and only its live owner may record a positive reply';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_object_multipart_part_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_object_multipart_part_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.multipart_part_writer_id IS NOT NULL AND EXISTS(SELECT 1 FROM object_multipart_part_writers WHERE id=OLD.multipart_part_writer_id AND NOT settled) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Settle the original part writer before deleting its receipt';
  END IF;
  RETURN OLD;
 ELSIF TG_OP='UPDATE' THEN
  IF NEW.multipart_part_writer_id IS NOT NULL OR OLD.multipart_part_writer_id IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Original part receipts are immutable';
  END IF;
 ELSIF NEW.multipart_part_writer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM object_multipart_part_writers d WHERE d.id=NEW.multipart_part_writer_id AND d.id=NEW.id AND d.managed AND d.dispatched AND NOT d.settled AND d.bucket_id=NEW.bucket_id AND d.backend_id=NEW.backend_id AND d.backend_fingerprint=NEW.backend_fingerprint AND d.physical_name=NEW.physical_name AND NEW.kind='request') THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Bind the receipt to its original claimed part attempt';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_object_multipart_part_writer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_object_multipart_part_writer() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE u object_storage_multipart_uploads%ROWTYPE; g object_storage_multipart_part_grants%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.dispatched AND NOT OLD.settled THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Uncertain part evidence cannot be deleted';
  END IF;
  RETURN OLD;
 END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Part writers require READ COMMITTED';
 END IF;
 SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.upload_id;
 PERFORM id FROM resource_namespaces WHERE id=u.account_id FOR UPDATE;
 PERFORM id FROM object_buckets WHERE id=u.bucket_id FOR UPDATE;
 SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.upload_id FOR UPDATE;
 SELECT * INTO g FROM object_storage_multipart_part_grants WHERE upload_id=NEW.upload_id AND part_number=NEW.part_number;
 IF u.id IS NULL OR u.bucket_id<>NEW.bucket_id OR NOT EXISTS(SELECT 1 FROM object_buckets b WHERE b.id=u.bucket_id AND b.account_id=u.account_id AND b.app_id=u.app_id AND b.state='ready' AND b.backend_id=NEW.backend_id AND b.backend_fingerprint=NEW.backend_fingerprint AND b.physical_name=NEW.physical_name) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Part writer requires its original placement';
 END IF;
 IF TG_OP='INSERT' THEN
  IF EXISTS(SELECT 1 FROM object_bucket_write_fences WHERE bucket_id=u.bucket_id) THEN
   RAISE EXCEPTION USING ERRCODE='55000',CONSTRAINT='object_multipart_part_capture_fenced',MESSAGE='Capture fences new part transfer admission';
  END IF;
  IF NOT NEW.managed OR NEW.dispatched OR NEW.settled OR u.state<>'active' OR g.transfer_token IS DISTINCT FROM NEW.transfer_token THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Reserve part evidence only with new unfenced transfer authority';
  END IF;
 ELSIF (to_jsonb(NEW)-ARRAY['dispatched','settled','copy_intent','put_intent','body_sha256']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['dispatched','settled','copy_intent','put_intent','body_sha256']) OR OLD.settled OR NOT OLD.managed OR NOT (
  (OLD.copy_intent IS NULL AND OLD.put_intent IS NULL AND OLD.body_sha256='' AND NEW.body_sha256='' AND NOT OLD.dispatched AND NEW.dispatched AND NOT NEW.settled AND u.state='active' AND u.expires_at>clock_timestamp() AND g.transfer_token IS NOT DISTINCT FROM NEW.transfer_token AND g.unsafe_until>clock_timestamp()) OR
  (NEW.copy_intent IS NOT DISTINCT FROM OLD.copy_intent AND NEW.put_intent IS NOT DISTINCT FROM OLD.put_intent AND NEW.body_sha256=OLD.body_sha256 AND NEW.dispatched=OLD.dispatched AND NEW.settled AND (NOT OLD.dispatched OR g.transfer_token IS NOT DISTINCT FROM NEW.transfer_token))
  OR (OLD.dispatched AND NOT OLD.settled AND NEW.dispatched AND NOT NEW.settled AND OLD.put_intent IS NOT NULL AND OLD.copy_intent IS NULL
   AND NEW.put_intent IS NOT DISTINCT FROM OLD.put_intent AND NEW.copy_intent IS NOT DISTINCT FROM OLD.copy_intent
   AND (OLD.body_sha256='' OR OLD.body_sha256=NEW.body_sha256) AND NEW.body_sha256 ~ '^[0-9a-f]{64}$' AND g.transfer_token IS NOT DISTINCT FROM NEW.transfer_token
   AND (OLD.put_intent->>'expected_sha256'='' OR OLD.put_intent->>'expected_sha256'=NEW.body_sha256))
 ) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Dispatch once; settle only the original attempt with qualified proof';
 END IF;
 IF TG_OP='UPDATE' AND NOT OLD.dispatched AND NEW.dispatched AND NEW.copy_intent IS NOT NULL AND NOT COALESCE((
  NEW.copy_intent->>'destination_key'=u.object_key AND NEW.copy_intent->>'provider_upload_id'=u.provider_upload_id
  AND (NEW.copy_intent->>'expected_size')::bigint BETWEEN 1 AND g.max_bytes
  AND (NEW.copy_intent->>'source_size')::bigint >= (NEW.copy_intent->>'expected_size')::bigint
  AND NEW.copy_intent->>'source_etag'<>'' AND NEW.copy_intent->>'source_key'<>''
  AND ((g.source_bucket_id IS NULL AND NEW.copy_intent->>'source_bucket_id'=u.bucket_id::text)
   OR (NEW.copy_intent->>'source_bucket_id'=g.source_bucket_id::text AND NEW.copy_intent->>'source_key'=g.source_key))
  AND EXISTS(SELECT 1 FROM object_buckets b WHERE b.id::text=NEW.copy_intent->>'source_bucket_id' AND b.account_id=u.account_id AND b.state='ready'
   AND b.backend_id=NEW.copy_intent->>'source_backend_id' AND b.backend_fingerprint=NEW.copy_intent->>'source_backend_fingerprint' AND b.physical_name=NEW.copy_intent->>'source_physical_name')
  AND (((NEW.copy_intent->>'has_range')::boolean AND (NEW.copy_intent->>'range_first')::bigint>=0 AND (NEW.copy_intent->>'range_last')::bigint<(NEW.copy_intent->>'source_size')::bigint
    AND (NEW.copy_intent->>'expected_size')::bigint=(NEW.copy_intent->>'range_last')::bigint-(NEW.copy_intent->>'range_first')::bigint+1)
   OR (NOT (NEW.copy_intent->>'has_range')::boolean AND (NEW.copy_intent->>'range_first')::bigint=0 AND (NEW.copy_intent->>'range_last')::bigint=0 AND NEW.copy_intent->>'expected_size'=NEW.copy_intent->>'source_size'))
 ),false) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Copy intent requires the original measured source, range and destination';
 END IF;
 IF TG_OP='UPDATE' AND NOT OLD.dispatched AND NEW.dispatched AND NEW.put_intent IS NOT NULL AND NOT COALESCE((
  NEW.copy_intent IS NULL AND g.source_bucket_id IS NULL
  AND NEW.put_intent->>'destination_key'=u.object_key AND NEW.put_intent->>'provider_upload_id'=u.provider_upload_id
  AND ((g.url_credential_id IS NULL AND (NEW.put_intent->>'expected_size')::bigint BETWEEN 1 AND g.max_bytes)
   OR (g.url_credential_id IS NOT NULL AND u.part_count>0 AND u.part_size_bytes>0 AND u.size_bytes>0
    AND NEW.part_number BETWEEN 1 AND u.part_count
    AND (NEW.put_intent->>'expected_size')::bigint=least(u.part_size_bytes,u.size_bytes-(NEW.part_number-1)::bigint*u.part_size_bytes)))
  AND (NEW.put_intent->>'expected_sha256'='' OR NEW.put_intent->>'expected_sha256' ~ '^[0-9a-f]{64}$')
 ),false) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='PUT intent requires its original destination and admitted size';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_object_storage_billing_origin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_object_storage_billing_origin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.object_storage_owned_from IS NOT NULL AND NEW.object_storage_owned_from IS DISTINCT FROM OLD.object_storage_owned_from THEN
  RAISE EXCEPTION 'storage billing origin is immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_org_managed_postgres_databases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_org_managed_postgres_databases() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF (NEW.deleted_pending OR NEW.status='deleted_pending') AND EXISTS(
     SELECT 1 FROM managed_postgres_databases WHERE org_id=NEW.id AND state<>'deleted') THEN
  RAISE EXCEPTION 'organization has managed PostgreSQL databases' USING ERRCODE='23514',CONSTRAINT='org_has_managed_postgres_databases';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_org_object_buckets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_org_object_buckets() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF (NEW.deleted_pending OR NEW.status='deleted_pending') AND EXISTS(SELECT 1 FROM object_buckets b WHERE b.org_id=NEW.id AND b.state<>'deleted') THEN
  RAISE EXCEPTION 'organization has object buckets' USING ERRCODE='23514',CONSTRAINT='org_has_object_buckets';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_org_queue_bindings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_org_queue_bindings() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF (NEW.deleted_pending OR NEW.status='deleted_pending') AND EXISTS
  (SELECT 1 FROM queue_bindings b WHERE b.org_id=NEW.id AND b.retired_at IS NULL) THEN
  RAISE EXCEPTION 'retire organization queue bindings before deletion' USING ERRCODE='23514',CONSTRAINT='org_has_queue_bindings';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_outbound_app_binding_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_outbound_app_binding_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM apps app
          JOIN outbound_integrations integration
            ON integration.id = NEW.integration_id
         WHERE app.id = NEW.app_id
           AND app.account_id = NEW.account_id
           AND app.status <> 'deleted'
           AND integration.account_id = NEW.account_id
           AND integration.provider_auth_mode = 'managed'
    ) THEN
        RAISE EXCEPTION 'outbound binding owner mismatch or integration is not managed'
            USING ERRCODE = '23514', CONSTRAINT = 'outbound_app_binding_owner';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_outbound_credential_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_outbound_credential_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM outbound_integrations integration
         WHERE integration.id = NEW.integration_id
           AND integration.account_id = NEW.account_id
           AND integration.provider_auth_mode = 'managed'
           AND integration.credential_source = 'customer_sealed'
    ) THEN
        RAISE EXCEPTION 'outbound credential owner or source mismatch'
            USING ERRCODE = '23514', CONSTRAINT = 'outbound_credential_owner';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_outbound_integration_app_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_outbound_integration_app_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM outbound_integrations integration
        JOIN apps app ON app.id = NEW.app_id
        WHERE integration.id = NEW.integration_id
          AND integration.account_id = app.account_id
          AND app.status <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'outbound integration app owner mismatch or app is deleted'
            USING ERRCODE = '23514', CONSTRAINT = 'outbound_integration_app_owner';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_outbound_integration_owner_kind(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_outbound_integration_owner_kind() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.owner_kind <> NEW.owner_kind THEN
        RAISE EXCEPTION 'outbound integration owner kind is immutable'
            USING ERRCODE = '23514', CONSTRAINT = 'outbound_integration_owner_kind_immutable';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_production_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_production_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE gate canary_route_gates%ROWTYPE; fence jsonb;
BEGIN
 IF NEW.status<>'live' OR NEW.traffic_percent<=0 OR coalesce(nullif(NEW.scope,''),'default') NOT IN ('default','prod','production') OR
 (TG_OP='UPDATE' AND OLD.status='live' AND NEW.traffic_percent<=OLD.traffic_percent AND NEW.app_id=OLD.app_id AND NEW.scope IS NOT DISTINCT FROM OLD.scope) THEN RETURN NEW; END IF;
 PERFORM 1 FROM apps WHERE id=NEW.app_id FOR UPDATE;
 SELECT * INTO gate FROM canary_route_gates WHERE app_id=NEW.app_id;

 SELECT value INTO fence FROM jsonb_array_elements(coalesce(nullif(current_setting('faas.lifecycle_fences',true),''),'[]')::jsonb)
 WHERE value->>'deployment_id'=NEW.id::text LIMIT 1;
 IF coalesce(gate.mode,'report')='enforce' AND (fence IS NULL OR fence->>'scope' IS DISTINCT FROM coalesce(nullif(NEW.scope,''),'default') OR fence->'inputs' IS DISTINCT FROM lifecycle_traffic_inputs(NEW.app_id)) THEN
 RAISE EXCEPTION 'production lifecycle review required' USING ERRCODE='23514',CONSTRAINT='production_lifecycle_required'; END IF;
 -- Expiry and capture invalidation are rechecked at the actual traffic write.
 PERFORM 1 FROM route_lifecycle_approvals r WHERE r.id::text IN (SELECT jsonb_array_elements_text(coalesce(nullif(fence->'approval_ids','null'::jsonb),'[]'::jsonb))) ORDER BY r.id FOR SHARE;
 IF coalesce(gate.mode,'report')='enforce' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(nullif(fence->'approval_ids','null'::jsonb),'[]'::jsonb)) x(id)
 WHERE NOT EXISTS(SELECT 1 FROM route_lifecycle_approvals r WHERE r.id::text=x.id AND r.app_id=NEW.app_id
 AND r.invalidated_at IS NULL AND r.valid_until>clock_timestamp()
 AND r.successor_snapshot=lifecycle_approval_successor_bindings(r.app_id,r.receipt))) THEN
 RAISE EXCEPTION 'production lifecycle receipt expired or invalidated' USING ERRCODE='23514',CONSTRAINT='production_lifecycle_required'; END IF;
 INSERT INTO production_lifecycle_reviews(app_id,deployment_id,decision,recovery,scope,evidence) VALUES(NEW.app_id,NEW.id,coalesce(fence->'decision',jsonb_build_object('mode','report','status','report_only','reasons',jsonb_build_array('lifecycle_transaction_review_unavailable'))),coalesce((fence->>'recovery')::boolean,false),coalesce(nullif(NEW.scope,''),'default'),lifecycle_history_evidence(NEW.app_id,NEW.id,coalesce(fence->'decision','{}'::jsonb)));
 RETURN NEW;
END $$;


--
-- Name: guard_project_deactivation_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_project_deactivation_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE g jsonb;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.deactivation IS NOT NULL THEN RAISE EXCEPTION 'receipt requires retirement' USING ERRCODE='23514',CONSTRAINT='binding_release_required'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.deactivation IS NOT DISTINCT FROM OLD.deactivation THEN RETURN NEW; END IF;
 g:=nullif(current_setting('gregale.binding_release_graph',true),'')::jsonb;
 IF OLD.deactivation IS NOT NULL OR NEW.deactivation IS NULL OR g->>'action' IS DISTINCT FROM 'deactivate' OR g->>'old_id' IS DISTINCT FROM NEW.id::text OR NEW.deactivation->>'id' IS DISTINCT FROM g->>'receipt_id' THEN
  RAISE EXCEPTION 'immutable checked deactivation receipt' USING ERRCODE='23514',CONSTRAINT='binding_release_required';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_queue_binding_environment_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_queue_binding_environment_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE environment uuid;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF NEW.environment_id IS DISTINCT FROM OLD.environment_id OR NEW.deployment_scope IS DISTINCT FROM OLD.deployment_scope OR
      (OLD.deployment_scope<>'' AND (NEW.id IS DISTINCT FROM OLD.id
        OR NEW.app_id IS DISTINCT FROM OLD.app_id OR NEW.account_id IS DISTINCT FROM OLD.account_id)) THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_binding_scope_identity',
        MESSAGE='queue binding environment identity is immutable';
    END IF;
  ELSIF NEW.deployment_scope<>'' THEN
    SELECT e.id INTO environment FROM apps a JOIN project_environments e ON e.project_id=a.project_id
      AND e.account_id=a.account_id AND e.slug=NEW.deployment_scope
      WHERE a.id=NEW.app_id AND a.account_id=NEW.account_id AND a.status<>'deleted'
      FOR SHARE OF a,e;
    IF NOT FOUND OR (NEW.environment_id IS NOT NULL AND NEW.environment_id IS DISTINCT FROM environment) THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_binding_environment_membership',
        MESSAGE='scoped queue binding requires an account-owned project environment';
    END IF;
    NEW.environment_id=environment;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_queue_binding_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_queue_binding_retirement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.retired_at IS NOT NULL AND EXISTS(SELECT 1 FROM apps WHERE id=OLD.app_id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='queue_binding_retirement_identity',MESSAGE='retired queue identity requires explicit recovery';
  END IF;
  RETURN OLD;
 END IF;
 IF OLD.retired_at IS NOT NULL AND NEW.retired_at IS NULL
  AND (to_jsonb(NEW)-'retired_at'-'updated_at')=(to_jsonb(OLD)-'retired_at'-'updated_at')
  AND environment_gitops_queue_recovery_authorized(OLD.id) THEN
  RETURN NEW;
 END IF;
 IF OLD.retired_at IS NOT NULL AND
  (NEW.retired_at IS DISTINCT FROM OLD.retired_at OR NEW.id IS DISTINCT FROM OLD.id
   OR NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.app_id IS DISTINCT FROM OLD.app_id
   OR NEW.name IS DISTINCT FROM OLD.name OR NEW.queue_name IS DISTINCT FROM OLD.queue_name
   OR NEW.mode IS DISTINCT FROM OLD.mode OR NEW.workload_class IS DISTINCT FROM OLD.workload_class
   OR NEW.enabled IS DISTINCT FROM OLD.enabled OR NEW.max_concurrency IS DISTINCT FROM OLD.max_concurrency
   OR NEW.retry_policy IS DISTINCT FROM OLD.retry_policy) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='queue_binding_retirement_identity',MESSAGE='retired queue binding requires explicit recovery';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_queue_consumer_binding_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_queue_consumer_binding_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.queue_binding_id IS NOT NULL
    AND (NEW.queue_binding_id IS DISTINCT FROM OLD.queue_binding_id
      OR NEW.app_id IS DISTINCT FROM OLD.app_id
      OR NEW.account_id IS DISTINCT FROM OLD.account_id) THEN
    RAISE EXCEPTION 'queue consumer binding identity is immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'queue_consumer_binding_identity';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_queue_consumer_environment_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_queue_consumer_environment_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE scope text; environment uuid;
BEGIN
  IF TG_OP='UPDATE' AND (NEW.queue_binding_scope IS DISTINCT FROM OLD.queue_binding_scope
    OR NEW.queue_binding_environment_id IS DISTINCT FROM OLD.queue_binding_environment_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_consumer_scope_identity',
      MESSAGE='queue consumer environment identity is immutable';
  END IF;
  IF NEW.queue_binding_id IS NULL THEN
    IF NEW.queue_binding_scope<>'' OR NEW.queue_binding_environment_id IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_consumer_scope_identity',
        MESSAGE='scoped consumer requires an immutable binding';
    END IF;
  ELSE
    SELECT b.deployment_scope,b.environment_id INTO scope,environment FROM queue_bindings b
      WHERE b.id=NEW.queue_binding_id AND b.app_id=NEW.app_id AND b.account_id=NEW.account_id FOR SHARE;
    IF NOT FOUND THEN RETURN NEW; END IF; -- The existing deferred tenant FK owns this rejection.
    IF (TG_OP='UPDATE' AND (NEW.queue_binding_scope IS DISTINCT FROM scope OR NEW.queue_binding_environment_id IS DISTINCT FROM environment))
      OR (TG_OP='INSERT' AND ((NEW.queue_binding_scope<>'' AND NEW.queue_binding_scope IS DISTINCT FROM scope)
        OR (NEW.queue_binding_environment_id IS NOT NULL AND NEW.queue_binding_environment_id IS DISTINCT FROM environment))) THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_consumer_scope_identity',
        MESSAGE='queue consumer must retain its parent environment';
    END IF;
    NEW.queue_binding_scope=scope;
    NEW.queue_binding_environment_id=environment;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_retired_queue_invocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_retired_queue_invocation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE binding_retired_at timestamptz; binding_scope text; binding_environment uuid;
BEGIN
  IF NEW.environment_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.source='queue' AND (TG_OP='INSERT' OR
    (NEW.state='dispatching' AND OLD.state IS DISTINCT FROM 'dispatching')) THEN
    SELECT b.retired_at,b.deployment_scope,b.environment_id INTO binding_retired_at,binding_scope,binding_environment FROM queue_bindings b
      WHERE b.app_id=NEW.app_id AND b.account_id=NEW.account_id AND
        (b.id=NEW.queue_binding_id OR (NEW.queue_binding_id IS NULL
          AND b.deployment_scope='' AND b.queue_name=NEW.queue_name)) FOR SHARE;
    IF binding_scope<>'' AND NOT EXISTS (SELECT 1 FROM apps a JOIN project_environments e
      ON e.project_id=a.project_id AND e.account_id=a.account_id WHERE a.id=NEW.app_id
        AND e.id=binding_environment AND e.slug=binding_scope) THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_binding_environment_unavailable',
        MESSAGE='captured queue binding environment is unavailable';
    END IF;
    IF binding_retired_at IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_binding_retired', MESSAGE='queue binding is retired';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_retired_workload_execution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_retired_workload_execution() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE application uuid; environment uuid; scope text; linked_job uuid; r environment_workload_retirements%ROWTYPE; d deployments%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='instances' THEN
  IF TG_OP='UPDATE' AND (NEW.state IS NOT DISTINCT FROM OLD.state OR NEW.state IN ('draining','snapshotting','parked','stopped','failed','evicting_account_deleting')) THEN RETURN NEW; END IF;
  SELECT * INTO d FROM deployments WHERE id=NEW.deployment_id;
  application:=NEW.app_id;scope:=d.scope;
 ELSIF TG_TABLE_NAME='deployments' THEN
  IF NEW.status<>'live' OR TG_OP='UPDATE' AND OLD.status='live' THEN RETURN NEW; END IF;
  application:=NEW.app_id;scope:=NEW.scope;
 ELSIF TG_TABLE_NAME='invocations' THEN
  IF TG_OP='UPDATE' AND (NEW.state<>'dispatching' OR OLD.state='dispatching') THEN RETURN NEW; END IF;
  application:=NEW.app_id;environment:=NEW.environment_id;scope:=NEW.deployment_scope;
 ELSIF TG_TABLE_NAME='trigger_records' THEN
  IF NEW.state<>'claimed' THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' THEN IF OLD.state='claimed' AND OLD.claim_generation=NEW.claim_generation THEN RETURN NEW; END IF; END IF;
  SELECT app_id,queue_binding_scope INTO application,scope FROM triggers WHERE id=NEW.trigger_id;
 ELSIF TG_TABLE_NAME='job_runs' THEN linked_job:=NEW.job_id;
 ELSIF TG_TABLE_NAME='job_tasks' THEN
  IF NEW.status<>'claimed' OR TG_OP='UPDATE' AND OLD.status='claimed' THEN RETURN NEW; END IF;
  SELECT job_id INTO linked_job FROM job_runs WHERE id=NEW.run_id;
 END IF;
 IF coalesce(scope,'') IN ('','default') THEN scope:='production'; END IF;
 IF application IS NOT NULL THEN
  PERFORM id FROM apps WHERE id=application FOR SHARE;
 ELSIF linked_job IS NOT NULL THEN
  PERFORM a.id FROM apps a JOIN environment_workload_retirements x ON x.app_id=a.id WHERE x.job_id=linked_job FOR SHARE OF a;
 END IF;
 SELECT * INTO r FROM environment_workload_retirements x WHERE x.phase IN ('retiring','retired','recovering') AND
  (linked_job IS NOT NULL AND x.job_id=linked_job OR application=x.app_id AND
   (environment=x.environment_id OR scope=(SELECT slug FROM project_environments WHERE id=x.environment_id)));
 IF r.id IS NULL THEN RETURN NEW; END IF;
 -- Serialize dispatch with the app lock held through cutover. Recheck after
 -- obtaining the lock to avoid admitting work from an earlier snapshot.
 PERFORM id FROM apps WHERE id=r.app_id FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM environment_workload_retirements WHERE id=r.id AND phase IN ('retiring','retired','recovering')) THEN RETURN NEW; END IF;
 IF r.phase='recovering' THEN
  IF TG_TABLE_NAME='deployments' THEN
   IF NEW.id<>ALL(r.deployment_ids) AND environment_workload_activation_authorized(NEW) THEN RETURN NEW; END IF;
  END IF;
  IF TG_TABLE_NAME='instances' AND d.environment_workload_held AND d.environment_workload_runtime->>'revision_id'=r.recovery_revision_id::text
   AND d.environment_workload_runtime->>'generation'=r.recovery_generation::text THEN RETURN NEW; END IF;
 END IF;
 RAISE EXCEPTION 'workload execution is retired in this environment' USING ERRCODE='23514',CONSTRAINT='environment_workload_retired';
END $$;


--
-- Name: guard_route_removal_traffic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_route_removal_traffic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p app_route_removal_policies%ROWTYPE; result jsonb; fence jsonb;
BEGIN
 IF NEW.status<>'live' OR NEW.traffic_percent<=0 OR
 (TG_OP='UPDATE' AND OLD.status='live' AND NEW.traffic_percent<=OLD.traffic_percent AND NEW.scope IS NOT DISTINCT FROM OLD.scope AND NEW.app_id=OLD.app_id) THEN RETURN NEW; END IF;
 -- Policy setters and deployment activation already take the app lock. This
 -- additionally fences direct SQL/worker/canary transitions with the policy.
 PERFORM 1 FROM apps WHERE id=NEW.app_id FOR UPDATE;
 SELECT * INTO p FROM app_route_removal_policies WHERE app_id=NEW.app_id;
 SELECT value INTO fence FROM jsonb_array_elements(coalesce(nullif(current_setting('faas.route_removal_fences',true),''),'[]')::jsonb)
 WHERE value->>'deployment_id'=NEW.id::text LIMIT 1;
 -- Captures update the policy observation clock after locking their document.
 -- Keep that document-before-policy order while holding the application lock.
 IF fence IS NOT NULL THEN
 PERFORM 1 FROM deployment_openapi_docs WHERE deployment_id IN (NEW.id,p.baseline_deployment_id) ORDER BY deployment_id FOR SHARE;
 PERFORM 1 FROM deployment_openapi_snapshots WHERE deployment_id IN (NEW.id,p.baseline_deployment_id) ORDER BY deployment_id FOR SHARE;
 END IF;
 SELECT * INTO p FROM app_route_removal_policies WHERE app_id=NEW.app_id FOR UPDATE;
 IF coalesce(nullif(NEW.scope,''),'default') NOT IN ('default','prod','production') THEN RETURN NEW; END IF;
 IF NOT FOUND THEN
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(nullif(current_setting('faas.route_removal_fences',true),''),'[]')::jsonb) WHERE value->>'deployment_id'=NEW.id::text) THEN
 RAISE EXCEPTION 'route removal policy disappeared after contract preflight' USING ERRCODE='23514',CONSTRAINT='route_removal_required'; END IF;
 RETURN NEW; END IF;
 PERFORM lock_route_removal_coverage(NEW.app_id);
 result:=route_removal_check(NEW.id,coalesce(NEW.scope,''),NEW.app_id);
 SELECT value INTO fence FROM jsonb_array_elements(coalesce(nullif(current_setting('faas.route_removal_fences',true),''),'[]')::jsonb)
 WHERE value->>'deployment_id'=NEW.id::text LIMIT 1;
 IF fence IS NOT NULL AND (p.mode<>'enforce' OR result->>'status'<>'passed' OR
 p.revision::text IS DISTINCT FROM fence->>'policy_revision' OR
 p.baseline_deployment_id::text IS DISTINCT FROM fence->>'baseline_deployment_id' OR
 result->>'approval_id' IS DISTINCT FROM fence->>'approval_id' OR
 result->>'baseline_contract_sha256' IS DISTINCT FROM fence->>'baseline_sha256' OR
 result->>'candidate_contract_sha256' IS DISTINCT FROM fence->>'candidate_sha256') THEN
 RAISE EXCEPTION 'route removal approval changed after contract preflight' USING ERRCODE='23514',CONSTRAINT='route_removal_required';
 END IF;
 IF fence IS NOT NULL AND (
 (coalesce(fence->>'baseline_snapshot_sha256','')<>'' AND NOT EXISTS(SELECT 1 FROM deployment_openapi_snapshots WHERE deployment_id=p.baseline_deployment_id AND sha256=fence->>'baseline_snapshot_sha256')) OR
 (coalesce(fence->>'candidate_snapshot_sha256','')<>'' AND (EXISTS(SELECT 1 FROM deployment_openapi_snapshots WHERE deployment_id=NEW.id AND sha256 IS DISTINCT FROM fence->>'candidate_snapshot_sha256') OR (TG_OP='UPDATE' AND OLD.status='live' AND NOT EXISTS(SELECT 1 FROM deployment_openapi_snapshots WHERE deployment_id=NEW.id AND sha256=fence->>'candidate_snapshot_sha256'))))) THEN
 RAISE EXCEPTION 'route removal contract snapshot changed after preflight' USING ERRCODE='23514',CONSTRAINT='route_removal_required'; END IF;
 IF p.mode='enforce' AND result->>'status'='blocked' THEN
 RAISE EXCEPTION 'route removal blocked' USING ERRCODE='23514',CONSTRAINT='route_removal_required',DETAIL=result::text;
 END IF;
 -- Keep a durable baseline even if callers zero/supersede its row first.
 -- Partial canaries keep the original baseline until a full cutover.
 IF NEW.traffic_percent=100 AND p.baseline_deployment_id IS DISTINCT FROM NEW.id THEN
 UPDATE app_route_removal_policies SET baseline_deployment_id=NEW.id,baseline_since=clock_timestamp() WHERE app_id=NEW.app_id;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_release_qualification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_release_qualification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP = 'INSERT' THEN
  IF NOT EXISTS (SELECT 1 FROM runtime_releases WHERE id=NEW.release_id AND architecture=NEW.architecture) THEN
   RAISE EXCEPTION 'runtime qualification architecture differs from release' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
  RAISE EXCEPTION 'runtime qualification evidence is retained' USING ERRCODE = '23514';
 END IF;
 IF ROW(NEW.release_id,NEW.profile,NEW.architecture,NEW.host_id,NEW.kernel_boot_id,NEW.source_commit,
  NEW.kernel_sha256,NEW.firecracker_sha256,NEW.report_sha256,NEW.test_metal_sha256,NEW.leakcheck_sha256,
  NEW.started_at,NEW.completed_at,NEW.recorded_at) IS DISTINCT FROM
  ROW(OLD.release_id,OLD.profile,OLD.architecture,OLD.host_id,OLD.kernel_boot_id,OLD.source_commit,
  OLD.kernel_sha256,OLD.firecracker_sha256,OLD.report_sha256,OLD.test_metal_sha256,OLD.leakcheck_sha256,
  OLD.started_at,OLD.completed_at,OLD.recorded_at) OR
  (OLD.revoked_at IS NOT NULL AND ROW(NEW.revoked_at,NEW.revocation_sha256) IS DISTINCT FROM ROW(OLD.revoked_at,OLD.revocation_sha256)) THEN
  RAISE EXCEPTION 'runtime qualification evidence and revocation are immutable' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_runtime_upgrade_external_fence_authority(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_external_fence_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' OR (TG_OP='INSERT' AND (NEW.revoked_at IS NOT NULL OR NEW.created_at>clock_timestamp())) THEN
  RAISE EXCEPTION 'external authority history cannot be erased or pre-revoked' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND (OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL OR NEW.revoked_at>clock_timestamp()
  OR (to_jsonb(NEW)-'revoked_at') IS DISTINCT FROM (to_jsonb(OLD)-'revoked_at')) THEN
  RAISE EXCEPTION 'authority key is immutable and revocation is irreversible' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_external_fence_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_external_fence_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE withdrawn runtime_upgrade_public_edge_withdrawals;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'external fence intent is immutable' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton AND revision=NEW.gateway_revision FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'external fence internal head changed' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton AND revision=NEW.public_revision FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'external fence public head changed' USING ERRCODE='23514'; END IF;
 SELECT * INTO withdrawn FROM runtime_upgrade_public_edge_withdrawals WHERE id=NEW.withdrawal_id FOR UPDATE;
 IF NOT FOUND OR NEW.created_at<withdrawn.created_at OR NEW.created_at>clock_timestamp()
  OR EXISTS(SELECT 1 FROM runtime_upgrade_public_edge_withdrawal_receipts WHERE withdrawal_id=NEW.withdrawal_id)
  OR EXISTS(SELECT 1 FROM runtime_upgrade_external_fence_receipts WHERE withdrawal_id=NEW.withdrawal_id) THEN
  RAISE EXCEPTION 'external fence requires unresolved exact withdrawal' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_external_fence_authorities WHERE id=NEW.authority_id AND revoked_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'external fence authority unavailable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_external_fence_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_external_fence_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE reviewed runtime_upgrade_external_fence_intents;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'external fence receipt is immutable' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton FOR SHARE;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton FOR SHARE;
 SELECT * INTO reviewed FROM runtime_upgrade_external_fence_intents WHERE id=NEW.intent_id FOR SHARE;
 IF NOT FOUND OR reviewed.withdrawal_id<>NEW.withdrawal_id THEN
  RAISE EXCEPTION 'external receipt intent mismatch' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_public_edge_withdrawals WHERE id=NEW.withdrawal_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM runtime_upgrade_public_edge_withdrawal_receipts WHERE withdrawal_id=NEW.withdrawal_id)
  OR NOT EXISTS(SELECT 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton AND revision=reviewed.gateway_revision)
  OR NOT EXISTS(SELECT 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton AND revision=reviewed.public_revision) THEN
  RAISE EXCEPTION 'external receipt resolved elsewhere or head changed' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_external_fence_authorities WHERE id=reviewed.authority_id AND revoked_at IS NULL FOR SHARE;
 IF NOT FOUND OR NEW.enforced_at<reviewed.created_at OR NEW.observed_at>clock_timestamp()
  OR clock_timestamp()-NEW.issued_at>interval '60 seconds'
  OR encode(sha256(NEW.envelope),'hex')<>NEW.envelope_sha256 THEN
  RAISE EXCEPTION 'external receipt authority, clock or bytes invalid' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_gateway_roster(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_gateway_roster() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE canonical uuid[]; unique_sessions integer;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'immutable runtime upgrade gateway roster' USING ERRCODE='23514';
 END IF;
 SELECT array_agg(DISTINCT s ORDER BY s) INTO canonical FROM unnest(NEW.slot_ids) s;
 SELECT count(DISTINCT s) INTO unique_sessions FROM unnest(NEW.gateway_sessions) s;
 IF NEW.slot_ids IS DISTINCT FROM canonical OR unique_sessions<>cardinality(NEW.gateway_sessions)
  OR array_position(NEW.slot_ids,NULL::uuid) IS NOT NULL OR array_position(NEW.gateway_sessions,NULL::uuid) IS NOT NULL
  OR array_position(NEW.slot_ids,'00000000-0000-0000-0000-000000000000'::uuid) IS NOT NULL
  OR array_position(NEW.gateway_sessions,'00000000-0000-0000-0000-000000000000'::uuid) IS NOT NULL THEN
  RAISE EXCEPTION 'invalid runtime upgrade gateway roster' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_native_public_startup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_native_public_startup() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE roster runtime_upgrade_public_edge_rosters; body jsonb; selected jsonb; epoch jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'native startup provenance is immutable' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton AND revision=NEW.gateway_revision FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'native startup internal head changed' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton AND revision=NEW.public_revision FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'native startup public head changed' USING ERRCODE='23514'; END IF;
 SELECT * INTO roster FROM runtime_upgrade_public_edge_rosters WHERE revision=NEW.public_revision;
 IF roster.gateway_roster_revision IS DISTINCT FROM NEW.gateway_revision
  OR roster.public_sessions[array_position(roster.slot_ids,NEW.slot_id)] IS DISTINCT FROM NEW.public_session_id
  OR roster.config_sha256s[array_position(roster.slot_ids,NEW.slot_id)] IS DISTINCT FROM NEW.config_sha256
  OR NEW.observed_at<roster.created_at OR NEW.recorded_at>clock_timestamp()
  OR EXISTS(SELECT 1 FROM runtime_upgrade_public_edge_withdrawals WHERE public_session_id=NEW.public_session_id)
  OR NOT EXISTS(SELECT 1 FROM runtime_upgrade_public_edge_guards WHERE slot_id=NEW.slot_id AND public_session_id=NEW.public_session_id
    AND public_roster_revision=NEW.public_revision AND config_sha256=NEW.config_sha256 AND guard_enabled
    AND observed_at<=clock_timestamp() AND expires_at>clock_timestamp()) THEN
  RAISE EXCEPTION 'native startup requires exact current guarded member before withdrawal' USING ERRCODE='23514';
 END IF;
 IF encode(sha256(NEW.review),'hex')<>NEW.review_sha256 OR encode(sha256(NEW.envelope),'hex')<>NEW.envelope_sha256 THEN
  RAISE EXCEPTION 'native startup evidence digest mismatch' USING ERRCODE='23514';
 END IF;
 selected:=convert_from(NEW.review,'UTF8')::jsonb;
 body:=convert_from(NEW.envelope,'UTF8')::jsonb;
 epoch:=body#>'{proof,startup,epoch}';
 IF body->'review' IS DISTINCT FROM selected OR jsonb_array_length(body->'native') IS DISTINCT FROM 2
  OR body#>>'{proof,startup,slot_id}' IS DISTINCT FROM NEW.slot_id::text
  OR body#>>'{proof,startup,session_id}' IS DISTINCT FROM NEW.public_session_id::text
  OR body#>>'{proof,startup,config_sha256}' IS DISTINCT FROM NEW.config_sha256
  OR epoch->>'machine_id' IS DISTINCT FROM NEW.machine_id OR epoch->>'boot_id' IS DISTINCT FROM NEW.boot_id::text
  OR epoch->>'pid' IS DISTINCT FROM NEW.pid::text OR epoch->>'start_ticks' IS DISTINCT FROM NEW.start_ticks
  OR epoch->>'pid_namespace' IS DISTINCT FROM NEW.pid_namespace OR epoch->>'net_namespace' IS DISTINCT FROM NEW.net_namespace THEN
  RAISE EXCEPTION 'native startup evidence identity mismatch' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_operation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_operation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.id,NEW.account_id,NEW.app_id,NEW.deployment_id,NEW.serving_deployment_id,NEW.target_release_id,
      NEW.source_sha256,NEW.qualification_report_sha256,NEW.created_at,NEW.deadline_at,NEW.source_path)
   IS DISTINCT FROM
     (OLD.id,OLD.account_id,OLD.app_id,OLD.deployment_id,OLD.serving_deployment_id,OLD.target_release_id,
      OLD.source_sha256,OLD.qualification_report_sha256,OLD.created_at,OLD.deadline_at,OLD.source_path)
   OR OLD.phase IN ('complete','blocked','cancelled')
   OR (OLD.phase='waiting' AND NEW.phase IN ('reserved','prepared'))
   OR (OLD.phase='prepared' AND NEW.phase='reserved')
   OR (OLD.phase='reserved' AND NEW.phase IN ('waiting','complete')) THEN
   RAISE EXCEPTION 'immutable runtime upgrade intent or terminal operation' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.phase='complete' AND NOT EXISTS (
  SELECT 1 FROM deployment_runtime_upgrade_cutovers c WHERE c.deployment_id=NEW.deployment_id
   AND c.serving_deployment_id=NEW.serving_deployment_id AND c.target_release_id=NEW.target_release_id
   AND c.qualification_report_sha256=NEW.qualification_report_sha256 AND c.wake_id=NEW.wake_id
 ) THEN
  RAISE EXCEPTION 'runtime upgrade completion requires retained cutover' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_operation_effect(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_operation_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE operation_phase text;
BEGIN
 PERFORM 1 FROM apps a JOIN deployments d ON d.app_id=a.id WHERE d.id=NEW.deployment_id FOR UPDATE OF a;
 SELECT phase INTO operation_phase FROM runtime_upgrade_operations WHERE deployment_id=NEW.deployment_id;
 IF (TG_TABLE_NAME='builds' AND operation_phase IN ('reserved','blocked','cancelled','complete'))
  OR (TG_TABLE_NAME='deployment_runtime_upgrade_cutovers' AND operation_phase IS NOT NULL AND operation_phase<>'waiting') THEN
  RAISE EXCEPTION 'runtime upgrade operation cannot publish this effect' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_public_edge_activity_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_activity_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.public_session_id=NEW.public_session_id AND OLD.public_roster_revision=NEW.public_roster_revision AND (
  NEW.activity_version < OLD.activity_version
  OR (NOT OLD.coverage_known AND NEW.coverage_known)
  OR (NEW.activity_version=OLD.activity_version AND
   (NEW.coverage_known,NEW.pending_forwards,NEW.current_forwards,NEW.previous_forwards)
   IS DISTINCT FROM (OLD.coverage_known,OLD.pending_forwards,OLD.current_forwards,OLD.previous_forwards))) THEN
  RAISE EXCEPTION 'public ingress activity cannot rewind or restore unknown coverage' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_public_edge_fact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_fact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton FOR SHARE;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton FOR SHARE;
 IF NOT EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_rosters r
  JOIN runtime_upgrade_public_edge_roster_head h ON h.revision=r.revision
  JOIN runtime_upgrade_gateway_roster_head g ON g.revision=r.gateway_roster_revision
  WHERE r.revision=NEW.public_roster_revision
   AND r.public_sessions[array_position(r.slot_ids,NEW.slot_id)]=NEW.public_session_id
   AND r.config_sha256s[array_position(r.slot_ids,NEW.slot_id)]=NEW.config_sha256) THEN
  RAISE EXCEPTION 'public guard fact requires exact current reviewed process and config' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_public_edge_head_withdrawals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_head_withdrawals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE next_roster runtime_upgrade_public_edge_rosters;
BEGIN
 IF TG_OP='DELETE' OR NEW.revision IS NULL THEN
  RAISE EXCEPTION 'public edge head cannot erase withdrawal history' USING ERRCODE='23514';
 END IF;
 SELECT * INTO next_roster FROM runtime_upgrade_public_edge_rosters WHERE revision=NEW.revision;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton AND revision=next_roster.gateway_roster_revision FOR SHARE;
 IF NOT FOUND OR EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_withdrawals w WHERE w.public_session_id=ANY(next_roster.public_sessions)) THEN
  RAISE EXCEPTION 'public review cannot resurrect a withdrawn process or bind an old internal review' USING ERRCODE='23514';
 END IF;
 IF EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_rosters prior, generate_subscripts(prior.public_sessions,1) i
  WHERE prior.revision=OLD.revision AND prior.public_sessions[i]=ANY(next_roster.public_sessions)
   AND (prior.slot_ids[i],prior.config_sha256s[i]) IS DISTINCT FROM
    (next_roster.slot_ids[array_position(next_roster.public_sessions,prior.public_sessions[i])],next_roster.config_sha256s[array_position(next_roster.public_sessions,prior.public_sessions[i])])) THEN
  RAISE EXCEPTION 'startup session cannot change public slot or configuration' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_public_edge_roster(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_roster() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE canonical uuid[];
BEGIN
 IF TG_OP <> 'INSERT' THEN
  RAISE EXCEPTION 'immutable public edge roster' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton AND revision=NEW.gateway_roster_revision FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'public edge roster requires current internal roster' USING ERRCODE='23514';
 END IF;
 SELECT array_agg(DISTINCT s ORDER BY s) INTO canonical FROM unnest(NEW.slot_ids) s;
 IF NEW.slot_ids IS DISTINCT FROM canonical
  OR (SELECT count(DISTINCT s) FROM unnest(NEW.public_sessions) s) <> cardinality(NEW.public_sessions)
  OR array_position(NEW.slot_ids,NULL::uuid) IS NOT NULL OR array_position(NEW.public_sessions,NULL::uuid) IS NOT NULL
  OR array_position(NEW.slot_ids,'00000000-0000-0000-0000-000000000000'::uuid) IS NOT NULL
  OR array_position(NEW.public_sessions,'00000000-0000-0000-0000-000000000000'::uuid) IS NOT NULL
  OR EXISTS (SELECT 1 FROM unnest(NEW.config_sha256s) s WHERE s IS NULL OR s !~ '^[0-9a-f]{64}$') THEN
  RAISE EXCEPTION 'invalid public edge roster' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_runtime_upgrade_public_edge_withdrawal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_withdrawal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP <> 'INSERT' THEN
  RAISE EXCEPTION 'immutable public edge withdrawal' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton FOR SHARE;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton FOR SHARE;
 IF EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_rosters r JOIN runtime_upgrade_public_edge_roster_head h ON h.revision=r.revision WHERE NEW.public_session_id=ANY(r.public_sessions))
  OR NOT EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_rosters r WHERE r.revision=NEW.roster_revision
   AND r.public_sessions[array_position(r.slot_ids,NEW.slot_id)]=NEW.public_session_id
   AND r.config_sha256s[array_position(r.slot_ids,NEW.slot_id)]=NEW.config_sha256) THEN
  RAISE EXCEPTION 'withdrawal requires exact previously reviewed absent process' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_public_edge_withdrawal_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_withdrawal_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE withdrawn runtime_upgrade_public_edge_withdrawals;
BEGIN
 IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'immutable public edge withdrawal receipt' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton FOR SHARE;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton FOR SHARE;
 SELECT * INTO withdrawn FROM runtime_upgrade_public_edge_withdrawals WHERE id=NEW.withdrawal_id FOR UPDATE;
 IF NOT FOUND OR NEW.observed_at < withdrawn.created_at OR NEW.observed_at > clock_timestamp()
  OR EXISTS(SELECT 1 FROM runtime_upgrade_external_fence_receipts WHERE withdrawal_id=NEW.withdrawal_id)
  OR EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_rosters r JOIN runtime_upgrade_public_edge_roster_head h ON h.revision=r.revision WHERE withdrawn.public_session_id=ANY(r.public_sessions)) THEN
  RAISE EXCEPTION 'withdrawal receipt requires an absent unresolved process and current clock' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM deployment_runtime_upgrade_targets WHERE deployment_id = OLD.id) AND
  ROW(NEW.app_id, NEW.source_sha256, NEW.source_root, NEW.source_bytes, NEW.kind, NEW.handler)
  IS DISTINCT FROM ROW(OLD.app_id, OLD.source_sha256, OLD.source_root, OLD.source_bytes, OLD.kind, OLD.handler) THEN
  RAISE EXCEPTION 'runtime upgrade source is immutable' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_runtime_upgrade_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP = 'DELETE' THEN
  IF EXISTS(SELECT 1 FROM deployments WHERE id = OLD.deployment_id) THEN
   RAISE EXCEPTION 'runtime upgrade target is immutable' USING ERRCODE = '23514';
  END IF;
  RETURN OLD;
 END IF;
 IF NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'runtime upgrade target is immutable' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_runtime_upgrade_verification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_verification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE canonical uuid[];
BEGIN
 SELECT array_agg(DISTINCT s ORDER BY s) INTO canonical FROM unnest(NEW.gateway_sessions) s;
 IF NEW.gateway_sessions IS DISTINCT FROM canonical OR array_position(NEW.gateway_sessions,NULL::uuid) IS NOT NULL
  OR array_position(NEW.gateway_sessions,'00000000-0000-0000-0000-000000000000'::uuid) IS NOT NULL THEN
  RAISE EXCEPTION 'invalid runtime upgrade verification participants' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
  PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton FOR SHARE;
  IF NEW.gateway_roster_revision IS NULL OR NOT EXISTS (
   SELECT 1 FROM runtime_upgrade_gateway_rosters r JOIN runtime_upgrade_gateway_roster_head h ON h.revision=r.revision
   WHERE r.revision=NEW.gateway_roster_revision AND NEW.gateway_sessions=(SELECT array_agg(s ORDER BY s) FROM unnest(r.gateway_sessions) s)) THEN
   RAISE EXCEPTION 'runtime upgrade verification requires full current gateway roster' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM runtime_upgrade_operations o JOIN deployment_runtime_upgrade_cutovers c ON c.deployment_id=o.deployment_id
   WHERE o.id=NEW.operation_id AND o.phase='complete' AND c.cutover_at=NEW.cutover_at AND c.serving_deployment_id=o.serving_deployment_id
   AND c.target_release_id=o.target_release_id AND c.wake_id=o.wake_id AND c.qualification_report_sha256=o.qualification_report_sha256) THEN
   RAISE EXCEPTION 'runtime upgrade verification requires matching activation' USING ERRCODE='23514';
  END IF;
 ELSIF (NEW.operation_id,NEW.gateway_sessions,NEW.gateway_roster_revision,NEW.cutover_at,NEW.created_at,NEW.deadline_at)
   IS DISTINCT FROM (OLD.operation_id,OLD.gateway_sessions,OLD.gateway_roster_revision,OLD.cutover_at,OLD.created_at,OLD.deadline_at)
   OR (OLD.phase<>'pending' AND NEW IS DISTINCT FROM OLD) THEN
  RAISE EXCEPTION 'immutable runtime upgrade verification' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_scoped_queue_binding_work(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_scoped_queue_binding_work() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE scope text; environment uuid;
BEGIN
  IF NEW.source='queue' AND NEW.queue_binding_id IS NOT NULL AND (TG_OP='INSERT'
    OR (NEW.state='dispatching' AND OLD.state IS DISTINCT FROM 'dispatching')) THEN
    SELECT b.deployment_scope,b.environment_id INTO scope,environment FROM queue_bindings b
      WHERE b.id=NEW.queue_binding_id AND b.app_id=NEW.app_id AND b.account_id=NEW.account_id FOR SHARE;
    IF scope<>'' THEN
      IF scope IS DISTINCT FROM NEW.deployment_scope THEN
        RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_queue_binding_tenant',
          MESSAGE='queue binding must retain the admitted environment';
      END IF;
      PERFORM 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
        WHERE a.id=NEW.app_id AND e.id=environment AND e.slug=scope FOR SHARE OF a,e;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_binding_environment_unavailable',
          MESSAGE='captured queue binding environment is unavailable';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_scoped_queue_consumer_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_scoped_queue_consumer_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM triggers t WHERE t.id=NEW.trigger_id AND t.queue_binding_scope<>'')
    AND NOT EXISTS (SELECT 1 FROM triggers t JOIN invocations i ON i.id::text=NEW.item_identifier
      AND i.app_id=t.app_id AND i.account_id=t.account_id AND i.source='queue'
      AND i.queue_binding_id=t.queue_binding_id AND i.deployment_scope=t.queue_binding_scope
      WHERE t.id=NEW.trigger_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_consumer_receipt_scope',
      MESSAGE='scoped consumer receipt requires work captured for its binding';
  END IF;
  IF NEW.state='claimed' AND (TG_OP='INSERT' OR OLD.state IS DISTINCT FROM 'claimed'
    OR NEW.claim_generation IS DISTINCT FROM OLD.claim_generation) AND EXISTS (
      SELECT 1 FROM triggers t WHERE t.id=NEW.trigger_id AND t.queue_binding_scope<>'') THEN
    PERFORM 1 FROM triggers t JOIN apps a ON a.id=t.app_id JOIN project_environments e
        ON e.project_id=a.project_id AND e.account_id=a.account_id AND e.id=t.queue_binding_environment_id
        AND e.slug=t.queue_binding_scope WHERE t.id=NEW.trigger_id FOR SHARE OF a,e;
    IF NOT FOUND THEN RETURN NULL; END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_sidecar_layer_artifact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_sidecar_layer_artifact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM require_retained_layer_artifact(NEW.storage_key);
    RETURN NEW;
END;
$$;


--
-- Name: guard_snapshot_layer_artifacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_snapshot_layer_artifacts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT NEW.stale THEN
        PERFORM require_deployment_layer_artifacts(NEW.deployment_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_source_migration_admissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_source_migration_admissions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF (TG_OP='DELETE' OR NEW.lease_token IS DISTINCT FROM OLD.lease_token) AND EXISTS(SELECT 1 FROM migration_admissions WHERE instance_id=OLD.instance_id AND lease_token=OLD.lease_token AND phase NOT IN ('cleaned','committed')) THEN
  RAISE EXCEPTION 'source lease has unresolved incoming migrations' USING ERRCODE='23514',CONSTRAINT='migration_admission_current';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF NEW.lease_token IS DISTINCT FROM OLD.lease_token THEN NEW.resume_fenced=false; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_source_migration_lease_node(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_source_migration_lease_node() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE n compute_nodes%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM migration_sources WHERE lease_token=OLD.lease_token) AND (
  (NEW.lease_token,NEW.instance_id,NEW.source_node_id) IS DISTINCT FROM (OLD.lease_token,OLD.instance_id,OLD.source_node_id)
  OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NOT OLD.pending AND NEW.pending
  OR OLD.mem_storage_key<>'' AND NEW.mem_storage_key<>OLD.mem_storage_key
  OR OLD.vmstate_storage_key<>'' AND NEW.vmstate_storage_key<>OLD.vmstate_storage_key
 ) THEN RAISE EXCEPTION 'source lease identity and cleanup handles must be retained' USING ERRCODE='23514',CONSTRAINT='migration_source_current'; END IF;
 IF NEW.source_node_id<>'' THEN
  SELECT * INTO n FROM compute_nodes WHERE id::text=NEW.source_node_id FOR SHARE;
  IF NOT FOUND OR n.lifecycle IN ('maintenance','retired') THEN
   RAISE EXCEPTION 'migration source node is closed' USING ERRCODE='23514',CONSTRAINT='migration_source_current';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_worker_admission_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_worker_admission_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (OLD.mode = 'worker' OR NEW.mode = 'worker') AND OLD.mode IS DISTINCT FROM NEW.mode THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'instances_worker_admission_identity',
      MESSAGE = 'worker mode is immutable; create a reserved instance';
  END IF;
  IF NEW.mode = 'worker'
     AND OLD.state NOT IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm','frozen')
     AND NEW.state IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm','frozen') THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'instances_worker_admission_identity',
      MESSAGE = 'worker residency requires a newly reserved instance';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_workflow_code_pin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_workflow_code_pin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='UPDATE' THEN
        IF NEW.deployment_id IS DISTINCT FROM OLD.deployment_id OR NEW.app_id IS DISTINCT FROM OLD.app_id THEN
            RAISE EXCEPTION 'workflow deployment is immutable' USING ERRCODE='23514', CONSTRAINT='workflow_code_immutable';
        END IF;
    ELSE
        PERFORM pin_workflow_code(NEW.app_id,NEW.deployment_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_workflow_event_code_pins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_workflow_event_code_pins() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE recipient jsonb;
BEGIN
    DELETE FROM workflow_event_code_refs WHERE outbox_id=NEW.id;
    FOR recipient IN SELECT r FROM jsonb_array_elements(NEW.recipient_snapshot) r
        WHERE r ? 'workflow' AND coalesce(r->>'deployment_id','')<>'' ORDER BY r->>'app_id',r->>'deployment_id'
    LOOP
        IF NOT EXISTS(SELECT 1 FROM apps a WHERE a.id::text=recipient->>'app_id'
            AND a.account_id=NEW.account_id AND a.account_id::text=recipient->>'account_id') THEN
            RAISE EXCEPTION 'workflow event owner is unavailable' USING ERRCODE='23514', CONSTRAINT='workflow_code_available';
        END IF;
        PERFORM pin_workflow_code((recipient->>'app_id')::uuid,(recipient->>'deployment_id')::uuid);
        INSERT INTO workflow_event_code_refs(outbox_id,deployment_id,app_id)
        VALUES(NEW.id,(recipient->>'deployment_id')::uuid,(recipient->>'app_id')::uuid) ON CONFLICT DO NOTHING;
    END LOOP;
    RETURN NEW;
END;
$$;


--
-- Name: guard_workflow_webhook_routing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_workflow_webhook_routing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE endpoint uuid;
BEGIN
    IF TG_TABLE_NAME = 'exclusive_work_trigger_bindings' THEN
        IF NEW.source <> 'inbound_webhook' THEN RETURN NEW; END IF;
        endpoint := NEW.trigger_id;
    ELSE
        endpoint := NEW.endpoint_id;
    END IF;
    PERFORM 1 FROM inbound_webhook_endpoints WHERE id = endpoint FOR UPDATE;
    IF TG_TABLE_NAME = 'workflow_webhook_bindings' THEN
        IF EXISTS (SELECT 1 FROM workflow_callback_webhook_bindings WHERE endpoint_id = endpoint)
           OR EXISTS (SELECT 1 FROM exclusive_work_trigger_bindings WHERE source = 'inbound_webhook' AND trigger_id = endpoint)
           OR EXISTS (SELECT 1 FROM customer_operation_webhook_bindings WHERE endpoint_id = endpoint) THEN
            RAISE EXCEPTION 'endpoint already has a callback or operation binding' USING ERRCODE = '23505';
        END IF;
    ELSIF EXISTS (SELECT 1 FROM workflow_webhook_bindings WHERE endpoint_id = endpoint) THEN
        RAISE EXCEPTION 'endpoint already starts an automation' USING ERRCODE = '23505';
    ELSIF TG_TABLE_NAME = 'exclusive_work_trigger_bindings'
          AND EXISTS (SELECT 1 FROM customer_operation_webhook_bindings WHERE endpoint_id = endpoint) THEN
        RAISE EXCEPTION 'endpoint already starts a customer operation' USING ERRCODE = '23505';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_workload_retirement_source_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_workload_retirement_source_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM environment_workload_retirements r WHERE r.source_id=OLD.id AND r.phase NOT IN ('recovered','cancelled')) AND
  EXISTS(SELECT 1 FROM accounts WHERE id=OLD.account_id AND status<>'deleted_pending') THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'retained workloads must recover before detaching their source' USING ERRCODE='23514'; END IF;
  IF NEW.detached OR NEW.mode<>'enforce' OR ROW(NEW.account_id,NEW.project_id,NEW.environment_id,NEW.provider,NEW.repository_id,NEW.repository,NEW.installation_id)
   IS DISTINCT FROM ROW(OLD.account_id,OLD.project_id,OLD.environment_id,OLD.provider,OLD.repository_id,OLD.repository,OLD.installation_id) THEN
   RAISE EXCEPTION 'retained workloads must recover before changing their source identity' USING ERRCODE='23514';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;RETURN NEW;
END $$;


--
-- Name: image_preparation_phase_timing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.image_preparation_phase_timing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.phase_started_at := clock_timestamp();
    ELSIF NEW.phase IS DISTINCT FROM OLD.phase THEN
        NEW.phase_started_at := clock_timestamp();
    ELSE
        NEW.phase_started_at := OLD.phase_started_at;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: initialize_clone_configuration_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.initialize_clone_configuration_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO project_environment_clone_configuration_guards(project_id, account_id)
    VALUES (NEW.id, NEW.account_id)
    ON CONFLICT (project_id) DO UPDATE SET account_id = EXCLUDED.account_id,
        generation = project_environment_clone_configuration_guards.generation + 1
    WHERE project_environment_clone_configuration_guards.state = 'open';
    RETURN NEW;
END;
$$;


--
-- Name: instance_node_admission_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.instance_node_admission_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE current_lifecycle compute_node_lifecycle;
BEGIN
 IF NEW.state NOT IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm','frozen') THEN
  RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND NEW.node_id IS NOT DISTINCT FROM OLD.node_id
  AND OLD.state IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm','frozen') THEN
  RETURN NEW;
 END IF;
 SELECT lifecycle INTO current_lifecycle FROM compute_nodes WHERE id=NEW.node_id FOR SHARE;
 IF NOT FOUND OR current_lifecycle NOT IN ('active','recovering') THEN
  RAISE EXCEPTION 'node is not admitting resident work' USING ERRCODE='23514',CONSTRAINT='instance_node_admission_current';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: instance_readiness_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.instance_readiness_notify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.kind IN ('wake.sidecar_health', 'wake.app_readiness')
       AND NEW.data->>'status' IN ('ready', 'unready')
       AND coalesce(NEW.data->>'app_id', '') <> ''
       AND coalesce(NEW.data->>'instance_id', '') <> '' THEN
        PERFORM pg_notify('instance_readiness_changed', json_build_object(
            'app_id', NEW.data->>'app_id',
            'instance_id', NEW.data->>'instance_id',
            'source', CASE
                WHEN NEW.kind = 'wake.app_readiness' THEN 'primary_app'
                ELSE 'sidecar:' || coalesce(NEW.data->>'sidecar_name', '')
            END,
            'status', NEW.data->>'status',
            'at', NEW.at,
            'event_id', NEW.id
        )::text);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: instances_started_at_set(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.instances_started_at_set() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.started_at is null then
    new.started_at = now();
  end if;
  return new;
end
$$;


--
-- Name: invalidate_lifecycle_project_successors(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_lifecycle_project_successors() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 -- A generation change is permanent, even if the old graph is reactivated.
 -- Include retained receipts so neither rollback nor restore revives them.
 UPDATE route_lifecycle_approvals r SET invalidated_at=clock_timestamp()
 WHERE r.invalidated_at IS NULL AND r.successor_snapshot IS DISTINCT FROM lifecycle_approval_successor_bindings(r.app_id,r.receipt);
 RETURN NULL;
END $$;


--
-- Name: invalidate_lifecycle_successor_routes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_lifecycle_successor_routes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE oldrow jsonb; newrow jsonb; affected uuid; owner uuid; hostname text;
 watched text[] := ARRAY['status','slug','manifest','visibility','org_id','project_id','account_id',
                         'only_declared_routes','declared_routes','consumer_auth_mode','maintenance_mode'];
BEGIN
 IF TG_OP<>'INSERT' THEN oldrow:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN newrow:=to_jsonb(NEW); END IF;
 IF TG_TABLE_NAME='tenant_hostnames' THEN
  UPDATE route_lifecycle_approvals r SET invalidated_at=clock_timestamp() WHERE r.invalidated_at IS NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(r.receipt->'mappings') m WHERE split_part(m->>'successor_url','/',3) IN (oldrow->>'hostname',newrow->>'hostname'));
  RETURN NULL;
 END IF;
 IF TG_TABLE_NAME='apps' AND TG_OP='UPDATE' AND
    (SELECT jsonb_object_agg(k, CASE WHEN k='status' AND v #>> '{}' IN ('active','evicted_cold') THEN '"scale_to_zero"'::jsonb ELSE v END)
       FROM jsonb_each(oldrow) e(k,v) WHERE k=ANY(watched))
    IS NOT DISTINCT FROM
    (SELECT jsonb_object_agg(k, CASE WHEN k='status' AND v #>> '{}' IN ('active','evicted_cold') THEN '"scale_to_zero"'::jsonb ELSE v END)
       FROM jsonb_each(newrow) e(k,v) WHERE k=ANY(watched)) THEN
  RETURN NULL;
 END IF;
 FOR affected IN SELECT DISTINCT id FROM (VALUES(coalesce(oldrow->>'app_id',CASE WHEN TG_TABLE_NAME='apps' THEN oldrow->>'id' END)::uuid),(coalesce(newrow->>'app_id',CASE WHEN TG_TABLE_NAME='apps' THEN newrow->>'id' END)::uuid)) ids(id) WHERE id IS NOT NULL LOOP
  SELECT account_id INTO owner FROM apps WHERE id=affected;
  PERFORM 1 FROM accounts WHERE id=owner FOR NO KEY UPDATE;
  UPDATE route_lifecycle_approvals r SET invalidated_at=clock_timestamp() WHERE r.invalidated_at IS NULL AND
   ((TG_TABLE_NAME<>'deployments' AND r.app_id=affected) OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.receipt->'mappings') m WHERE m->>'successor_app_id'=affected::text AND (TG_TABLE_NAME<>'deployments' OR affected<>r.app_id)));
 END LOOP;
 RETURN NULL;
END $$;


--
-- Name: invalidate_object_usage_on_adoption(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_object_usage_on_adoption() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.resource_ownership_enabled AND (TG_OP='INSERT' OR NOT OLD.resource_ownership_enabled) THEN
  IF NEW.object_storage_owned_from IS NULL THEN
   UPDATE orgs SET object_storage_owned_from=now() WHERE id=NEW.id;
  END IF;
  IF EXISTS(SELECT 1 FROM object_storage_billing_periods p WHERE p.period_start>=date_trunc('month',now())
    AND EXISTS(SELECT 1 FROM object_buckets b WHERE b.org_id=NEW.id AND b.account_id=p.account_id)) THEN
   RAISE EXCEPTION 'remediate finalized current-period object billing before adoption' USING ERRCODE='23514';
  END IF;
  DELETE FROM object_storage_usage_heads h WHERE h.period_start>=date_trunc('month',now()) AND
   (h.account_id=NEW.id OR EXISTS(SELECT 1 FROM object_buckets b WHERE b.org_id=NEW.id AND b.account_id=h.account_id));
 END IF;
 RETURN NEW;
END $$;


--
-- Name: invalidate_route_lifecycle_approvals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_route_lifecycle_approvals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 UPDATE route_lifecycle_approvals r SET invalidated_at=clock_timestamp()
 WHERE r.invalidated_at IS NULL AND ((r.app_id=OLD.app_id AND (r.baseline_deployment_id=OLD.deployment_id OR r.candidate_deployment_id=OLD.deployment_id)) OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.receipt->'mappings') m WHERE m->>'successor_deployment_id'=OLD.deployment_id::text));
 RETURN NULL;
END $$;


--
-- Name: invocation_async_subject(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invocation_async_subject(app uuid, namespace uuid) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN NOT o.personal_org AND o.resource_ownership_enabled THEN o.id ELSE a.account_id END
 FROM apps a JOIN orgs o ON o.id=a.org_id WHERE a.id=app AND a.account_id=namespace;
$$;


--
-- Name: invocation_done_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invocation_done_notify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    payload jsonb;
begin
    if (tg_op = 'UPDATE' and old.state in ('pending','dispatching')
        and new.state in ('completed','failed','cancelled')) then
        payload := jsonb_build_object(
            'invocation_id', new.id::text,
            'app_id', new.app_id::text,
            'source', new.source,
            'state', new.state
        );
        perform pg_notify('invocation_done', payload::text);
    end if;
    return new;
end;
$$;


