--
-- Name: issue_tracker_inbound_bump(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_tracker_inbound_bump() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target uuid;
 source_change boolean;
BEGIN
 IF TG_TABLE_NAME = 'apps' THEN
  target := NEW.id;
 ELSIF TG_TABLE_NAME = 'issue_tracker_links' THEN
  IF TG_OP = 'DELETE' THEN
   SELECT app_id INTO target FROM app_issues WHERE id=OLD.issue_id;
  ELSE
   SELECT app_id INTO target FROM app_issues WHERE id=NEW.issue_id;
  END IF;
 ELSIF TG_OP = 'DELETE' THEN
  target := OLD.app_id;
 ELSE
  target := NEW.app_id;
 END IF;
 source_change := TG_TABLE_NAME IN ('apps','issue_tracker_linear_connections');
 INSERT INTO issue_tracker_inbound_guards(app_id) SELECT target WHERE EXISTS(SELECT 1 FROM apps WHERE id=target)
 ON CONFLICT(app_id) DO UPDATE SET revision=issue_tracker_inbound_guards.revision+1,
 source_revision=CASE WHEN source_change THEN nextval('issue_tracker_source_revision_seq') ELSE issue_tracker_inbound_guards.source_revision END;
 IF TG_TABLE_NAME='app_issues' THEN
  IF TG_OP<>'DELETE' THEN PERFORM issue_tracker_source_bump(NEW.id); END IF;
 ELSIF TG_TABLE_NAME='issue_group_links' THEN
  IF TG_OP<>'INSERT' THEN
   PERFORM issue_tracker_source_bump(OLD.issue_id);
   PERFORM issue_tracker_source_bump(OLD.canonical_issue_id);
  END IF;
  IF TG_OP<>'DELETE' THEN
   PERFORM issue_tracker_source_bump(NEW.issue_id);
   PERFORM issue_tracker_source_bump(NEW.canonical_issue_id);
  END IF;
 ELSIF TG_TABLE_NAME='issue_split_rules' THEN
  IF TG_OP<>'INSERT' THEN
   PERFORM issue_tracker_source_bump(OLD.source_issue_id);
   PERFORM issue_tracker_source_bump(OLD.target_issue_id);
  END IF;
  IF TG_OP<>'DELETE' THEN
   PERFORM issue_tracker_source_bump(NEW.source_issue_id);
   PERFORM issue_tracker_source_bump(NEW.target_issue_id);
  END IF;
 ELSIF TG_TABLE_NAME='issue_tracker_links' THEN
  IF TG_OP<>'INSERT' THEN PERFORM issue_tracker_source_bump(OLD.issue_id); END IF;
  IF TG_OP<>'DELETE' THEN PERFORM issue_tracker_source_bump(NEW.issue_id); END IF;
 END IF;
 RETURN NULL;
END $$;


--
-- Name: issue_tracker_inbound_install_bump(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_tracker_inbound_install_bump() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 INSERT INTO issue_tracker_inbound_guards(app_id)
 SELECT id FROM apps WHERE
  (TG_OP <> 'INSERT' AND github_install_id=OLD.installation_id AND github_install_account_id=OLD.account_id) OR
  (TG_OP <> 'DELETE' AND github_install_id=NEW.installation_id AND github_install_account_id=NEW.account_id)
 ORDER BY id
 ON CONFLICT(app_id) DO UPDATE SET revision=issue_tracker_inbound_guards.revision+1,source_revision=nextval('issue_tracker_source_revision_seq');
 RETURN NULL;
END $$;


--
-- Name: issue_tracker_source_bump(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_tracker_source_bump(target uuid) RETURNS void
    LANGUAGE sql
    AS $$
 INSERT INTO issue_tracker_source_guards(issue_id) SELECT id FROM app_issues WHERE id=target
 ON CONFLICT(issue_id) DO UPDATE SET revision=nextval('issue_tracker_source_revision_seq');
$$;


--
-- Name: job_tasks_notify_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_tasks_notify_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    channel text;
    payload jsonb;
BEGIN
    IF TG_OP = 'INSERT' AND NEW.status = 'queued' THEN
        channel := 'job_tasks_queued';
        payload := jsonb_build_object(
            'v', 1,
            'op', TG_OP,
            'run_id', NEW.run_id,
            'task_index', NEW.task_index,
            'attempt', NEW.attempt
        );
    ELSIF TG_OP = 'UPDATE'
        AND OLD.status = 'queued' AND NEW.status = 'claimed' THEN
        channel := 'job_tasks_dispatched';
        payload := jsonb_build_object(
            'v', 1,
            'op', TG_OP,
            'run_id', NEW.run_id,
            'task_index', NEW.task_index,
            'attempt', NEW.attempt,
            'instance_id', NEW.instance_id,
            'lease_token', NEW.lease_token
        );
    ELSIF TG_OP = 'UPDATE'
        AND OLD.status IN ('queued', 'claimed')
        AND NEW.status IN ('succeeded', 'failed', 'timeout', 'cancelled', 'oom') THEN
        channel := 'job_tasks_terminal';
        payload := jsonb_build_object(
            'v', 1,
            'op', TG_OP,
            'run_id', NEW.run_id,
            'task_index', NEW.task_index,
            'attempt', NEW.attempt,
            'status', NEW.status,
            'exit_code', NEW.exit_code,
            'error_class', NEW.error_class,
            'finished_at', NEW.finished_at
        );
    ELSE
        RETURN NEW;
    END IF;

    PERFORM pg_notify(channel, payload::text);
    RETURN NEW;
END;
$$;


--
-- Name: keep_failed_rollback_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.keep_failed_rollback_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.status = 'failed' AND OLD.status = 'snapshotting' AND OLD.serving_ended_at IS NOT NULL THEN
  NEW.status := 'superseded';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: lifecycle_approval_successor_bindings(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_approval_successor_bindings(source uuid, receipt jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 SELECT lifecycle_successor_bindings(source,coalesce((SELECT jsonb_agg(m || jsonb_build_object('candidate_deployment_id',receipt->>'candidate_deployment_id')) FROM jsonb_array_elements(receipt->'mappings') m),'[]'::jsonb))
$$;


--
-- Name: lifecycle_configuration(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_configuration(app uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 SELECT jsonb_build_object('app',jsonb_build_object('id',a.id,'account',a.account_id,'slug',a.slug,
 'consumer_auth_mode',a.consumer_auth_mode,'maintenance_mode',a.maintenance_mode,
 'manifest',a.manifest,'ram_mb',a.ram_mb,'max_concurrency',a.max_concurrency,'idle_timeout_s',a.idle_timeout_s,'type',a.type,'cpu_millicores',a.cpu_millicores,'scaling_policy',a.scaling_policy,'request_rate_limit_rps',a.request_rate_limit_rps,'request_rate_limit_burst',a.request_rate_limit_burst),
 'account',jsonb_build_object('plan',c.plan,'status',c.status,'past_due_at',c.past_due_at,'abuse_hold_at',c.abuse_hold_at),
 'rules',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM edge_rules r WHERE r.app_id=a.id),'[]'::jsonb))
 FROM apps a JOIN app_resource_accounts c ON c.app_id=a.id WHERE a.id=app
$$;


--
-- Name: lifecycle_history_evidence(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_history_evidence(app uuid, deployment uuid, decision jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 WITH candidates AS (SELECT r.*,coalesce(decision->'lifecycle_approval_ids','[]'::jsonb) ? r.id::text used
 FROM route_lifecycle_approvals r WHERE r.app_id=app AND r.candidate_deployment_id=deployment),
 chosen AS (SELECT * FROM candidates ORDER BY used DESC,approved_at DESC,id DESC LIMIT 20),
 captures AS (
 SELECT d.deployment_id::text id,encode(d.doc_sha256,'hex') sha FROM deployment_openapi_docs d JOIN deployments dep ON dep.id=d.deployment_id
 WHERE d.app_id=app AND (dep.id=deployment OR (dep.status='live' AND dep.traffic_percent>0 AND coalesce(nullif(dep.scope,''),'default') IN ('default','prod','production')))
 UNION SELECT baseline_deployment_id::text,receipt->>'baseline_contract_sha256' FROM chosen
 UNION SELECT m->>'successor_deployment_id',m->>'successor_contract_sha256' FROM chosen,LATERAL jsonb_array_elements(receipt->'mappings') m WHERE nullif(m->>'successor_deployment_id','') IS NOT NULL)
 SELECT jsonb_build_object(
 'truncated',(SELECT count(*)>20 FROM candidates) OR (SELECT count(*)>64 FROM captures) OR EXISTS(SELECT 1 FROM chosen WHERE jsonb_array_length(coalesce(successor_snapshot,'[]'::jsonb))>64),
 'captures',coalesce((SELECT jsonb_agg(jsonb_build_object('deployment_id',id,'sha256',sha) ORDER BY id,sha) FROM (SELECT * FROM captures ORDER BY id,sha LIMIT 64) c),'[]'::jsonb),
 'graph_ids',coalesce((SELECT jsonb_agg(rs.id::text ORDER BY rs.id) FROM project_release_sets rs JOIN apps a ON a.project_id=rs.project_id AND a.account_id=rs.account_id WHERE a.id=app AND rs.active AND rs.environment_slug='production'),'[]'::jsonb),
 'approvals',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'used',used,'baseline_deployment_id',baseline_deployment_id,'candidate_deployment_id',candidate_deployment_id,'baseline_contract_sha256',receipt->>'baseline_contract_sha256','candidate_contract_sha256',receipt->>'candidate_contract_sha256','configuration_sha256',receipt->>'configuration_sha256','valid_until',valid_until,'graph_ids',lifecycle_history_graph_ids(successor_snapshot)) ORDER BY used DESC,approved_at DESC,id DESC) FROM chosen),'[]'::jsonb))
$$;


--
-- Name: lifecycle_history_graph_ids(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_history_graph_ids(snapshot jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 SELECT coalesce(jsonb_agg(id ORDER BY id),'[]'::jsonb) FROM (
 SELECT DISTINCT g->>'id' id FROM jsonb_array_elements(coalesce(snapshot,'[]'::jsonb)) b,
 LATERAL jsonb_array_elements(coalesce(nullif(b#>'{project,graphs}','null'::jsonb),'[]'::jsonb)) g
 WHERE g->>'id' IS NOT NULL ORDER BY id LIMIT 64) graphs
$$;


--
-- Name: lifecycle_project_successor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_project_successor(app uuid, deployment uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 SELECT jsonb_build_object('graphs',coalesce((SELECT jsonb_agg(to_jsonb(rs)||jsonb_build_object('members',coalesce((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.app_id) FROM project_release_members m WHERE m.release_id=rs.id),'[]'::jsonb)) ORDER BY rs.id) FROM project_release_sets rs WHERE rs.project_id=a.project_id AND rs.account_id=a.account_id AND rs.environment_slug='production' AND rs.active),'[]'::jsonb),
 'spec',(SELECT to_jsonb(s)||jsonb_build_object('settings_raw',s.settings::text,'environment',to_jsonb(e)) FROM project_environment_workload_deployment_specs p JOIN project_environment_workload_specs s ON s.id=p.spec_id JOIN project_environments e ON e.id=s.environment_id WHERE p.deployment_id=deployment AND s.app_id=a.id AND e.project_id=a.project_id AND e.account_id=a.account_id AND e.slug='production'),
 'live',EXISTS(SELECT 1 FROM deployments d WHERE d.id=deployment AND d.app_id=a.id AND d.status='live' AND d.scope='production'))
 FROM apps a WHERE a.id=app AND a.project_id IS NOT NULL
$$;


--
-- Name: lifecycle_successor_bindings(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_successor_bindings(source uuid, mappings jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 SELECT coalesce(jsonb_agg(item||jsonb_build_object('project',lifecycle_project_successor((item->>'app')::uuid,coalesce(nullif(item#>>'{mapping,successor_deployment_id}','')::uuid,nullif(item#>>'{mapping,candidate_deployment_id}','')::uuid))) ORDER BY item#>>'{mapping,method}',item#>>'{mapping,path}'),'[]'::jsonb)
 FROM jsonb_array_elements(lifecycle_successor_bindings_v736(source,mappings)) item
$$;


--
-- Name: lifecycle_successor_bindings_v736(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_successor_bindings_v736(source uuid, mappings jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('mapping',m,'app',a.id,'status',a.status,'visibility',a.visibility,'org_id',a.org_id,'project_id',a.project_id,'only_declared_routes',a.only_declared_routes,'declared_routes',a.declared_routes,
 'configuration',lifecycle_configuration(a.id),
 'domain', (SELECT jsonb_build_object('domain',d.domain,'app_id',d.app_id,'environment_id',d.environment_id,'verified_at',d.verified_at) FROM custom_domains d WHERE d.domain::text=split_part(split_part(m->>'successor_url','/',3),':',1)),
 'claimed',EXISTS(SELECT 1 FROM tenant_hostnames h WHERE h.hostname::text=split_part(split_part(m->>'successor_url','/',3),':',1)),
 'capture',(SELECT jsonb_build_object('sha',encode(c.doc_sha256,'hex'),'document_sha',encode(sha256(convert_to(c.doc::text,'UTF8')),'hex'),'truncated',c.truncated,'captured_at',c.captured_at,'updated_at',c.updated_at) FROM deployment_openapi_docs c WHERE c.deployment_id=coalesce(nullif(m->>'successor_deployment_id','')::uuid, nullif(m->>'candidate_deployment_id','')::uuid) AND c.app_id=a.id),
 'routes',CASE WHEN a.id=source THEN '[]'::jsonb ELSE coalesce((SELECT jsonb_agg(jsonb_build_object('id',d.id,'scope',d.scope,'status',d.status,'traffic',d.traffic_percent) ORDER BY d.id) FROM deployments d WHERE d.app_id=a.id AND d.status='live' AND d.traffic_percent>0 AND coalesce(nullif(d.scope,''),'default') IN ('default','prod','production')),'[]'::jsonb) END) ORDER BY m->>'method',m->>'path'),'[]'::jsonb)
 FROM jsonb_array_elements(mappings) m LEFT JOIN apps a ON a.id=coalesce(nullif(m->>'successor_app_id','')::uuid,source)
$$;


--
-- Name: lifecycle_traffic_inputs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_traffic_inputs(app uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 SELECT jsonb_build_object('configuration',lifecycle_configuration(app),
 'gate',coalesce((SELECT to_jsonb(g) FROM canary_route_gates g WHERE g.app_id=app),'{}'::jsonb),
 'requirements',coalesce((SELECT to_jsonb(s) FROM saved_route_requirements s WHERE s.app_id=app),'{}'::jsonb),
 'removal',coalesce((SELECT to_jsonb(p)-'baseline_since'-'baseline_deployment_id' FROM app_route_removal_policies p WHERE p.app_id=app),'{}'::jsonb),
 'captures',coalesce((SELECT jsonb_agg(jsonb_build_object('id',d.deployment_id,'sha',encode(d.doc_sha256,'hex'),'document_sha',encode(sha256(convert_to(d.doc::text,'UTF8')),'hex'),'truncated',d.truncated,'captured_at',d.captured_at,'updated_at',d.updated_at) ORDER BY d.deployment_id) FROM deployment_openapi_docs d WHERE d.app_id=app),'[]'::jsonb))
$$;


--
-- Name: accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email public.citext NOT NULL,
    plan text DEFAULT 'free'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    provider_customer_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    deletion_requested_at timestamp with time zone,
    stripe_subscription_item text,
    last_quota_warning_at timestamp with time zone,
    past_due_at timestamp with time zone,
    mfa_enrolled_at timestamp with time zone,
    mfa_secret_encrypted bytea,
    mfa_recovery_codes_hash bytea[],
    mfa_required boolean DEFAULT false NOT NULL,
    overage_cap_cents bigint,
    key_grace_window_days integer,
    egress_allowlist_extra integer DEFAULT 0 NOT NULL,
    email_verified_at timestamp with time zone,
    business_name text,
    billing_address text,
    tax_id text,
    suspended_reason text,
    abuse_hold_at timestamp with time zone,
    abuse_hold_reason text,
    password_reset_revision bigint DEFAULT 1 NOT NULL,
    mfa_revision bigint DEFAULT 1 NOT NULL,
    billing_mail_revision bigint DEFAULT 1 NOT NULL,
    quota_mail_revision bigint DEFAULT 1 NOT NULL,
    subscription_mail_revision bigint DEFAULT 1 NOT NULL,
    deployment_mail_revision bigint DEFAULT 1 NOT NULL,
    CONSTRAINT accounts_abuse_hold_valid CHECK ((((abuse_hold_at IS NULL) = (abuse_hold_reason IS NULL)) AND ((abuse_hold_reason IS NULL) OR (abuse_hold_reason = ANY (ARRAY['egress_fanout'::text, 'egress_flood'::text, 'operator'::text]))))),
    CONSTRAINT accounts_billing_address_length_chk CHECK (((billing_address IS NULL) OR ((char_length(billing_address) >= 1) AND (char_length(billing_address) <= 1000)))),
    CONSTRAINT accounts_billing_mail_revision_check CHECK ((billing_mail_revision > 0)),
    CONSTRAINT accounts_business_name_length_chk CHECK (((business_name IS NULL) OR ((char_length(business_name) >= 1) AND (char_length(business_name) <= 256)))),
    CONSTRAINT accounts_deployment_mail_revision_check CHECK ((deployment_mail_revision > 0)),
    CONSTRAINT accounts_egress_allowlist_extra_check CHECK ((egress_allowlist_extra >= 0)),
    CONSTRAINT accounts_key_grace_window_days_check CHECK (((key_grace_window_days IS NULL) OR (key_grace_window_days >= 0))),
    CONSTRAINT accounts_mfa_enrolled_shape_chk CHECK (((mfa_enrolled_at IS NULL) OR ((mfa_secret_encrypted IS NOT NULL) AND ((mfa_recovery_codes_hash IS NULL) OR (array_length(mfa_recovery_codes_hash, 1) >= 0))))),
    CONSTRAINT accounts_mfa_revision_check CHECK ((mfa_revision > 0)),
    CONSTRAINT accounts_overage_cap_cents_chk CHECK (((overage_cap_cents IS NULL) OR (overage_cap_cents >= 0))),
    CONSTRAINT accounts_password_reset_revision_check CHECK ((password_reset_revision > 0)),
    CONSTRAINT accounts_plan_check CHECK ((plan = ANY (ARRAY['free'::text, 'hobby'::text, 'pro'::text, 'scale'::text]))),
    CONSTRAINT accounts_quota_mail_revision_check CHECK ((quota_mail_revision > 0)),
    CONSTRAINT accounts_status_check CHECK ((status = ANY (ARRAY['active'::text, 'past_due'::text, 'suspended'::text, 'deleted_pending'::text]))),
    CONSTRAINT accounts_subscription_mail_revision_check CHECK ((subscription_mail_revision > 0)),
    CONSTRAINT accounts_suspended_reason_check CHECK (((suspended_reason IS NULL) OR ((suspended_reason = 'free_quota'::text) AND (status = 'suspended'::text)))),
    CONSTRAINT accounts_tax_id_length_chk CHECK (((tax_id IS NULL) OR ((char_length(tax_id) >= 1) AND (char_length(tax_id) <= 128))))
);


--
-- Name: orgs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.orgs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    personal_org boolean DEFAULT false NOT NULL,
    personal_owner_account_id uuid,
    plan text DEFAULT 'free'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    provider_customer_id text,
    stripe_subscription_item text,
    deleted_pending boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resource_ownership_enabled boolean DEFAULT false NOT NULL,
    past_due_at timestamp with time zone,
    last_quota_warning_at timestamp with time zone,
    suspended_reason text,
    abuse_hold_at timestamp with time zone,
    abuse_hold_reason text,
    billing_email text DEFAULT ''::text NOT NULL,
    business_name text DEFAULT ''::text NOT NULL,
    billing_address text DEFAULT ''::text NOT NULL,
    tax_id text DEFAULT ''::text NOT NULL,
    object_storage_owned_from timestamp with time zone,
    CONSTRAINT org_object_storage_owned_from_finite CHECK (((object_storage_owned_from IS NULL) OR isfinite(object_storage_owned_from))),
    CONSTRAINT orgs_personal_owner_link CHECK ((((personal_org = true) AND (personal_owner_account_id IS NOT NULL)) OR ((personal_org = false) AND (personal_owner_account_id IS NULL)))),
    CONSTRAINT orgs_plan_chk CHECK ((plan = ANY (ARRAY['free'::text, 'hobby'::text, 'pro'::text, 'scale'::text]))),
    CONSTRAINT orgs_slug_shape CHECK ((slug ~ '^[a-z0-9][a-z0-9-]{1,30}[a-z0-9]$'::text)),
    CONSTRAINT orgs_status_chk CHECK ((status = ANY (ARRAY['active'::text, 'past_due'::text, 'suspended'::text, 'deleted_pending'::text]))),
    CONSTRAINT orgs_suspended_reason_check CHECK (((suspended_reason IS NULL) OR (suspended_reason = 'free_quota'::text)))
);


--
-- Name: app_resource_accounts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.app_resource_accounts AS
 SELECT a.id AS app_id,
    a.account_id AS id,
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN o.past_due_at
            ELSE ac.past_due_at
        END AS past_due_at,
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN NULL::timestamp with time zone
            ELSE ac.deletion_requested_at
        END AS deletion_requested_at,
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN o.last_quota_warning_at
            ELSE ac.last_quota_warning_at
        END AS last_quota_warning_at,
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN o.suspended_reason
            ELSE ac.suspended_reason
        END AS suspended_reason,
    COALESCE(
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN o.plan
            ELSE ac.plan
        END, ''::text) AS plan,
    COALESCE(
        CASE
            WHEN ((o.personal_org = false) AND (o.resource_ownership_enabled OR (o.status <> ALL (ARRAY['active'::text, 'past_due'::text])) OR o.deleted_pending)) THEN
            CASE
                WHEN o.deleted_pending THEN 'deleted_pending'::text
                ELSE o.status
            END
            ELSE ac.status
        END, ''::text) AS status,
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN o.abuse_hold_at
            ELSE ac.abuse_hold_at
        END AS abuse_hold_at,
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN o.abuse_hold_reason
            ELSE ac.abuse_hold_reason
        END AS abuse_hold_reason,
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN 0
            ELSE ac.egress_allowlist_extra
        END AS egress_allowlist_extra,
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN o.created_at
            ELSE ac.created_at
        END AS created_at,
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN o.billing_email
            ELSE (ac.email)::text
        END AS email,
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN o.provider_customer_id
            ELSE ac.provider_customer_id
        END AS provider_customer_id,
        CASE
            WHEN ((o.personal_org = false) AND o.resource_ownership_enabled) THEN o.stripe_subscription_item
            ELSE ac.stripe_subscription_item
        END AS stripe_subscription_item
   FROM ((public.apps a
     LEFT JOIN public.orgs o ON ((o.id = a.org_id)))
     LEFT JOIN public.accounts ac ON ((ac.id = a.account_id)));


--
-- Name: lock_app_resource_account(uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_app_resource_account(application_id uuid, exclusive_lock boolean, fail_fast boolean) RETURNS SETOF public.app_resource_accounts
    LANGUAGE plpgsql
    AS $$
DECLARE target_org uuid; target_namespace uuid; legacy_owner boolean;
BEGIN
 SELECT org_id,account_id INTO target_org,target_namespace FROM apps WHERE id=application_id;
 IF NOT FOUND THEN RETURN; END IF;
 IF exclusive_lock AND fail_fast THEN
  SELECT personal_org OR NOT resource_ownership_enabled INTO legacy_owner FROM orgs WHERE id=target_org FOR UPDATE NOWAIT;
 ELSIF exclusive_lock THEN
  SELECT personal_org OR NOT resource_ownership_enabled INTO legacy_owner FROM orgs WHERE id=target_org FOR UPDATE;
 ELSIF fail_fast THEN
  SELECT personal_org OR NOT resource_ownership_enabled INTO legacy_owner FROM orgs WHERE id=target_org FOR SHARE NOWAIT;
 ELSE
  SELECT personal_org OR NOT resource_ownership_enabled INTO legacy_owner FROM orgs WHERE id=target_org FOR SHARE;
 END IF;
 IF NOT FOUND THEN RETURN; END IF;
 IF legacy_owner THEN
  IF exclusive_lock AND fail_fast THEN
   PERFORM id FROM accounts WHERE id=target_namespace FOR UPDATE NOWAIT;
  ELSIF exclusive_lock THEN
   PERFORM id FROM accounts WHERE id=target_namespace FOR UPDATE;
  ELSIF fail_fast THEN
   PERFORM id FROM accounts WHERE id=target_namespace FOR SHARE NOWAIT;
  ELSE
   PERFORM id FROM accounts WHERE id=target_namespace FOR SHARE;
  END IF;
  IF NOT FOUND THEN RETURN; END IF;
 END IF;
 IF exclusive_lock AND fail_fast THEN
  PERFORM id FROM apps WHERE id=application_id AND org_id=target_org AND account_id=target_namespace FOR UPDATE NOWAIT;
 ELSIF exclusive_lock THEN
  PERFORM id FROM apps WHERE id=application_id AND org_id=target_org AND account_id=target_namespace FOR UPDATE;
 ELSIF fail_fast THEN
  PERFORM id FROM apps WHERE id=application_id AND org_id=target_org AND account_id=target_namespace FOR SHARE NOWAIT;
 ELSE
  PERFORM id FROM apps WHERE id=application_id AND org_id=target_org AND account_id=target_namespace FOR SHARE;
 END IF;
 IF NOT FOUND THEN RETURN; END IF;
 RETURN QUERY SELECT * FROM app_resource_accounts WHERE app_id=application_id;
END $$;


--
-- Name: lock_build_export_publication(jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_build_export_publication(input jsonb, publisher text, fresh boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE c jsonb:=input->'claims';a apps%ROWTYPE;d deployments%ROWTYPE;b builds%ROWTYPE;p build_provenance%ROWTYPE;key_der bytea;
BEGIN
 SELECT * INTO d FROM deployments WHERE id=(c->>'deployment_id')::uuid FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'build export owner missing' USING ERRCODE='23514',CONSTRAINT='build_export_publication_missing';END IF;
 SELECT * INTO a FROM apps WHERE id=(c->>'app_id')::uuid FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'build export owner missing' USING ERRCODE='23514',CONSTRAINT='build_export_publication_missing';END IF;
 -- The build lock serializes publication for one exact claim. No parent wait.
 SELECT * INTO b FROM builds WHERE id=(c->>'build_id')::uuid FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'build export claim missing' USING ERRCODE='23514',CONSTRAINT='build_export_publication_missing';END IF;
 IF (a.id=d.app_id AND b.deployment_id=d.id AND a.account_id::text=c->>'account_id'
  AND coalesce(a.org_id::text,'')=c->>'org_id' AND (coalesce(a.runtime,'')=c->>'runtime' OR (a.type<>'function' AND coalesce(a.runtime,'')='' AND c->>'runtime' IN ('node22','node24'))) AND a.status<>'deleted'
  AND b.started_at=(c->>'claim_started_at')::timestamptz
  AND d.kind IN ('tarball','dockerfile','github','preview')
  AND d.status IN ('pending','building','imaging','snapshotting','live','superseded')
  AND (coalesce(d.source_sha256,'')='' OR d.source_sha256=c->>'source_sha256')) IS NOT TRUE THEN
  RAISE EXCEPTION 'build export owner changed' USING ERRCODE='23514',CONSTRAINT='build_export_publication_stale';
 END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('gregale.application-standard.controls.'||a.id::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('gregale.application-standard.artifact-children.'||d.id::text,0)) THEN
  RAISE EXCEPTION 'build export inputs busy' USING ERRCODE='55P03',CONSTRAINT='build_export_publication_busy';
 END IF;
 IF fresh OR b.status='succeeded' THEN
  SELECT * INTO p FROM build_provenance WHERE build_id=b.id FOR SHARE NOWAIT;
  IF (b.status='succeeded' AND p.started_at=b.started_at AND p.source_sha256=c->>'source_sha256'
   AND coalesce(p.builder_node_id,'')=c->>'builder_node_id') IS NOT TRUE THEN
   RAISE EXCEPTION 'build export completion changed' USING ERRCODE='23514',CONSTRAINT='build_export_publication_stale';
  END IF;
 ELSIF b.status<>'running' THEN
  RAISE EXCEPTION 'build export claim changed' USING ERRCODE='23514',CONSTRAINT='build_export_publication_stale';
 END IF;
 SELECT cosign_public_key INTO key_der FROM app_trusted_signers WHERE app_id=a.id AND account_id=a.account_id AND encode(sha256(cosign_public_key),'hex')=input->'proof'->>'publisher_key_sha256' ORDER BY signer_name LIMIT 1;
 RETURN jsonb_build_object('key_der',coalesce(encode(key_der,'base64'),''),'checked_at',clock_timestamp());
EXCEPTION WHEN lock_not_available THEN
 RAISE EXCEPTION 'build export inputs busy' USING ERRCODE='55P03',CONSTRAINT='build_export_publication_busy';
END;
$$;


