--
-- Name: notify_github_deployment_status_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_github_deployment_status_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (TG_OP = 'INSERT'
      OR NEW.status IS DISTINCT FROM OLD.status
      OR NEW.rollout_state IS DISTINCT FROM OLD.rollout_state
      OR NEW.canary_step IS DISTINCT FROM OLD.canary_step
      OR NEW.traffic_percent IS DISTINCT FROM OLD.traffic_percent)
     AND NEW.kind IN ('github', 'preview') THEN
    INSERT INTO github_check_updates (deployment_id)
    VALUES (NEW.id)
    ON CONFLICT (deployment_id) DO UPDATE SET
      generation = github_check_updates.generation + 1,
      status = 'pending',
      attempts = 0,
      next_attempt_at = now(),
      last_error = '',
      processed_at = NULL,
      updated_at = now();

    PERFORM pg_notify('github_deployment_changed', json_build_object(
      'kind', NEW.kind,
      'app_id', NEW.app_id,
      'deployment_id', NEW.id,
      'status', NEW.status,
      'rollout_state', NEW.rollout_state,
      'canary_step', NEW.canary_step,
      'traffic_percent', NEW.traffic_percent
    )::text);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: notify_org_app_resource_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_org_app_resource_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE application record;
BEGIN
 IF ROW(NEW.plan,NEW.status,NEW.deleted_pending,NEW.abuse_hold_at,NEW.resource_ownership_enabled) IS NOT DISTINCT FROM
    ROW(OLD.plan,OLD.status,OLD.deleted_pending,OLD.abuse_hold_at,OLD.resource_ownership_enabled) THEN RETURN NEW;END IF;
 FOR application IN SELECT id,account_id FROM apps WHERE org_id=NEW.id ORDER BY id LOOP
  PERFORM pg_notify('app_changed',jsonb_build_object('kind','updated','app_id',application.id,'account_id',application.account_id)::text);
 END LOOP;
 RETURN NEW;
END $$;


