-- Name: notify_tenant_surface_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_tenant_surface_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    surface_uuid uuid;
BEGIN
    IF TG_TABLE_NAME = 'tenant_hostnames' THEN
        IF TG_OP = 'DELETE' THEN
            surface_uuid := OLD.surface_id;
        ELSE
            surface_uuid := NEW.surface_id;
        END IF;
    ELSIF TG_OP = 'DELETE' THEN
        surface_uuid := OLD.id;
    ELSE
        surface_uuid := NEW.id;
    END IF;
    PERFORM pg_notify('tenant_surface_changed', surface_uuid::text);
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END
$$;


--
-- Name: object_compute_trigger_ownership_valid(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_compute_trigger_ownership_valid(rules jsonb, managed jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT CASE WHEN jsonb_typeof(rules) <> 'array' OR jsonb_typeof(managed) <> 'array' THEN false ELSE
   jsonb_array_length(managed) <= 1000
   AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(managed) m WHERE jsonb_typeof(m) <> 'object' OR jsonb_typeof(m->'id') IS DISTINCT FROM 'string' OR length(m->>'id') = 0 OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(rules) r WHERE r = m))
   AND (SELECT count(*) = count(DISTINCT m->>'id') FROM jsonb_array_elements(managed) m)
 END
$$;


--
-- Name: object_event_hold_retention_valid(jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_event_hold_retention_valid(r jsonb, writing boolean) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE p jsonb; n numeric; d timestamptz;
BEGIN
 IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR octet_length(r::text)>16384
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(r) AS k WHERE k NOT IN ('mode','retain_until_date','event_hold','event_hold_duration')) THEN RETURN false; END IF;
 IF r='{}'::jsonb THEN RETURN true; END IF;
 IF jsonb_typeof(r->'mode') IS DISTINCT FROM 'string' OR r->>'mode' NOT IN ('COMPLIANCE','GOVERNANCE') THEN RETURN false; END IF;
 IF r ? 'retain_until_date' THEN
  IF jsonb_typeof(r->'retain_until_date') IS DISTINCT FROM 'string' OR r->>'retain_until_date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' THEN RETURN false; END IF;
  d:=(r->>'retain_until_date')::timestamptz;
  IF NOT isfinite(d) OR extract(year FROM d) NOT BETWEEN 1 AND 9999 THEN RETURN false; END IF;
 END IF;
 IF r ? 'event_hold' THEN
  IF jsonb_typeof(r->'event_hold') IS DISTINCT FROM 'string' OR r->>'event_hold' NOT IN ('ON','OFF') THEN RETURN false; END IF;
 ELSE
  RETURN r ? 'retain_until_date' AND NOT r ? 'event_hold_duration';
 END IF;
 IF r ? 'event_hold_duration' THEN
  p:=r->'event_hold_duration';
  IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p))<>1 OR NOT (p ? 'days' OR p ? 'years') THEN RETURN false; END IF;
  IF jsonb_typeof(coalesce(p->'days',p->'years')) IS DISTINCT FROM 'number' OR coalesce(p->>'days',p->>'years') !~ '^[0-9]+$' THEN RETURN false; END IF;
  n:=coalesce(p->>'days',p->>'years')::numeric;
  IF n<1 OR n>(CASE WHEN p ? 'days' THEN 36500 ELSE 100 END) THEN RETURN false; END IF;
 END IF;
 IF r->>'event_hold'='ON' AND NOT r ? 'event_hold_duration' THEN RETURN false; END IF;
 IF writing THEN RETURN r->>'event_hold'<>'OFF' OR NOT r ? 'event_hold_duration'; END IF;
 RETURN r ? 'retain_until_date';
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range THEN RETURN false;
END $_$;


--
-- Name: object_lock_drained(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_lock_drained(bid uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT NOT EXISTS(SELECT 1 FROM object_deletions WHERE bucket_id=bid AND state IN ('prepared','dispatched'))
 AND NOT EXISTS(SELECT 1 FROM object_storage_write_admissions w LEFT JOIN object_storage_multipart_uploads m ON m.id=w.multipart_upload_id
  WHERE w.bucket_id=bid AND ((w.kind='proxy' AND w.state='pending') OR (w.kind='multipart' AND m.state NOT IN ('completed','aborted'))))
 AND NOT EXISTS(SELECT 1 FROM object_storage_key_grants WHERE bucket_id=bid AND NOT reclaimable)
 AND NOT EXISTS(SELECT 1 FROM object_storage_multipart_uploads m WHERE m.bucket_id=bid AND
  (m.state NOT IN ('completed','aborted') OR (m.state<>'completed' AND EXISTS(SELECT 1 FROM object_storage_multipart_part_grants p WHERE p.upload_id=m.id))))
 AND NOT EXISTS(SELECT 1 FROM object_storage_capacity_reconciliations WHERE bucket_id=bid AND state IN ('waiting','scanning'))
$$;


--
-- Name: object_lock_versioning_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_lock_versioning_ready(bid uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM object_bucket_versioning v JOIN object_storage_capacity_reconciliations c ON c.id=v.capacity_job_id
 WHERE v.bucket_id=bid AND v.state='ready' AND v.desired_status='Enabled' AND v.observed_status='Enabled'
 AND v.versions_required AND v.propagation_until<=now() AND c.bucket_id=bid AND c.state='completed'
 AND c.inventory_scope='all_versions' AND c.inventory_verified AND c.created_at>=v.propagation_until)
$$;


--
-- Name: object_multipart_checksum_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_multipart_checksum_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  a text; t text; v text; p jsonb; n integer; item jsonb; i integer;
BEGIN
  IF jsonb_typeof(NEW.checksum_snapshot) <> 'object'
     OR octet_length(NEW.checksum_snapshot::text) > 2097152
     OR NEW.checksum_snapshot - ARRAY['algorithm','type','value','parts'] <> '{}' THEN
    RAISE EXCEPTION 'invalid multipart checksum snapshot' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' THEN
    IF (OLD.checksum_snapshot->>'algorithm',OLD.checksum_snapshot->>'type') IS DISTINCT FROM
       (NEW.checksum_snapshot->>'algorithm',NEW.checksum_snapshot->>'type')
       OR OLD.checksum_verified AND NOT NEW.checksum_verified
       OR OLD.state IN ('completing','completing_conditional','completed','aborting','aborted')
          AND OLD.checksum_snapshot <> NEW.checksum_snapshot THEN
      RAISE EXCEPTION 'immutable multipart checksum intent' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.checksum_snapshot='{}' THEN
    IF NEW.checksum_verified THEN
      RAISE EXCEPTION 'checksum verification requires an intent' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  a := NEW.checksum_snapshot->>'algorithm';
  t := NEW.checksum_snapshot->>'type';
  v := coalesce(NEW.checksum_snapshot->>'value','');
  p := coalesce(NEW.checksum_snapshot->'parts','[]');
  IF a IS NULL OR t IS NULL OR NOT (
     a IN ('CRC32','CRC32C') AND t IN ('COMPOSITE','FULL_OBJECT') OR
     a='CRC64NVME' AND t='FULL_OBJECT' OR
     a IN ('SHA1','SHA256') AND t='COMPOSITE') OR jsonb_typeof(p)<>'array' THEN
    RAISE EXCEPTION 'invalid multipart checksum policy' USING ERRCODE='23514';
  END IF;
  n := jsonb_array_length(p);
  IF NEW.state IN ('initiating','active') OR TG_OP='INSERT' THEN
    IF n<>0 OR v<>'' OR NEW.checksum_verified THEN
      RAISE EXCEPTION 'initial multipart checksum has no completion proof' USING ERRCODE='23514';
    END IF;
  ELSIF NEW.state IN ('completing','completing_conditional','completed') THEN
    IF n<1 OR n>10000 OR n<>jsonb_array_length(NEW.completion_parts)
       OR v='' OR length(v)>128 THEN
      RAISE EXCEPTION 'multipart checksum completion requires selected parts' USING ERRCODE='23514';
    END IF;
    FOR item, i IN SELECT value, ordinality::integer FROM jsonb_array_elements(p) WITH ORDINALITY LOOP
      IF jsonb_typeof(item)<>'object' OR item - ARRAY['number','size','value']<>'{}'
         OR (item->>'number')::integer IS DISTINCT FROM i
         OR (NEW.completion_parts->(i-1)->>'part_number')::integer IS DISTINCT FROM i
         OR (item->>'size')::bigint IS NULL OR (item->>'size')::bigint NOT BETWEEN 1 AND 5368709120
         OR item->>'value' IS NULL OR length(item->>'value')>88
         OR item->>'value' !~ '^[A-Za-z0-9+/]+={0,2}$' THEN
        RAISE EXCEPTION 'invalid selected multipart checksum part' USING ERRCODE='23514';
      END IF;
    END LOOP;
  END IF;
  IF NEW.state='completed' AND NOT NEW.checksum_verified OR
     NEW.checksum_verified AND NEW.state<>'completed' THEN
    RAISE EXCEPTION 'multipart checksum result must be verified before settlement' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: object_storage_credential_live(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_storage_credential_live(credential uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM object_storage_s3_credentials c JOIN object_buckets b ON b.id=c.bucket_id
 JOIN orgs o ON o.id=b.org_id WHERE c.id=credential AND c.status='active' AND b.state='ready' AND NOT o.deleted_pending
 AND (CASE WHEN NOT o.personal_org AND o.resource_ownership_enabled THEN o.status IN ('active','past_due') AND o.abuse_hold_at IS NULL
 ELSE EXISTS(SELECT 1 FROM accounts a WHERE a.id=b.account_id AND a.status IN ('active','past_due') AND a.abuse_hold_at IS NULL) END)
 AND (o.personal_org OR c.managed_app_id IS NOT NULL OR c.rotation_parent_id IS NOT NULL
      OR EXISTS(SELECT 1 FROM org_memberships m WHERE m.org_id=b.org_id AND m.account_id=c.issuer_account_id
         AND m.removed_at IS NULL AND m.access_revision=c.issuer_access_revision AND m.role IN ('owner','admin','developer'))))
$$;


--
-- Name: object_storage_key_live(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_storage_key_live(key_id uuid, bucket_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM api_keys k JOIN object_buckets b ON b.id=bucket_id JOIN orgs o ON o.id=b.org_id
 WHERE k.id=key_id AND k.status IN ('active','grace') AND (k.expires_at IS NULL OR k.expires_at>now())

 AND ((o.personal_org AND k.account_id=b.account_id AND k.org_id=o.id)
 OR (NOT o.personal_org AND k.org_id=o.id AND EXISTS(SELECT 1 FROM org_memberships m
 WHERE m.org_id=o.id AND m.account_id=k.account_id AND m.removed_at IS NULL AND m.role IN ('owner','admin','developer')))))
$$;


--
-- Name: object_storage_usage_subject(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_storage_usage_subject(owner_org uuid, namespace uuid) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
 SELECT object_storage_usage_subject(owner_org,namespace,date_trunc('month',now()))
$$;


--
-- Name: object_storage_usage_subject(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_storage_usage_subject(owner_org uuid, namespace uuid, period_start timestamp with time zone) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN EXISTS(SELECT 1 FROM orgs o WHERE o.id=owner_org AND NOT o.personal_org AND o.resource_ownership_enabled
 AND period_start>=date_trunc('month',coalesce(o.object_storage_owned_from,now()) AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') THEN owner_org ELSE namespace END
$$;


--
-- Name: object_url_issuer_live(uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_url_issuer_live(owner uuid, bucket uuid, issuer uuid, permission text, expiry timestamp with time zone) RETURNS boolean
    LANGUAGE sql
    AS $$
 SELECT expiry>clock_timestamp() AND EXISTS(SELECT 1 FROM object_buckets b WHERE b.id=bucket AND b.account_id=owner AND b.state='ready') AND
  (issuer IS NULL OR EXISTS(SELECT 1 FROM api_keys k
    WHERE k.id=issuer AND object_storage_key_live(k.id,bucket) AND k.status IN ('active','grace') AND (k.expires_at IS NULL OR k.expires_at>clock_timestamp()) AND
    ('admin'=ANY(k.scopes) OR (('storage:'||permission)=ANY(k.scopes) AND EXISTS(SELECT 1 FROM object_storage_access_grants g WHERE g.api_key_id=k.id AND g.account_id=owner AND g.bucket_id=bucket AND (g.permission=permission OR g.permission='read_write'))))));
$$;


--
-- Name: valid_object_conditional_url_request(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.valid_object_conditional_url_request(r jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $$
BEGIN
 IF NOT coalesce(valid_object_versioned_url_request(r-ARRAY['if_match','if_none_match']),false) OR octet_length(r::text)>32768 THEN RETURN false; END IF;
 IF NOT (r ? 'if_match' OR r ? 'if_none_match') THEN RETURN true; END IF;
 IF r->>'method'<>'PUT' OR r ? 'multipart' OR r ? 'if_match' AND r ? 'if_none_match' THEN RETURN false; END IF;
 IF r ? 'if_match' AND (jsonb_typeof(r->'if_match') IS DISTINCT FROM 'string' OR octet_length(r->>'if_match') NOT BETWEEN 1 AND 256 OR (r->>'if_match') ~ '[\x01-\x1f\x7f]') THEN RETURN false; END IF;
 IF r ? 'if_none_match' AND (jsonb_typeof(r->'if_none_match') IS DISTINCT FROM 'string' OR r->>'if_none_match'<>'*') THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;


--
-- Name: valid_object_encryption_snapshot(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.valid_object_encryption_snapshot(e jsonb, owner uuid) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE s jsonb; algorithm text; context_bytes bytea; context_doc json; entries bigint; distinct_entries bigint;
BEGIN
 IF e='{}'::jsonb THEN RETURN true; END IF;
 IF jsonb_typeof(e)<>'object' OR octet_length(e::text)>16384 OR
  e - ARRAY['account_id','selection','provider_key_id','key_identity'] <> '{}'::jsonb OR
  jsonb_typeof(e->'account_id') IS DISTINCT FROM 'string' OR e->>'account_id'<>owner::text OR
  owner='00000000-0000-0000-0000-000000000000'::uuid THEN RETURN false; END IF;
 s:=e->'selection'; algorithm:=s->>'algorithm';
 IF jsonb_typeof(s) IS DISTINCT FROM 'object' OR jsonb_typeof(s->'algorithm') IS DISTINCT FROM 'string' OR
  s - ARRAY['algorithm','key_id','bucket_key_enabled','context'] <> '{}'::jsonb THEN RETURN false; END IF;
 IF algorithm='AES256' THEN
  RETURN s='{"algorithm":"AES256"}'::jsonb AND NOT e ?| ARRAY['provider_key_id','key_identity'];
 END IF;
 IF algorithm NOT IN ('aws:kms','aws:kms:dsse') OR algorithm IS NULL OR
  jsonb_typeof(s->'key_id') IS DISTINCT FROM 'string' OR
  octet_length(s->>'key_id')>512 OR
  (s->>'key_id') !~ '^arn:gregale:kms:[a-z][a-z0-9-]{0,62}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:key/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR
  split_part(s->>'key_id',':',5)<>owner::text OR
  split_part(s->>'key_id',':',6)='key/00000000-0000-0000-0000-000000000000' OR
  jsonb_typeof(e->'provider_key_id') IS DISTINCT FROM 'string' OR
  octet_length(e->>'provider_key_id') NOT BETWEEN 1 AND 512 OR
  (e->>'provider_key_id') ~ '[\x01-\x1f\x7f]' OR
  jsonb_typeof(e->'key_identity') IS DISTINCT FROM 'string' OR
  (e->>'key_identity') !~ '^[0-9a-f]{64}$' OR (e->>'key_identity')=repeat('0',64) OR
  (algorithm='aws:kms' AND jsonb_typeof(s->'bucket_key_enabled') IS DISTINCT FROM 'boolean') OR
  (algorithm='aws:kms:dsse' AND s ? 'bucket_key_enabled') THEN RETURN false; END IF;
 IF s ? 'context' THEN
  IF jsonb_typeof(s->'context') IS DISTINCT FROM 'string' OR octet_length(s->>'context')>10924 THEN RETURN false; END IF;
  IF s->>'context'<>'' THEN
   context_bytes:=decode(s->>'context','base64');
   IF octet_length(context_bytes)>8192 OR replace(encode(context_bytes,'base64'),E'\n','')<>s->>'context' THEN RETURN false; END IF;
   context_doc:=convert_from(context_bytes,'UTF8')::json;
   IF json_typeof(context_doc)<>'object' THEN RETURN false; END IF;
   SELECT count(*),count(DISTINCT key) INTO entries,distinct_entries FROM json_each(context_doc);
   IF entries>32 OR entries<>distinct_entries OR EXISTS(SELECT 1 FROM json_each(context_doc) WHERE key='' OR json_typeof(value)<>'string') THEN RETURN false; END IF;
  END IF;
 END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;


--
-- Name: valid_object_event_write_protection(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.valid_object_event_write_protection(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE r jsonb; d jsonb; t timestamptz; minimum timestamptz; period jsonb; n integer;
BEGIN
 IF p='{}' THEN RETURN true; END IF;
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR octet_length(p::text)>16384 OR p-ARRAY['enabled','revision','captured_at','default_retention','requested']<>'{}' OR p->'enabled' IS DISTINCT FROM 'true'::jsonb OR
  p ? 'revision' AND (jsonb_typeof(p->'revision') IS DISTINCT FROM 'number' OR p->>'revision' !~ '^[0-9]+$' OR (p->>'revision')::numeric NOT BETWEEN 0 AND 9007199254740991) OR jsonb_typeof(p->'captured_at') IS DISTINCT FROM 'string' THEN RETURN false; END IF;
 t:=(p->>'captured_at')::timestamptz;
 IF NOT isfinite(t) OR extract(year from t) NOT BETWEEN 1 AND 9999 THEN RETURN false; END IF;
 IF p ? 'default_retention' AND NOT coalesce(valid_object_lock_configuration(jsonb_build_object('enabled',true,'default_retention',p->'default_retention')),false) THEN RETURN false; END IF;
 r:=coalesce(p->'requested','{}'::jsonb);
 IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR r-ARRAY['retention','legal_hold']<>'{}' THEN RETURN false; END IF;
 IF r ? 'retention' THEN
  d:=r->'retention';
  IF d='{}' OR NOT object_event_hold_retention_valid(d,true) OR NOT (d->>'event_hold'='ON' OR d ? 'retain_until_date') THEN RETURN false; END IF;
  IF d ? 'retain_until_date' AND date_trunc('milliseconds',(d->>'retain_until_date')::timestamptz)<>(d->>'retain_until_date')::timestamptz THEN RETURN false; END IF;
  IF d->>'event_hold'='ON' THEN period:=d->'event_hold_duration'; END IF;
 ELSE
  d:=p->'default_retention';
  period:=d->'default_event_hold';
  IF d ? 'days' THEN minimum:=t+(d->>'days')::integer*interval '1 day'; END IF;
  IF d ? 'years' THEN minimum:=t+(d->>'years')::integer*interval '1 year'; END IF;
  IF minimum IS NOT NULL AND extract(year FROM minimum) NOT BETWEEN 1 AND 9999 THEN RETURN false; END IF;
 END IF;
 IF period IS NOT NULL THEN
  n:=CASE WHEN period ? 'days' THEN (period->>'days')::integer ELSE (period->>'years')::integer*365 END;
  minimum:=t+n*interval '1 day';
  IF extract(year FROM minimum) NOT BETWEEN 1 AND 9999 THEN RETURN false; END IF;
 END IF;
 IF r ? 'legal_hold' AND (jsonb_typeof(r->'legal_hold') IS DISTINCT FROM 'object' OR (r->'legal_hold')-ARRAY['status']<>'{}' OR coalesce(r->'legal_hold'->>'status','') NOT IN ('ON','OFF')) THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;


--
-- Name: object_storage_multipart_uploads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.object_storage_multipart_uploads (
    id uuid NOT NULL,
    account_id uuid NOT NULL,
    app_id uuid NOT NULL,
    bucket_id uuid NOT NULL,
    object_key text NOT NULL,
    size_bytes bigint NOT NULL,
    part_size_bytes bigint NOT NULL,
    part_count integer NOT NULL,
    content_type text DEFAULT ''::text NOT NULL,
    provider_upload_id text DEFAULT ''::text NOT NULL,
    completion_parts jsonb DEFAULT '[]'::jsonb NOT NULL,
    state text DEFAULT 'initiating'::text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    lease_token text,
    lease_until timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    retry_at timestamp with time zone DEFAULT now() NOT NULL,
    last_error_code text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    object_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    part_revision bigint DEFAULT 0 NOT NULL,
    completion_if_match text DEFAULT ''::text NOT NULL,
    completion_if_none_match text DEFAULT ''::text NOT NULL,
    completion_error_code text DEFAULT ''::text NOT NULL,
    completion_etag text DEFAULT ''::text NOT NULL,
    completion_version_id text DEFAULT ''::text NOT NULL,
    completion_recovery_cursor text DEFAULT ''::text NOT NULL,
    completion_versions_observed boolean DEFAULT false NOT NULL,
    completion_dispatched boolean DEFAULT false NOT NULL,
    part_url_unsafe_until timestamp with time zone,
    lifecycle_scan_id uuid,
    lifecycle_binding jsonb DEFAULT '{}'::jsonb NOT NULL,
    encryption_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    encryption_lease_token text DEFAULT ''::text NOT NULL,
    encryption_verified boolean DEFAULT false NOT NULL,
    fixed_admission boolean DEFAULT false NOT NULL,
    encryption_default_revision bigint DEFAULT 0 NOT NULL,
    protection_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    protection_lease_token text DEFAULT ''::text NOT NULL,
    protection_verified boolean DEFAULT false NOT NULL,
    checksum_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    checksum_verified boolean DEFAULT false NOT NULL,
    CONSTRAINT object_multipart_completion_conditions CHECK (((octet_length(completion_if_match) <= 256) AND (completion_if_match !~ '[[:cntrl:]]'::text) AND (completion_if_none_match = ANY (ARRAY[''::text, '*'::text])) AND ((completion_if_match = ''::text) OR (completion_if_none_match = ''::text)) AND ((state <> ALL (ARRAY['initiating'::text, 'active'::text, 'completing'::text])) OR ((completion_if_match = ''::text) AND (completion_if_none_match = ''::text))) AND ((state <> 'completing_conditional'::text) OR ((part_count = 0) AND ((completion_if_match <> ''::text) OR (completion_if_none_match <> ''::text)))))),
    CONSTRAINT object_multipart_completion_error CHECK (((completion_error_code = ANY (ARRAY[''::text, 'precondition_failed'::text, 'conditional_conflict'::text, 'conditional_not_found'::text])) AND ((completion_error_code = ''::text) OR ((state = ANY (ARRAY['aborting'::text, 'aborted'::text])) AND ((completion_if_match <> ''::text) OR (completion_if_none_match <> ''::text)))))),
    CONSTRAINT object_multipart_encryption_phase CHECK ((((encryption_lease_token = ''::text) OR ((encryption_snapshot <> '{}'::jsonb) AND (lease_token IS NOT NULL) AND (encryption_lease_token = lease_token))) AND ((NOT encryption_verified) OR ((encryption_snapshot <> '{}'::jsonb) AND (state = 'completed'::text) AND completion_dispatched)) AND ((encryption_snapshot = '{}'::jsonb) OR (state <> 'completed'::text) OR encryption_verified))),
    CONSTRAINT object_multipart_event_protection_snapshot CHECK (public.valid_object_event_write_protection(protection_snapshot)),
    CONSTRAINT object_multipart_lifecycle_binding CHECK ((((lifecycle_scan_id IS NULL) AND (lifecycle_binding = '{}'::jsonb)) OR ((lifecycle_scan_id IS NOT NULL) AND (jsonb_typeof(lifecycle_binding) = 'object'::text) AND (lifecycle_binding ?& ARRAY['scan_id'::text, 'scan_token'::text, 'rule_id'::text, 'expected_provider_upload_id'::text, 'expected_created_at'::text]) AND ((lifecycle_binding - ARRAY['scan_id'::text, 'scan_token'::text, 'rule_id'::text, 'expected_provider_upload_id'::text, 'expected_created_at'::text]) = '{}'::jsonb) AND (jsonb_typeof((lifecycle_binding -> 'scan_id'::text)) = 'string'::text) AND ((lifecycle_binding ->> 'scan_id'::text) = (lifecycle_scan_id)::text) AND (jsonb_typeof((lifecycle_binding -> 'scan_token'::text)) = 'string'::text) AND ((octet_length((lifecycle_binding ->> 'scan_token'::text)) >= 1) AND (octet_length((lifecycle_binding ->> 'scan_token'::text)) <= 128)) AND (jsonb_typeof((lifecycle_binding -> 'rule_id'::text)) = 'string'::text) AND ((char_length((lifecycle_binding ->> 'rule_id'::text)) >= 1) AND (char_length((lifecycle_binding ->> 'rule_id'::text)) <= 255)) AND (jsonb_typeof((lifecycle_binding -> 'expected_provider_upload_id'::text)) = 'string'::text) AND ((lifecycle_binding ->> 'expected_provider_upload_id'::text) = provider_upload_id) AND (provider_upload_id <> ''::text) AND (jsonb_typeof((lifecycle_binding -> 'expected_created_at'::text)) = 'string'::text) AND ((lifecycle_binding ->> 'expected_created_at'::text) <> ''::text) AND (octet_length((lifecycle_binding)::text) <= 8192) AND (state = ANY (ARRAY['aborting'::text, 'aborted'::text]))))),
    CONSTRAINT object_multipart_part_url_deadline_shape CHECK (((part_url_unsafe_until IS NULL) OR ((part_count > 0) AND (part_url_unsafe_until >= created_at)))),
    CONSTRAINT object_multipart_protection_phase CHECK ((((protection_lease_token = ''::text) OR ((protection_snapshot <> '{}'::jsonb) AND (lease_token IS NOT NULL) AND (protection_lease_token = lease_token))) AND ((NOT protection_verified) OR ((protection_snapshot <> '{}'::jsonb) AND (state = 'completed'::text) AND completion_dispatched AND (completion_version_id <> ''::text) AND (completion_version_id <> 'null'::text))) AND ((protection_snapshot = '{}'::jsonb) OR (state <> 'completed'::text) OR protection_verified))),
    CONSTRAINT object_multipart_result_shape CHECK ((((state = 'completed'::text) OR ((completion_etag = ''::text) AND (completion_version_id = ''::text))) AND ((completion_version_id = ''::text) OR (completion_etag <> ''::text)) AND ((state <> 'completed'::text) OR (completion_recovery_cursor = ''::text)) AND ((state <> 'completed'::text) OR (NOT completion_dispatched) OR (completion_etag <> ''::text)))),
    CONSTRAINT object_storage_multipart_uploa_completion_recovery_cursor_check CHECK (((octet_length(completion_recovery_cursor) <= 8192) AND (completion_recovery_cursor ~ '^[A-Za-z0-9_-]*$'::text))),
    CONSTRAINT object_storage_multipart_uploads_attempt_count_check CHECK (((attempt_count >= 0) AND (attempt_count <= 30))),
    CONSTRAINT object_storage_multipart_uploads_check CHECK (((lease_token IS NULL) = (lease_until IS NULL))),
    CONSTRAINT object_storage_multipart_uploads_check1 CHECK (((state = 'initiating'::text) OR (provider_upload_id <> ''::text))),
    CONSTRAINT object_storage_multipart_uploads_check2 CHECK (public.valid_object_encryption_snapshot(encryption_snapshot, account_id)),
    CONSTRAINT object_storage_multipart_uploads_check3 CHECK (((NOT fixed_admission) OR ((size_bytes > 0) AND (part_size_bytes > 0) AND (part_count > 0) AND (part_count = (((size_bytes + part_size_bytes) - 1) / part_size_bytes))))),
    CONSTRAINT object_storage_multipart_uploads_check4 CHECK ((((encryption_default_revision >= 0) AND (encryption_default_revision <= '9007199254740991'::bigint)) AND ((encryption_default_revision = 0) OR (encryption_snapshot <> '{}'::jsonb)))),
    CONSTRAINT object_storage_multipart_uploads_completion_etag_check CHECK (((octet_length(completion_etag) <= 256) AND (completion_etag !~ '[\x01-\x1f\x7f]'::text) AND ((completion_etag = ''::text) OR (btrim(completion_etag) <> ''::text)))),
    CONSTRAINT object_storage_multipart_uploads_completion_parts_check CHECK ((jsonb_typeof(completion_parts) = 'array'::text)),
    CONSTRAINT object_storage_multipart_uploads_completion_version_id_check CHECK (((completion_version_id = ''::text) OR (completion_version_id = 'null'::text) OR (completion_version_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text))),
    CONSTRAINT object_storage_multipart_uploads_content_type_check CHECK ((length(content_type) <= 255)),
    CONSTRAINT object_storage_multipart_uploads_encryption_lease_token_check CHECK ((octet_length(encryption_lease_token) <= 128)),
    CONSTRAINT object_storage_multipart_uploads_last_error_code_check CHECK ((length(last_error_code) <= 32)),
    CONSTRAINT object_storage_multipart_uploads_layout_check CHECK ((((size_bytes = 0) AND (part_size_bytes = 0) AND (part_count = 0)) OR ((size_bytes > 0) AND (part_size_bytes = 0) AND (part_count = 0)) OR ((size_bytes > 0) AND (part_size_bytes > 0) AND (part_count > 0)))),
    CONSTRAINT object_storage_multipart_uploads_object_key_check CHECK (((length(object_key) >= 1) AND (length(object_key) <= 1024))),
    CONSTRAINT object_storage_multipart_uploads_object_metadata_check CHECK ((jsonb_typeof(object_metadata) = 'object'::text)),
    CONSTRAINT object_storage_multipart_uploads_object_metadata_check1 CHECK ((octet_length((object_metadata)::text) <= 32768)),
    CONSTRAINT object_storage_multipart_uploads_part_count_check CHECK (((part_count >= 0) AND (part_count <= 10000))),
    CONSTRAINT object_storage_multipart_uploads_part_revision_check CHECK ((part_revision >= 0)),
    CONSTRAINT object_storage_multipart_uploads_part_size_bytes_check CHECK (((part_size_bytes >= 0) AND (part_size_bytes <= '5368709120'::bigint))),
    CONSTRAINT object_storage_multipart_uploads_protection_lease_token_check CHECK ((octet_length(protection_lease_token) <= 128)),
    CONSTRAINT object_storage_multipart_uploads_provider_upload_id_check CHECK ((length(provider_upload_id) <= 4096)),
    CONSTRAINT object_storage_multipart_uploads_size_bytes_check CHECK (((size_bytes >= 0) AND (size_bytes <= '5497558138880'::bigint))),
    CONSTRAINT object_storage_multipart_uploads_state_check CHECK ((state = ANY (ARRAY['initiating'::text, 'active'::text, 'completing'::text, 'completing_conditional'::text, 'aborting'::text, 'completed'::text, 'aborted'::text])))
);


--
-- Name: object_storage_s3_credentials; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.object_storage_s3_credentials (
    id uuid NOT NULL,
    account_id uuid NOT NULL,
    bucket_id uuid NOT NULL,
    access_key_id text NOT NULL,
    secret_sealed bytea NOT NULL,
    kid text NOT NULL,
    label text NOT NULL,
    permission text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_used_at timestamp with time zone,
    revoked_at timestamp with time zone,
    managed_app_id uuid,
    managed_scope text,
    managed_prefix text,
    rotation_parent_id uuid,
    rotation_wake_id uuid,
    rotation_stamped_at timestamp with time zone,
    url_request jsonb,
    url_api_key_id uuid,
    url_expires_at timestamp with time zone,
    url_receipt_id uuid,
    issuer_account_id uuid,
    issuer_access_revision bigint,
    CONSTRAINT object_s3_conditional_url_request CHECK (((url_request IS NULL) OR public.valid_object_conditional_url_request(url_request))),
    CONSTRAINT object_s3_issuer_pair CHECK ((((issuer_account_id IS NULL) AND (issuer_access_revision IS NULL)) OR ((issuer_account_id IS NOT NULL) AND (issuer_access_revision IS NOT NULL) AND (issuer_access_revision > 0)))),
    CONSTRAINT object_storage_s3_credentials_access_key_id_check CHECK ((access_key_id ~ '^GRGA[A-Z2-7]{16}$'::text)),
    CONSTRAINT object_storage_s3_credentials_check CHECK ((((status = 'active'::text) AND (revoked_at IS NULL)) OR ((status = 'revoked'::text) AND (revoked_at IS NOT NULL)))),
    CONSTRAINT object_storage_s3_credentials_kid_check CHECK (((length(kid) >= 1) AND (length(kid) <= 255))),
    CONSTRAINT object_storage_s3_credentials_label_check CHECK (((length(label) >= 1) AND (length(label) <= 64))),
    CONSTRAINT object_storage_s3_credentials_managed_shape_check CHECK ((((managed_app_id IS NULL) AND (managed_scope IS NULL) AND (managed_prefix IS NULL)) OR ((managed_app_id IS NOT NULL) AND (managed_scope ~ '^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$'::text) AND (managed_prefix ~ '^[A-Z][A-Z0-9_]{0,47}$'::text)))),
    CONSTRAINT object_storage_s3_credentials_permission_check CHECK ((permission = ANY (ARRAY['read'::text, 'write'::text, 'read_write'::text]))),
    CONSTRAINT object_storage_s3_credentials_rotation_shape_check CHECK ((((rotation_parent_id IS NULL) AND (rotation_wake_id IS NULL) AND (rotation_stamped_at IS NULL)) OR ((rotation_parent_id IS NOT NULL) AND (rotation_wake_id IS NOT NULL) AND (managed_app_id IS NULL) AND (managed_scope IS NULL) AND (managed_prefix IS NULL)))),
    CONSTRAINT object_storage_s3_credentials_secret_sealed_check CHECK ((length(secret_sealed) > 0)),
    CONSTRAINT object_storage_s3_credentials_status_check CHECK ((status = ANY (ARRAY['active'::text, 'revoked'::text]))),
    CONSTRAINT object_storage_s3_credentials_url_api_key_id_check CHECK (((url_api_key_id IS NULL) OR (url_api_key_id <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT object_url_credential_shape CHECK ((((url_request IS NULL) AND (url_api_key_id IS NULL) AND (url_expires_at IS NULL) AND (url_receipt_id IS NULL)) OR ((url_request IS NOT NULL) AND (url_expires_at IS NOT NULL) AND (url_expires_at > created_at) AND (url_expires_at <= (created_at + '00:15:00'::interval)) AND (managed_app_id IS NULL) AND (rotation_parent_id IS NULL) AND ((((url_request ->> 'method'::text) = 'PUT'::text) AND (permission = 'write'::text) AND (((NOT (url_request ? 'multipart'::text)) AND (url_receipt_id IS NOT NULL)) OR ((url_request ? 'multipart'::text) AND (url_receipt_id IS NULL)))) OR (((url_request ->> 'method'::text) = ANY (ARRAY['GET'::text, 'HEAD'::text])) AND (permission = 'read'::text) AND (url_receipt_id IS NULL))))))
);


--
-- Name: object_url_multipart_matches(public.object_storage_s3_credentials, public.object_storage_multipart_uploads); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_url_multipart_matches(c public.object_storage_s3_credentials, u public.object_storage_multipart_uploads) RETURNS boolean
    LANGUAGE sql
    AS $$
 SELECT c.url_request ? 'multipart' AND c.permission='write' AND c.status='active' AND
 c.account_id=u.account_id AND c.bucket_id=u.bucket_id AND
 c.url_request->>'key'=u.object_key AND c.url_request->'multipart'->>'upload_id'=u.id::text AND
 u.state='active' AND u.part_count>0 AND u.provider_upload_id<>'' AND u.expires_at>clock_timestamp() AND c.url_expires_at<=u.expires_at AND
 (c.url_request->'multipart'->>'part_number')::int BETWEEN 1 AND u.part_count AND
 (c.url_request->>'size_bytes')::bigint=least(u.part_size_bytes,u.size_bytes-((c.url_request->'multipart'->>'part_number')::int-1)*u.part_size_bytes) AND
 object_url_issuer_live(c.account_id,c.bucket_id,c.url_api_key_id,c.permission,c.url_expires_at);
$$;


--
-- Name: object_url_receipt_committed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.object_url_receipt_committed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.url_receipt_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM object_upload_completions w JOIN object_buckets b ON b.id=NEW.bucket_id
  WHERE w.id=NEW.url_receipt_id AND w.subject_id=NEW.id::text AND w.account_id=NEW.account_id AND w.bucket_id=NEW.bucket_id AND w.app_id=b.app_id AND w.origin='gateway' AND w.write_phase='prepared' AND w.status='pending') THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed PUT URL requires an atomic prepared receipt';
 END IF;
 RETURN NULL;
END $$;


--
-- Name: observe_realtime_circuit(uuid, bigint, bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.observe_realtime_circuit(gid uuid, seq bigint, fence bigint, success boolean, reason text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE g managed_realtime_consumer_groups%ROWTYPE;
BEGIN
 SELECT * INTO g FROM managed_realtime_consumer_groups WHERE id=gid FOR UPDATE;
 IF NOT FOUND OR NOT g.circuit_enabled THEN RETURN; END IF;
 IF g.circuit_state='half_open' AND g.circuit_probe_sequence=seq AND g.circuit_probe_fencing_token=fence THEN
  UPDATE managed_realtime_consumer_groups SET circuit_state=CASE WHEN success THEN 'closed' ELSE 'open' END,
   circuit_failures=CASE WHEN success THEN 0 ELSE circuit_threshold END,
   circuit_open_until=CASE WHEN success THEN NULL ELSE clock_timestamp()+make_interval(secs=>circuit_cooldown_seconds) END,
   circuit_probe_sequence=NULL,circuit_probe_fencing_token=NULL,circuit_reason=CASE WHEN success THEN 'probe_success' ELSE 'probe_failed' END WHERE id=gid;
 ELSIF g.circuit_state='closed' THEN
  IF success THEN UPDATE managed_realtime_consumer_groups SET circuit_failures=0 WHERE id=gid;
  ELSIF reason IN ('handler_failure','lease_expired') THEN
   UPDATE managed_realtime_consumer_groups SET circuit_failures=least(circuit_threshold,circuit_failures+1),
    circuit_state=CASE WHEN circuit_failures+1>=circuit_threshold THEN 'open' ELSE 'closed' END,
    circuit_open_until=CASE WHEN circuit_failures+1>=circuit_threshold THEN clock_timestamp()+make_interval(secs=>circuit_cooldown_seconds) ELSE NULL END,
    circuit_reason=reason WHERE id=gid;
  END IF;
 END IF;
END $$;


--
-- Name: observe_realtime_circuit_failure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.observe_realtime_circuit_failure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.status='leased' AND NEW.status='ready' AND NEW.release_count>OLD.release_count THEN
  UPDATE managed_realtime_consumer_groups SET circuit_probe_sequence=NULL,circuit_probe_fencing_token=NULL
   WHERE id=NEW.group_id AND circuit_state='half_open' AND circuit_probe_sequence=OLD.sequence AND circuit_probe_fencing_token=OLD.fencing_token;
  RETURN NEW;
 END IF;
 IF OLD.status='leased' AND NEW.status IN ('ready','dead') THEN
  PERFORM observe_realtime_circuit(NEW.group_id,NEW.sequence,OLD.fencing_token,false,
   CASE WHEN NEW.failure_code='lease_expired' THEN 'lease_expired'
        WHEN NEW.deadline_invalid OR (NEW.delivery_deadline IS NOT NULL AND NEW.delivery_deadline<=clock_timestamp()) THEN 'deadline'
        ELSE 'handler_failure' END);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: observe_realtime_delivery_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.observe_realtime_delivery_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE lease_expired boolean;
BEGIN
 IF OLD.status='leased' AND NEW.status='ready' AND NEW.release_count>OLD.release_count THEN
  PERFORM record_realtime_delivery_history(NEW.group_id,NEW.sequence,'released',OLD.attempts,OLD.fencing_token,'');
 ELSIF NEW.status='leased' AND OLD.status='ready' THEN
  PERFORM record_realtime_delivery_history(NEW.group_id,NEW.sequence,'claimed',NEW.attempts,NEW.fencing_token,'');
 ELSIF OLD.status='dead' AND NEW.status='ready' THEN
  PERFORM record_realtime_delivery_history(NEW.group_id,NEW.sequence,'replayed',NEW.attempts,NEW.fencing_token,'');
 ELSIF NEW.status='dead' AND OLD.status<>'dead' THEN
  IF NEW.deadline_invalid THEN
   PERFORM record_realtime_delivery_history(NEW.group_id,NEW.sequence,'invalid_deadline',NEW.attempts,NEW.fencing_token,NEW.failure_code);
  ELSIF NEW.delivery_deadline IS NOT NULL AND NEW.delivery_deadline<=clock_timestamp() THEN
   PERFORM record_realtime_delivery_history(NEW.group_id,NEW.sequence,'deadline_expired',NEW.attempts,NEW.fencing_token,NEW.failure_code);
  ELSIF OLD.status='leased' AND OLD.lease_until<=clock_timestamp() AND NEW.failure_code='lease_expired' THEN
   PERFORM record_realtime_delivery_history(NEW.group_id,NEW.sequence,'lease_expired',NEW.attempts,NEW.fencing_token,NEW.failure_code);
  END IF;
  PERFORM record_realtime_delivery_history(NEW.group_id,NEW.sequence,'dead_lettered',NEW.attempts,NEW.fencing_token,NEW.failure_code);
 ELSIF OLD.status='leased' AND NEW.status='ready' THEN
  lease_expired:=OLD.lease_until<=clock_timestamp() AND NEW.failure_code='lease_expired';
  PERFORM record_realtime_delivery_history(NEW.group_id,NEW.sequence,CASE WHEN lease_expired THEN 'lease_expired' ELSE 'retried' END,NEW.attempts,NEW.fencing_token,NEW.failure_code);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: operator_node_completion_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.operator_node_completion_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE receipt operator_node_executions%ROWTYPE;
BEGIN
 IF OLD.kind IN ('node_drain','node_force_drain','node_activate','node_retire') THEN
  SELECT * INTO receipt FROM operator_node_executions WHERE intent_id=OLD.id;
  IF FOUND THEN
   IF (OLD.status IN ('succeeded','failed') AND NEW IS DISTINCT FROM OLD)
    OR (NEW.kind,NEW.target_id,NEW.actor_id,NEW.account_id,NEW.reason,NEW.metadata,NEW.trace_id)
       IS DISTINCT FROM (OLD.kind,OLD.target_id,OLD.actor_id,OLD.account_id,OLD.reason,OLD.metadata,OLD.trace_id)
    OR (NEW.kind,NEW.target_id,NEW.claim_token,NEW.status,coalesce(NEW.error,''),NEW.finished_at,NEW.completion_audit_outbox_id)
       IS DISTINCT FROM (receipt.kind,receipt.target_id,receipt.claim_token,receipt.status,receipt.error,receipt.finished_at,receipt.audit_outbox_id) THEN
    RAISE EXCEPTION 'Operator node completion does not match immutable receipt' USING ERRCODE='23514';
   END IF;
  ELSIF NEW.status IN ('succeeded','failed') THEN
   RAISE EXCEPTION 'Operator node completion requires an atomic receipt' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: operator_node_receipt_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.operator_node_receipt_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 RAISE EXCEPTION 'Operator node execution receipts are immutable' USING ERRCODE='23514';
END $$;


--
-- Name: org_app_identity_erasure_blocked(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_app_identity_erasure_blocked(identity_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE resource_table text; found boolean;
BEGIN
    IF EXISTS (SELECT 1 FROM org_memberships m JOIN orgs o ON o.id=m.org_id
               WHERE m.account_id=identity_id AND m.removed_at IS NULL
                 AND m.role='owner' AND NOT o.personal_org AND NOT o.deleted_pending) THEN
        RETURN true;
    END IF;
    IF EXISTS (SELECT 1 FROM managed_postgres_databases d JOIN orgs o ON o.id=d.org_id
               WHERE d.account_id=identity_id AND NOT o.personal_org AND NOT o.resource_ownership_enabled) THEN
        RETURN true;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM managed_postgres_databases d JOIN orgs o ON o.id=d.org_id
                   WHERE d.account_id=identity_id AND NOT o.personal_org)
       AND NOT EXISTS (SELECT 1 FROM apps a JOIN orgs o ON o.id=a.org_id
                   WHERE a.account_id=identity_id AND NOT o.personal_org)
       AND NOT EXISTS (SELECT 1 FROM projects p JOIN orgs o ON o.id=p.org_id
                       WHERE p.account_id=identity_id AND NOT o.personal_org) THEN
        RETURN false;
    END IF;
    IF EXISTS (SELECT 1 FROM apps a JOIN orgs o ON o.id=a.org_id
               WHERE a.account_id=identity_id AND NOT o.personal_org
                 AND (a.github_install_id IS NOT NULL OR NOT o.resource_ownership_enabled)) THEN
        RETURN true;
    END IF;
    IF EXISTS (SELECT 1 FROM projects p JOIN orgs o ON o.id=p.org_id
               WHERE p.account_id=identity_id AND NOT o.personal_org
                 AND (coalesce(p.install_id,0) <> 0 OR NOT o.resource_ownership_enabled))
       OR EXISTS (SELECT 1 FROM environment_git_sources g JOIN projects p ON p.id=g.project_id
                  JOIN orgs o ON o.id=p.org_id WHERE p.account_id=identity_id AND NOT o.personal_org) THEN
        RETURN true;
    END IF;
    IF EXISTS (SELECT 1 FROM triggers t JOIN apps a ON a.id=t.app_id JOIN orgs o ON o.id=a.org_id
       WHERE t.account_id=identity_id AND NOT o.personal_org AND NOT
       (t.kind='queue' AND t.source='queue' AND EXISTS(SELECT 1 FROM queue_bindings b
        WHERE b.id=t.queue_binding_id AND b.app_id=t.app_id AND b.account_id=t.account_id AND b.org_id=a.org_id))) THEN
      RETURN true;
    END IF;
    IF EXISTS (SELECT 1 FROM dead_letter_events d LEFT JOIN apps a ON a.id=d.app_id
       LEFT JOIN orgs o ON o.id=a.org_id WHERE d.account_id=identity_id AND (a.id IS NULL OR
       (NOT o.personal_org AND NOT (
        (d.source='invocation' AND (d.origin='queue' OR EXISTS(SELECT 1 FROM invocations i WHERE i.id=d.source_id AND i.source='queue' AND i.app_id=d.app_id)))
        OR (d.source='trigger_record' AND EXISTS(SELECT 1 FROM triggers t JOIN queue_bindings b ON b.id=t.queue_binding_id
          WHERE t.id=d.trigger_id AND t.app_id=d.app_id AND t.account_id=d.account_id AND t.kind='queue' AND t.source='queue')))))) THEN
      RETURN true;
    END IF;
    FOR resource_table IN SELECT unnest(ARRAY[
        'alert_deliveries',
        'alert_rules',
        'api_consumer_plan_admissions',
        'api_consumer_plan_assignments',
        'api_consumer_plans',
        'api_consumer_rate_cards',
        'api_consumer_route_usage_minutes',
        'api_consumer_usage_alerts',
        'api_consumer_usage_events',
        'api_consumer_usage_minutes',
        'api_consumer_usage_statement_handoffs',
        'api_consumer_usage_statements',
        'api_consumers',
        'app_api_routes',
        'app_issues',
        'app_private_network_attachment_nodes',
        'app_private_network_attachments',
        'app_route_priorities',
        'app_route_removal_policies',
        'app_tcp_listeners',
        'app_udp_listeners',
        'app_webhook_deliveries',
        'app_webhook_event_outbox',
        'app_webhooks',
        'application_standard_snapshot_captures',
        'automatic_route_checks',
        'canary_route_gates',
        'ci_automation_branches',
        'ci_automation_event_retries',
        'ci_automation_events',
        'ci_automation_path_checks',
        'ci_automation_policies',
        'ci_automation_pull_requests',
        'ci_execution_archives',
