--
-- Name: project_environment_config_env(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_environment_config_env(config jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $_$
    SELECT coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
      FROM jsonb_each(CASE WHEN jsonb_typeof(config) = 'object' THEN config ELSE '{}'::jsonb END) e
     WHERE e.key ~ '^[A-Z][A-Z0-9_]*$' AND length(e.key) <= 128
       AND jsonb_typeof(e.value) IN ('string', 'number', 'boolean');
$_$;


--
-- Name: project_environment_config_runtime_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_environment_config_runtime_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    previous jsonb;
BEGIN
    SELECT c.config_json INTO previous
      FROM project_environment_config_versions c
     WHERE c.project_id = NEW.project_id AND c.environment_slug = NEW.environment_slug
       AND c.version < NEW.version
     ORDER BY c.version DESC
     LIMIT 1;
    IF project_environment_config_env(previous) = project_environment_config_env(NEW.config_json) THEN
        RETURN NULL;
    END IF;
    -- The default scope reads production (workloadEnvironmentSlug).
    WITH member AS (
        SELECT a.id FROM apps a
         WHERE a.project_id = NEW.project_id AND a.account_id = NEW.account_id AND a.status <> 'deleted'
    ), scopes AS (
        SELECT unnest(CASE WHEN NEW.environment_slug = 'production'
            THEN ARRAY['production', 'default'] ELSE ARRAY[NEW.environment_slug] END) AS scope
    ), stamped AS (
        INSERT INTO app_runtime_config_scope_changes (app_id, scope, changed_at)
        SELECT member.id, scopes.scope, clock_timestamp() FROM member, scopes
        ON CONFLICT (app_id, scope) DO UPDATE
            SET changed_at = greatest(app_runtime_config_scope_changes.changed_at, excluded.changed_at)
        RETURNING app_id, scope, changed_at
    )
    UPDATE snapshots SET stale = true
      FROM deployments d, stamped
     WHERE snapshots.deployment_id = d.id AND d.app_id = stamped.app_id
       AND coalesce(nullif(d.scope, ''), 'default') = stamped.scope
       AND NOT snapshots.stale AND snapshots.created_at <= stamped.changed_at;
    RETURN NULL;
END;
$$;


--
-- Name: project_event_routing_backlog_recipient(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_event_routing_backlog_recipient() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        PERFORM refresh_event_routing_backlog(OLD.outbox_id,OLD.subscription_id);
        RETURN OLD;
    END IF;
    PERFORM refresh_event_routing_backlog(NEW.outbox_id,NEW.subscription_id);
    RETURN NEW;
END;
$$;


--
-- Name: project_event_routing_backlog_root(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_event_routing_backlog_root() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE sub text;
BEGIN
    IF TG_OP='INSERT' THEN
        PERFORM refresh_event_routing_backlog(NEW.id);
    ELSIF (NEW.recipient_snapshot,NEW.state,NEW.available_at,NEW.lease_until,NEW.recipient_claims,NEW.created_at,NEW.account_id)
       IS DISTINCT FROM (OLD.recipient_snapshot,OLD.state,OLD.available_at,OLD.lease_until,OLD.recipient_claims,OLD.created_at,OLD.account_id) THEN
        PERFORM refresh_event_routing_backlog(NEW.id);
    ELSE
        FOR sub IN SELECT k FROM (
            SELECT jsonb_object_keys(NEW.recipient_progress) AS k
            UNION SELECT jsonb_object_keys(OLD.recipient_progress) AS k
        ) keys WHERE NEW.recipient_progress->k IS DISTINCT FROM OLD.recipient_progress->k ORDER BY k
        LOOP PERFORM refresh_event_routing_backlog(NEW.id,sub); END LOOP;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: project_release_member_policy_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_release_member_policy_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- The parent is inserted before its immutable members. Inactive retained
    -- graphs and stage graph publication cannot change ordinary ingress.
    IF EXISTS (SELECT 1 FROM project_release_sets
               WHERE id = NEW.release_id AND active AND environment_slug = 'production') THEN
        PERFORM record_project_release_policy_change(NEW.release_id, NEW.app_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: project_release_set_policy_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_release_set_policy_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE member_app uuid;
BEGIN
    IF OLD.environment_slug = 'production' THEN
        FOR member_app IN SELECT app_id FROM project_release_members WHERE release_id = OLD.id LOOP
            PERFORM record_project_release_policy_change(OLD.id, member_app);
        END LOOP;
    END IF;
    RETURN OLD;
END;
$$;


--
-- Name: protect_bound_multipart_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_bound_multipart_journal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM object_bucket_mutations WHERE multipart_upload_id=OLD.id) AND (
  (to_jsonb(NEW)-ARRAY['expires_at','provider_upload_id','size_bytes','part_count','part_revision','completion_parts','completion_if_match','completion_if_none_match','completion_error_code','completion_etag','completion_version_id','completion_recovery_cursor','completion_versions_observed','completion_dispatched','part_url_unsafe_until','lifecycle_scan_id','lifecycle_binding','state','lease_token','lease_until','attempt_count','retry_at','last_error_code','updated_at','encryption_lease_token','encryption_verified','protection_lease_token','protection_verified','checksum_snapshot','checksum_verified']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['expires_at','provider_upload_id','size_bytes','part_count','part_revision','completion_parts','completion_if_match','completion_if_none_match','completion_error_code','completion_etag','completion_version_id','completion_recovery_cursor','completion_versions_observed','completion_dispatched','part_url_unsafe_until','lifecycle_scan_id','lifecycle_binding','state','lease_token','lease_until','attempt_count','retry_at','last_error_code','updated_at','encryption_lease_token','encryption_verified','protection_lease_token','protection_verified','checksum_snapshot','checksum_verified']) OR
  (NEW.expires_at>OLD.expires_at) OR
  (NEW.provider_upload_id IS DISTINCT FROM OLD.provider_upload_id AND NOT (OLD.state='initiating' AND OLD.provider_upload_id='' AND NEW.state='active' AND NEW.provider_upload_id<>'')) OR
  (OLD.completion_dispatched AND (NEW.size_bytes IS DISTINCT FROM OLD.size_bytes OR NEW.completion_parts IS DISTINCT FROM OLD.completion_parts OR NEW.completion_if_match IS DISTINCT FROM OLD.completion_if_match OR NEW.completion_if_none_match IS DISTINCT FROM OLD.completion_if_none_match))
 ) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_bound_journal_immutable',MESSAGE='An original provider receipt cannot be reassigned to another session intent';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_bound_upload_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_bound_upload_journal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM object_bucket_mutations WHERE upload_id=OLD.id) AND
  ((to_jsonb(NEW)-ARRAY['route_id','status','etag','error_code','write_phase','recovery_token','recovery_lease_until','recovery_retry_at','recovery_cursor','recovery_versions_observed','version_id','protection_verified','protection_dispatched','encryption_dispatched','encryption_verified']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['route_id','status','etag','error_code','write_phase','recovery_token','recovery_lease_until','recovery_retry_at','recovery_cursor','recovery_versions_observed','version_id','protection_verified','protection_dispatched','encryption_dispatched','encryption_verified']) OR
   (NEW.route_id IS NOT NULL AND NEW.route_id IS DISTINCT FROM OLD.route_id)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_upload_bound_journal_immutable',MESSAGE='An original provider receipt cannot be reassigned to a different upload intent';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_financial_budget_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_financial_budget_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Account removal may erase its financial data; ordinary policy deletion
  -- is a revisioned tombstone and never removes the audit trail.
  IF TG_OP = 'DELETE' AND NOT EXISTS(SELECT 1 FROM resource_namespaces WHERE id = OLD.account_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'financial budget revisions are append-only';
END $$;


--
-- Name: protect_financial_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_financial_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND NOT EXISTS(SELECT 1 FROM resource_namespaces WHERE id = OLD.account_id) THEN RETURN OLD; END IF;
  IF TG_TABLE_NAME = 'financial_price_snapshots' AND TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'financial history is append-only';
END $$;


--
-- Name: protect_fixed_multipart_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_fixed_multipart_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.fixed_admission AND OLD.state NOT IN ('completed','aborted') THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_fixed_multipart_admission_fenced',MESSAGE='Live fixed multipart sessions cannot be removed';
  END IF;
  RETURN OLD;
 END IF;
 IF NEW.fixed_admission IS DISTINCT FROM OLD.fixed_admission OR
  (OLD.fixed_admission AND (NEW.id,NEW.account_id,NEW.app_id,NEW.bucket_id,NEW.object_key,NEW.size_bytes,NEW.part_size_bytes,NEW.part_count)
   IS DISTINCT FROM (OLD.id,OLD.account_id,OLD.app_id,OLD.bucket_id,OLD.object_key,OLD.size_bytes,OLD.part_size_bytes,OLD.part_count)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_fixed_multipart_admission_fenced',MESSAGE='Fixed multipart admission identity and layout are immutable';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_managed_postgres_accounting_reconciliation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_managed_postgres_accounting_reconciliation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM accounts WHERE id = OLD.account_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'managed postgres accounting reconciliation evidence is append-only';
END $$;


--
-- Name: protect_managed_postgres_usage_import(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_managed_postgres_usage_import() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM accounts WHERE id = OLD.account_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'managed postgres usage import evidence is append-only';
END $$;


--
-- Name: protect_object_bucket_encryption(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_bucket_encryption() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE b object_buckets;
BEGIN
 SELECT * INTO b FROM object_buckets WHERE id=coalesce(NEW.bucket_id,OLD.bucket_id);
 IF TG_OP='DELETE' THEN
  IF FOUND AND b.state NOT IN ('deleting','deleted') THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_bucket_encryption_fenced',MESSAGE='Clear policies without removing their revision tombstones';
  END IF;
  RETURN OLD;
 END IF;
 IF NOT FOUND OR (NEW.account_id,NEW.app_id) IS DISTINCT FROM (b.account_id,b.app_id) OR b.state<>'ready' OR
  EXISTS(SELECT 1 FROM object_deletions WHERE bucket_id=b.id AND state IN ('prepared','dispatched')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_bucket_encryption_fenced',MESSAGE='Encryption configuration requires an owned ready bucket';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.revision<>1 OR NEW.state<>'waiting' OR NEW.encryption_snapshot<>'{}' OR NEW.dispatched THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_bucket_encryption_fenced',MESSAGE='Encryption configuration requires a durable initial request';
  END IF;
  RETURN NEW;
 END IF;
 IF (NEW.bucket_id,NEW.account_id,NEW.app_id) IS DISTINCT FROM (OLD.bucket_id,OLD.account_id,OLD.app_id) OR
  NEW.revision<OLD.revision OR NEW.revision>OLD.revision+1 OR
  (NEW.revision<>OLD.revision AND (OLD.state<>'ready' OR NEW.state<>'waiting' OR NEW.dispatched)) OR
  (NEW.revision=OLD.revision AND (NEW.desired_snapshot IS DISTINCT FROM OLD.desired_snapshot OR (OLD.dispatched AND NOT NEW.dispatched))) OR
  (NEW.encryption_snapshot IS DISTINCT FROM OLD.encryption_snapshot AND NOT
   (OLD.state='applying' AND OLD.lease_until>clock_timestamp() AND NEW.state='ready' AND NEW.revision=OLD.revision AND NEW.encryption_snapshot=OLD.desired_snapshot)) OR
  (OLD.state<>'ready' AND NEW.state='ready' AND NOT
   (OLD.state='applying' AND OLD.lease_until>clock_timestamp() AND NEW.revision=OLD.revision AND NEW.encryption_snapshot=OLD.desired_snapshot)) OR
  (NEW.state='applying' AND NEW.lease_token IS DISTINCT FROM OLD.lease_token AND
   ((OLD.lease_until IS NOT NULL AND OLD.lease_until>clock_timestamp()) OR OLD.retry_at>clock_timestamp())) OR
  (NOT OLD.dispatched AND NEW.dispatched AND NOT (OLD.state='applying' AND NEW.state='applying' AND
   OLD.lease_token=NEW.lease_token AND OLD.lease_until>clock_timestamp())) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_bucket_encryption_fenced',MESSAGE='Encryption identity and leased configuration progress are immutable';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_bucket_encryption_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_bucket_encryption_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.state<>OLD.state AND NEW.state='deleting' AND EXISTS(SELECT 1 FROM object_bucket_encryption WHERE bucket_id=OLD.id AND state<>'ready') THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_bucket_encryption_fenced',MESSAGE='Drain encryption configuration before deleting a bucket';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_bucket_object_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_bucket_object_lock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE b object_buckets;
BEGIN
 SELECT * INTO b FROM object_buckets WHERE id=coalesce(NEW.bucket_id,OLD.bucket_id) FOR NO KEY UPDATE;
 IF TG_OP='DELETE' THEN
  IF FOUND AND b.state<>'deleted' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Preserve permanent Object Lock history until physical bucket deletion'; END IF;
  RETURN OLD;
 END IF;
 IF NOT FOUND OR b.state<>'ready' OR (NEW.account_id,NEW.app_id) IS DISTINCT FROM (b.account_id,b.app_id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Object Lock configuration requires an owned ready bucket';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.revision>1 OR NEW.state='applying' OR NEW.dispatched THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Object Lock requires an initial observation or durable request';
  END IF;
 ELSE
  IF (NEW.bucket_id,NEW.account_id,NEW.app_id) IS DISTINCT FROM (OLD.bucket_id,OLD.account_id,OLD.app_id)
   OR (OLD.enabled_required AND NOT NEW.enabled_required) OR (OLD.native_enabled_observed AND NOT NEW.native_enabled_observed)
   OR NEW.revision<OLD.revision OR NEW.revision>OLD.revision+1
   OR (NEW.revision=OLD.revision AND (NEW.desired_snapshot IS DISTINCT FROM OLD.desired_snapshot OR (OLD.dispatched AND NOT NEW.dispatched)))
   OR (NEW.revision<>OLD.revision AND (NEW.state<>'waiting' OR NEW.dispatched OR
    (OLD.state<>'ready' AND NOT (OLD.revision=0 AND OLD.desired_snapshot='null' AND (OLD.lease_until IS NULL OR OLD.lease_until<=clock_timestamp())))))
   OR (NEW.state='applying' AND NEW.lease_token IS DISTINCT FROM OLD.lease_token AND
    ((OLD.lease_until IS NOT NULL AND OLD.lease_until>clock_timestamp()) OR OLD.retry_at>clock_timestamp()))
   OR (OLD.state<>'ready' AND NEW.state='ready' AND NOT
    (OLD.state='applying' AND OLD.lease_until>clock_timestamp() AND NEW.revision=OLD.revision))
   OR (NOT OLD.dispatched AND NEW.dispatched AND NOT
    (OLD.state='applying' AND NEW.state='applying' AND OLD.lease_token=NEW.lease_token AND OLD.lease_until>clock_timestamp())) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Object Lock intent, enablement history and leased progress are immutable';
  END IF;
 END IF;
 IF (NEW.enabled_required OR NEW.desired_snapshot<>'null' OR NOT NEW.observed_known) AND
  (NEW.state='applying' OR NEW.state='ready' AND (TG_OP='INSERT' OR OLD.state<>'ready')) AND
  (NOT object_lock_drained(NEW.bucket_id) OR NEW.enabled_required AND NOT object_lock_versioning_ready(NEW.bucket_id)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Object Lock requires drained transfers and verified Enabled versioning';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_bucket_versioning(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_bucket_versioning() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.bucket_id<>OLD.bucket_id OR NEW.revision<OLD.revision OR NEW.revision>OLD.revision+1
   OR (NEW.revision<>OLD.revision AND OLD.state<>'ready' AND NOT (
    OLD.desired_status='Suspended' AND NEW.desired_status='Enabled' AND NEW.observed_status='Enabled'
    AND NEW.versions_required AND NOT NEW.dispatched AND NEW.lease_token='' AND NEW.lease_until IS NULL
    AND NEW.propagation_until>=clock_timestamp()+interval '14 minutes'
    AND (OLD.state<>'inventory' OR (NEW.state='inventory' AND NEW.capacity_job_id=OLD.capacity_job_id))
    AND EXISTS(SELECT 1 FROM object_bucket_object_lock l WHERE l.bucket_id=NEW.bucket_id AND l.native_enabled_observed)))
   OR (NEW.desired_status<>OLD.desired_status AND NEW.revision<>OLD.revision+1)
   OR (NEW.revision=OLD.revision AND OLD.dispatched AND NOT NEW.dispatched) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Versioning transition identity cannot change';
  END IF;
  NEW.versions_required:=OLD.versions_required OR NEW.versions_required;
 END IF;
 IF NEW.versions_required AND NEW.state='ready' AND (TG_OP='INSERT' OR OLD.state<>'ready') AND NOT EXISTS(
  SELECT 1 FROM object_storage_capacity_reconciliations c WHERE c.id=NEW.capacity_job_id AND c.bucket_id=NEW.bucket_id
  AND c.state='completed' AND c.inventory_scope='all_versions' AND c.inventory_verified AND c.created_at>=NEW.propagation_until AND NEW.propagation_until<=now()
 ) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Versioning cutover requires propagated configuration and verified version inventory'; END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_copy_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_copy_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.source_bucket_id IS NOT NULL AND
  (NEW.id,NEW.account_id,NEW.app_id,NEW.bucket_id,NEW.subject_id,NEW.origin,NEW.object_key,NEW.bytes) IS DISTINCT FROM
  (OLD.id,OLD.account_id,OLD.app_id,OLD.bucket_id,OLD.subject_id,OLD.origin,OLD.object_key,OLD.bytes) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Cross-copy receipt ownership is immutable';
 END IF;
 IF TG_OP='UPDATE' AND (NEW.source_bucket_id,NEW.source_copy_grant_id,NEW.source_key,NEW.source_etag)
  IS DISTINCT FROM (OLD.source_bucket_id,OLD.source_copy_grant_id,OLD.source_key,OLD.source_etag) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Copy receipt source is immutable';
 END IF;
 IF NEW.source_bucket_id IS NOT NULL AND (TG_OP='INSERT' OR
  (OLD.write_phase='prepared' AND NEW.write_phase='dispatched')) THEN
  PERFORM assert_object_copy_source_authority(NEW.account_id,NEW.bucket_id,NEW.subject_id,
   NEW.source_bucket_id,NEW.source_key,NEW.source_copy_grant_id);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_default_legacy_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_default_legacy_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_TABLE_NAME='object_storage_key_grants' THEN
  IF NEW.last_write_id IS NULL THEN PERFORM require_object_bucket_default(NEW.bucket_id,'{}',0); END IF;
 ELSE
  IF NEW.kind='proxy' AND NOT NEW.route_receipt THEN PERFORM require_object_bucket_default(NEW.bucket_id,'{}',0); END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_default_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_default_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.encryption_default_revision IS DISTINCT FROM OLD.encryption_default_revision THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_bucket_default_fenced',MESSAGE='Captured default revisions are immutable';
  END IF;
 ELSE
  IF TG_TABLE_NAME<>'object_upload_completions' THEN
   PERFORM require_object_bucket_default(NEW.bucket_id,NEW.encryption_snapshot,NEW.encryption_default_revision);
  ELSIF NEW.status<>'rejected' THEN
   PERFORM require_object_bucket_default(NEW.bucket_id,NEW.encryption_snapshot,NEW.encryption_default_revision);
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.id<>OLD.id OR NEW.bucket_id<>OLD.bucket_id OR NEW.object_key<>OLD.object_key OR NEW.selector<>OLD.selector
  OR NEW.created_at<>OLD.created_at OR NEW.provider_status<>OLD.provider_status OR NEW.reserved_bytes<>OLD.reserved_bytes
  OR NEW.target_provider_version_id<>OLD.target_provider_version_id
  OR (OLD.recovery_claimed AND NOT NEW.recovery_claimed)
  OR (OLD.state<>'prepared' AND NEW.baseline<>OLD.baseline)
  OR (OLD.state='dispatched' AND NEW.state NOT IN ('dispatched','completed') AND NOT (NEW.state='failed' AND NEW.last_error_code='provider_rejected' AND NOT OLD.recovery_claimed))
  OR OLD.state IN ('completed','failed') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Deletion identity and dispatched attempt are immutable';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_event_hold_baseline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_event_hold_baseline() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.event_hold_baseline IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Event hold baseline requires a live worker lease'; END IF;
 ELSIF NEW.event_hold_baseline IS DISTINCT FROM OLD.event_hold_baseline THEN
  IF OLD.event_hold_baseline IS NOT NULL OR OLD.dispatched OR NEW.dispatched OR OLD.state<>'applying' OR NEW.state<>'applying'
   OR OLD.lease_token='' OR NEW.lease_token<>OLD.lease_token OR OLD.lease_until<=clock_timestamp() THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Preserve immutable event hold baseline';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_lifecycle_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_lifecycle_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.bucket_id<>OLD.bucket_id OR NEW.revision<OLD.revision OR NEW.revision>OLD.revision+1
  OR (NEW.rules<>OLD.rules AND NEW.revision<>OLD.revision+1)
  OR (NEW.revision<>OLD.revision AND EXISTS(SELECT 1 FROM object_lifecycle_scans WHERE bucket_id=NEW.bucket_id AND state='scanning' AND lease_until>clock_timestamp())) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Lifecycle policy identity or a live scan lease prevents replacement';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_lifecycle_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_lifecycle_scan() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.id<>OLD.id OR NEW.bucket_id<>OLD.bucket_id OR NEW.revision<>OLD.revision
  OR NEW.rules<>OLD.rules OR NEW.created_at<>OLD.created_at
  OR NEW.scanned_keys<OLD.scanned_keys OR NEW.scanned_keys>OLD.scanned_keys+1
  OR (NEW.last_key IS DISTINCT FROM OLD.last_key AND (OLD.phase<>'objects' OR NEW.last_key COLLATE "C"<=OLD.last_key COLLATE "C" OR NEW.scanned_keys<>OLD.scanned_keys+1))
  OR (NEW.last_key=OLD.last_key AND NEW.scanned_keys<>OLD.scanned_keys)
  OR NEW.scanned_uploads<OLD.scanned_uploads OR NEW.scanned_uploads>OLD.scanned_uploads+1
  OR (NEW.last_upload_id IS DISTINCT FROM OLD.last_upload_id AND (OLD.phase<>'multipart' OR NEW.last_upload_id IS NULL OR NEW.last_upload_id<=OLD.last_upload_id OR NEW.scanned_uploads<>OLD.scanned_uploads+1))
  OR (NEW.last_upload_id IS NOT DISTINCT FROM OLD.last_upload_id AND NEW.scanned_uploads<>OLD.scanned_uploads)
  OR (NEW.phase<>OLD.phase AND (OLD.phase<>'objects' OR NEW.phase<>'multipart'
   OR NEW.last_key<>OLD.last_key OR NEW.scanned_keys<>OLD.scanned_keys OR NEW.scanned_uploads<>OLD.scanned_uploads
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(OLD.rules) r WHERE r->>'status'='Enabled' AND r ? 'abort_incomplete_multipart_days')))
  OR (OLD.state<>'scanning' AND NEW IS DISTINCT FROM OLD) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Lifecycle scan identity and progress cannot be rewritten';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_lock_bucket_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_lock_bucket_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM object_bucket_object_lock WHERE bucket_id=OLD.id) THEN
  IF TG_OP='DELETE' THEN
   IF OLD.state<>'deleted' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Object Lock history requires confirmed physical bucket deletion'; END IF;
   RETURN OLD;
  END IF;
  IF (NEW.id,NEW.account_id,NEW.app_id,NEW.backend_id,NEW.backend_fingerprint,NEW.physical_name) IS DISTINCT FROM
   (OLD.id,OLD.account_id,OLD.app_id,OLD.backend_id,OLD.backend_fingerprint,OLD.physical_name) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Object Lock ownership and native placement are immutable';
  END IF;
  IF NEW.state='deleted' AND OLD.state<>'deleted' AND
   (OLD.state<>'deleting' OR OLD.lease_until IS NULL OR OLD.lease_until<=clock_timestamp()) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Object Lock bucket deletion requires its active native deletion lease';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_multipart_copy_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_multipart_copy_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE u object_storage_multipart_uploads;
BEGIN
 IF TG_OP='UPDATE' AND
  (NEW.source_bucket_id,NEW.source_copy_grant_id,NEW.source_subject_id,NEW.source_key) IS DISTINCT FROM
  (OLD.source_bucket_id,OLD.source_copy_grant_id,OLD.source_subject_id,OLD.source_key) AND
  (NEW.transfer_token IS NULL OR NEW.transfer_token IS NOT DISTINCT FROM OLD.transfer_token) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Dispatched part copy source is immutable';
 END IF;
 IF NEW.source_bucket_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.transfer_token IS DISTINCT FROM OLD.transfer_token) AND NEW.transfer_token IS NOT NULL THEN
  SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.upload_id;
  IF u.id IS NULL OR u.state<>'active' OR u.expires_at<=clock_timestamp() OR NEW.source_bucket_id=u.bucket_id THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Copy destination session is unavailable';
  END IF;
  PERFORM assert_object_copy_source_authority(u.account_id,u.bucket_id,NEW.source_subject_id,
   NEW.source_bucket_id,NEW.source_key,NEW.source_copy_grant_id);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_multipart_encryption(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_multipart_encryption() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.encryption_snapshot<>'{}' AND (NEW.state<>'initiating' OR NEW.lease_token IS NOT NULL OR NEW.encryption_lease_token<>'' OR NEW.encryption_verified) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Encrypted multipart requires an initiating intent';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.encryption_snapshot IS DISTINCT FROM OLD.encryption_snapshot OR
  (OLD.encryption_snapshot<>'{}' AND (NEW.id,NEW.account_id,NEW.app_id,NEW.bucket_id,NEW.object_key)
   IS DISTINCT FROM (OLD.id,OLD.account_id,OLD.app_id,OLD.bucket_id,OLD.object_key)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart encryption identity is immutable';
 END IF;
 IF OLD.encryption_snapshot<>'{}' THEN
  IF NEW.lease_token IS NOT NULL AND NEW.encryption_lease_token IS DISTINCT FROM NEW.lease_token THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Encrypted multipart requires a cipher-aware claimant';
  END IF;
  IF NEW.encryption_verified IS DISTINCT FROM OLD.encryption_verified AND NOT
   (OLD.state IN ('completing','completing_conditional') AND NEW.state='completed' AND OLD.completion_dispatched AND NEW.encryption_verified) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Encrypted multipart requires verified completion';
  END IF;
 END IF;
 IF NEW.lease_token IS NULL THEN NEW.encryption_lease_token:=''; END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_multipart_initiation_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_multipart_initiation_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE d object_multipart_initiation_dispatches%ROWTYPE;
BEGIN
 SELECT * INTO d FROM object_multipart_initiation_dispatches WHERE multipart_upload_id=OLD.id;
 IF d.multipart_upload_id IS NOT NULL AND OLD.state='initiating' AND (NEW.size_bytes IS DISTINCT FROM OLD.size_bytes OR NEW.part_count IS DISTINCT FROM OLD.part_count) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_intent',MESSAGE='Original initiation layout cannot change between authority checks and dispatch';
 END IF;
 IF d.dispatched AND d.dispatch_token<>'' AND NEW.provider_upload_id IS DISTINCT FROM OLD.provider_upload_id AND (
  OLD.state<>'initiating' OR NEW.state<>'active' OR OLD.lease_token IS NULL OR OLD.lease_until IS NULL OR OLD.lease_until<=clock_timestamp() OR d.provider_upload_id='' OR NEW.provider_upload_id<>d.provider_upload_id
 ) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_positive_result',MESSAGE='Activate only the durably observed original initiation reply';
 END IF;
 IF d.dispatched AND d.provider_upload_id='' AND OLD.provider_upload_id='' AND NEW.state IN ('completed','aborted') THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_uncertain',MESSAGE='An uncertain initiation cannot be settled by an empty listing or a timeout';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_multipart_part_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_multipart_part_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF (NEW.state IN ('completed','aborted') AND EXISTS(SELECT 1 FROM object_multipart_part_writers WHERE upload_id=OLD.id AND dispatched AND NOT settled)) OR (EXISTS(SELECT 1 FROM object_multipart_part_writers WHERE upload_id=OLD.id AND NOT settled) AND (
  (NEW.account_id,NEW.app_id,NEW.bucket_id,NEW.object_key,NEW.provider_upload_id,NEW.encryption_snapshot,NEW.protection_snapshot) IS DISTINCT FROM
  (OLD.account_id,OLD.app_id,OLD.bucket_id,OLD.object_key,OLD.provider_upload_id,OLD.encryption_snapshot,OLD.protection_snapshot)
 )) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Uncertain independent writers retain their original parent intent';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_multipart_part_transfer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_multipart_part_transfer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'INSERT' AND EXISTS(SELECT 1 FROM object_multipart_part_writers WHERE upload_id=OLD.upload_id AND part_number=OLD.part_number AND transfer_token=OLD.transfer_token AND dispatched AND NOT settled) AND (TG_OP='DELETE' OR NEW IS DISTINCT FROM OLD) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='An uncertain dispatched transfer cannot expire, change or be replaced';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_multipart_part_url_deadline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_multipart_part_url_deadline() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.part_url_unsafe_until IS DISTINCT FROM OLD.part_url_unsafe_until
  AND (OLD.state<>'active' OR NEW.state<>'active' OR NEW.part_url_unsafe_until IS NULL
   OR (OLD.part_url_unsafe_until IS NOT NULL AND NEW.part_url_unsafe_until<OLD.part_url_unsafe_until)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart part URL cleanup deadline cannot be shortened or changed after admission';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_multipart_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_multipart_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.completion_etag<>'' OR NEW.completion_version_id<>'' OR NEW.completion_recovery_cursor<>'' OR NEW.completion_dispatched OR NEW.completion_versions_observed THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart result requires a dispatched completion';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.completion_dispatched AND NOT NEW.completion_dispatched THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart dispatch cannot be forgotten';
 END IF;
 IF NOT OLD.completion_dispatched AND NEW.completion_dispatched
  AND NOT (OLD.state IN ('completing','completing_conditional') AND NEW.state=OLD.state) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart dispatch requires a completing intent';
 END IF;
 IF (NEW.completion_etag IS DISTINCT FROM OLD.completion_etag OR NEW.completion_version_id IS DISTINCT FROM OLD.completion_version_id)
  AND NOT (OLD.state IN ('completing','completing_conditional') AND NEW.state='completed' AND OLD.completion_dispatched) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart result is immutable';
 END IF;
 IF NEW.completion_version_id<>'' AND NOT EXISTS(SELECT 1 FROM object_version_references v WHERE v.bucket_id=NEW.bucket_id AND v.object_key=NEW.object_key
  AND ((NEW.completion_version_id='null' AND v.native_version_id='null') OR (v.id::text=NEW.completion_version_id AND v.native_version_id<>'null'))) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart version must belong to its bucket and key';
 END IF;
 NEW.completion_versions_observed:=OLD.completion_versions_observed OR NEW.completion_versions_observed;
 RETURN NEW;
END $$;


--
-- Name: protect_object_multipart_url_credential(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_multipart_url_credential() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE u object_storage_multipart_uploads;
BEGIN
 IF NEW.url_request ? 'multipart' THEN
  SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=(NEW.url_request->'multipart'->>'upload_id')::uuid FOR UPDATE;
  IF NOT FOUND OR NOT object_url_multipart_matches(NEW,u) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Multipart URL requires its active owned fixed session';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_multipart_url_part(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_multipart_url_part() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE u object_storage_multipart_uploads; c object_storage_s3_credentials; dispatch boolean;
BEGIN
 SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.upload_id FOR UPDATE;
 IF u.part_count=0 THEN
  IF NEW.max_bytes<1 OR NEW.url_credential_id IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Dynamic multipart parts require their capacity grant';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.max_bytes<>0 OR NEW.url_credential_id IS NULL OR NOT NEW.cleanup_tracked OR NEW.part_number>u.part_count THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Fixed multipart transfers use their existing full-object reservation';
 END IF;
 dispatch:=NEW.transfer_token IS NOT NULL;
 IF TG_OP='UPDATE' THEN
  IF (NEW.upload_id,NEW.part_number) IS DISTINCT FROM (OLD.upload_id,OLD.part_number) OR
   (NEW.transfer_token IS NOT DISTINCT FROM OLD.transfer_token AND NEW.url_credential_id IS DISTINCT FROM OLD.url_credential_id) OR
   (NEW.transfer_token IS NULL AND NEW.url_credential_id IS DISTINCT FROM OLD.url_credential_id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Multipart transfer identity is immutable';
  END IF;
  dispatch:=NEW.transfer_token IS NOT NULL AND NEW.transfer_token IS DISTINCT FROM OLD.transfer_token;
  IF dispatch AND OLD.transfer_token IS NOT NULL AND OLD.unsafe_until>clock_timestamp() THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Multipart part already has an unsafe native attempt';
  END IF;
  IF NOT dispatch AND NEW.transfer_token IS NOT NULL AND NEW.unsafe_until IS DISTINCT FROM OLD.unsafe_until THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Multipart transfer deadline cannot change';
  END IF;
 END IF;
 IF dispatch THEN
  SELECT * INTO c FROM object_storage_s3_credentials WHERE id=NEW.url_credential_id;
  IF NOT FOUND OR NOT object_url_multipart_matches(c,u) OR (c.url_request->'multipart'->>'part_number')::int<>NEW.part_number OR NEW.unsafe_until<clock_timestamp()+interval '35 minutes' THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Multipart part requires current fixed URL dispatch authority';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_multipart_url_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_multipart_url_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.part_count>0 AND NEW.state IN ('completing','completing_conditional','completed','aborted') AND
  EXISTS(SELECT 1 FROM object_storage_multipart_part_grants WHERE upload_id=NEW.id AND transfer_token IS NOT NULL AND unsafe_until>clock_timestamp()) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Fixed multipart transitions must drain native attempts';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_route_encryption_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_route_encryption_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE r object_upload_routes;
BEGIN
 IF NEW.route_id IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO r FROM object_upload_routes WHERE id=NEW.route_id FOR SHARE;
 IF NOT FOUND THEN RETURN NEW; END IF;
 IF (NEW.write_phase='prepared' AND
   ((r.encryption_snapshot<>'{}' AND (NEW.encryption_snapshot IS DISTINCT FROM r.encryption_snapshot OR NEW.encryption_default_revision<>0)) OR
    (r.encryption_snapshot='{}' AND NEW.encryption_snapshot<>'{}' AND NEW.encryption_default_revision=0))) OR
  (r.encryption_snapshot<>'{}' AND NEW.status<>'rejected' AND
   ((NEW.account_id,NEW.app_id,NEW.bucket_id) IS DISTINCT FROM (r.account_id,r.app_id,r.bucket_id) OR
    NEW.encryption_snapshot IS DISTINCT FROM r.encryption_snapshot OR NEW.encryption_default_revision<>0 OR NEW.write_phase<>'prepared' OR NEW.status<>'pending')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_upload_route_encryption_fenced',MESSAGE='Route writes require the current captured encryption policy';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_s3_copy_source_epoch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_s3_copy_source_epoch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' OR EXISTS(SELECT 1 FROM resource_namespaces WHERE id=OLD.account_id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Published copy source identities are immutable';
 END IF;
 RETURN OLD;
END $$;


--
-- Name: protect_object_s3_copy_source_grant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_s3_copy_source_grant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE c object_storage_s3_credentials; d object_buckets; s object_buckets;
BEGIN
 SELECT * INTO c FROM object_storage_s3_credentials WHERE id=NEW.credential_id FOR NO KEY UPDATE;
 IF NOT FOUND OR c.account_id<>NEW.account_id OR c.bucket_id<>NEW.bucket_id OR
 c.status<>'active' OR c.permission NOT IN ('write','read_write') OR c.url_request IS NOT NULL OR c.rotation_parent_id IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Copy source grants require an owned destination writer';
 END IF;
 SELECT * INTO d FROM object_buckets WHERE id=NEW.bucket_id;
 SELECT * INTO s FROM object_buckets WHERE id=NEW.source_bucket_id;
 IF d.id IS NULL OR s.id IS NULL OR d.account_id<>NEW.account_id OR s.account_id<>NEW.account_id OR
 d.state<>'ready' OR s.state<>'ready' OR (d.backend_id,d.backend_fingerprint) IS DISTINCT FROM (s.backend_id,s.backend_fingerprint) OR
 EXISTS(SELECT 1 FROM object_deletions WHERE bucket_id IN (d.id,s.id) AND state IN ('prepared','dispatched')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Copy sources require owned ready buckets on one placement';
 END IF;
 IF TG_OP='UPDATE' THEN
  IF (NEW.account_id,NEW.credential_id,NEW.bucket_id,NEW.source_bucket_id,NEW.created_at) IS DISTINCT FROM
   (OLD.account_id,OLD.credential_id,OLD.bucket_id,OLD.source_bucket_id,OLD.created_at) OR
   (NEW.prefix IS DISTINCT FROM OLD.prefix AND NEW.id=OLD.id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Copy source ownership and grant epochs are immutable';
  END IF;
 ELSIF NOT EXISTS(SELECT 1 FROM object_s3_copy_source_grants WHERE credential_id=c.id AND source_bucket_id=s.id) AND
  (SELECT count(*) FROM object_s3_copy_source_grants WHERE credential_id=c.id)>=32 THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Copy source grant limit exceeded';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_upload_encryption(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_upload_encryption() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.encryption_snapshot<>'{}' AND (NEW.write_phase<>'prepared' OR NEW.status<>'pending' OR NEW.encryption_dispatched OR NEW.encryption_verified) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Encrypted write requires a prepared intent';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.encryption_snapshot IS DISTINCT FROM OLD.encryption_snapshot OR
  (OLD.encryption_snapshot<>'{}' AND (NEW.id,NEW.account_id,NEW.app_id,NEW.bucket_id,NEW.object_key,NEW.bytes,NEW.origin,NEW.source_key,NEW.source_etag)
   IS DISTINCT FROM (OLD.id,OLD.account_id,OLD.app_id,OLD.bucket_id,OLD.object_key,OLD.bytes,OLD.origin,OLD.source_key,OLD.source_etag)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Write encryption identity is immutable';
 END IF;
 IF OLD.encryption_snapshot<>'{}' THEN
  IF (OLD.encryption_dispatched AND NOT NEW.encryption_dispatched) OR
   (NEW.write_phase='dispatched' AND NOT NEW.encryption_dispatched) OR
   (NOT OLD.encryption_dispatched AND NEW.encryption_dispatched AND NOT (OLD.write_phase='prepared' AND NEW.write_phase='dispatched')) OR
   (NEW.encryption_verified IS DISTINCT FROM OLD.encryption_verified AND NOT (OLD.write_phase='dispatched' AND NEW.write_phase='settled' AND NEW.status='completed' AND NEW.encryption_verified)) OR
   (OLD.write_phase='settled' AND (NEW.status,NEW.etag,NEW.error_code,NEW.version_id) IS DISTINCT FROM (OLD.status,OLD.etag,OLD.error_code,OLD.version_id)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Encrypted write requires verified dispatch and settlement';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_url_credential(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_url_credential() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.url_request,NEW.url_api_key_id,NEW.url_expires_at,NEW.url_receipt_id) IS DISTINCT FROM (OLD.url_request,OLD.url_api_key_id,OLD.url_expires_at,OLD.url_receipt_id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed URL authority is immutable';
 END IF;
 IF NEW.url_request IS NOT NULL THEN
  IF TG_OP='INSERT' AND NOT object_url_issuer_live(NEW.account_id,NEW.bucket_id,NEW.url_api_key_id,NEW.permission,NEW.url_expires_at) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed URL requires a live owned issuer';
  END IF;
  IF TG_OP='UPDATE' AND (NEW.id,NEW.account_id,NEW.bucket_id,NEW.access_key_id,NEW.permission,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.account_id,OLD.bucket_id,OLD.access_key_id,OLD.permission,OLD.created_at) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed URL signing identity is immutable';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status='revoked' AND NEW.status<>'revoked' THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed URL revocation is final';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_url_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_url_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE c object_storage_s3_credentials;
BEGIN
 IF TG_OP='UPDATE' THEN
  SELECT * INTO c FROM object_storage_s3_credentials WHERE id::text=OLD.subject_id AND url_request IS NOT NULL;
 ELSE
  SELECT * INTO c FROM object_storage_s3_credentials WHERE id::text=NEW.subject_id AND url_request IS NOT NULL;
 END IF;
 IF NOT FOUND THEN RETURN NEW; END IF;
 IF c.id::text<>NEW.subject_id OR c.url_receipt_id IS NULL OR c.url_receipt_id<>NEW.id OR c.account_id<>NEW.account_id OR c.bucket_id<>NEW.bucket_id OR NEW.origin<>'gateway' OR NEW.route_id IS NOT NULL OR
  NEW.object_key<>c.url_request->>'key' OR NEW.bytes<>(c.url_request->>'size_bytes')::bigint OR
  NEW.content_type<>coalesce(c.url_request->>'content_type','') OR
  coalesce(NEW.encryption_snapshot->'selection','{}')<>coalesce(c.url_request->'encryption','{}') THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed URL requires its bound write receipt';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.write_phase<>'prepared' OR NEW.status<>'pending' THEN RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed URL requires a prepared write'; END IF;
  NEW.recovery_retry_at:=c.url_expires_at;
 ELSE
  IF (NEW.id,NEW.account_id,NEW.app_id,NEW.bucket_id,NEW.subject_id,NEW.object_key,NEW.bytes,NEW.content_type,NEW.origin,NEW.encryption_snapshot) IS DISTINCT FROM
   (OLD.id,OLD.account_id,OLD.app_id,OLD.bucket_id,OLD.subject_id,OLD.object_key,OLD.bytes,OLD.content_type,OLD.origin,OLD.encryption_snapshot) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed URL write identity is immutable';
  END IF;
  IF (OLD.write_phase='dispatched' AND NEW.write_phase NOT IN ('dispatched','settled')) OR (OLD.write_phase='prepared' AND NEW.write_phase NOT IN ('prepared','dispatched','settled')) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed URL write phases cannot rewind';
  END IF;
  IF NEW.write_phase='dispatched' AND OLD.write_phase<>'dispatched' AND
   (OLD.write_phase<>'prepared' OR c.status<>'active' OR NOT object_url_issuer_live(c.account_id,c.bucket_id,c.url_api_key_id,c.permission,c.url_expires_at)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed URL dispatch authority expired or revoked';
  END IF;
  IF OLD.write_phase='prepared' AND NEW.write_phase='prepared' AND NEW.recovery_retry_at IS DISTINCT FROM c.url_expires_at THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed URL preparation lasts until URL expiry';
  END IF;
  IF OLD.write_phase='settled' AND (NEW.write_phase,NEW.status,NEW.etag,NEW.error_code,NEW.version_id) IS DISTINCT FROM (OLD.write_phase,OLD.status,OLD.etag,OLD.error_code,OLD.version_id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_url_capability_fenced',MESSAGE='Signed URL terminal result is immutable';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_version_protection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_version_protection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE b object_buckets; owner uuid;
BEGIN
 -- The admission/cascade boundary uses account-before-bucket locking.
 SELECT account_id INTO owner FROM object_buckets WHERE id=coalesce(NEW.bucket_id,OLD.bucket_id);
 PERFORM 1 FROM resource_namespaces WHERE id=owner FOR UPDATE;
 SELECT * INTO b FROM object_buckets WHERE id=coalesce(NEW.bucket_id,OLD.bucket_id) FOR NO KEY UPDATE;
 IF TG_OP='DELETE' THEN
  IF FOUND AND b.state<>'deleted' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Preserve protection receipts until physical bucket deletion'; END IF;
  RETURN OLD;
 END IF;
 IF NOT FOUND OR b.state<>'ready' OR (NEW.account_id,NEW.app_id) IS DISTINCT FROM (b.account_id,b.app_id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Protection requires an owned ready bucket';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'waiting' OR NEW.dispatched OR NOT object_lock_versioning_ready(NEW.bucket_id) OR NOT object_lock_drained(NEW.bucket_id)
   OR NOT EXISTS(SELECT 1 FROM object_bucket_object_lock WHERE bucket_id=NEW.bucket_id AND state='ready' AND observed_known AND native_enabled_observed AND observed_snapshot->>'enabled'='true')
   OR EXISTS(SELECT 1 FROM object_deletions WHERE bucket_id=NEW.bucket_id AND state IN ('prepared','dispatched'))
   OR EXISTS(SELECT 1 FROM object_bucket_encryption WHERE bucket_id=NEW.bucket_id AND state<>'ready') THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Protection requires verified Object Lock and drained mutations';
  END IF;
  IF NEW.public_version_id<>'null' AND NOT EXISTS(SELECT 1 FROM object_version_references WHERE id=NEW.public_version_id::uuid AND bucket_id=NEW.bucket_id AND object_key=NEW.object_key AND native_version_id=NEW.native_version_id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Protection requires an owned exact version';
  END IF;
 ELSE
  IF (NEW.id,NEW.bucket_id,NEW.account_id,NEW.app_id,NEW.object_key,NEW.public_version_id,NEW.native_version_id,NEW.intent,NEW.created_at)
   IS DISTINCT FROM (OLD.id,OLD.bucket_id,OLD.account_id,OLD.app_id,OLD.object_key,OLD.public_version_id,OLD.native_version_id,OLD.intent,OLD.created_at)
   OR OLD.state IN ('ready','failed') OR OLD.dispatched AND NOT NEW.dispatched
   OR NEW.state='applying' AND NEW.lease_token<>OLD.lease_token AND (OLD.lease_until>clock_timestamp() OR OLD.retry_at>clock_timestamp())
   OR NOT OLD.dispatched AND NEW.dispatched AND NOT (OLD.state='applying' AND NEW.state='applying' AND OLD.lease_token=NEW.lease_token AND OLD.lease_until>clock_timestamp())
   OR NEW.state IN ('ready','failed') AND NOT (OLD.state='applying' AND OLD.lease_until>clock_timestamp())
   OR NEW.state='failed' AND OLD.dispatched AND NEW.last_error_code<>'provider_rejected' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Protection intent and leased progress are immutable';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: protect_object_version_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_version_reference() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM object_buckets WHERE id=OLD.bucket_id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Version references remain until bucket deletion';
  END IF;
  RETURN OLD;
 END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.bucket_id IS DISTINCT FROM OLD.bucket_id OR NEW.object_key IS DISTINCT FROM OLD.object_key OR NEW.native_version_id IS DISTINCT FROM OLD.native_version_id THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Version reference identity is immutable';
 END IF;
 NEW.versions_observed:=OLD.versions_observed OR NEW.versions_observed;
 RETURN NEW;
END $$;


--
-- Name: protect_object_write_protection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_object_write_protection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE j object_bucket_object_lock; protected boolean; url_request jsonb;
BEGIN
 IF TG_OP='INSERT' THEN
  PERFORM 1 FROM resource_namespaces WHERE id=NEW.account_id FOR UPDATE;
  PERFORM 1 FROM object_buckets WHERE id=NEW.bucket_id FOR NO KEY UPDATE;
  SELECT * INTO j FROM object_bucket_object_lock WHERE bucket_id=NEW.bucket_id;
  protected := FOUND AND (j.enabled_required OR j.native_enabled_observed OR j.observed_snapshot->>'enabled'='true');
  IF TG_TABLE_NAME='object_upload_completions' THEN
   IF NEW.status='rejected' AND NEW.protection_snapshot='{}' THEN RETURN NEW; END IF;
   SELECT c.url_request INTO url_request FROM object_storage_s3_credentials c WHERE c.id::text=NEW.subject_id AND c.url_request IS NOT NULL;
   IF FOUND AND coalesce(url_request->'protection','{}'::jsonb) IS DISTINCT FROM coalesce(NEW.protection_snapshot->'requested','{}'::jsonb) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Signed URL protection requires its bound receipt'; END IF;
  END IF;
  IF protected OR NEW.protection_snapshot<>'{}' THEN
   IF NOT protected OR j.state<>'ready' OR NOT j.observed_known OR j.observed_snapshot->>'enabled' IS DISTINCT FROM 'true' OR
    NOT object_lock_versioning_ready(NEW.bucket_id) OR NEW.protection_snapshot='{}' OR
    coalesce((NEW.protection_snapshot->>'revision')::bigint,0)<>j.revision OR
    coalesce(NEW.protection_snapshot->'default_retention','null'::jsonb) IS DISTINCT FROM coalesce(j.observed_snapshot->'default_retention','null'::jsonb) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='New writes require the admitted Object Lock policy';
   END IF;
   IF TG_TABLE_NAME='object_upload_completions' THEN
    IF NEW.status<>'pending' OR NEW.write_phase<>'prepared' OR NEW.protection_dispatched OR NEW.protection_verified THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Protected write requires a prepared intent'; END IF;
   ELSE
    IF NEW.state<>'initiating' OR NEW.lease_token IS NOT NULL OR NEW.protection_lease_token<>'' OR NEW.protection_verified THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Protected multipart requires an initiating intent'; END IF;
   END IF;
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.protection_snapshot IS DISTINCT FROM OLD.protection_snapshot OR (OLD.protection_snapshot<>'{}' AND
  (NEW.id,NEW.account_id,NEW.app_id,NEW.bucket_id,NEW.object_key,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.account_id,OLD.app_id,OLD.bucket_id,OLD.object_key,OLD.created_at)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Write protection snapshot and ownership are immutable';
 END IF;
 IF TG_TABLE_NAME='object_upload_completions' THEN
  IF OLD.protection_snapshot<>'{}' AND ((NEW.bytes,NEW.origin,NEW.source_key,NEW.source_etag) IS DISTINCT FROM (OLD.bytes,OLD.origin,OLD.source_key,OLD.source_etag) OR
   OLD.protection_dispatched AND NOT NEW.protection_dispatched OR NEW.write_phase='dispatched' AND NOT NEW.protection_dispatched OR
   NOT OLD.protection_dispatched AND NEW.protection_dispatched AND NOT (OLD.write_phase='prepared' AND NEW.write_phase='dispatched') OR
   NEW.protection_verified IS DISTINCT FROM OLD.protection_verified AND NOT (OLD.write_phase='dispatched' AND NEW.write_phase='settled' AND NEW.status='completed' AND NEW.protection_verified) OR
   OLD.write_phase='settled' AND (NEW.status,NEW.etag,NEW.error_code,NEW.version_id) IS DISTINCT FROM (OLD.status,OLD.etag,OLD.error_code,OLD.version_id)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Protected write requires aware dispatch and verified settlement';
  END IF;
 ELSE
  IF OLD.protection_snapshot<>'{}' AND (NEW.lease_token IS NOT NULL AND NEW.protection_lease_token IS DISTINCT FROM NEW.lease_token OR
   NEW.protection_verified IS DISTINCT FROM OLD.protection_verified AND NOT (OLD.state IN ('completing','completing_conditional') AND NEW.state='completed' AND OLD.completion_dispatched AND NEW.protection_verified)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Protected multipart requires aware claims and verified completion';
  END IF;
  IF NEW.lease_token IS NULL THEN NEW.protection_lease_token:=''; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: prune_pr_preview_set_on_root_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_pr_preview_set_on_root_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    delete from pr_preview_sets where root_app_id = new.id;
    return new;
end;
$$;


--
-- Name: publish_instance_on_generation(uuid, uuid, uuid, uuid, uuid, text, text, text, inet, integer, text, uuid, text, text, text, jsonb, text, text, boolean, text, timestamp with time zone, jsonb, jsonb, boolean, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_instance_on_generation(p_instance_id uuid, p_app_id uuid, p_deployment_id uuid, p_node_id uuid, p_wake_id uuid, p_expected_state text, p_target_state text, p_netns text, p_host_ip inet, p_guest_uid integer, p_config_fingerprint text, p_environment_id uuid, p_scope text, p_secret_fingerprint text, p_event_kind text, p_event_data jsonb, p_notify_channel text, p_notify_payload text, p_record_receipt boolean, p_receipt_scope text, p_boundary_at timestamp with time zone, p_variables jsonb, p_secret_versions jsonb, p_all_secrets boolean, p_secret_refs jsonb, p_sidecar_secret_versions jsonb, p_guard_generation bigint, OUT published public.instances, OUT snapshot_backoff_recorded boolean) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
    receipts integer;
    current_generation bigint;
BEGIN
    UPDATE instances SET netns = p_netns, host_ip = p_host_ip, guest_uid = p_guest_uid,
           started_at = clock_timestamp(), state = p_target_state
     WHERE id = p_instance_id AND app_id = p_app_id AND deployment_id = p_deployment_id
       AND node_id = p_node_id AND wake_id = p_wake_id AND state = p_expected_state
       AND p_expected_state NOT IN ('warm', 'frozen')
    RETURNING * INTO published;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'instance is not in its admitted state'
            USING ERRCODE = '23514', CONSTRAINT = 'instance_publication_current';
    END IF;
    INSERT INTO runtime_instance_config_proofs(instance_id, wake_id, node_id, deployment_id, environment_id, scope,
                                               secret_fingerprint, config_fingerprint)
    VALUES (published.id, published.wake_id, published.node_id, published.deployment_id, p_environment_id, p_scope,
            p_secret_fingerprint, p_config_fingerprint)
    ON CONFLICT (instance_id) DO UPDATE SET wake_id = excluded.wake_id, node_id = excluded.node_id,
        deployment_id = excluded.deployment_id, environment_id = excluded.environment_id, scope = excluded.scope,
        secret_fingerprint = excluded.secret_fingerprint, config_fingerprint = excluded.config_fingerprint;
    IF p_event_kind IS NOT NULL THEN
        INSERT INTO events(actor, kind, subject, data) VALUES ('schedd', p_event_kind, p_instance_id, p_event_data);
    END IF;
    IF p_notify_channel IS NOT NULL THEN
        PERFORM pg_notify(p_notify_channel, p_notify_payload);
    END IF;
    SELECT EXISTS (SELECT 1 FROM deployments d WHERE d.id = published.deployment_id
                     AND (d.snapshot_miss_count <> 0 OR d.snapshot_miss_last_at IS NOT NULL
                          OR d.snapshot_miss_backoff_until IS NOT NULL))
      INTO snapshot_backoff_recorded;
    IF p_record_receipt THEN
        INSERT INTO instance_runtime_config_receipts(instance_id, wake_id, scope, boundary_at, variables, secret_versions,
                                                     all_secrets, secret_refs, sidecar_secret_versions)
        SELECT i.id, i.wake_id, d.scope, p_boundary_at, p_variables, p_secret_versions, p_all_secrets, p_secret_refs,
               p_sidecar_secret_versions
          FROM instances i JOIN deployments d ON d.id = i.deployment_id
         WHERE i.id = p_instance_id AND i.wake_id = p_wake_id AND i.state = 'running' AND d.scope = p_receipt_scope
        FOR UPDATE OF i
        ON CONFLICT (instance_id) DO UPDATE SET wake_id = excluded.wake_id, scope = excluded.scope,
            boundary_at = excluded.boundary_at, variables = excluded.variables, secret_versions = excluded.secret_versions,
            all_secrets = excluded.all_secrets, secret_refs = excluded.secret_refs,
            sidecar_secret_versions = excluded.sidecar_secret_versions, acknowledged_at = now()
        WHERE instance_runtime_config_receipts.wake_id <> excluded.wake_id OR
            (instance_runtime_config_receipts.scope = excluded.scope AND instance_runtime_config_receipts.boundary_at = excluded.boundary_at
             AND instance_runtime_config_receipts.variables = excluded.variables AND instance_runtime_config_receipts.secret_versions = excluded.secret_versions
             AND instance_runtime_config_receipts.all_secrets = excluded.all_secrets AND instance_runtime_config_receipts.secret_refs = excluded.secret_refs
             AND instance_runtime_config_receipts.sidecar_secret_versions = excluded.sidecar_secret_versions);
        GET DIAGNOSTICS receipts = ROW_COUNT;
        IF receipts <> 1 THEN
            RAISE EXCEPTION 'runtime config receipt does not match the instance'
                USING ERRCODE = '23514', CONSTRAINT = 'instance_runtime_config_receipt_current';
        END IF;
    END IF;
    -- Taken last, after every row lock above (ADR-1741 lock order).
    SELECT generation INTO current_generation FROM app_runtime_generations WHERE app_id = p_app_id FOR SHARE;
    IF NOT FOUND OR current_generation <> p_guard_generation THEN
        RAISE EXCEPTION 'app runtime generation moved'
            USING ERRCODE = '23514', CONSTRAINT = 'app_runtime_generation_current';
    END IF;
END $$;


--
-- Name: purge_inactive_outbound_credential(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_inactive_outbound_credential() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.credential_source = 'customer_sealed'
       AND (NEW.credential_source <> 'customer_sealed' OR NEW.provider_auth_mode <> 'managed') THEN
        DELETE FROM outbound_integration_credentials WHERE integration_id = NEW.id;
        DELETE FROM outbound_integration_credential_keys WHERE integration_id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: rearm_queue_replay_receipts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_queue_replay_receipts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.state='dead_letter' AND NEW.state='pending' AND NEW.source IN ('queue','delayed_task') THEN
    -- Preserve the original receipt UUID, payload, work lane and failure audit.
    -- A renamed private binding is addressed only by its immutable identity.
    UPDATE trigger_records r SET state='pending', attempts=0, last_error=NULL,
      next_fire_at=clock_timestamp(), claim_generation=r.claim_generation+1, claim_expires_at=NULL
      FROM triggers t WHERE t.id=r.trigger_id AND t.app_id=NEW.app_id AND t.account_id=NEW.account_id
        AND t.kind='queue' AND t.source=NEW.source AND r.item_identifier=NEW.id::text
        AND (NEW.queue_binding_id IS NULL OR t.queue_binding_id=NEW.queue_binding_id)
        AND r.state NOT IN ('superseded','cancelled','expired');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: reconcile_queue_work_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_queue_work_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE trigger_records tr
       SET state = NEW.state,
           claim_expires_at = NULL,
           last_error = 'queue work ' || NEW.state
      FROM triggers t
     WHERE t.id = tr.trigger_id
       AND t.app_id = NEW.app_id
       AND t.kind = 'queue'
       AND tr.item_identifier = NEW.id::text
       AND tr.state IN ('pending', 'retry', 'claimed');
    RETURN NEW;
END;
$$;


--
-- Name: record_clone_checkpoint_migration_adoption(uuid, uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_clone_checkpoint_migration_adoption(instance uuid, app uuid, deployment uuid, destination uuid, mem_key text, state_key text, token text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE owner instances%ROWTYPE; reason text; original migration_leases%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'adoption dispatch requires a current snapshot' USING ERRCODE='40001';
 END IF;
 LOCK TABLE deployments IN ROW EXCLUSIVE MODE;
 LOCK TABLE instances IN ROW EXCLUSIVE MODE;
 LOCK TABLE migration_leases IN ROW EXCLUSIVE MODE;
 SELECT * INTO owner FROM instances WHERE id=instance FOR UPDATE;
 IF NOT FOUND OR (owner.app_id,owner.deployment_id) IS DISTINCT FROM (app,deployment) OR owner.state<>'migrating' THEN
  RAISE EXCEPTION 'adoption dispatch ownership changed' USING ERRCODE='23514',CONSTRAINT='clone_checkpoint_migration_adoption_owner';
 END IF;
 SELECT d.reason INTO reason FROM deployments d WHERE d.id=deployment;
 IF clone_checkpoint_deployment_fenced(deployment,reason) THEN
  RAISE EXCEPTION 'clone adoption request permanently fenced' USING ERRCODE='23514',CONSTRAINT='clone_checkpoint_scheduler_request_fenced';
 END IF;
 IF reason LIKE 'environment-clone:%' THEN
  SELECT * INTO original FROM migration_leases WHERE instance_id=instance FOR SHARE;
  IF NOT FOUND OR original.pending OR original.lease_expires_at<=clock_timestamp()
   OR (original.lease_token,original.mem_storage_key,original.vmstate_storage_key) IS DISTINCT FROM (token,mem_key,state_key) THEN
   RAISE EXCEPTION 'original adoption lease changed' USING ERRCODE='23514',CONSTRAINT='clone_checkpoint_migration_adoption_owner';
  END IF;
  INSERT INTO project_environment_clone_migration_adoptions(instance_id,app_id,deployment_id,wake_id,request_reason,lease_token,source_node_id,destination_node_id,lease_created_at,lease_expires_at,mem_storage_key,vmstate_storage_key)
  VALUES(instance,app,deployment,owner.wake_id,reason,token,original.source_node_id,destination,original.created_at,original.lease_expires_at,mem_key,state_key);
 END IF;
END $$;


--
-- Name: record_clone_checkpoint_migration_resume(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_clone_checkpoint_migration_resume(instance uuid, source text, token text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE owner instances%ROWTYPE; reason text; original migration_leases%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'resume dispatch requires a current snapshot' USING ERRCODE='40001';
 END IF;
 LOCK TABLE deployments IN ROW EXCLUSIVE MODE;
 LOCK TABLE instances IN ROW EXCLUSIVE MODE;
 LOCK TABLE migration_leases IN ROW EXCLUSIVE MODE;
 SELECT * INTO owner FROM instances WHERE id=instance FOR UPDATE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'resume dispatch ownership missing' USING ERRCODE='23514',CONSTRAINT='clone_checkpoint_migration_resume_owner';
 END IF;
 SELECT d.reason INTO reason FROM deployments d WHERE d.id=owner.deployment_id;
 IF clone_checkpoint_deployment_fenced(owner.deployment_id,reason) THEN
  RAISE EXCEPTION 'clone resume request permanently fenced' USING ERRCODE='23514',CONSTRAINT='clone_checkpoint_scheduler_request_fenced';
 END IF;
 IF reason LIKE 'environment-clone:%' THEN
  SELECT * INTO original FROM migration_leases WHERE instance_id=instance FOR SHARE;
  IF NOT FOUND OR (original.lease_token,original.source_node_id) IS DISTINCT FROM (token,source) THEN
   RAISE EXCEPTION 'original resume lease changed' USING ERRCODE='23514',CONSTRAINT='clone_checkpoint_migration_resume_owner';
  END IF;
  INSERT INTO project_environment_clone_migration_resumes(instance_id,app_id,deployment_id,wake_id,request_reason,lease_token,source_node_id,lease_created_at,lease_expires_at)
  VALUES(instance,owner.app_id,owner.deployment_id,owner.wake_id,reason,token,source,original.created_at,original.lease_expires_at);
 END IF;
END $$;


--
-- Name: record_clone_checkpoint_wake_dispatch(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_clone_checkpoint_wake_dispatch(instance uuid, app uuid, deployment uuid, node uuid, wake_method text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE owner instances%ROWTYPE; reason text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'wake dispatch requires a current snapshot' USING ERRCODE='40001';
 END IF;
 -- Match the retirement fence order before reading original ownership.
 LOCK TABLE deployments IN ROW EXCLUSIVE MODE;
 LOCK TABLE instances IN ROW EXCLUSIVE MODE;
 SELECT * INTO owner FROM instances WHERE id=instance FOR UPDATE;
 IF NOT FOUND OR (owner.app_id,owner.deployment_id,owner.node_id) IS DISTINCT FROM (app,deployment,node)
 OR owner.state NOT IN ('waking','cold_booting') THEN
  RAISE EXCEPTION 'wake dispatch ownership changed' USING ERRCODE='23514',CONSTRAINT='clone_checkpoint_wake_dispatch_owner';
 END IF;
 SELECT d.reason INTO reason FROM deployments d WHERE d.id=deployment;
 IF clone_checkpoint_deployment_fenced(deployment,reason) THEN
  RAISE EXCEPTION 'clone wake request permanently fenced' USING ERRCODE='23514',CONSTRAINT='clone_checkpoint_scheduler_request_fenced';
 END IF;
 IF reason LIKE 'environment-clone:%' THEN
  INSERT INTO project_environment_clone_wake_dispatches(instance_id,app_id,deployment_id,node_id,wake_id,request_reason,method)
  VALUES(instance,app,deployment,node,owner.wake_id,reason,wake_method);
 END IF;
END $$;


--
-- Name: record_commit_managed_operation_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_commit_managed_operation_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 UPDATE commit_receipts SET operation_state=CASE NEW.state
 WHEN 'pending' THEN 'accepted' WHEN 'running' THEN 'running'
 WHEN 'completed' THEN 'completed' WHEN 'cancelled' THEN 'cancelled'
 WHEN 'failed' THEN 'failed' WHEN 'expired' THEN 'failed'
 ELSE 'unknown' END, completed_at=NEW.completed_at
 WHERE operation_id=NEW.id;
 RETURN NEW;
END;
$$;


--
-- Name: record_commit_operation_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_commit_operation_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 UPDATE commit_receipts SET operation_state=CASE NEW.state
 WHEN 'pending' THEN 'accepted' WHEN 'dispatching' THEN 'running'
 WHEN 'completed' THEN 'completed' WHEN 'cancelled' THEN 'cancelled'
 WHEN 'failed' THEN 'failed' WHEN 'dead_letter' THEN 'failed'
 ELSE 'unknown' END, completed_at=NEW.completed_at
 WHERE invocation_id=NEW.id;
 RETURN NEW;
END;
$$;


--
-- Name: record_event_execution_outcome(uuid, timestamp with time zone, uuid, timestamp with time zone, uuid, uuid, bigint, integer, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_event_execution_outcome(p_id uuid, p_created timestamp with time zone, p_root uuid, p_root_created timestamp with time zone, p_account uuid, p_app uuid, p_generation bigint, p_attempt integer, p_kind text, p_finished timestamp with time zone, p_outcome text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE root_record event_execution_roots%ROWTYPE;
BEGIN
 SELECT * INTO root_record FROM event_execution_roots WHERE root_invocation_id=coalesce(p_root,p_id)
 AND root_created_at=coalesce(p_root_created,p_created) AND account_id=p_account AND app_id=p_app;
 IF NOT FOUND THEN RETURN; END IF;
 IF EXISTS (SELECT 1 FROM event_execution_outcomes WHERE invocation_id=p_id AND invocation_created_at=p_created AND replay_generation=p_generation AND attempt=p_attempt AND kind=p_kind) THEN RETURN; END IF;
 IF NOT isfinite(p_finished) OR p_finished<greatest(root_record.root_created_at,root_record.accepted_at) THEN
  UPDATE event_execution_coverage SET ledger_lost_through_at=greatest(ledger_lost_through_at,clock_timestamp(),root_record.root_created_at,root_record.accepted_at) WHERE subscription_id=root_record.subscription_id;
  RETURN;
 END IF;
 INSERT INTO event_execution_outcomes(root_invocation_id,root_created_at,invocation_id,invocation_created_at,replay_generation,attempt,kind,
 subscription_id,account_id,app_id,finished_at,outcome,latency_seconds,retain_until)
 SELECT r.root_invocation_id,r.root_created_at,p_id,p_created,p_generation,p_attempt,p_kind,
 r.subscription_id,r.account_id,r.app_id,p_finished,p_outcome,
 CASE WHEN p_kind='completion' THEN extract(epoch FROM p_finished-r.accepted_at)::double precision ELSE 0 END,
 p_finished+make_interval(secs=>r.retention_seconds)
 FROM event_execution_roots r JOIN apps a ON a.id=r.app_id
 WHERE r.root_invocation_id=coalesce(p_root,p_id) AND r.root_created_at=coalesce(p_root_created,p_created)
 AND r.account_id=p_account AND r.app_id=p_app AND p_finished>=r.root_created_at
 ON CONFLICT DO NOTHING;
END $$;


--
-- Name: record_event_recovery_admitted_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_event_recovery_admitted_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.state<>'queued' OR NEW.replay_invocation_id IS NULL THEN RETURN NEW; END IF;
 PERFORM capture_event_recovery_invocation_result(inv.id,inv.account_id,inv.app_id,inv.created_at,inv.replay_generation,
  inv.state,inv.outcome,inv.attempts,inv.completed_at)
 FROM invocations inv JOIN event_recovery_jobs job ON job.id=NEW.job_id
 WHERE job.selection->>'mode'='execution' AND inv.id=NEW.replay_invocation_id AND inv.account_id=job.account_id
  AND inv.app_id=job.app_id AND inv.replay_generation=NEW.replay_generation AND inv.created_at=NEW.replay_created_at;
 RETURN NEW;
END $$;


--
-- Name: record_event_recovery_invocation_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_event_recovery_invocation_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  PERFORM capture_event_recovery_invocation_result(OLD.id,OLD.account_id,OLD.app_id,OLD.created_at,OLD.replay_generation,
   OLD.state,OLD.outcome,OLD.attempts,OLD.completed_at);
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF (OLD.id,OLD.account_id,OLD.app_id,OLD.created_at,OLD.replay_generation)
   IS DISTINCT FROM (NEW.id,NEW.account_id,NEW.app_id,NEW.created_at,NEW.replay_generation) THEN
   PERFORM capture_event_recovery_invocation_result(OLD.id,OLD.account_id,OLD.app_id,OLD.created_at,OLD.replay_generation,
    OLD.state,OLD.outcome,OLD.attempts,OLD.completed_at);
  END IF;
 END IF;
 PERFORM capture_event_recovery_invocation_result(NEW.id,NEW.account_id,NEW.app_id,NEW.created_at,NEW.replay_generation,
  NEW.state,NEW.outcome,NEW.attempts,NEW.completed_at);
 RETURN NEW;
END $$;


--
-- Name: record_event_recovery_workflow_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_event_recovery_workflow_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP IN ('DELETE','UPDATE') THEN
  PERFORM capture_event_recovery_workflow_result(OLD.id,OLD.app_id,OLD.workflow_name,OLD.resume_count,
   OLD.status,OLD.updated_at,OLD.finished_at,OLD.cancelled_at IS NOT NULL OR coalesce(OLD.last_error='cancelled by operator',false));
 END IF;
 IF TG_OP<>'DELETE' THEN
  PERFORM capture_event_recovery_workflow_result(NEW.id,NEW.app_id,NEW.workflow_name,NEW.resume_count,
   NEW.status,NEW.updated_at,NEW.finished_at,NEW.cancelled_at IS NOT NULL OR coalesce(NEW.last_error='cancelled by operator',false));
  RETURN NEW;
 END IF;
 RETURN OLD;
END $$;


--
-- Name: record_invocation_attempt_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_invocation_attempt_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  recorded_at timestamptz := clock_timestamp();
  attempt_outcome text;
BEGIN
  IF NEW.source NOT IN ('async_invoke','replay') THEN RETURN NEW; END IF;
  -- Both writes share the execution transaction. No backfill or pre-claim attempts.
  IF OLD.state='dispatching' AND (NEW.state<>'dispatching'
      OR NEW.attempts<>OLD.attempts OR NEW.replay_generation<>OLD.replay_generation) THEN
    attempt_outcome := CASE
      WHEN NEW.replay_generation<>OLD.replay_generation THEN 'unknown'
      WHEN NEW.state='completed' THEN 'succeeded'
      WHEN NEW.outcome='uncertain' THEN 'unknown'
      WHEN NEW.state='pending' AND NEW.last_error='dispatch lease expired; requeued' THEN 'unknown'
      WHEN NEW.state='pending' THEN 'retry'
      WHEN NEW.state='failed' THEN 'failed'
      WHEN NEW.state='dead_letter' THEN 'dead_letter'
      WHEN NEW.state='cancelled' THEN 'cancelled'
      ELSE 'unknown' END;
    UPDATE invocation_attempt_history SET
      finished_at=greatest(recorded_at,started_at), outcome=attempt_outcome,
      error_detail=left(coalesce(NEW.last_error,''),1024),
      next_attempt_at=CASE WHEN NEW.state='pending' THEN NEW.due_at END,
      retain_until=least(coalesce(NEW.result_retention_until,recorded_at+interval '30 days'),recorded_at+interval '30 days')
    WHERE invocation_id=OLD.id AND replay_generation=OLD.replay_generation
      AND attempt=OLD.attempts AND outcome='running';
  END IF;
  IF NEW.state='dispatching' AND NEW.attempts>0 AND (OLD.state<>'dispatching'
      OR NEW.attempts<>OLD.attempts OR NEW.replay_generation<>OLD.replay_generation) THEN
    INSERT INTO invocation_attempt_history(invocation_id,account_id,app_id,
      root_invocation_id,root_created_at,replay_generation,attempt,started_at,outcome,retain_until)
    VALUES(NEW.id,NEW.account_id,NEW.app_id,coalesce(NEW.replay_root_invocation_id,NEW.id),
      coalesce(NEW.replay_root_created_at,NEW.created_at),NEW.replay_generation,NEW.attempts,
      recorded_at,'running',recorded_at+interval '30 days');
  END IF;
  RETURN NEW;
END $$;


--
-- Name: record_job_task_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_job_task_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.attempt > OLD.attempt THEN
        -- A claimed VM may fail before a terminal task row is written. Its
        -- retry transition still consumes an attempt and needs a result.
        INSERT INTO job_task_attempts (
            run_id, task_index, attempt, status, instance_id, error_class,
            error_message, exit_code, started_at, finished_at, log_content,
            log_truncated, output_manifest, work_decision, outcome_code)
        VALUES (
            OLD.run_id, OLD.task_index, OLD.attempt,
            CASE WHEN OLD.status = 'claimed' THEN
                CASE WHEN NEW.error_class = 'infra' THEN 'failed' ELSE 'timeout' END
                ELSE OLD.status END,
            OLD.instance_id,
            CASE WHEN OLD.status = 'claimed' THEN COALESCE(NEW.error_class, 'infra') ELSE OLD.error_class END,
            CASE WHEN OLD.status = 'claimed' THEN
                COALESCE(NEW.error_message, 'reaper reclaimed stale lease')
                ELSE OLD.error_message END,
            CASE WHEN OLD.status = 'claimed' THEN
                CASE WHEN NEW.error_class = 'infra' THEN 1 ELSE 124 END
                ELSE OLD.exit_code END,
            OLD.started_at, COALESCE(OLD.finished_at, clock_timestamp()),
            OLD.log_content, OLD.log_truncated, OLD.output_manifest,
            COALESCE(NEW.work_decision, OLD.work_decision), COALESCE(NEW.outcome_code, OLD.outcome_code))
        ON CONFLICT (run_id, task_index, attempt) DO NOTHING;
    ELSIF NEW.status IN ('succeeded', 'failed', 'timeout', 'cancelled', 'oom')
       AND OLD.status NOT IN ('succeeded', 'failed', 'timeout', 'cancelled', 'oom') THEN
        INSERT INTO job_task_attempts (
            run_id, task_index, attempt, status, instance_id, error_class,
            error_message, exit_code, started_at, finished_at, log_content,
            log_truncated, output_manifest, work_decision, outcome_code)
        VALUES (
            NEW.run_id, NEW.task_index, NEW.attempt, NEW.status, NEW.instance_id,
            NEW.error_class, NEW.error_message, NEW.exit_code, NEW.started_at,
            COALESCE(NEW.finished_at, clock_timestamp()), NEW.log_content,
            NEW.log_truncated, NEW.output_manifest, NEW.work_decision, NEW.outcome_code)
        ON CONFLICT (run_id, task_index, attempt) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: record_object_s3_copy_source_epoch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_object_s3_copy_source_epoch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 -- AFTER runs only for the winning insert/update of an upsert. An idempotent
 -- update of the current identity is valid; every new identity is single use.
 IF TG_OP='INSERT' OR NEW.id IS DISTINCT FROM OLD.id THEN
  INSERT INTO object_s3_copy_source_epochs(id,account_id) VALUES(NEW.id,NEW.account_id) ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Copy source identity was already published';
  END IF;
 END IF;
 RETURN NEW;
END $$;


