--
-- Name: reject_reserved_app_slug_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_reserved_app_slug_allocation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.slug = ANY (ARRAY[
        'account','admin','api','assets','billing','cdn','console','dashboard',
        'docs','help','login','logout','mail','ns','operations','security',
        'signup','static','status','support','www'
    ]::text[])
       AND (TG_OP = 'INSERT' OR NEW.slug IS DISTINCT FROM OLD.slug) THEN
        RAISE EXCEPTION 'app slug % is reserved for a Gregale service', NEW.slug
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_status_update_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_status_update_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'status incident updates cannot be deleted' USING ERRCODE = '55000';
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.incident_id IS DISTINCT FROM OLD.incident_id
       OR NEW.lifecycle_state IS DISTINCT FROM OLD.lifecycle_state
       OR NEW.posted_at IS DISTINCT FROM OLD.posted_at
       OR NEW.actor IS DISTINCT FROM OLD.actor
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR NEW.impact IS DISTINCT FROM OLD.impact
       OR NEW.affected_components IS DISTINCT FROM OLD.affected_components
       OR NEW.edited_at IS NULL THEN
        RAISE EXCEPTION 'status incident update correction may change only message and edited_at' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


