CREATE FUNCTION public.retain_object_version_history_latch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.recovery_versions_observed THEN NEW.recovery_versions_observed:=true; END IF;
 RETURN NEW;
END $$;


--
-- Name: retain_queue_dead_letter_failures(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retain_queue_dead_letter_failures() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM triggers t WHERE t.id=NEW.trigger_id AND t.kind='queue'
    AND t.source IN ('queue','delayed_task')) THEN
    UPDATE trigger_dead_letter d SET reason=NEW.reason,routed_to=NEW.routed_to,
      detail=NEW.detail,created_at=NEW.created_at,
      failure_history=d.failure_history || jsonb_build_array(jsonb_build_object(
        'reason',d.reason,'routed_to',d.routed_to,'detail',d.detail,'created_at',d.created_at))
      WHERE d.record_id=NEW.record_id AND d.trigger_id=NEW.trigger_id;
    IF FOUND THEN RETURN NULL; END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: revise_cron_schedule_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revise_cron_schedule_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.schedule IS DISTINCT FROM OLD.schedule
    OR NEW.timezone IS DISTINCT FROM OLD.timezone
    OR NEW.schedule_policy IS DISTINCT FROM OLD.schedule_policy
    OR NEW.failure_rules IS DISTINCT FROM OLD.failure_rules THEN
  NEW.schedule_revision := OLD.schedule_revision + 1;
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: revise_job_schedule_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revise_job_schedule_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.cron_schedule IS DISTINCT FROM OLD.cron_schedule OR NEW.cron_timezone IS DISTINCT FROM OLD.cron_timezone OR NEW.schedule_policy IS DISTINCT FROM OLD.schedule_policy THEN
  NEW.schedule_revision := OLD.schedule_revision + 1;
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: revoke_object_storage_member_keys(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_object_storage_member_keys() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' OR NEW.access_revision<>OLD.access_revision THEN
  UPDATE object_storage_s3_credentials c SET status='revoked',revoked_at=coalesce(c.revoked_at,now())
  FROM object_buckets b WHERE b.id=c.bucket_id AND b.org_id=OLD.org_id AND c.issuer_account_id=OLD.account_id AND c.status='active';
 END IF;
 RETURN NULL;
END $$;


--
-- Name: revoke_removed_org_member_credentials(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_removed_org_member_credentials() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.removed_at IS NOT NULL AND OLD.removed_at IS NULL THEN
        UPDATE api_keys SET status = 'revoked', revoked_at = coalesce(revoked_at, now())
        WHERE org_id = NEW.org_id AND account_id = NEW.account_id AND status <> 'revoked';
        UPDATE deploy_tokens t SET status = 'revoked', revoked_at = coalesce(t.revoked_at, now())
        FROM apps a WHERE t.app_id = a.id AND a.org_id = NEW.org_id
          AND t.account_id = NEW.account_id AND t.status <> 'revoked';
        UPDATE org_invitations SET revoked_at = coalesce(revoked_at, now())
        WHERE org_id = NEW.org_id AND consumed_at IS NULL AND revoked_at IS NULL
          AND lower(email::text) = (SELECT lower(email::text) FROM accounts WHERE id = NEW.account_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: route_policy_account_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_policy_account_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target uuid;
BEGIN
    IF ROW(NEW.plan, NEW.status, NEW.abuse_hold_at IS NULL) IS DISTINCT FROM ROW(OLD.plan, OLD.status, OLD.abuse_hold_at IS NULL) THEN
        FOR target IN SELECT id FROM apps WHERE account_id = NEW.id AND status <> 'deleted' ORDER BY id LOOP
            PERFORM enqueue_route_policy_checks(target);
        END LOOP;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: route_policy_app_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_policy_app_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF ROW(NEW.slug, NEW.type, NEW.consumer_auth_mode, NEW.maintenance_mode, NEW.manifest->'request_timeout_s', NEW.request_rate_limit_rps, NEW.request_rate_limit_burst, NEW.ram_mb, NEW.cpu_millicores, NEW.max_concurrency, NEW.scaling_policy)
        IS DISTINCT FROM ROW(OLD.slug, OLD.type, OLD.consumer_auth_mode, OLD.maintenance_mode, OLD.manifest->'request_timeout_s', OLD.request_rate_limit_rps, OLD.request_rate_limit_burst, OLD.ram_mb, OLD.cpu_millicores, OLD.max_concurrency, OLD.scaling_policy) THEN
        PERFORM enqueue_route_policy_checks(NEW.id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: route_policy_deployment_live(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_policy_deployment_live() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'live' AND OLD.status IS DISTINCT FROM NEW.status THEN
        PERFORM enqueue_route_policy_checks(NEW.app_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: route_policy_rule_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_policy_rule_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        PERFORM enqueue_route_policy_checks(OLD.app_id);
        RETURN OLD;
    END IF;
    IF TG_OP = 'INSERT' OR ROW(NEW.app_id, NEW.account_id, NEW.match_host, NEW.match_path, NEW.match_methods, NEW.match_headers, NEW.priority, NEW.enabled, NEW.kind, NEW.action, NEW.validate_mode)
        IS DISTINCT FROM ROW(OLD.app_id, OLD.account_id, OLD.match_host, OLD.match_path, OLD.match_methods, OLD.match_headers, OLD.priority, OLD.enabled, OLD.kind, OLD.action, OLD.validate_mode) THEN
        IF TG_OP = 'UPDATE' AND NEW.app_id IS DISTINCT FROM OLD.app_id THEN
            PERFORM enqueue_route_policy_checks(OLD.app_id);
        END IF;
        PERFORM enqueue_route_policy_checks(NEW.app_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: route_removal_check(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_removal_check(target_id uuid, proposed_scope text DEFAULT NULL::text, proposed_app_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE p app_route_removal_policies%ROWTYPE; d deployments%ROWTYPE;
 b deployment_openapi_docs%ROWTYPE; c deployment_openapi_docs%ROWTYPE;
 approval route_removal_approvals%ROWTYPE; removed jsonb := '[]'; blockers jsonb := '[]'; stamp timestamptz := clock_timestamp(); earliest timestamptz;
BEGIN
 SELECT * INTO d FROM deployments WHERE id=target_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'deployment not found'; END IF;
 IF proposed_scope IS NOT NULL THEN d.scope:=proposed_scope; END IF;
 IF proposed_app_id IS NOT NULL THEN d.app_id:=proposed_app_id; END IF;
 SELECT * INTO p FROM app_route_removal_policies WHERE app_id=d.app_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','not_configured','removed',removed,'blockers',blockers); END IF;
 IF coalesce(nullif(d.scope,''),'default') NOT IN ('default','prod','production') OR p.baseline_deployment_id IS NULL OR p.baseline_deployment_id=d.id THEN
 RETURN jsonb_build_object('status','not_required','removed',removed,'blockers',blockers); END IF;
 SELECT * INTO b FROM deployment_openapi_docs WHERE deployment_id=p.baseline_deployment_id AND app_id=d.app_id AND account_id=p.account_id;
 SELECT * INTO c FROM deployment_openapi_docs WHERE deployment_id=d.id AND app_id=d.app_id AND account_id=p.account_id;
 IF b.deployment_id IS NULL OR c.deployment_id IS NULL OR b.truncated OR c.truncated OR
 coalesce(b.doc->>'openapi','') NOT LIKE '3.%' OR coalesce(c.doc->>'openapi','') NOT LIKE '3.%' OR
 jsonb_typeof(b.doc->'paths') IS DISTINCT FROM 'object' OR jsonb_typeof(c.doc->'paths') IS DISTINCT FROM 'object' THEN
 blockers := jsonb_build_array('contract_unavailable');
 ELSIF EXISTS(SELECT 1 FROM jsonb_each(b.doc->'paths') x WHERE jsonb_typeof(x.value)<>'object' OR x.value ? '$ref' OR x.key NOT LIKE '/%') OR
 EXISTS(SELECT 1 FROM jsonb_each(c.doc->'paths') x WHERE jsonb_typeof(x.value)<>'object' OR x.value ? '$ref' OR x.key NOT LIKE '/%') THEN
 blockers := jsonb_build_array('path_reference_or_invalid_item');
 ELSIF EXISTS(SELECT 1 FROM jsonb_each(b.doc->'paths') item CROSS JOIN LATERAL jsonb_each(item.value) o WHERE lower(o.key) IN ('get','put','post','delete','options','head','patch','trace') AND jsonb_typeof(o.value)<>'object') OR
 EXISTS(SELECT 1 FROM jsonb_each(c.doc->'paths') item CROSS JOIN LATERAL jsonb_each(item.value) o WHERE lower(o.key) IN ('get','put','post','delete','options','head','patch','trace') AND jsonb_typeof(o.value)<>'object') THEN
 blockers:=jsonb_build_array('invalid_operation');
 ELSE
 SELECT coalesce(jsonb_agg(jsonb_build_object('method',x.method,'path',x.path) ORDER BY x.method,x.path),'[]') INTO removed
 FROM (SELECT * FROM route_removal_operations(b.doc) EXCEPT SELECT * FROM route_removal_operations(c.doc)) x;
 IF jsonb_array_length(removed)>0 THEN
 earliest:=date_trunc('minute',greatest(p.baseline_since,b.captured_at))+make_interval(secs=>p.grace_seconds)+interval '3 minutes';
 blockers:=blockers||route_removal_coverage_blockers(p.app_id,date_trunc('minute',stamp-interval '2 minutes')-make_interval(secs=>p.grace_seconds),date_trunc('minute',stamp-interval '2 minutes'));
 SELECT greatest(earliest,date_trunc('minute',max(healthy_since))+make_interval(secs=>p.grace_seconds)+interval '3 minutes') INTO earliest FROM request_telemetry_coverage cv JOIN compute_nodes n ON n.name=cv.node_name WHERE n.active;
 SELECT greatest(earliest,date_trunc('minute',max(g.last_gap_at))+make_interval(secs=>p.grace_seconds)+interval '3 minutes') INTO earliest FROM request_telemetry_app_gaps g JOIN compute_nodes n ON n.name=g.node_name WHERE n.active AND g.app_id=p.app_id;
 IF stamp < earliest THEN
 blockers:=blockers||jsonb_build_array('grace_period_not_elapsed'); END IF;
 SELECT * INTO approval FROM route_removal_approvals a WHERE a.app_id=p.app_id AND a.account_id=p.account_id AND
 a.policy_revision=p.revision AND a.baseline_deployment_id=p.baseline_deployment_id AND a.candidate_deployment_id=d.id AND
 a.baseline_sha256=b.doc_sha256 AND a.candidate_sha256=c.doc_sha256 AND p.baseline_since<=a.observation_from AND a.valid_until>stamp AND
 a.approved_at>=stamp-make_interval(secs=>p.max_approval_age_seconds) AND
 a.observation_from<=a.observation_until-make_interval(secs=>p.grace_seconds) AND
 a.observation_until>=stamp-make_interval(secs=>p.max_approval_age_seconds)-interval '3 minutes' AND
 NOT EXISTS (SELECT 1 FROM jsonb_array_elements(removed) r WHERE NOT EXISTS
 (SELECT 1 FROM jsonb_array_elements(a.mappings) m WHERE m->>'method'=r->>'method' AND m->>'path'=r->>'path'))
 ORDER BY a.approved_at DESC LIMIT 1;
 IF NOT FOUND THEN blockers:=blockers||jsonb_build_array('fresh_authenticated_approval_required');
 ELSE
 blockers:=blockers||route_removal_coverage_blockers(p.app_id,approval.observation_from,date_trunc('minute',stamp-interval '2 minutes'));
 IF EXISTS (SELECT 1 FROM request_telemetry rt JOIN deployments td ON td.id=rt.deployment_id
 JOIN jsonb_array_elements(removed) r ON rt.method=r->>'method' AND rt.route IN (r->>'path',(r->>'method')||' '||(r->>'path'))
 WHERE rt.app_id=p.app_id AND rt.account_id=p.account_id AND coalesce(nullif(td.scope,''),'default') IN ('default','prod','production')
 AND rt.received_at>=approval.observation_from AND rt.count>0) THEN
 blockers:=blockers||jsonb_build_array('old_route_observed'); END IF;
 END IF;
 END IF;
 END IF;
 SELECT coalesce(jsonb_agg(DISTINCT x),'[]') INTO blockers FROM jsonb_array_elements(blockers) x;
 RETURN jsonb_strip_nulls(jsonb_build_object('status',CASE WHEN jsonb_array_length(blockers)>0 THEN 'blocked' WHEN jsonb_array_length(removed)>0 THEN 'passed' ELSE 'not_required' END,
 'removed',removed,'blockers',blockers,'approval_id',coalesce(approval.id::text,''),
 'earliest_approval_at',earliest,'approval_valid_until',approval.valid_until,
 'baseline_contract_sha256',encode(b.doc_sha256,'hex'),'candidate_contract_sha256',encode(c.doc_sha256,'hex')));
END $_$;


--
-- Name: route_removal_coverage_blockers(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_removal_coverage_blockers(window_from timestamp with time zone, window_until timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE blockers jsonb:='[]'; stamp timestamptz:=clock_timestamp();
BEGIN
 IF NOT EXISTS(SELECT 1 FROM compute_nodes WHERE active) OR EXISTS(SELECT 1 FROM compute_nodes n LEFT JOIN request_telemetry_coverage c ON c.node_name=n.name WHERE n.active AND c.node_name IS NULL) THEN
 blockers:=blockers||jsonb_build_array('telemetry_coverage_missing'); END IF;
 IF EXISTS(SELECT 1 FROM request_telemetry_coverage c JOIN compute_nodes n ON n.name=c.node_name WHERE n.active AND c.received_at<stamp-interval '30 seconds') THEN
 blockers:=blockers||jsonb_build_array('telemetry_coverage_stale'); END IF;
 IF EXISTS(SELECT 1 FROM request_telemetry_coverage c JOIN compute_nodes n ON n.name=c.node_name WHERE n.active AND NOT c.enabled) THEN
 blockers:=blockers||jsonb_build_array('telemetry_disabled'); END IF;
 IF EXISTS(SELECT 1 FROM request_telemetry_coverage c JOIN compute_nodes n ON n.name=c.node_name WHERE n.active AND c.sampling_basis_points<>10000) THEN
 blockers:=blockers||jsonb_build_array('telemetry_sampled'); END IF;
 IF EXISTS(SELECT 1 FROM request_telemetry_coverage c JOIN compute_nodes n ON n.name=c.node_name WHERE n.active AND ((CASE WHEN c.app_scoped THEN c.unattributed_pending_count ELSE c.pending_count END)>0 OR c.source_at<window_until)) THEN
 blockers:=blockers||jsonb_build_array('telemetry_ingestion_pending'); END IF;
 IF EXISTS(SELECT 1 FROM request_telemetry_coverage c JOIN compute_nodes n ON n.name=c.node_name WHERE n.active AND (c.healthy_since IS NULL OR c.healthy_since>window_from)) THEN
 blockers:=blockers||jsonb_build_array('telemetry_window_incomplete'); END IF;
 RETURN blockers;
END $$;


--
-- Name: route_removal_coverage_blockers(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_removal_coverage_blockers(target_app uuid, window_from timestamp with time zone, window_until timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE blockers jsonb:=route_removal_coverage_blockers(window_from,window_until);
BEGIN
 IF EXISTS(SELECT 1 FROM request_telemetry_app_gaps g JOIN compute_nodes n ON n.name=g.node_name WHERE n.active AND g.app_id=target_app AND g.pending_count>0) THEN
 blockers:=blockers||jsonb_build_array('telemetry_ingestion_pending'); END IF;
 IF EXISTS(SELECT 1 FROM request_telemetry_app_gaps g JOIN compute_nodes n ON n.name=g.node_name WHERE n.active AND g.app_id=target_app AND g.last_gap_at>window_from) THEN
 blockers:=blockers||jsonb_build_array('telemetry_window_incomplete'); END IF;
 SELECT coalesce(jsonb_agg(DISTINCT x),'[]') INTO blockers FROM jsonb_array_elements(blockers) x;
 RETURN blockers;
END $$;


--
-- Name: route_removal_operations(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_removal_operations(document jsonb) RETURNS TABLE(method text, path text)
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT upper(o.key),p.key FROM jsonb_each(document->'paths') p
 CROSS JOIN LATERAL jsonb_each(p.value) o
 WHERE lower(o.key) IN ('get','put','post','delete','options','head','patch','trace')
$$;


--
-- Name: route_requirements_findings_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_requirements_findings_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE recipients uuid[]; app_slug text;
BEGIN
    IF OLD.safety_state <> 'violated' OR NEW.latest_changes->>'status' <> 'comparable'
        OR COALESCE((NEW.latest_changes->'summary'->>'newly_violated')::integer, 0) = 0 THEN
        RETURN NEW;
    END IF;
    SELECT a.slug INTO app_slug FROM apps a JOIN deployments d ON d.app_id = a.id
        WHERE a.id = NEW.app_id AND a.account_id = NEW.account_id AND a.status <> 'deleted'
          AND d.id = NEW.deployment_id AND d.status = 'live';
    IF NOT FOUND THEN RETURN NEW; END IF;
    SELECT array_agg(h.id ORDER BY h.id) INTO recipients FROM app_webhooks h
        WHERE h.scope = 'app' AND h.app_id = NEW.app_id AND h.account_id = NEW.account_id AND h.enabled
          AND (cardinality(h.event_filter) = 0 OR 'routes.requirements.changed' = ANY(h.event_filter));
    IF recipients IS NULL THEN RETURN NEW; END IF;
    INSERT INTO app_webhook_event_outbox(account_id, app_id, event, source_id, payload, recipient_webhook_ids)
    VALUES (NEW.account_id, NEW.app_id, 'routes.requirements.changed', NEW.completed_request_id,
        jsonb_build_object('app_id', NEW.app_id, 'deployment_id', NEW.deployment_id,
            'status', NEW.latest_check->'report'->>'status', 'transition_id', NEW.completed_request_id,
            'checked_at', NEW.checked_at, 'requirements_revision', NEW.latest_check->'requirements_revision',
            'requirements_sha256', NEW.latest_check->>'requirements_sha256',
            'configuration_sha256', NEW.latest_check->>'configuration_sha256', 'capture_sha256', NEW.capture_sha256,
            'summary', NEW.latest_changes->'summary', 'comparison_status', NEW.latest_changes->>'status',
            'result_path', '/v1/apps/' || app_slug || '/route-requirements/checks/' || NEW.deployment_id::text,
            'history_path', '/v1/apps/' || app_slug || '/route-requirements/checks/' || NEW.deployment_id::text || '/history/' || NEW.completed_request_id::text), recipients)
    ON CONFLICT (event, source_id) DO NOTHING;
    RETURN NEW;
END;
$$;


--
-- Name: route_requirements_safety_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_requirements_safety_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE event_name text; recipients uuid[]; event_payload jsonb; app_slug text;
BEGIN
    IF NEW.safety_state = 'violated' THEN
        event_name := 'routes.requirements.violated';
    ELSIF NEW.safety_state = 'satisfied' AND OLD.safety_state = 'violated' THEN
        event_name := 'routes.requirements.recovered';
    ELSE
        RETURN NEW;
    END IF;
    SELECT a.slug INTO app_slug FROM apps a JOIN deployments d ON d.app_id = a.id
        WHERE a.id = NEW.app_id AND a.account_id = NEW.account_id AND a.status <> 'deleted'
          AND d.id = NEW.deployment_id AND d.status = 'live';
    IF NOT FOUND THEN RETURN NEW; END IF;
    SELECT array_agg(h.id ORDER BY h.id) INTO recipients FROM app_webhooks h
        WHERE h.scope = 'app' AND h.app_id = NEW.app_id AND h.account_id = NEW.account_id AND h.enabled
          AND (cardinality(h.event_filter) = 0 OR event_name = ANY(h.event_filter));
    IF recipients IS NULL THEN RETURN NEW; END IF;
    event_payload := jsonb_build_object(
        'app_id', NEW.app_id, 'deployment_id', NEW.deployment_id,
        'status', NEW.safety_state, 'previous_status', OLD.safety_state,
        'transition_id', NEW.completed_request_id, 'checked_at', NEW.checked_at,
        'requirements_revision', NEW.latest_check->'requirements_revision',
        'requirements_sha256', NEW.latest_check->>'requirements_sha256',
        'configuration_sha256', NEW.latest_check->>'configuration_sha256',
        'capture_sha256', NEW.capture_sha256,
        'result_path', '/v1/apps/' || app_slug || '/route-requirements/checks/' || NEW.deployment_id::text);
    INSERT INTO app_webhook_event_outbox(account_id, app_id, event, source_id, payload, recipient_webhook_ids)
        VALUES (NEW.account_id, NEW.app_id, event_name, NEW.completed_request_id, event_payload, recipients)
        ON CONFLICT (event, source_id) DO NOTHING;
    RETURN NEW;
END;
$$;


--
-- Name: scenario_action_sealed_effect_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_action_sealed_effect_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE source_app uuid;
BEGIN
 IF TG_TABLE_NAME = 'exclusive_work_effects' THEN
  SELECT app_id INTO source_app FROM exclusive_work_operations WHERE id = NEW.operation_id;
 ELSE
  source_app := NEW.app_id;
 END IF;
 PERFORM id FROM apps WHERE id = source_app FOR KEY SHARE;
 IF EXISTS (SELECT 1 FROM scenario_test_action_policies WHERE app_id = source_app AND sealed_at IS NOT NULL) THEN
  RAISE EXCEPTION 'scenario action window is sealed' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_cold_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_cold_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p scenario_test_action_policies%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM apps WHERE id=OLD.app_id) AND EXISTS(SELECT 1 FROM accounts WHERE id=OLD.account_id)
   THEN RAISE EXCEPTION 'cold-start evidence is retained until app deletion' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 SELECT * INTO p FROM scenario_test_action_policies WHERE app_id=NEW.app_id;
 PERFORM pg_advisory_xact_lock(hashtextextended('scenario-action-run:'||p.account_id::text||':'||p.run_id,0));
 SELECT * INTO p FROM scenario_test_action_policies WHERE app_id=NEW.app_id;
 IF p.cold_start_spec IS NULL OR p.sealed_at IS NOT NULL OR p.recorder_closing OR p.account_id<>NEW.account_id OR p.run_id<>NEW.run_id THEN
  RAISE EXCEPTION 'cold-start enrollment is unavailable or sealed' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state NOT IN ('armed','retired') OR (NEW.state='armed')<>(NEW.instance_id IS NOT NULL)
   OR NEW.boot_instance_id IS NOT NULL OR NEW.ready_at IS NOT NULL THEN
   RAISE EXCEPTION 'cold-start preparation must begin unacknowledged' USING ERRCODE='23514'; END IF;
 ELSE
  IF (NEW.id,NEW.account_id,NEW.app_id,NEW.run_id,NEW.deployment_id,NEW.instance_id,NEW.recorder_session_id,NEW.created_at)
   IS DISTINCT FROM (OLD.id,OLD.account_id,OLD.app_id,OLD.run_id,OLD.deployment_id,OLD.instance_id,OLD.recorder_session_id,OLD.created_at)
   OR NOT((OLD.state='armed' AND NEW.state='claimed') OR (OLD.state='claimed' AND NEW.state='fenced')
    OR (OLD.state='fenced' AND NEW.state='retired') OR (OLD.state='retired' AND NEW.state='ready')
    OR (OLD.state='ready' AND NEW.state='booted') OR (OLD.state NOT IN ('booted','failed') AND NEW.state='failed'))
   OR (OLD.state<>'ready' AND (NEW.boot_instance_id,NEW.boot_recorder_session_id,NEW.wake_id,NEW.method,NEW.startup_ms)
     IS DISTINCT FROM (OLD.boot_instance_id,OLD.boot_recorder_session_id,OLD.wake_id,OLD.method,OLD.startup_ms))
   OR (NEW.state<>'ready' AND NEW.ready_at IS DISTINCT FROM OLD.ready_at) THEN
   RAISE EXCEPTION 'cold-start identity or lifecycle is immutable' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.state='ready' AND (EXISTS(SELECT 1 FROM instances WHERE app_id=NEW.app_id AND state NOT IN ('stopped','parked','failed'))
   OR EXISTS(SELECT 1 FROM snapshots s JOIN deployments d ON d.id=s.deployment_id WHERE d.app_id=NEW.app_id AND NOT s.stale)
   OR NEW.ready_at IS NULL) THEN
  RAISE EXCEPTION 'cold-start preparation requires drained instances and invalidated snapshots' USING ERRCODE='23514'; END IF;
 IF NEW.state='booted' AND NOT EXISTS(SELECT 1 FROM scenario_recorder_sessions r JOIN instances i ON i.id=r.instance_id
  WHERE r.id=NEW.boot_recorder_session_id AND r.app_id=NEW.app_id AND r.deployment_id=NEW.deployment_id AND r.status='recording'
  AND i.id=NEW.boot_instance_id AND i.app_id=NEW.app_id AND i.deployment_id=NEW.deployment_id AND i.wake_id::text=NEW.wake_id
  AND r.created_at>=NEW.ready_at AND i.state IN ('waking','cold_booting','running')) THEN
  RAISE EXCEPTION 'cold-start boot requires its original live recorder and new instance' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_cold_policy_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_cold_policy_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN IF NEW.cold_start_spec IS DISTINCT FROM OLD.cold_start_spec THEN
 RAISE EXCEPTION 'cold-start plan is immutable' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;


--
-- Name: scenario_command_network_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_command_network_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NOT NEW.active OR NOT EXISTS(SELECT 1 FROM app_tasks t JOIN scenario_recorder_sessions r ON r.instance_id=t.id AND r.app_id=t.app_id
   WHERE t.id=NEW.task_id AND t.lease_token=NEW.lease_token AND t.lease_expires_at>clock_timestamp()
    AND t.status='restoring' AND t.cancel_requested_at IS NULL AND r.status='recording'
    AND t.command[1]='__gregale_rehearsal_command_v1__') THEN
   RAISE EXCEPTION 'command network identity requires the restoring owner' USING ERRCODE='23514';
  END IF;
 ELSIF (NEW.task_id,NEW.node_id,NEW.host_ip,NEW.lease_token) IS DISTINCT FROM (OLD.task_id,OLD.node_id,OLD.host_ip,OLD.lease_token)
    OR NOT OLD.active OR NEW.active THEN
  RAISE EXCEPTION 'command network identity is immutable and retirement irreversible' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_command_retirement_network_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_command_retirement_network_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.command_result IS NOT NULL AND NOT EXISTS(SELECT 1 FROM scenario_command_networks
    WHERE task_id=NEW.instance_id AND NOT active) THEN
  RAISE EXCEPTION 'command retirement requires revoked network authority' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_managed_work_capture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_managed_work_capture() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p scenario_test_action_policies%ROWTYPE; participant jsonb; dep uuid; deployment_count integer;
 doc jsonb; attempts jsonb; item jsonb; outcome text; invalid boolean:=false;
BEGIN
 SELECT * INTO p FROM scenario_test_action_policies WHERE app_id=CASE WHEN TG_OP='INSERT' THEN NEW.app_id ELSE OLD.app_id END;
 IF TG_OP='UPDATE' AND p.managed_work_plan IS NULL THEN SELECT * INTO p FROM scenario_test_action_policies WHERE app_id=NEW.app_id; END IF;
 IF p.managed_work_plan IS NULL THEN RETURN COALESCE(NEW,OLD); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('scenario-action-run:'||p.account_id::text||':'||p.run_id,0));
 SELECT * INTO p FROM scenario_test_action_policies WHERE app_id=p.app_id;
 IF TG_OP='DELETE' THEN
  IF p.sealed_at IS NULL THEN UPDATE scenario_test_action_policies SET managed_work_failed=true WHERE account_id=p.account_id AND run_id=p.run_id; END IF;
  RETURN OLD;
 END IF;
 IF p.sealed_at IS NOT NULL THEN
  RAISE EXCEPTION 'managed rehearsal work is sealed' USING ERRCODE='23514';
 END IF;
 SELECT value INTO participant FROM jsonb_array_elements(p.managed_work_plan->'participants') WHERE value->>'workload'=p.workload_name;
 SELECT count(*),min(id::text)::uuid INTO deployment_count,dep FROM deployments WHERE app_id=p.app_id;
 IF TG_OP='INSERT' THEN
  invalid:=p.managed_work_closing OR p.recorder_closing OR NOT COALESCE((participant->>'async')::boolean,false)
   OR NEW.source<>'async_invoke' OR NEW.state<>'pending' OR NEW.attempts<>0 OR NEW.replay_generation<>0
   OR NEW.account_id<>p.account_id OR deployment_count<>1 OR COALESCE(NEW.work_policy_name,'')<>''
   OR octet_length(COALESCE(NEW.payload,'null'::jsonb)::text)>8192 OR length(NEW.path)>2048
   OR NOT EXISTS(SELECT 1 FROM apps a WHERE a.id=p.app_id AND a.status<>'deleted' AND a.preview_pr_state='open' AND a.preview_expires_at>clock_timestamp());
  IF (SELECT count(*) FROM scenario_managed_work WHERE account_id=p.account_id AND run_id=p.run_id)>=64 THEN
   invalid:=true;
  ELSE
   doc:=jsonb_build_object('id',NEW.id,'workload',p.workload_name,'app_id',p.app_id,'deployment_id',dep,
     'method',NEW.method,'path',left(NEW.path,2048),'state',CASE WHEN invalid THEN 'cancelled' ELSE NEW.state END,'attempts','[]'::jsonb);
   INSERT INTO scenario_managed_work(invocation_id,app_id,account_id,run_id,document,payload)
    VALUES(NEW.id,p.app_id,p.account_id,p.run_id,doc,
     CASE WHEN octet_length(COALESCE(NEW.payload,'null'::jsonb)::text)<=8192 THEN COALESCE(NEW.payload,'null'::jsonb) ELSE 'null'::jsonb END);
  END IF;
  IF invalid THEN
   UPDATE scenario_test_action_policies SET managed_work_failed=true WHERE account_id=p.account_id AND run_id=p.run_id;
   NEW.state:='cancelled'; NEW.last_error:='rehearsal: unsupported or closed managed-work admission'; NEW.completed_at:=clock_timestamp();
  END IF;
  RETURN NEW;
 END IF;
 SELECT document INTO doc FROM scenario_managed_work WHERE invocation_id=OLD.id FOR UPDATE;
 IF doc IS NULL THEN invalid:=true;
 ELSE
  attempts:=doc->'attempts';
  invalid:=(NEW.id,NEW.app_id,NEW.account_id,NEW.source,NEW.method,NEW.path,NEW.payload,NEW.replay_generation)
    IS DISTINCT FROM (OLD.id,OLD.app_id,OLD.account_id,OLD.source,OLD.method,OLD.path,OLD.payload,OLD.replay_generation)
    OR deployment_count<>1 OR dep IS DISTINCT FROM (doc->>'deployment_id')::uuid;
  IF OLD.state='dispatching' AND (NEW.state<>'dispatching' OR NEW.attempts<>OLD.attempts) THEN
   outcome:=CASE WHEN NEW.state='completed' THEN 'succeeded'
     WHEN NEW.state='pending' AND NEW.last_error<>'dispatch lease expired; requeued' THEN 'retry'
     WHEN NEW.state='pending' THEN 'unknown' ELSE NEW.state END;
   IF jsonb_array_length(attempts)=OLD.attempts AND OLD.attempts>0 THEN
    attempts:=jsonb_set(attempts,ARRAY[(OLD.attempts-1)::text,'outcome'],to_jsonb(outcome));
   ELSE invalid:=true; END IF;
  END IF;
  IF NEW.state='dispatching' AND (OLD.state<>'dispatching' OR NEW.attempts<>OLD.attempts) AND EXISTS
   (SELECT 1 FROM scenario_worker_faults f WHERE f.app_id=NEW.app_id AND (f.state<>'terminated' OR EXISTS
    (SELECT 1 FROM instances i WHERE i.id=f.instance_id AND i.state IN ('waking','cold_booting','running','draining'))))
  THEN RAISE EXCEPTION 'worker fault blocks dispatch until confirmed teardown' USING ERRCODE='23514'; END IF;
  IF NEW.state='dispatching' AND NULLIF(NEW.instance_id,'') IS NOT NULL AND (OLD.state<>'dispatching' OR NEW.attempts<>OLD.attempts OR jsonb_array_length(attempts)=NEW.attempts-1) THEN
   SELECT jsonb_build_object('number',NEW.attempts,'instance_id',i.id,'deployment_id',i.deployment_id,'outcome','running') INTO item
    FROM instances i WHERE i.id=NULLIF(NEW.instance_id,'')::uuid AND i.app_id=p.app_id AND i.deployment_id=dep;
   IF item IS NULL OR jsonb_array_length(attempts)>=32 OR NEW.attempts<>jsonb_array_length(attempts)+1 THEN invalid:=true;
   ELSE attempts:=attempts||jsonb_build_array(item); END IF;
  END IF;
  IF NEW.state='dispatching' AND NEW.attempts>0 AND jsonb_array_length(attempts)=NEW.attempts
   AND attempts->(NEW.attempts-1)->>'instance_id' IS DISTINCT FROM NEW.instance_id THEN invalid:=true; END IF;
  doc:=jsonb_set(jsonb_set(doc,'{state}',to_jsonb(NEW.state)),'{attempts}',attempts);
  UPDATE scenario_managed_work SET document=doc WHERE invocation_id=OLD.id;
 END IF;
 IF invalid THEN UPDATE scenario_test_action_policies SET managed_work_failed=true WHERE account_id=p.account_id AND run_id=p.run_id; END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_managed_work_journal_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_managed_work_journal_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF pg_trigger_depth()<2 THEN
  RAISE EXCEPTION 'managed work journal is owned by invocation transitions' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND ((NEW.invocation_id,NEW.app_id,NEW.account_id,NEW.run_id,NEW.payload)
   IS DISTINCT FROM (OLD.invocation_id,OLD.app_id,OLD.account_id,OLD.run_id,OLD.payload)
   OR (NEW.document - ARRAY['state','attempts']) IS DISTINCT FROM (OLD.document - ARRAY['state','attempts'])) THEN
  RAISE EXCEPTION 'managed work journal intent is immutable' USING ERRCODE='23514';
 END IF;
 RETURN COALESCE(NEW,OLD);
END $$;


--
-- Name: scenario_managed_work_policy_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_managed_work_policy_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.managed_work_plan IS DISTINCT FROM OLD.managed_work_plan
  OR (OLD.managed_work_closing AND NOT NEW.managed_work_closing)
  OR (OLD.managed_work_failed AND NOT NEW.managed_work_failed) THEN
  RAISE EXCEPTION 'managed rehearsal policy is immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_network_policy_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_network_policy_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (NEW.app_id, NEW.account_id, NEW.run_id, NEW.network_mode)
       IS DISTINCT FROM (OLD.app_id, OLD.account_id, OLD.run_id, OLD.network_mode) THEN
        RAISE EXCEPTION 'rehearsal network policy is immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: scenario_object_attempt_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_object_attempt_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE old_attempt jsonb; new_attempt jsonb; ordinal bigint;
BEGIN
 IF jsonb_array_length(NEW.document->'Attempts') < jsonb_array_length(OLD.document->'Attempts')
 OR jsonb_array_length(NEW.document->'Attempts') > 256
 OR (OLD.status<>'ready' AND jsonb_array_length(NEW.document->'Attempts')<>jsonb_array_length(OLD.document->'Attempts')) THEN
  RAISE EXCEPTION 'object admission inventory is immutable' USING ERRCODE='23514';
 END IF;
 FOR old_attempt,ordinal IN SELECT value,ordinality FROM jsonb_array_elements(OLD.document->'Attempts') WITH ORDINALITY LOOP
  new_attempt := NEW.document->'Attempts'->(ordinal::integer-1);
  IF (old_attempt - ARRAY['Pending','Mutation']) IS DISTINCT FROM (new_attempt - ARRAY['Pending','Mutation'])
  OR (NOT (old_attempt->>'Pending')::boolean AND old_attempt IS DISTINCT FROM new_attempt)
  OR ((new_attempt->>'Pending')::boolean AND old_attempt IS DISTINCT FROM new_attempt) THEN
   RAISE EXCEPTION 'object completion receipt is immutable' USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NEW;
END $$;


--
-- Name: scenario_object_fixture_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_object_fixture_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE old_collector text; new_collector text; old_closed boolean; new_closed boolean;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.status NOT IN ('complete','deleted') THEN
   RAISE EXCEPTION 'object fixture requires cleanup before purge' USING ERRCODE='23514';
  END IF;
  RETURN OLD;
 END IF;
 old_collector:=COALESCE(OLD.document->>'CollectorID','');new_collector:=COALESCE(NEW.document->>'CollectorID','');
 old_closed:=COALESCE((OLD.document->>'CollectorClosed')::boolean,false);new_closed:=COALESCE((NEW.document->>'CollectorClosed')::boolean,false);
 IF (NEW.id,NEW.account_id,NEW.run_id,NEW.app_id,NEW.expires_at)
   IS DISTINCT FROM (OLD.id,OLD.account_id,OLD.run_id,OLD.app_id,OLD.expires_at)
 OR (NEW.document - ARRAY['Status','Current','Attempts','Failed','Evidence','CollectorID','CollectorClosed'])
   IS DISTINCT FROM (OLD.document - ARRAY['Status','Current','Attempts','Failed','Evidence','CollectorID','CollectorClosed'])
 OR (OLD.status IN ('complete','deleted') AND NEW IS DISTINCT FROM OLD)
 OR NOT (NEW.status=OLD.status OR (OLD.status='ready' AND NEW.status='sealing')
   OR (OLD.status='sealing' AND NEW.status='complete') OR NEW.status='deleted')
 OR ((OLD.document->>'Failed')::boolean AND NOT (NEW.document->>'Failed')::boolean)
 OR (NEW.status IN ('complete','deleted') AND jsonb_array_length(NEW.document->'Current')<>0)
 OR (old_collector<>'' AND new_collector<>old_collector)
 OR (old_collector='' AND new_collector<>'' AND (OLD.status<>'ready' OR NEW.status<>'ready' OR new_collector !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'))
 OR (old_closed AND NOT new_closed)
 OR (NOT old_closed AND new_closed AND (OLD.status<>'sealing' OR NEW.status<>'sealing' OR old_collector=''))
 OR (NEW.status='complete' AND (NOT new_closed OR new_collector='' OR (NEW.document->>'Failed')::boolean))
 THEN RAISE EXCEPTION 'object fixture journal is immutable' USING ERRCODE='23514'; END IF;
 IF NOT old_closed AND new_closed AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.document->'Attempts') a WHERE (a->>'Pending')::boolean) THEN
  RAISE EXCEPTION 'object collector has pending requests' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: scenario_postgres_backend_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_postgres_backend_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
 IF TG_OP='INSERT' AND NEW.backend_sha256!~'^[a-f0-9]{64}$'
 OR TG_OP='UPDATE' AND NEW.backend_sha256 IS DISTINCT FROM OLD.backend_sha256 THEN
  RAISE EXCEPTION 'rehearsal PostgreSQL backend identity is immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: scenario_postgres_fault_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_postgres_fault_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE p scenario_test_action_policies%ROWTYPE; f scenario_postgres_fixtures%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM scenario_postgres_fixtures WHERE id=OLD.resource_id AND status NOT IN ('complete','deleted'))
   THEN RAISE EXCEPTION 'PostgreSQL fault recovery is retained until resource cleanup' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF (NEW.id,NEW.resource_id,NEW.account_id,NEW.run_id,NEW.app_id,NEW.owner_id) IS DISTINCT FROM
     (OLD.id,OLD.resource_id,OLD.account_id,OLD.run_id,OLD.app_id,OLD.owner_id)
   OR (NEW.receipt - ARRAY['state','activated','recovered','closed_connections','outage_ms','recovery_ms','error','restore_at','deadline_at']) IS DISTINCT FROM
      (OLD.receipt - ARRAY['state','activated','recovered','closed_connections','outage_ms','recovery_ms','error','restore_at','deadline_at'])
   OR NOT ((OLD.phase='requested' AND NEW.phase IN ('cutting','recovering')) OR
    (OLD.phase='cutting' AND NEW.phase IN ('active','recovering')) OR (OLD.phase='active' AND NEW.phase='recovering') OR
    (OLD.phase='recovering' AND NEW.phase IN ('recovered','failed')) OR (OLD.phase='failed' AND NEW.phase='recovering') OR
    (OLD.phase='recovered' AND NEW.phase='failed'))
   OR (OLD.receipt->>'error' IS NOT NULL AND NEW.receipt->>'error' IS DISTINCT FROM OLD.receipt->>'error')
   OR (OLD.receipt->>'activated'='true' AND NEW.receipt->>'activated' IS DISTINCT FROM 'true')
   OR (OLD.receipt->>'recovered'='true' AND NEW.receipt->>'recovered' IS DISTINCT FROM 'true')
   OR ((OLD.receipt->>'restore_at')::timestamptz > '0001-01-01 UTC'::timestamptz AND NEW.receipt->>'restore_at' IS DISTINCT FROM OLD.receipt->>'restore_at')
   OR (NEW.receipt->>'deadline_at')::timestamptz < (OLD.receipt->>'deadline_at')::timestamptz
   THEN RAISE EXCEPTION 'PostgreSQL fault identity or phase is immutable' USING ERRCODE='23514'; END IF;
  IF NEW.phase='recovered' AND NOT ((NEW.receipt->>'activated'='true' AND NEW.receipt->>'recovered'='true'
   AND NOT NEW.receipt ? 'error' AND (NEW.receipt->>'outage_ms')::bigint >= (NEW.receipt->'spec'->>'unavailable_ms')::bigint
   AND (NEW.receipt->>'recovery_ms')::bigint>=0) IS TRUE)
   THEN RAISE EXCEPTION 'PostgreSQL recovery proof is missing' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO p FROM scenario_test_action_policies WHERE app_id=NEW.app_id;
 PERFORM pg_advisory_xact_lock(hashtextextended('scenario-action-run:'||NEW.account_id::text||':'||NEW.run_id,0));
 SELECT * INTO p FROM scenario_test_action_policies WHERE app_id=NEW.app_id;
 SELECT * INTO f FROM scenario_postgres_fixtures WHERE id=NEW.resource_id;
 IF NEW.phase<>'requested' OR p.managed_work_plan->'postgres_fault' IS DISTINCT FROM NEW.receipt->'spec'
  OR NEW.receipt->>'activated' IS DISTINCT FROM 'false' OR NEW.receipt->>'recovered' IS DISTINCT FROM 'false'
  OR NEW.receipt->>'closed_connections' IS DISTINCT FROM '0' OR NEW.receipt->>'outage_ms' IS DISTINCT FROM '0'
  OR NEW.receipt->>'recovery_ms' IS DISTINCT FROM '0' OR NEW.receipt ? 'error'
  OR NOT coalesce(NEW.receipt->>'plan_sha256' ~ '^[a-f0-9]{64}$',false)
  OR p.account_id IS DISTINCT FROM NEW.account_id OR p.run_id IS DISTINCT FROM NEW.run_id
  OR p.sealed_at IS NOT NULL OR p.recorder_closing OR p.managed_work_failed
  OR f.owner_id IS DISTINCT FROM NEW.owner_id OR f.account_id IS DISTINCT FROM NEW.account_id OR f.run_id IS DISTINCT FROM NEW.run_id
  OR f.backend_sha256 IS DISTINCT FROM NEW.receipt->>'backend_sha256' OR f.status IS DISTINCT FROM 'ready' OR f.expires_at<=clock_timestamp()
  OR NOT EXISTS(SELECT 1 FROM scenario_recorder_sessions r JOIN scenario_recorder_requests q ON q.session_id=r.id
   JOIN instances i ON i.id=r.instance_id JOIN invocations v ON nullif(v.instance_id,'')::uuid=i.id AND v.app_id=i.app_id
   WHERE r.id=(NEW.receipt->>'recorder_session_id')::uuid AND r.app_id=NEW.app_id AND r.instance_id=(NEW.receipt->>'instance_id')::uuid
    AND r.deployment_id=(NEW.receipt->>'deployment_id')::uuid AND r.status='recording' AND q.status='admitted'
    AND q.attempt_id=(NEW.receipt->>'checkpoint_attempt_id')::uuid AND i.state='running'
    AND v.id=(NEW.receipt->>'invocation_id')::uuid AND v.state='dispatching' AND v.source='async_invoke'
    AND v.attempts=1 AND v.replay_generation=0 AND v.lease_expires_at>clock_timestamp())
  THEN RAISE EXCEPTION 'PostgreSQL fault checkpoint is not owned by its original dispatch' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $_$;


--
-- Name: scenario_postgres_fault_policy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_postgres_fault_policy_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE f jsonb; p jsonb;
BEGIN
 f:=NEW.managed_work_plan->'postgres_fault'; p:=NEW.managed_work_plan;
 IF f IS NULL THEN RETURN NEW; END IF;
 IF NOT ((f->>'workload' ~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'
  AND f->>'checkpoint' ~ '^[a-z][a-z0-9-]{0,62}$'
  AND (f->>'unavailable_ms')::bigint BETWEEN 100 AND 30000
  AND (f->>'recover_within_ms')::bigint BETWEEN 1 AND 120000
  AND NEW.suspend_resume_spec IS NULL AND NEW.cold_start_spec IS NULL AND NOT p ? 'worker_termination'
  AND jsonb_array_length(p->'participants')=2
  AND (SELECT count(*) FROM jsonb_array_elements(p->'participants') v WHERE coalesce((v->>'async')::boolean,false))=1
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(p->'participants') v WHERE v->>'workload'=f->>'workload' AND v->>'postgres'='read_write' AND v->>'async'='true')
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(p->'participants') v WHERE v->>'workload'=p->>'primary' AND v->>'postgres'='read_write' AND NOT coalesce((v->>'async')::boolean,false))
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.simulation_plan->'fixtures') v
   WHERE v->>'workload'=f->>'workload' AND v->>'name'=f->>'checkpoint' AND v->>'integration'='checkpoint'
   AND v->>'adapter'='http' AND v->>'method'='POST' AND jsonb_array_length(v->'responses')=1
   AND v->'responses'->0->>'status'='200' AND coalesce(v->'responses'->0->>'fault','')=''
   AND coalesce(v->'responses'->0->>'delay_ms','0')='0' AND coalesce(v->'responses'->0->>'retry_after_seconds','0')='0')) IS TRUE)
  THEN RAISE EXCEPTION 'unsupported PostgreSQL fault enrollment' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $_$;


--
-- Name: scenario_postgres_fault_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_postgres_fault_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p scenario_test_action_policies%ROWTYPE;
BEGIN
 SELECT * INTO p FROM scenario_test_action_policies WHERE app_id=NEW.app_id;
 IF p.managed_work_plan->'postgres_fault' IS NULL THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('scenario-action-run:'||p.account_id::text||':'||p.run_id,0));
 IF TG_OP='INSERT' THEN
  IF p.workload_name IS DISTINCT FROM p.managed_work_plan->'postgres_fault'->>'workload' OR NEW.source<>'async_invoke'
   OR EXISTS(SELECT 1 FROM invocations v JOIN scenario_test_action_policies w ON w.app_id=v.app_id WHERE w.account_id=p.account_id AND w.run_id=p.run_id)
   THEN RAISE EXCEPTION 'PostgreSQL fault supports one managed HTTP job' USING ERRCODE='23514'; END IF;
 ELSIF NEW.state='dispatching' AND (NEW.state,NEW.attempts,NEW.instance_id) IS DISTINCT FROM (OLD.state,OLD.attempts,OLD.instance_id) THEN
  IF EXISTS(SELECT 1 FROM scenario_postgres_faults f WHERE f.account_id=p.account_id AND f.run_id=p.run_id AND
   (f.phase IN ('requested','cutting') OR (nullif(NEW.instance_id,'') IS NOT NULL AND NEW.instance_id IS DISTINCT FROM f.receipt->>'instance_id')))
   THEN RAISE EXCEPTION 'PostgreSQL recovery retains its original worker dispatch' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_postgres_fixture_delete_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_postgres_fixture_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.status NOT IN ('complete','deleted') THEN
  RAISE EXCEPTION 'rehearsal PostgreSQL cleanup must be confirmed before deleting its journal' USING ERRCODE='23514';
 END IF;
 RETURN OLD;
END $$;


--
-- Name: scenario_postgres_fixture_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_postgres_fixture_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF (NEW.id,NEW.account_id,NEW.run_id,NEW.app_id,NEW.owner_id,NEW.database_name,NEW.role_name,NEW.spec,NEW.expires_at)
   IS DISTINCT FROM (OLD.id,OLD.account_id,OLD.run_id,OLD.app_id,OLD.owner_id,OLD.database_name,OLD.role_name,OLD.spec,OLD.expires_at)
 OR NOT ((OLD.status='provisioning' AND NEW.status IN ('ready','failed','deleted'))
 OR (OLD.status='ready' AND NEW.status IN ('sealing','failed','deleted'))
 OR (OLD.status='sealing' AND NEW.status IN ('complete','failed','deleted'))
 OR (OLD.status='failed' AND NEW.status='deleted'))
 OR (OLD.status<>'provisioning' AND NEW.initial_snapshot IS DISTINCT FROM OLD.initial_snapshot)
 OR (NEW.status<>'complete' AND NEW.evidence IS DISTINCT FROM OLD.evidence) THEN
  RAISE EXCEPTION 'rehearsal PostgreSQL journal is immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_recorder_closing_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_recorder_closing_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.recorder_closing AND NOT NEW.recorder_closing THEN
  RAISE EXCEPTION 'recorder closing is irreversible' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_recorder_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_recorder_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target_app uuid; policy scenario_test_action_policies%ROWTYPE; parent scenario_recorder_sessions%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='scenario_recorder_sessions' THEN
  target_app:=NEW.app_id;
  IF TG_OP='UPDATE' AND ((NEW.id,NEW.app_id,NEW.instance_id,NEW.deployment_id,NEW.created_at)
       IS DISTINCT FROM (OLD.id,OLD.app_id,OLD.instance_id,OLD.deployment_id,OLD.created_at)
       OR OLD.status<>'recording' OR NEW.status NOT IN ('closed','failed')) THEN
   RAISE EXCEPTION 'recorder identity or terminal receipt is immutable' USING ERRCODE='23514';
  END IF;
 ELSE
  SELECT * INTO parent FROM scenario_recorder_sessions WHERE id=NEW.session_id;
  target_app:=parent.app_id;
  IF TG_OP='UPDATE' AND ((NEW.id,NEW.session_id) IS DISTINCT FROM (OLD.id,OLD.session_id)
       OR (OLD.attempt_id IS NOT NULL AND NEW.attempt_id IS DISTINCT FROM OLD.attempt_id)
       OR NOT ((OLD.status='pending' AND NEW.status IN ('admitted','failed'))
            OR (OLD.status='admitted' AND NEW.status IN ('completed','failed')))) THEN
   RAISE EXCEPTION 'recorder request identity or terminal receipt is immutable' USING ERRCODE='23514';
  END IF;
 END IF;
 SELECT * INTO policy FROM scenario_test_action_policies WHERE app_id=target_app;
 PERFORM pg_advisory_xact_lock(hashtextextended('scenario-action-run:' || policy.account_id::text || ':' || policy.run_id,0));
 PERFORM id FROM apps WHERE id=target_app FOR KEY SHARE;
 SELECT * INTO policy FROM scenario_test_action_policies WHERE app_id=target_app;
 IF policy.app_id IS NULL OR policy.simulation_plan IS NULL OR policy.sealed_at IS NOT NULL THEN
  RAISE EXCEPTION 'recorder window is unavailable or sealed' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' AND (policy.recorder_closing OR
      (TG_TABLE_NAME='scenario_recorder_sessions' AND NEW.status<>'recording') OR
      (TG_TABLE_NAME='scenario_recorder_requests' AND (NEW.status<>'pending' OR parent.status<>'recording'))) THEN
  RAISE EXCEPTION 'recorder admission is closed' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME='scenario_recorder_sessions' THEN
  IF TG_OP='INSERT' AND NEW.command_result IS NOT NULL THEN
   RAISE EXCEPTION 'command retirement cannot be supplied at recorder start' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND NOT scenario_rehearsal_execution_active(NEW.app_id,NEW.instance_id,NEW.deployment_id) THEN
   RAISE EXCEPTION 'recorder execution identity is unavailable' USING ERRCODE='23514';
  END IF;
  IF NEW.command_result IS NOT NULL AND (NEW.command_result::jsonb->>'task_id' IS DISTINCT FROM NEW.instance_id::text
      OR NOT scenario_rehearsal_execution_active(NEW.app_id,NEW.instance_id,NEW.deployment_id)
      OR NOT EXISTS(SELECT 1 FROM app_tasks WHERE id=NEW.instance_id)) THEN
   RAISE EXCEPTION 'command retirement requires its active task identity' USING ERRCODE='23514';
  END IF;
  IF NEW.status='closed' AND ((NOT policy.recorder_closing AND NEW.command_result IS NULL AND NOT EXISTS
     (SELECT 1 FROM scenario_worker_faults f WHERE f.recorder_session_id=NEW.id AND f.app_id=NEW.app_id
      AND f.instance_id=NEW.instance_id AND f.deployment_id=NEW.deployment_id AND f.account_id=policy.account_id
      AND f.run_id=policy.run_id AND f.state='terminated') AND NOT EXISTS
     (SELECT 1 FROM scenario_cold_preparations c WHERE c.recorder_session_id=NEW.id AND c.app_id=NEW.app_id
      AND c.instance_id=NEW.instance_id AND c.deployment_id=NEW.deployment_id AND c.account_id=policy.account_id
      AND c.run_id=policy.run_id AND c.state IN ('retired','ready','booted'))) OR EXISTS(SELECT 1 FROM scenario_recorder_requests
      WHERE session_id=NEW.id AND status<>'completed')) THEN
   RAISE EXCEPTION 'recorder closing requires settled request receipts' USING ERRCODE='23514';
  END IF;
 ELSE
  IF NEW.attempt_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM scenario_simulation_attempts e
      WHERE e.id=NEW.attempt_id AND e.app_id=target_app AND
       ((NEW.status='admitted' AND e.evidence->>'status'='pending') OR
        (NEW.status='completed' AND e.evidence->>'status'='completed') OR
        (NEW.status='failed' AND e.evidence->>'status' IN ('interrupted','unsupported')))) THEN
   RAISE EXCEPTION 'recorder acknowledgement does not match simulation evidence' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_rehearsal_command_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_rehearsal_command_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE policy scenario_test_action_policies%ROWTYPE; spec jsonb;
BEGIN
 SELECT * INTO policy FROM scenario_test_action_policies WHERE app_id=NEW.app_id;
 spec:=scenario_rehearsal_command_spec(NEW.command);
 IF policy.network_mode IS DISTINCT FROM 'contained' AND NEW.command[1] IS DISTINCT FROM '__gregale_rehearsal_command_v1__' THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('scenario-action-run:' || policy.account_id::text || ':' || policy.run_id,0));
 PERFORM id FROM apps WHERE id=NEW.app_id FOR KEY SHARE;
 SELECT * INTO policy FROM scenario_test_action_policies WHERE app_id=NEW.app_id;
 IF spec IS NULL OR policy.app_id IS NULL OR policy.account_id<>NEW.account_id
  OR policy.network_mode IS DISTINCT FROM 'contained' OR policy.simulation_plan IS NULL
  OR policy.sealed_at IS NOT NULL OR policy.recorder_closing OR policy.simulation_failed
  OR spec->>'run_id'<>policy.run_id OR spec->>'deployment_id'<>NEW.deployment_id::text
  OR NEW.kind<>'manual' OR NEW.command_shell OR NEW.max_output_bytes<>65536
  OR NOT EXISTS(SELECT 1 FROM deployments WHERE id=NEW.deployment_id AND app_id=NEW.app_id AND status='live')
  OR EXISTS(SELECT 1 FROM app_task_attach_sessions WHERE task_id=NEW.id) THEN
  RAISE EXCEPTION 'contained command admission is unavailable' USING ERRCODE='23514';
 END IF;
 IF (SELECT count(*) FROM app_tasks t JOIN scenario_test_action_policies p ON p.app_id=t.app_id
     WHERE p.account_id=policy.account_id AND p.run_id=policy.run_id)>=256 THEN
  RAISE EXCEPTION 'contained command evidence bound exceeded' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_rehearsal_command_attach_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_rehearsal_command_attach_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM app_tasks t WHERE t.id=NEW.task_id AND
  (t.command[1]='__gregale_rehearsal_command_v1__' OR EXISTS(SELECT 1 FROM scenario_test_action_policies p WHERE p.app_id=t.app_id AND p.network_mode='contained'))) THEN
  RAISE EXCEPTION 'contained commands cannot attach an interactive client' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_rehearsal_command_spec(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_rehearsal_command_spec(argv text[]) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE spec jsonb;
BEGIN
 IF argv[1] IS DISTINCT FROM '__gregale_rehearsal_command_v1__' OR cardinality(argv) NOT BETWEEN 2 AND 5 THEN RETURN NULL; END IF;
 BEGIN spec:=array_to_string(argv[2:cardinality(argv)],'')::jsonb;
 EXCEPTION WHEN invalid_text_representation THEN RETURN NULL; END;
 IF octet_length(array_to_string(argv,''))>16384 OR spec->>'version' IS DISTINCT FROM '1'
  OR coalesce(spec->>'run_id','')!~'^[0-9a-f]{32}$'
  OR coalesce(spec->>'deployment_id','')!~'^[0-9a-f-]{36}$' THEN RETURN NULL; END IF;
 RETURN spec;
END $_$;


--
-- Name: scenario_rehearsal_command_update_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_rehearsal_command_update_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.command[1] IS DISTINCT FROM '__gregale_rehearsal_command_v1__'
  AND NEW.command[1] IS DISTINCT FROM '__gregale_rehearsal_command_v1__'
  AND NOT EXISTS(SELECT 1 FROM scenario_test_action_policies WHERE app_id=OLD.app_id AND network_mode='contained') THEN RETURN NEW; END IF;
 IF (NEW.id,NEW.account_id,NEW.app_id,NEW.deployment_id,NEW.kind,NEW.command,NEW.command_shell,
     NEW.timeout_seconds,NEW.max_output_bytes,NEW.artifact_key,NEW.image_digest,NEW.deployment_scope)
  IS DISTINCT FROM
    (OLD.id,OLD.account_id,OLD.app_id,OLD.deployment_id,OLD.kind,OLD.command,OLD.command_shell,
     OLD.timeout_seconds,OLD.max_output_bytes,OLD.artifact_key,OLD.image_digest,OLD.deployment_scope) THEN
  RAISE EXCEPTION 'contained command intent is immutable' USING ERRCODE='23514';
 END IF;
 IF NEW.status='succeeded' AND (NEW.output_truncated OR NOT EXISTS(
  SELECT 1 FROM scenario_recorder_sessions r WHERE r.instance_id=NEW.id AND r.app_id=NEW.app_id
   AND r.deployment_id=NEW.deployment_id AND r.status='closed' AND r.command_result=NEW.stdout_tail)) THEN
  RAISE EXCEPTION 'contained command success requires its owner retirement receipt' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_rehearsal_execution_active(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_rehearsal_execution_active(target_app uuid, execution_id uuid, deployment uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT scenario_suspend_execution_active(target_app,execution_id) AND NOT EXISTS(SELECT 1 FROM scenario_worker_faults f WHERE f.app_id=target_app AND f.instance_id=execution_id AND f.state IN ('fenced','terminated','failed')) AND
 (EXISTS(SELECT 1 FROM instances i WHERE i.id=execution_id AND i.app_id=target_app
  AND (deployment IS NULL OR i.deployment_id=deployment) AND (i.state IN ('waking','cold_booting','running','draining') OR i.state='frozen' AND EXISTS
   (SELECT 1 FROM scenario_suspend_resumes r WHERE r.app_id=target_app AND r.instance_id=i.id AND r.state IN ('resuming','resumed')))
  AND NOT EXISTS(SELECT 1 FROM scenario_cold_preparations c WHERE c.app_id=target_app AND
   (c.state='failed' OR c.deployment_id<>i.deployment_id OR
    (c.state IN ('armed','claimed') AND c.instance_id IS DISTINCT FROM i.id) OR
    c.state IN ('fenced','retired') OR c.instance_id=i.id AND c.state IN ('ready','booted') OR
    c.state='booted' AND c.boot_instance_id<>i.id)))
 OR EXISTS(SELECT 1 FROM app_tasks t JOIN scenario_test_action_policies p ON p.app_id=t.app_id
  WHERE t.id=execution_id AND t.app_id=target_app AND t.account_id=p.account_id
  AND (deployment IS NULL OR t.deployment_id=deployment) AND t.status IN ('restoring','running')
  AND t.kind='manual' AND NOT t.command_shell AND t.max_output_bytes=65536
  AND scenario_rehearsal_command_spec(t.command)->>'run_id'=p.run_id
  AND scenario_rehearsal_command_spec(t.command)->>'deployment_id'=t.deployment_id::text
  AND p.network_mode='contained' AND p.simulation_plan IS NOT NULL AND p.sealed_at IS NULL));
$$;


--
-- Name: scenario_simulation_policy_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_simulation_policy_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.simulation_plan IS DISTINCT FROM OLD.simulation_plan OR
    (OLD.simulation_failed AND NOT NEW.simulation_failed) THEN
  RAISE EXCEPTION 'rehearsal simulation policy is immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_simulation_sealed_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_simulation_sealed_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.id,NEW.app_id,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.app_id,OLD.created_at)
     OR (NEW.evidence-'status') IS DISTINCT FROM (OLD.evidence-'status')
     OR OLD.evidence->>'status'<>'pending'
     OR NEW.evidence->>'status' NOT IN ('completed','interrupted') THEN
   RAISE EXCEPTION 'scenario simulation evidence is immutable' USING ERRCODE='23514';
  END IF;
 END IF;
 PERFORM id FROM apps WHERE id=NEW.app_id FOR KEY SHARE;
 IF NOT EXISTS(SELECT 1 FROM scenario_test_action_policies WHERE app_id=NEW.app_id AND simulation_plan IS NOT NULL AND sealed_at IS NULL) THEN
  RAISE EXCEPTION 'scenario simulation window is unavailable or sealed' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_suspend_dispatch_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_suspend_dispatch_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.state='dispatching' AND (NEW.state,NEW.attempts,NEW.instance_id) IS DISTINCT FROM (OLD.state,OLD.attempts,OLD.instance_id)
  AND EXISTS(SELECT 1 FROM scenario_suspend_resumes r WHERE r.app_id=NEW.app_id AND r.invocation_id IS NOT NULL AND r.state<>'complete') THEN
  RAISE EXCEPTION 'managed dispatch must wait for the original suspend/resume checkpoint' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_suspend_execution_active(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_suspend_execution_active(target_app uuid, execution_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT NOT EXISTS(SELECT 1 FROM scenario_suspend_resumes r WHERE r.app_id=target_app AND
  (r.state IN ('fenced','paused','failed') OR (r.instance_id<>execution_id AND EXISTS(SELECT 1 FROM instances i WHERE i.id=execution_id))));
$$;


--
-- Name: scenario_suspend_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_suspend_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p scenario_test_action_policies%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM apps WHERE id=OLD.app_id) AND EXISTS(SELECT 1 FROM accounts WHERE id=OLD.account_id)
   THEN RAISE EXCEPTION 'suspend/resume evidence is retained until app deletion' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 SELECT * INTO p FROM scenario_test_action_policies WHERE app_id=NEW.app_id;
 PERFORM pg_advisory_xact_lock(hashtextextended('scenario-action-run:'||p.account_id::text||':'||p.run_id,0));
 SELECT * INTO p FROM scenario_test_action_policies WHERE app_id=NEW.app_id;
 IF p.suspend_resume_spec IS NULL OR NOT (p.suspend_resume_spec->'workloads' ? p.workload_name)
  OR p.sealed_at IS NOT NULL OR p.recorder_closing OR p.simulation_failed
  OR p.account_id<>NEW.account_id OR p.run_id<>NEW.run_id THEN
  RAISE EXCEPTION 'suspend/resume enrollment unavailable or sealed' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>(CASE WHEN p.suspend_resume_spec->>'checkpoint'='managed_job' THEN 'waiting' ELSE 'armed' END) OR NEW.method IS NOT NULL OR NEW.pause_ms<>0 OR NEW.resume_ms<>0 OR NEW.paused_at IS NOT NULL THEN
   RAISE EXCEPTION 'suspend/resume must begin unacknowledged' USING ERRCODE='23514'; END IF;
 ELSE
  IF (NEW.id,NEW.account_id,NEW.app_id,NEW.run_id,NEW.deployment_id,NEW.instance_id,NEW.recorder_session_id,NEW.invocation_id,NEW.invocation_attempt,NEW.checkpoint_attempt_id,NEW.created_at)
   IS DISTINCT FROM (OLD.id,OLD.account_id,OLD.app_id,OLD.run_id,OLD.deployment_id,OLD.instance_id,OLD.recorder_session_id,OLD.invocation_id,OLD.invocation_attempt,OLD.checkpoint_attempt_id,OLD.created_at)
   OR NOT ((OLD.state='waiting' AND NEW.state='armed') OR (OLD.state='armed' AND NEW.state='claimed') OR (OLD.state='claimed' AND NEW.state='fenced')
    OR (OLD.state='fenced' AND NEW.state='paused') OR (OLD.state='paused' AND NEW.state='resuming')
    OR (OLD.state='resuming' AND NEW.state='resumed') OR (OLD.state='resumed' AND NEW.state='complete')
    OR (OLD.state NOT IN ('complete','failed') AND NEW.state='failed'))
   OR (NEW.state<>'paused' AND NEW.paused_at IS DISTINCT FROM OLD.paused_at)
   OR (NEW.state<>'resuming' AND NEW.pause_ms<>OLD.pause_ms)
   OR (NEW.state<>'resumed' AND (NEW.method,NEW.resume_ms) IS DISTINCT FROM (OLD.method,OLD.resume_ms)) THEN
   RAISE EXCEPTION 'suspend/resume identity or lifecycle is immutable' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.state<>'failed' AND NOT EXISTS(SELECT 1 FROM scenario_recorder_sessions r JOIN instances i ON i.id=r.instance_id
  JOIN apps a ON a.id=i.app_id JOIN scenario_test_members m ON m.app_id=a.id
  WHERE r.id=NEW.recorder_session_id AND r.app_id=NEW.app_id AND r.deployment_id=NEW.deployment_id AND r.status='recording'
   AND i.id=NEW.instance_id AND i.app_id=NEW.app_id AND i.deployment_id=NEW.deployment_id AND i.tail_count=0
   AND i.state=CASE WHEN NEW.state IN ('waiting','armed','claimed','complete') THEN 'running' ELSE 'frozen' END
   AND a.account_id=NEW.account_id AND a.status='active' AND a.preview_of_slug IS NOT NULL
   AND a.preview_pr_number=0 AND a.preview_pr_state='open' AND a.preview_expires_at>clock_timestamp()
   AND m.account_id=NEW.account_id AND m.run_id=NEW.run_id) THEN
  RAISE EXCEPTION 'suspend/resume requires its original live VM and recorder' USING ERRCODE='23514'; END IF;
 IF NEW.state<>'failed' AND (
  EXISTS(SELECT 1 FROM scenario_recorder_requests q WHERE q.session_id=NEW.recorder_session_id AND q.status<>'completed' AND NOT (NEW.state='waiting' AND q.status='admitted' AND q.attempt_id=NEW.checkpoint_attempt_id))
  OR EXISTS(SELECT 1 FROM invocations v JOIN scenario_test_action_policies w ON w.app_id=v.app_id WHERE w.account_id=p.account_id AND w.run_id=p.run_id AND (NEW.invocation_id IS NULL OR v.id<>NEW.invocation_id))
  OR EXISTS(SELECT 1 FROM app_tasks t JOIN scenario_test_action_policies w ON w.app_id=t.app_id
    WHERE w.account_id=p.account_id AND w.run_id=p.run_id AND t.status IN ('queued','restoring','running') AND NEW.state<>'waiting')
  OR EXISTS(SELECT 1 FROM instances i WHERE i.app_id=NEW.app_id AND i.id<>NEW.instance_id AND i.state NOT IN ('stopped','parked','failed'))
  OR EXISTS(SELECT 1 FROM exclusive_work_operations o WHERE o.app_id=NEW.app_id AND o.state IN ('pending','running'))
  OR EXISTS(SELECT 1 FROM workflow_runs w WHERE w.app_id=NEW.app_id AND w.status IN ('pending','running','awaiting_event'))
  OR (SELECT count(*) FROM deployments WHERE app_id=NEW.app_id)<>1) THEN
  RAISE EXCEPTION 'suspend/resume checkpoint has unsettled work' USING ERRCODE='23514'; END IF;
 IF (p.suspend_resume_spec->>'checkpoint'='managed_job') IS DISTINCT FROM (NEW.invocation_id IS NOT NULL)
  OR NEW.state<>'failed' AND NEW.invocation_id IS NOT NULL AND NOT scenario_suspend_job_active(NEW) THEN
  RAISE EXCEPTION 'suspend/resume enrolled dispatch changed or is unavailable' USING ERRCODE='23514'; END IF;
 IF NEW.state='armed' AND NEW.invocation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM scenario_simulation_attempts a
   WHERE a.id=NEW.checkpoint_attempt_id AND a.app_id=NEW.app_id AND a.evidence->>'status'='completed'
   AND a.evidence->>'fixture'=p.suspend_resume_spec->>'worker_checkpoint') THEN
  RAISE EXCEPTION 'suspend/resume checkpoint has not completed at its broker' USING ERRCODE='23514'; END IF;
 IF NEW.state='paused' AND NEW.paused_at IS NULL OR NEW.state IN ('resuming','resumed','complete')
  AND (NEW.paused_at IS NULL OR NEW.pause_ms<(p.suspend_resume_spec->>'pause_ms')::bigint) THEN
  RAISE EXCEPTION 'suspend/resume pause proof is missing' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_suspend_resumes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.scenario_suspend_resumes (
    id uuid NOT NULL,
    account_id uuid NOT NULL,
    app_id uuid NOT NULL,
    run_id text NOT NULL,
    deployment_id uuid NOT NULL,
    instance_id uuid NOT NULL,
    recorder_session_id uuid NOT NULL,
    state text NOT NULL,
    method text,
    pause_ms bigint DEFAULT 0 NOT NULL,
    resume_ms bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    paused_at timestamp with time zone,
    invocation_id uuid,
    invocation_attempt integer,
    checkpoint_attempt_id uuid,
    CONSTRAINT scenario_suspend_dispatch_identity CHECK ((((invocation_id IS NULL) AND (invocation_attempt IS NULL) AND (checkpoint_attempt_id IS NULL)) OR (((invocation_id IS NOT NULL) AND (invocation_attempt = 1) AND (checkpoint_attempt_id IS NOT NULL)) IS TRUE))),
    CONSTRAINT scenario_suspend_resumes_check CHECK (((state <> ALL (ARRAY['resumed'::text, 'complete'::text])) OR (method = 'in_place'::text))),
    CONSTRAINT scenario_suspend_resumes_method_check CHECK (((method IS NULL) OR (method = 'in_place'::text))),
    CONSTRAINT scenario_suspend_resumes_pause_ms_check CHECK ((pause_ms >= 0)),
    CONSTRAINT scenario_suspend_resumes_resume_ms_check CHECK ((resume_ms >= 0)),
    CONSTRAINT scenario_suspend_resumes_run_id_check CHECK ((run_id ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT scenario_suspend_resumes_state_check CHECK ((state = ANY (ARRAY['waiting'::text, 'armed'::text, 'claimed'::text, 'fenced'::text, 'paused'::text, 'resuming'::text, 'resumed'::text, 'complete'::text, 'failed'::text])))
);


--
-- Name: scenario_suspend_job_active(public.scenario_suspend_resumes); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_suspend_job_active(r public.scenario_suspend_resumes) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM invocations v WHERE v.id=r.invocation_id AND v.app_id=r.app_id
  AND nullif(v.instance_id,'')::uuid=r.instance_id AND v.state='dispatching' AND v.source='async_invoke'
  AND v.attempts=r.invocation_attempt AND v.attempts=1 AND v.lease_expires_at>clock_timestamp()
  AND v.replay_generation=0)
 AND (SELECT count(*) FROM invocations v JOIN scenario_test_action_policies p ON p.app_id=v.app_id
  WHERE p.account_id=r.account_id AND p.run_id=r.run_id)=1;
$$;


--
-- Name: scenario_suspend_policy_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_suspend_policy_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN IF NEW.suspend_resume_spec IS DISTINCT FROM OLD.suspend_resume_spec THEN
 RAISE EXCEPTION 'suspend/resume plan is immutable' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;


--
-- Name: scenario_suspend_work_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_suspend_work_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p scenario_test_action_policies%ROWTYPE;
BEGIN
 SELECT * INTO p FROM scenario_test_action_policies WHERE app_id=NEW.app_id;
 IF p.suspend_resume_spec IS NOT NULL THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('scenario-action-run:'||p.account_id::text||':'||p.run_id,0));
  IF TG_TABLE_NAME='invocations' AND p.suspend_resume_spec->>'checkpoint'='managed_job' THEN
   IF (p.workload_name<>(p.suspend_resume_spec->'workloads'->>0) OR NEW.source<>'async_invoke' OR
     EXISTS(SELECT 1 FROM invocations v JOIN scenario_test_action_policies w ON w.app_id=v.app_id WHERE w.account_id=p.account_id AND w.run_id=p.run_id)) THEN
    RAISE EXCEPTION 'running-job suspend supports one managed job in its run' USING ERRCODE='23514'; END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM scenario_suspend_resumes r WHERE r.account_id=p.account_id AND r.run_id=p.run_id AND r.state<>'complete') THEN
   RAISE EXCEPTION 'work must wait for the suspend/resume checkpoint' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scenario_webhook_delivery_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_webhook_delivery_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Serialize new deliveries with the registration transaction. A registration
    -- takes FOR UPDATE and refuses any app that already has work or deliveries.
    PERFORM id FROM apps
    WHERE id = NEW.app_id OR id = (SELECT app_id FROM app_webhooks WHERE id = NEW.webhook_id)
    ORDER BY id FOR KEY SHARE;
    IF EXISTS (
        SELECT 1 FROM scenario_test_action_policies p
        WHERE p.app_id = NEW.app_id
           OR p.app_id = (SELECT app_id FROM app_webhooks WHERE id = NEW.webhook_id)
    ) AND NEW.status IN ('pending', 'in_flight', 'failed') THEN
        NEW.status := 'dead';
        NEW.last_error := 'rehearsal: unsupported webhook delivery suppressed';
        NEW.updated_at := clock_timestamp();
    END IF;
    RETURN NEW;
END $$;


--
-- Name: scenario_worker_fault_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scenario_worker_fault_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM accounts WHERE id=OLD.account_id) AND EXISTS(SELECT 1 FROM apps WHERE id=OLD.app_id) AND EXISTS(SELECT 1 FROM scenario_test_action_policies WHERE app_id=OLD.app_id AND sealed_at IS NULL)
   THEN RAISE EXCEPTION 'unsealed worker fault evidence is retained' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF ROW(NEW.id,NEW.account_id,NEW.app_id,NEW.run_id,NEW.instance_id,NEW.deployment_id,NEW.invocation_id,NEW.checkpoint_attempt_id,NEW.recorder_session_id,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.id,OLD.account_id,OLD.app_id,OLD.run_id,OLD.instance_id,OLD.deployment_id,OLD.invocation_id,OLD.checkpoint_attempt_id,OLD.recorder_session_id,OLD.created_at)
  OR NOT(NEW.state=OLD.state OR (OLD.state<>'terminated' AND NEW.state='failed')
  OR (OLD.state='armed' AND NEW.state='ready') OR (OLD.state='ready' AND NEW.state='claimed')
  OR (OLD.state='claimed' AND NEW.state='fenced') OR (OLD.state='fenced' AND NEW.state='terminated'))
 THEN RAISE EXCEPTION 'worker fault identity or lifecycle is immutable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: seed_resource_namespace(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_resource_namespace() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO resource_namespaces(id) VALUES (NEW.id) ON CONFLICT DO NOTHING;
    RETURN NEW;
END $$;


--
-- Name: seed_runtime_upgrade_public_edge_withdrawals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_runtime_upgrade_public_edge_withdrawals() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton FOR SHARE;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton FOR SHARE;
 INSERT INTO runtime_upgrade_public_edge_withdrawals(id,slot_id,public_session_id,config_sha256,roster_revision)
 SELECT gen_random_uuid(),slot_id,public_session_id,config_sha256,revision FROM (
  SELECT DISTINCT ON (r.public_sessions[i]) r.slot_ids[i] AS slot_id,r.public_sessions[i] AS public_session_id,r.config_sha256s[i] AS config_sha256,r.revision
  FROM runtime_upgrade_public_edge_rosters r, generate_subscripts(r.public_sessions,1) i
  WHERE NOT EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_rosters live JOIN runtime_upgrade_public_edge_roster_head h ON h.revision=live.revision WHERE r.public_sessions[i]=ANY(live.public_sessions))
  ORDER BY r.public_sessions[i],r.created_at DESC,r.revision DESC
 ) historical ON CONFLICT (public_session_id) DO NOTHING;
END $$;


--
-- Name: serialize_clone_value_publication(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.serialize_clone_value_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE app_ids uuid[];
BEGIN
    IF TG_OP = 'INSERT' THEN
        app_ids := ARRAY[NEW.app_id];
    ELSIF TG_OP = 'DELETE' THEN
        app_ids := ARRAY[OLD.app_id];
    ELSE
        app_ids := ARRAY[OLD.app_id, NEW.app_id];
    END IF;
    PERFORM id FROM apps WHERE id = ANY(app_ids) ORDER BY id FOR NO KEY UPDATE;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: serialize_runtime_deployment_configuration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.serialize_runtime_deployment_configuration() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE deployment_ids uuid[];
BEGIN
    IF TG_OP='INSERT' THEN deployment_ids:=ARRAY[NEW.deployment_id];
    ELSIF TG_OP='DELETE' THEN deployment_ids:=ARRAY[OLD.deployment_id];
    ELSE deployment_ids:=ARRAY[OLD.deployment_id,NEW.deployment_id]; END IF;
    PERFORM id FROM deployments WHERE id=ANY(deployment_ids) ORDER BY id FOR NO KEY UPDATE;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: service_capacity_after_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_capacity_after_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE before_text text; prior jsonb; next jsonb; k text; value jsonb; grew boolean := false; excess boolean; physical_growth boolean:=false; service_growth boolean:=false;
BEGIN
    before_text := current_setting('gregale.capacity_' || TG_TABLE_NAME || '_' || pg_trigger_depth()::text,true);
    IF coalesce(before_text,'')='' THEN RETURN NULL; END IF;
    prior:=before_text::jsonb; next:=service_capacity_snapshot();
    FOR k,value IN SELECT * FROM jsonb_each(next->'demands') LOOP
        IF (value->>'count')::bigint>0 AND (
            NOT (prior->'demands' ? k) OR
            (value->>'count')::bigint>coalesce((prior->'demands'->k->>'count')::bigint,0) OR
            (value->>'ram')::bigint>(prior->'demands'->k->>'ram')::bigint OR
            (value->>'cpu')::bigint>(prior->'demands'->k->>'cpu')::bigint OR
            (value->>'vcpu')::bigint>(prior->'demands'->k->>'vcpu')::bigint) THEN grew:=true; END IF;
    END LOOP;
    FOR k,value IN SELECT * FROM jsonb_each(next->'resident') LOOP
        IF (value->>'ram')::bigint>coalesce((prior->'resident'->k->>'ram')::bigint,0) OR
           (value->>'cpu')::bigint>coalesce((prior->'resident'->k->>'cpu')::bigint,0) OR
           (value->>'vcpu')::bigint>coalesce((prior->'resident'->k->>'vcpu')::bigint,0) THEN
            physical_growth:=true;
            IF NOT (next->'other' ? k) THEN
                RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='service_capacity_protection',MESSAGE='node is not ready for protected admission';
            END IF;
            IF (next->'other'->k->>'ram')::bigint>coalesce((prior->'other'->k->>'ram')::bigint,0) OR
               (next->'other'->k->>'cpu')::bigint>coalesce((prior->'other'->k->>'cpu')::bigint,0) OR
               (next->'other'->k->>'vcpu')::bigint>coalesce((prior->'other'->k->>'vcpu')::bigint,0) THEN grew:=true; END IF;
        END IF;
    END LOOP;
    -- Instance role changes cannot remove declarations. Ordinary growth from
    -- these writes must preserve headroom; removing app/deployment intent may
    -- reclassify resident guests without blocking stops.
    IF TG_TABLE_NAME='instances' THEN
        FOR k,value IN SELECT * FROM jsonb_each(next->'other') LOOP
            IF (value->>'ram')::bigint>coalesce((prior->'other'->k->>'ram')::bigint,0) OR
               (value->>'cpu')::bigint>coalesce((prior->'other'->k->>'cpu')::bigint,0) OR
               (value->>'vcpu')::bigint>coalesce((prior->'other'->k->>'vcpu')::bigint,0) THEN grew:=true; END IF;
        END LOOP;
    END IF;
    -- Reclassification can occupy service slots without allocating resources.
    -- Include ineligible hosts here, even though placement excludes them.
    FOR k,value IN SELECT * FROM jsonb_each(next->'service_usage') LOOP
        IF value::bigint>coalesce((prior->'service_usage'->>k)::bigint,0) THEN
            service_growth:=true;
            IF NOT (next->'placement' ? k) THEN
                RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='service_capacity_protection',MESSAGE='node is not ready for protected admission';
            END IF;
        END IF;
    END LOOP;
    IF (next->>'replica_ram_mb')::bigint>(prior->>'replica_ram_mb')::bigint OR
       (next->>'replica_cpu_millicores')::bigint>(prior->>'replica_cpu_millicores')::bigint OR
       (next->>'replica_vcpu')::bigint>(prior->>'replica_vcpu')::bigint THEN grew:=true; END IF;
    SELECT EXISTS (SELECT 1 FROM jsonb_each_text(next->'actual') a
                    WHERE a.value::bigint>coalesce((next->'demands'->a.key->>'count')::bigint,0)
                      AND a.value::bigint>coalesce((prior->'actual'->>a.key)::bigint,0)) INTO excess;
    -- Service recovery spends an existing declaration even after a host has
    -- failed. New intent, bursts, mirrors, jobs and excess service replicas
    -- must leave the fleet protected. Releases and unrelated updates pass.
    IF ((grew OR excess) AND next->>'state'<>'protected') OR
       (NOT (next->>'placements_fit')::boolean AND (physical_growth OR service_growth)) THEN
        RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='service_capacity_protection',
            MESSAGE='service admission would consume bare-metal recovery capacity';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: service_capacity_before_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_capacity_before_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE is_enabled boolean; baseline_key text;
BEGIN
    LOOP
        SELECT enabled INTO is_enabled FROM service_capacity_policy WHERE singleton AND enabled FOR UPDATE;
        EXIT WHEN FOUND;
        SELECT enabled INTO is_enabled FROM service_capacity_policy WHERE singleton AND NOT enabled FOR SHARE;
        EXIT WHEN FOUND;
        IF NOT EXISTS (SELECT 1 FROM service_capacity_policy WHERE singleton) THEN
            RAISE EXCEPTION 'service capacity policy is missing';
        END IF;
    END LOOP;
    IF TG_NARGS>0 AND TG_ARGV[0]='lock_only' THEN RETURN NULL; END IF;
    baseline_key := 'gregale.capacity_' || TG_TABLE_NAME || '_' || pg_trigger_depth()::text;
    PERFORM set_config(baseline_key,CASE WHEN is_enabled THEN service_capacity_snapshot()::text ELSE '' END,true);
    RETURN NULL;
END;
$$;


--
-- Name: service_capacity_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_capacity_snapshot() RETURNS jsonb
    LANGUAGE sql
    SET jit TO 'off'
    AS $$
WITH policy AS (SELECT * FROM service_capacity_policy WHERE singleton),
eligible AS (
    SELECT a.id, a.ram_mb, a.cpu_millicores, a.manifest,
           coalesce((p.plan_vcpus->>ac.plan)::integer, 4) AS vcpu
      FROM apps a JOIN app_resource_accounts ac ON ac.app_id=a.id CROSS JOIN policy p
     WHERE a.status IN ('active','evicted_cold') AND a.manifest->>'execution_mode'='service'
), scopes AS (
    SELECT id AS app_id, 'default'::text AS scope FROM eligible
    UNION
    SELECT d.app_id, d.scope FROM deployments d JOIN eligible a ON a.id=d.app_id
     WHERE d.status IN ('pending','building','imaging','snapshotting','live')
), declaration AS (
    SELECT s.app_id::text || ':' || s.scope AS key,
           greatest(0, coalesce((a.manifest->'service_replicas'->>'desired')::integer,1)) AS desired,
           CASE WHEN EXISTS (SELECT 1 FROM deployments d WHERE d.app_id=a.id AND d.scope=s.scope AND d.status='live')
                  AND (EXISTS (SELECT 1 FROM deployments d WHERE d.app_id=a.id AND d.scope=s.scope AND d.status IN ('pending','building','imaging','snapshotting'))
                    OR (SELECT count(*) FROM deployments d WHERE d.app_id=a.id AND d.scope=s.scope AND d.status='live')>1)
                THEN 1 ELSE 0 END AS surge,
           a.ram_mb+p.overhead_mb+coalesce((
               SELECT max((SELECT coalesce(sum(greatest(0,(sc->>'ram_mb')::integer)),0)
                             FROM jsonb_array_elements(coalesce(d.sidecars,'[]'::jsonb)) sc))
                 FROM deployments d WHERE d.app_id=a.id AND d.scope=s.scope
                   AND d.status IN ('pending','building','imaging','snapshotting','live')),0) AS ram,
           greatest(a.cpu_millicores,p.startup_cpu)+coalesce((
               SELECT max((SELECT coalesce(sum(greatest(0,coalesce(nullif(greatest(0,(sc->>'cpu_millicores')::integer),0),p.startup_cpu))),0)
                             FROM jsonb_array_elements(coalesce(d.sidecars,'[]'::jsonb)) sc))
                 FROM deployments d WHERE d.app_id=a.id AND d.scope=s.scope
                   AND d.status IN ('pending','building','imaging','snapshotting','live')),0) AS cpu,
           a.vcpu
      FROM scopes s JOIN eligible a ON a.id=s.app_id CROSS JOIN policy p
), demand AS (
    SELECT key, CASE WHEN desired=0 THEN 0 ELSE desired+surge END AS count, desired, ram, cpu, vcpu
      FROM declaration
), resident AS (
    SELECT i.node_id, a.id::text || ':' || coalesce(d.scope,'default') AS key,
           greatest(i.capacity_ram_mb,i.ram_mb+p.overhead_mb+coalesce((SELECT sum(greatest(0,(sc->>'ram_mb')::integer))
                           FROM jsonb_array_elements(coalesce(d.sidecars,'[]'::jsonb)) sc),0)) AS ram,
           greatest(i.capacity_cpu_millicores,greatest(coalesce(a.cpu_millicores,p.startup_cpu),p.startup_cpu)+coalesce((
               SELECT sum(greatest(0,coalesce(nullif(greatest(0,(sc->>'cpu_millicores')::integer),0),p.startup_cpu)))
                 FROM jsonb_array_elements(coalesce(d.sidecars,'[]'::jsonb)) sc),0)) AS cpu,
           greatest(i.capacity_vcpu,CASE WHEN i.app_id IS NULL THEN 1 ELSE coalesce((p.plan_vcpus->>ac.plan)::integer,4) END) AS vcpu,
           (i.state<>'warm' AND i.mode IN ('normal','service') AND a.manifest->>'execution_mode'='service'
              AND EXISTS (SELECT 1 FROM demand x WHERE x.key=a.id::text || ':' || coalesce(d.scope,'default') )) AS service
      FROM instances i LEFT JOIN apps a ON a.id=i.app_id LEFT JOIN app_resource_accounts ac ON ac.app_id=a.id
      LEFT JOIN deployments d ON d.id=i.deployment_id CROSS JOIN policy p
     WHERE i.state IN ('waking','cold_booting','running','draining','warm','snapshotting','migrating')
    UNION ALL
    SELECT r.destination_node_id,NULL::text,r.ram_mb::bigint,r.cpu_millicores::bigint,r.vcpu::bigint,false
      FROM migration_admissions r WHERE r.phase NOT IN ('cleaned','committed')
       AND NOT EXISTS(SELECT 1 FROM instances i WHERE i.id=r.instance_id AND i.node_id=r.destination_node_id AND i.wake_id=r.destination_wake_id AND i.state='running')
    UNION ALL
    SELECT n.id,NULL::text,u.ram,u.cpu,u.vcpu,false FROM compute_nodes n CROSS JOIN LATERAL migration_source_node_usage(n.id) u
      WHERE u.ram>0 OR u.cpu>0 OR u.vcpu>0
), shape AS (
    SELECT greatest(coalesce((SELECT max(ram) FROM demand WHERE count>0),0),coalesce((SELECT max(ram) FROM resident WHERE service),0),1) AS ram,
           greatest(coalesce((SELECT max(cpu) FROM demand WHERE count>0),0),coalesce((SELECT max(cpu) FROM resident WHERE service),0),1) AS cpu,
           greatest(coalesce((SELECT max(vcpu) FROM demand WHERE count>0),0),coalesce((SELECT max(vcpu) FROM resident WHERE service),0),1) AS vcpu
), other_usage AS (
    SELECT node_id, sum(ram)::bigint AS ram, sum(cpu)::bigint AS cpu, sum(vcpu)::bigint AS vcpu
      FROM resident WHERE NOT coalesce(service,false) GROUP BY node_id
), service_usage AS (
    SELECT node_id, count(*)::bigint AS count FROM resident WHERE service GROUP BY node_id
), nodes AS (
    SELECT n.id, n.name, coalesce(u.ram,0) AS other_ram, coalesce(u.cpu,0) AS other_cpu, coalesce(u.vcpu,0) AS other_vcpu,
           coalesce(s.count,0) AS service_count,
           (coalesce(u.ram,0)<=n.admission_ceiling_mb AND coalesce(u.cpu,0)<=n.vpcpus::bigint*1000*p.cpu_overcommit AND coalesce(u.vcpu,0)<=n.vcpu_budget) AS ordinary_fit,
           greatest(0,least((n.admission_ceiling_mb-coalesce(u.ram,0))/sh.ram,
                       (n.vpcpus::bigint*1000*p.cpu_overcommit-coalesce(u.cpu,0))/sh.cpu,
                       (n.vcpu_budget-coalesce(u.vcpu,0))/sh.vcpu))::bigint AS slots
      FROM compute_nodes n CROSS JOIN policy p CROSS JOIN shape sh
      LEFT JOIN other_usage u ON u.node_id=n.id LEFT JOIN service_usage s ON s.node_id=n.id
     WHERE n.lifecycle='active' AND n.admission_ceiling_mb>0 AND n.vpcpus>0 AND n.vcpu_budget>0
       AND n.last_heartbeat_at>=clock_timestamp()-make_interval(secs=>p.heartbeat_seconds)
), totals AS (
    SELECT count(*) AS healthy_nodes, coalesce(sum(slots),0) AS fleet_slots,
           coalesce(sum(slots)-max(slots),0) AS failover_slots,
           coalesce(bool_and(service_count<=slots AND ordinary_fit),true) AS placements_fit FROM nodes
), required AS (SELECT coalesce(sum(count),0) AS count, coalesce(sum(desired),0) AS desired FROM demand),
actual_targets AS (SELECT key,count(*) AS count FROM resident WHERE service GROUP BY key),
projection AS (
    SELECT jsonb_build_object(
        'enabled',p.enabled,
        'state',CASE WHEN NOT p.enabled THEN 'disabled'
                     WHEN t.healthy_nodes>=2 AND t.placements_fit AND r.count<=t.failover_slots
                       AND NOT EXISTS (SELECT 1 FROM actual_targets a JOIN demand d ON d.key=a.key WHERE a.count>d.count) THEN 'protected'
                     WHEN t.placements_fit AND r.count<=t.fleet_slots THEN 'degraded' ELSE 'needs_hardware' END,
        'healthy_nodes',t.healthy_nodes,'desired_replicas',r.desired,'reserved_replicas',r.count,
        'replica_ram_mb',sh.ram,'replica_cpu_millicores',sh.cpu,'replica_vcpu',sh.vcpu,
        'fleet_slots',t.fleet_slots,'failover_slots',t.failover_slots,'placements_fit',t.placements_fit,
        'demands',coalesce((SELECT jsonb_object_agg(key,jsonb_build_object('count',count,'ram',ram,'cpu',cpu,'vcpu',vcpu)) FROM demand),'{}'::jsonb),
        'other',coalesce((SELECT jsonb_object_agg(id::text,jsonb_build_object('ram',other_ram,'cpu',other_cpu,'vcpu',other_vcpu)) FROM nodes),'{}'::jsonb),
        'placement',coalesce((SELECT jsonb_object_agg(id::text,jsonb_build_object('slots',slots,'used',service_count)) FROM nodes),'{}'::jsonb),
        'service_usage',coalesce((SELECT jsonb_object_agg(node_id::text,count) FROM service_usage),'{}'::jsonb),
        'resident',coalesce((SELECT jsonb_object_agg(node_id::text,cost) FROM (SELECT node_id,jsonb_build_object('ram',sum(ram),'cpu',sum(cpu),'vcpu',sum(vcpu)) AS cost FROM resident GROUP BY node_id) u),'{}'::jsonb),
        'actual',coalesce((SELECT jsonb_object_agg(key,count) FROM actual_targets),'{}'::jsonb)
    ) AS data FROM policy p CROSS JOIN totals t CROSS JOIN required r CROSS JOIN shape sh
) SELECT data FROM projection;
$$;


--
-- Name: set_service_capacity_protection(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_service_capacity_protection(wanted boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE result jsonb;
BEGIN
    PERFORM 1 FROM service_capacity_policy WHERE singleton FOR UPDATE;
    UPDATE service_capacity_policy SET enabled=wanted WHERE singleton;
    result:=service_capacity_snapshot();
    IF wanted AND result->>'state'<>'protected' THEN
        RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='service_capacity_protection',
            MESSAGE='fleet cannot yet preserve service capacity after one host failure';
    END IF;
    RETURN result;
END;
$$;


--
-- Name: snapshot_fanout_event_on_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_fanout_event_on_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.storage_key <> '' AND NOT NEW.stale THEN
        INSERT INTO snapshot_fanout_events (snapshot_id)
        VALUES (NEW.id)
        ON CONFLICT (snapshot_id) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: snapshot_recovery_generation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_recovery_generation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE current_generation bigint;
BEGIN
    IF NOT NEW.stale THEN
        SELECT snapshot_recovery_generation INTO current_generation
          FROM deployments WHERE id = NEW.deployment_id FOR SHARE NOWAIT;
        IF NEW.recovery_generation IS DISTINCT FROM current_generation THEN
            RAISE EXCEPTION 'snapshot recovery generation changed'
                USING ERRCODE = '23514', CONSTRAINT = 'snapshots_recovery_generation_current';
        END IF;
    END IF;
    RETURN NEW;
END $$;


--
-- Name: snapshot_replica_drop_after_stale(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_replica_drop_after_stale() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM snapshot_replicas
     WHERE snapshot_id = NEW.id;
    RETURN NEW;
END;
$$;


--
-- Name: snapshot_replica_refresh_after_compute_node(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_replica_refresh_after_compute_node() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.active THEN
        DELETE FROM snapshot_replicas r
        USING snapshots sn
        LEFT JOIN snapshot_origins so ON so.snapshot_id = sn.id
        WHERE r.snapshot_id = sn.id
          AND r.node_id = NEW.id
          AND so.region <> ''
          AND coalesce(NEW.region, '') <> so.region;

        INSERT INTO snapshot_replicas (snapshot_id, node_id, region)
        SELECT e.snapshot_id, NEW.id, coalesce(NEW.region, '')
          FROM snapshot_fanout_events e
          JOIN snapshots sn ON sn.id = e.snapshot_id
          JOIN deployments d ON d.id = sn.deployment_id
          JOIN apps a ON a.id = d.app_id
          LEFT JOIN snapshot_origins so ON so.snapshot_id = sn.id
         WHERE sn.stale = false
           AND sn.storage_key <> ''
           AND a.status <> 'deleted'
           AND d.status IN ('snapshotting', 'live', 'superseded')
           AND (so.region = '' OR coalesce(NEW.region, '') = so.region)
        ON CONFLICT (snapshot_id, node_id) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: snapshot_replica_refresh_after_origin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_replica_refresh_after_origin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM snapshot_replicas r
    USING compute_nodes cn
    WHERE r.snapshot_id = NEW.snapshot_id
      AND r.node_id = cn.id
      AND NEW.region <> ''
      AND coalesce(cn.region, '') <> NEW.region;

    INSERT INTO snapshot_replicas (snapshot_id, node_id, region)
    SELECT NEW.snapshot_id, cn.id, coalesce(cn.region, '')
      FROM compute_nodes cn
      JOIN snapshots sn ON sn.id = NEW.snapshot_id
      JOIN deployments d ON d.id = sn.deployment_id
      JOIN apps a ON a.id = d.app_id
     WHERE cn.active
       AND sn.stale = false
       AND sn.storage_key <> ''
       AND a.status <> 'deleted'
       AND d.status IN ('snapshotting', 'live', 'superseded')
       AND (NEW.region = '' OR coalesce(cn.region, '') = NEW.region)
    ON CONFLICT (snapshot_id, node_id) DO NOTHING;

    RETURN NEW;
END;
$$;


--
-- Name: snapshot_restore_pressure_acquire(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_restore_pressure_acquire(p_lock_name text) RETURNS TABLE(locked boolean, node_id text, active bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT pg_try_advisory_lock(hashtextextended(p_lock_name, 0)) THEN
        RETURN QUERY SELECT false, NULL::text, NULL::bigint;
        RETURN;
    END IF;
    DELETE FROM snapshot_restore_pressure_leases WHERE expires_at <= now();
    RETURN QUERY SELECT true, l.node_id::text, count(*) FROM snapshot_restore_pressure_leases l
                  WHERE l.expires_at > now() GROUP BY l.node_id;
    IF NOT FOUND THEN
        RETURN QUERY SELECT true, NULL::text, NULL::bigint;
    END IF;
END $$;


--
-- Name: snapshot_stale_after_app_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_stale_after_app_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE snapshots s
       SET stale = true
      FROM deployments d
     WHERE s.deployment_id = d.id
       AND d.app_id = NEW.id
       AND s.stale = false;
    RETURN NEW;
END;
$$;


