--
-- Name: soft_delete_job_if_no_live_instances(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.soft_delete_job_if_no_live_instances(p_job_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    flipped boolean;
BEGIN
    UPDATE jobs
       SET status = 'deleted', updated_at = now()
     WHERE id = p_job_id
       AND status <> 'deleted'
       AND NOT EXISTS (
           SELECT 1
             FROM instances
            WHERE job_id = p_job_id
              AND kind = 'job_task'
              AND state IN ('waking', 'cold_booting', 'running')
       )
    RETURNING TRUE INTO flipped;
    RETURN COALESCE(flipped, FALSE);
END;
$$;


--
-- Name: source_build_rootfs_current_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.source_build_rootfs_current_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' AND source_build_rootfs_owner_erasing(OLD.deployment_id) THEN RETURN OLD;END IF;
 IF TG_OP<>'DELETE' AND current_setting('gregale.source_build_rootfs_insert',true)=NEW.artifact_id::text
  AND (TG_OP='INSERT' OR NEW.deployment_id=OLD.deployment_id) THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'source rootfs selection must use private publication' USING ERRCODE='23514',CONSTRAINT='build_export_publication_immutable';
END;
$$;


--
-- Name: source_build_rootfs_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.source_build_rootfs_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' AND current_setting('gregale.source_build_rootfs_insert',true)=NEW.id::text THEN RETURN NEW;END IF;
 IF TG_OP='DELETE' AND source_build_rootfs_owner_erasing(OLD.deployment_id) THEN RETURN OLD;END IF;
 RAISE EXCEPTION 'source rootfs evidence is immutable/private' USING ERRCODE='23514',CONSTRAINT='build_export_publication_immutable';
END;
$$;


--
-- Name: source_build_rootfs_intent(public.apps, public.deployments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.source_build_rootfs_intent(a public.apps, d public.deployments) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT jsonb_build_object('slug',a.slug,'type',a.type,'runtime',coalesce(a.runtime,''),'start_command',coalesce(a.start_command,''),
 'manifest',a.manifest,'require_signed',a.require_signed,'security_policy',a.security_policy,'handler',coalesce(d.handler,''),
 'scope',d.scope,'override_entrypoint',d.override_entrypoint,'override_cmd',d.override_cmd,'override_env',d.override_env,
 'override_env_secrets',d.override_env_secrets,'override_port',coalesce(d.override_port,0),'override_healthcheck',d.override_healthcheck,
 'override_liveness_probe',d.override_liveness_probe,'override_readiness_probe',d.override_readiness_probe,
 'override_main_depends_on',d.override_main_depends_on);
$$;


--
-- Name: source_build_rootfs_owner_erasing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.source_build_rootfs_owner_erasing(deployment uuid) RETURNS boolean
    LANGUAGE sql
    AS $$
 SELECT NOT EXISTS(SELECT 1 FROM deployments WHERE id=deployment)
 OR EXISTS(SELECT 1 FROM deployments d JOIN apps a ON a.id=d.app_id
  WHERE d.id=deployment AND a.status='deleted' AND a.delete_grace_until<=clock_timestamp() AND a.purge_claimed_at IS NOT NULL);
$$;


--
-- Name: stamp_deployment_mail_failure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_deployment_mail_failure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE success bigint; recipient uuid; app_revision bigint; account_revision bigint; became_live boolean; became_failed boolean;
BEGIN
    IF TG_OP='DELETE' THEN
        UPDATE platform_mail_deployment_fences SET revision=revision+1 WHERE app_id=OLD.app_id AND scope=OLD.scope;
        RETURN OLD;
    END IF;
    -- Acquire the ordinary parent FK key-share before the scope fence on
    -- insert/reassignment. Capturers use NO KEY UPDATE for the cooldown,
    -- which is compatible with this lock and avoids a parent/fence cycle.
    IF TG_OP='INSERT' THEN
        PERFORM 1 FROM apps WHERE id=NEW.app_id FOR KEY SHARE;
    ELSIF NEW.app_id<>OLD.app_id THEN
        PERFORM 1 FROM apps WHERE id=NEW.app_id FOR KEY SHARE;
    END IF;
    IF TG_OP='UPDATE' THEN
        NEW.mail_failed_at := OLD.mail_failed_at;
        NEW.mail_failure_account_id := OLD.mail_failure_account_id;
        NEW.mail_failure_account_revision := OLD.mail_failure_account_revision;
        NEW.mail_failure_app_revision := OLD.mail_failure_app_revision;
        NEW.mail_failure_success_revision := OLD.mail_failure_success_revision;
        IF NEW.status IS NOT DISTINCT FROM OLD.status AND NEW.app_id=OLD.app_id AND NEW.scope=OLD.scope
            AND NEW.deployed_by_user_id IS NOT DISTINCT FROM OLD.deployed_by_user_id
            AND NEW.deleted_at IS NOT DISTINCT FROM OLD.deleted_at
            AND NEW.mail_failure_revision=OLD.mail_failure_revision THEN RETURN NEW;
        END IF;
        NEW.mail_failure_revision := OLD.mail_failure_revision+1;
        -- Ordered fences for the exceptional app/scope reassignment path.
        PERFORM 1 FROM platform_mail_deployment_fences
            WHERE (app_id=OLD.app_id AND scope=OLD.scope) OR (app_id=NEW.app_id AND scope=NEW.scope)
            ORDER BY app_id,scope FOR UPDATE;
        IF NEW.app_id<>OLD.app_id OR NEW.scope<>OLD.scope THEN
            UPDATE platform_mail_deployment_fences SET revision=revision+1 WHERE app_id=OLD.app_id AND scope=OLD.scope;
        END IF;
        became_live := NEW.status='live' AND (OLD.status<>'live' OR NEW.app_id<>OLD.app_id OR NEW.scope<>OLD.scope);
        became_failed := NEW.status='failed' AND OLD.status<>'failed';
    ELSE
        NEW.mail_failure_revision := 1;
        NEW.mail_failed_at := NULL; NEW.mail_failure_account_id := NULL;
        NEW.mail_failure_account_revision := NULL; NEW.mail_failure_app_revision := NULL; NEW.mail_failure_success_revision := NULL;
        became_live := NEW.status='live'; became_failed := NEW.status='failed';
    END IF;
    INSERT INTO platform_mail_deployment_fences(app_id,scope,success_revision)
        VALUES(NEW.app_id,NEW.scope,CASE WHEN became_live THEN 1 ELSE 0 END)
        ON CONFLICT(app_id,scope) DO UPDATE SET revision=platform_mail_deployment_fences.revision+1,
            success_revision=platform_mail_deployment_fences.success_revision+CASE WHEN became_live THEN 1 ELSE 0 END
        RETURNING success_revision INTO success;
    IF became_failed THEN
        SELECT coalesce(NEW.deployed_by_user_id,a.account_id),a.deployment_mail_revision
            INTO recipient,app_revision FROM apps a WHERE a.id=NEW.app_id;
        SELECT deployment_mail_revision INTO account_revision FROM accounts WHERE id=recipient;
        NEW.mail_failed_at := clock_timestamp(); NEW.mail_failure_account_id := recipient;
        NEW.mail_failure_account_revision := account_revision; NEW.mail_failure_app_revision := app_revision;
        NEW.mail_failure_success_revision := success;
    END IF;
    RETURN NEW;
END $$;


--
-- Name: stamp_deployment_serving_ended_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_deployment_serving_ended_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.status = 'live' AND NEW.traffic_percent > 0 THEN
  NEW.serving_ended_at := NULL;
 ELSIF OLD.status = 'live' AND OLD.traffic_percent > 0 AND NEW.status <> 'snapshotting' THEN
  NEW.serving_ended_at := now();
 END IF;
 RETURN NEW;
END $$;


--
-- Name: stamp_invocation_async_subject(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_invocation_async_subject() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected uuid;
BEGIN
 IF NEW.quota_reserved THEN
  expected:=invocation_async_subject(NEW.app_id,NEW.account_id);
  IF expected IS NULL THEN RAISE EXCEPTION 'invalid invocation quota ownership' USING ERRCODE='23514'; END IF;
  IF TG_OP='INSERT' OR NOT OLD.quota_reserved THEN
   NEW.async_quota_subject_id:=expected;
  ELSIF NEW.async_quota_subject_id IS DISTINCT FROM OLD.async_quota_subject_id AND NEW.async_quota_subject_id IS DISTINCT FROM expected THEN
   RAISE EXCEPTION 'invocation quota reservation ownership is fenced' USING ERRCODE='23514';
  END IF;
 ELSIF TG_OP='UPDATE' AND OLD.quota_reserved THEN
  NEW.async_quota_subject_id:=OLD.async_quota_subject_id;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: stamp_object_storage_issuer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_object_storage_issuer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE owner_org uuid; personal boolean; issuer_revision bigint;
BEGIN
 SELECT b.org_id,o.personal_org INTO owner_org,personal FROM object_buckets b JOIN orgs o ON o.id=b.org_id
 WHERE b.id=NEW.bucket_id AND b.account_id=NEW.account_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'invalid storage credential bucket' USING ERRCODE='23514'; END IF;
 IF NEW.managed_app_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM apps a WHERE a.id=NEW.managed_app_id AND a.org_id=owner_org AND a.account_id=NEW.account_id) THEN
  RAISE EXCEPTION 'invalid storage binding organization' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND (NEW.account_id<>OLD.account_id OR NEW.bucket_id<>OLD.bucket_id OR NEW.issuer_account_id IS DISTINCT FROM OLD.issuer_account_id
 OR NEW.issuer_access_revision IS DISTINCT FROM OLD.issuer_access_revision OR NEW.managed_app_id IS DISTINCT FROM OLD.managed_app_id OR NEW.rotation_parent_id IS DISTINCT FROM OLD.rotation_parent_id) THEN
  RAISE EXCEPTION 'storage credential ownership is immutable' USING ERRCODE='23514';
 END IF;
 IF (NEW.managed_app_id IS NOT NULL OR NEW.rotation_parent_id IS NOT NULL) AND NEW.issuer_account_id IS NOT NULL THEN
  RAISE EXCEPTION 'application credentials cannot carry human authority' USING ERRCODE='23514';
 END IF;
 IF NOT personal AND NEW.managed_app_id IS NULL AND NEW.rotation_parent_id IS NULL THEN
  NEW.issuer_account_id=coalesce(NEW.issuer_account_id,(SELECT account_id FROM api_keys WHERE id=NEW.url_api_key_id),NEW.account_id);
  SELECT access_revision INTO issuer_revision FROM org_memberships WHERE org_id=owner_org AND account_id=NEW.issuer_account_id
   AND removed_at IS NULL AND role IN ('owner','admin','developer') FOR SHARE;
  IF NOT FOUND OR (NEW.issuer_access_revision IS NOT NULL AND NEW.issuer_access_revision<>issuer_revision) THEN
   RAISE EXCEPTION 'organization access revoked' USING ERRCODE='42501';
  END IF;
  NEW.issuer_access_revision=issuer_revision;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: start_event_execution_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_event_execution_coverage() RETURNS trigger
    LANGUAGE plpgsql
