COMMENT ON TABLE public.api_consumer_plans IS 'Named consumer plans: enforcement limits plus their own rate-card history (api_consumer_rate_cards.plan_id).';


--
-- Name: COLUMN api_consumer_plans.alert_thresholds_percent; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.api_consumer_plans.alert_thresholds_percent IS 'Percentages of max_units_per_month at which a consumer.usage_threshold webhook fires, once per consumer per UTC month.';


--
-- Name: api_consumer_rate_cards; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.api_consumer_rate_cards (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    app_id uuid NOT NULL,
    currency text NOT NULL,
    unit text DEFAULT 'request'::text NOT NULL,
    price_millicents_per_unit bigint NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    included_units_per_month bigint DEFAULT 0 NOT NULL,
    tiers jsonb DEFAULT '[]'::jsonb NOT NULL,
    route_weights jsonb DEFAULT '{}'::jsonb NOT NULL,
    plan_id uuid,
    tier_mode text DEFAULT 'graduated'::text NOT NULL,
    base_fee_millicents_per_month bigint DEFAULT 0 NOT NULL,
    minimum_millicents_per_month bigint DEFAULT 0 NOT NULL,
    prorate_monthly_fees boolean DEFAULT false NOT NULL,
    CONSTRAINT api_consumer_rate_cards_currency_chk CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT api_consumer_rate_cards_effective_minute_chk CHECK ((effective_from = date_trunc('minute'::text, effective_from))),
    CONSTRAINT api_consumer_rate_cards_included_units_chk CHECK ((included_units_per_month >= 0)),
    CONSTRAINT api_consumer_rate_cards_monthly_fees_chk CHECK (((base_fee_millicents_per_month >= 0) AND (minimum_millicents_per_month >= 0))),
    CONSTRAINT api_consumer_rate_cards_price_chk CHECK ((price_millicents_per_unit >= 0)),
    CONSTRAINT api_consumer_rate_cards_route_weights_chk CHECK ((jsonb_typeof(route_weights) = 'object'::text)),
    CONSTRAINT api_consumer_rate_cards_tier_mode_chk CHECK (((tier_mode = 'graduated'::text) OR ((tier_mode = 'volume'::text) AND (jsonb_array_length(tiers) > 0)))),
    CONSTRAINT api_consumer_rate_cards_tiers_chk CHECK (((jsonb_typeof(tiers) = 'array'::text) AND (jsonb_array_length(tiers) <= 10))),
    CONSTRAINT api_consumer_rate_cards_unit_chk CHECK (((unit = ANY (ARRAY['request'::text, 'compute_second'::text, 'response_megabyte'::text])) OR (unit ~ '^app:[a-z][a-z0-9_]{0,31}$'::text)))
);


--
-- Name: COLUMN api_consumer_rate_cards.included_units_per_month; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.api_consumer_rate_cards.included_units_per_month IS 'Free request units per consumer per UTC calendar month, consumed in minute order while this card is effective.';


--
-- Name: COLUMN api_consumer_rate_cards.tiers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.api_consumer_rate_cards.tiers IS 'Graduated price ladder [{up_to, price_millicents_per_unit}], counted per consumer per UTC calendar month in minute order; empty means the single price and allowance apply.';


--
-- Name: COLUMN api_consumer_rate_cards.route_weights; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.api_consumer_rate_cards.route_weights IS 'Units charged per request on a route label ("METHOD /template" -> weight); unlisted routes count 1.';


--
-- Name: COLUMN api_consumer_rate_cards.plan_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.api_consumer_rate_cards.plan_id IS 'Plan whose price history this card belongs to; NULL is the app default plan.';


--
-- Name: api_consumer_route_usage_minutes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.api_consumer_route_usage_minutes (
    account_id uuid NOT NULL,
    app_id uuid NOT NULL,
    consumer_key text NOT NULL,
    route text NOT NULL,
    window_start timestamp with time zone NOT NULL,
    billable_units bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT api_consumer_route_usage_minutes_consumer_key_chk CHECK ((consumer_key ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text)),
    CONSTRAINT api_consumer_route_usage_minutes_minute_chk CHECK ((window_start = (date_trunc('minute'::text, (window_start AT TIME ZONE 'UTC'::text)) AT TIME ZONE 'UTC'::text))),
    CONSTRAINT api_consumer_route_usage_minutes_route_chk CHECK (((char_length(route) >= 3) AND (char_length(route) <= 256))),
    CONSTRAINT api_consumer_route_usage_minutes_units_chk CHECK ((billable_units >= 0))
);


--
-- Name: TABLE api_consumer_route_usage_minutes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.api_consumer_route_usage_minutes IS 'Billable units per consumer, bounded route label, and UTC minute; per-minute totals stay in api_consumer_usage_minutes.';


--
-- Name: api_consumer_spend_caps; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.api_consumer_spend_caps (
    consumer_id uuid NOT NULL,
    account_id uuid NOT NULL,
    app_id uuid NOT NULL,
    currency text NOT NULL,
    monthly_cap_millicents bigint NOT NULL,
    capped boolean DEFAULT false NOT NULL,
    month_start timestamp with time zone,
    amount_due_millicents bigint,
    checked_at timestamp with time zone,
    next_check_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT api_consumer_spend_caps_cap_chk CHECK ((monthly_cap_millicents >= 0)),
    CONSTRAINT api_consumer_spend_caps_capped_chk CHECK (((NOT capped) OR ((month_start IS NOT NULL) AND (checked_at IS NOT NULL)))),
    CONSTRAINT api_consumer_spend_caps_currency_chk CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT api_consumer_spend_caps_due_chk CHECK (((amount_due_millicents IS NULL) OR (amount_due_millicents >= 0)))
);


--
-- Name: TABLE api_consumer_spend_caps; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.api_consumer_spend_caps IS 'Monthly spend cap per API consumer; apid checks the month to date and the gateway denies capped consumers (ADR-1306).';


--
-- Name: api_consumer_trials; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.api_consumer_trials (
    consumer_id uuid NOT NULL,
    account_id uuid NOT NULL,
    app_id uuid NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT api_consumer_trials_minute_chk CHECK (((starts_at = (date_trunc('minute'::text, (starts_at AT TIME ZONE 'UTC'::text)) AT TIME ZONE 'UTC'::text)) AND (ends_at = (date_trunc('minute'::text, (ends_at AT TIME ZONE 'UTC'::text)) AT TIME ZONE 'UTC'::text)))),
    CONSTRAINT api_consumer_trials_window_chk CHECK (((ends_at > starts_at) AND ((ends_at - starts_at) <= '365 days'::interval)))
);


--
-- Name: TABLE api_consumer_trials; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.api_consumer_trials IS 'One free trial per API consumer (ADR-1314): usage in [starts_at, ends_at) is priced at zero.';


--
-- Name: api_consumer_usage_alerts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.api_consumer_usage_alerts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    app_id uuid NOT NULL,
    consumer_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    month_start timestamp with time zone NOT NULL,
    threshold_percent integer NOT NULL,
    limit_units bigint NOT NULL,
    used_units bigint NOT NULL,
    crossed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT api_consumer_usage_alerts_month_chk CHECK ((month_start = (date_trunc('month'::text, (month_start AT TIME ZONE 'UTC'::text)) AT TIME ZONE 'UTC'::text))),
    CONSTRAINT api_consumer_usage_alerts_threshold_chk CHECK (((threshold_percent >= 1) AND (threshold_percent <= 100))),
    CONSTRAINT api_consumer_usage_alerts_units_chk CHECK (((limit_units > 0) AND (used_units >= 0)))
);


--
-- Name: TABLE api_consumer_usage_alerts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.api_consumer_usage_alerts IS 'One row per consumer, UTC month, and plan alert threshold crossed at gateway admission; source of the consumer.usage_threshold webhook.';


--
-- Name: api_consumer_usage_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.api_consumer_usage_events (
    event_id uuid NOT NULL,
    account_id uuid NOT NULL,
    app_id uuid NOT NULL,
    consumer_key text NOT NULL,
    window_start timestamp with time zone NOT NULL,
    request_count bigint NOT NULL,
    error_count bigint NOT NULL,
    billable_units bigint NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    platform_tenant_id uuid,
    platform_tenant_surface_id uuid,
    platform_tenant_jwt_authorization_rule_id uuid,
    discovery_recorded boolean DEFAULT false NOT NULL,
    CONSTRAINT api_consumer_usage_events_check CHECK (((error_count >= 0) AND (error_count <= request_count))),
    CONSTRAINT api_consumer_usage_events_check1 CHECK (((billable_units >= 0) AND (billable_units <= request_count))),
    CONSTRAINT api_consumer_usage_events_consumer_key_chk CHECK (((consumer_key = '__anonymous__'::text) OR (consumer_key ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text))),
    CONSTRAINT api_consumer_usage_events_minute_chk CHECK ((window_start = (date_trunc('minute'::text, (window_start AT TIME ZONE 'UTC'::text)) AT TIME ZONE 'UTC'::text))),
    CONSTRAINT api_consumer_usage_events_request_count_check CHECK ((request_count > 0))
);


--
-- Name: api_consumer_usage_minutes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.api_consumer_usage_minutes (
    account_id uuid NOT NULL,
    app_id uuid NOT NULL,
    consumer_key text NOT NULL,
    window_start timestamp with time zone NOT NULL,
    request_count bigint DEFAULT 0 NOT NULL,
    error_count bigint DEFAULT 0 NOT NULL,
