    claimed_by text,
    claimed_at timestamp with time zone,
    lease_until timestamp with time zone,
    delivered_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT audit_event_outbox_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT audit_event_outbox_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'processing'::text, 'delivered'::text, 'dead_letter'::text])))
);


