    org_id uuid,
    timezone text DEFAULT 'UTC'::text NOT NULL,
    skip_if_running boolean DEFAULT false NOT NULL,
    suspended_reason text DEFAULT ''::text NOT NULL,
    command text[] DEFAULT '{}'::text[] NOT NULL,
    command_shell boolean DEFAULT false NOT NULL,
    command_timeout_seconds integer DEFAULT 600 NOT NULL,
    command_max_output_bytes integer DEFAULT 1048576 NOT NULL,
    retry_max integer DEFAULT 0 NOT NULL,
    retry_backoff_seconds integer DEFAULT 60 NOT NULL,
