CREATE TABLE public.status_incidents (
    id bigint NOT NULL,
    component text NOT NULL,
    severity text NOT NULL,
    message text NOT NULL,
    posted_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    public_id uuid NOT NULL,
    kind text NOT NULL,
    title text NOT NULL,
    impact text NOT NULL,
    affected_components text[] NOT NULL,
    lifecycle_state text NOT NULL,
    starts_at timestamp with time zone,
    scheduled_start_at timestamp with time zone,
    scheduled_end_at timestamp with time zone,
    updated_at timestamp with time zone NOT NULL,
    create_idempotency_key text NOT NULL,
    created_by text NOT NULL,
    edited_at timestamp with time zone,
    CONSTRAINT status_incidents_affected_components_chk CHECK (((cardinality(affected_components) > 0) AND (affected_components <@ ARRAY['api_console'::text, 'deployments'::text, 'app_execution'::text, 'networking'::text, 'observability'::text]))),
    CONSTRAINT status_incidents_component_chk CHECK ((component = ANY (ARRAY['apid'::text, 'schedd'::text, 'vmmd'::text, 'gatewayd'::text, 'meterd'::text, 'imaged'::text, 'builderd'::text, 'faas-control-plane'::text]))),
    CONSTRAINT status_incidents_edited_at_chk CHECK (((edited_at IS NULL) OR (edited_at >= posted_at))),
    CONSTRAINT status_incidents_impact_chk CHECK ((impact = ANY (ARRAY['maintenance'::text, 'degraded'::text, 'partial_outage'::text, 'major_outage'::text]))),
    CONSTRAINT status_incidents_kind_chk CHECK ((kind = ANY (ARRAY['incident'::text, 'maintenance'::text]))),
    CONSTRAINT status_incidents_lifecycle_chk CHECK ((((kind = 'incident'::text) AND (lifecycle_state = ANY (ARRAY['investigating'::text, 'identified'::text, 'monitoring'::text, 'resolved'::text]))) OR ((kind = 'maintenance'::text) AND (lifecycle_state = ANY (ARRAY['scheduled'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text]))))),
    CONSTRAINT status_incidents_message_len_chk CHECK ((length(message) <= 1024)),
    CONSTRAINT status_incidents_schedule_chk CHECK ((((kind = 'incident'::text) AND (starts_at IS NOT NULL) AND (scheduled_start_at IS NULL) AND (scheduled_end_at IS NULL)) OR ((kind = 'maintenance'::text) AND (starts_at IS NULL) AND (scheduled_start_at IS NOT NULL) AND (scheduled_end_at > scheduled_start_at)))),
    CONSTRAINT status_incidents_severity_chk CHECK ((severity = ANY (ARRAY['degraded'::text, 'partial_outage'::text, 'full_outage'::text, 'maintenance'::text]))),
    CONSTRAINT status_incidents_terminal_time_chk CHECK (((lifecycle_state = ANY (ARRAY['resolved'::text, 'completed'::text, 'cancelled'::text])) = (resolved_at IS NOT NULL))),
    CONSTRAINT status_incidents_title_len_chk CHECK (((char_length(btrim(title)) >= 1) AND (char_length(btrim(title)) <= 160)))
);


